function resolveShorthand(query, userShorthands, builtins = BUILTIN_SHORTHANDS) {
  const key = query.trim().toUpperCase();
  const merged = {...builtins, ...userShorthands};
  const val = merged[key];
  if (!val) return null;
  return Array.isArray(val) ? val : [val];
}

// Monster-name shorthands (separate map/storage from the item BUILTIN_SHORTHANDS
// above — "Abby" expanding to a wiki search prefix is a different domain than an
// item-name expansion, and the two could otherwise collide confusingly).
// Player community nicknames for bosses (Ben, 2026-07-20) — each resolved term
// verified directly against the wiki's own opensearch to make sure it lands on
// the right page (several of these have punctuation the wiki is picky about:
// apostrophes in K'ril/Kree'arra, a comma in "Kerapac, the bound", "&" in
// "Vindicta & Gorvek").
// Single-string values are one specific, unambiguous monster — the search
// jumps straight to it, same as typing its exact name would. Array values
// (even single-element ones, like ABBY) mean "deliberately show every
// candidate" — either because there are genuinely several real targets
// (RAX), or because the whole point is fanning out to a family (ABBY).
const BUILTIN_MONSTER_SHORTHANDS = {
  'ABBY':   ['Abyssal'],
  'AOD':    'Nex Angel of Death',
  'ROTS':   'Barrows rise of the six',
  'RAGO':   'Vorago',
  'RAX':    ['Araxxor', 'Araxxi'], // either boss, same nickname
  'KRIL':   "K'ril Tsutsaroth",
  'KREE':   "Kree'arra",
  'ZIL':    'Commander Zilyana',
  'VINDY':  'Vindicta & Gorvek',
  'GREG':   'Gregorovic',
  'FURIES': 'Twin Furies',
  'AG':     'Arch-Glacor',
  'KERA':   'Kerapac, the bound',
  'CRO':    'Croesus',
  'ZUK':    'TzKal-Zuk',
  'CORP':   'Corporeal Beast',
  'KBD':    'King Black Dragon',
  'QBD':    'Queen Black Dragon',
  'KQ':     'Kalphite Queen',
  'KK':     'Kalphite King',
  'RIPPER': 'Ripper Demon',
};

function useSearch(items, userShorthands = {}) {
  const [query, setQuery] = useState('');
  const [focused, setFocused] = useState(false);
  const [focusIdx, setFocusIdx] = useState(0);
  const ref = useRef(null);
  const results = useMemo(() => {
    if (!query.trim() || query.length < 2) return [];
    const resolved = resolveShorthand(query, userShorthands);
    if (resolved) {
      const seen = new Set();
      const out = [];
      for (const name of resolved) {
        const q = name.toLowerCase();
        items
          .filter(it => it.name.toLowerCase().includes(q) && !seen.has(it.id))
          .sort((a,b) => {
            const ai=a.name.toLowerCase().indexOf(q), bi=b.name.toLowerCase().indexOf(q);
            if (ai !== bi) return ai - bi;
            return a.name.localeCompare(b.name);
          })
          .forEach(it => { seen.add(it.id); out.push(it); });
      }
      return out.slice(0, 12);
    }
    const q = query.toLowerCase();
    return items
      .filter(it => it.name.toLowerCase().includes(q))
      .sort((a,b) => {
        const ai=a.name.toLowerCase().indexOf(q), bi=b.name.toLowerCase().indexOf(q);
        if (ai !== bi) return ai - bi;
        return a.name.localeCompare(b.name);
      })
      .slice(0, 12);
  }, [query, items, userShorthands]);
  useEffect(() => { setFocusIdx(0); }, [results]);
  function onKey(e, onSelect) {
    if (!results.length) return;
    if (e.key==='ArrowDown') { e.preventDefault(); setFocusIdx(i=>Math.min(i+1,results.length-1)); }
    if (e.key==='ArrowUp')   { e.preventDefault(); setFocusIdx(i=>Math.max(i-1,0)); }
    if (e.key==='Enter')     { e.preventDefault(); onSelect(results[focusIdx]); setQuery(''); setFocused(false); }
    if (e.key==='Escape')    { setQuery(''); setFocused(false); }
  }
  return {query, setQuery, focused, setFocused, results, focusIdx, ref, onKey};
}

function GESearchBar({items, onSelect, userShorthands}) {
  const s = useSearch(items, userShorthands);
  const showDrop = s.focused && s.results.length > 0;
  // Portaled to document.body (Ben, 2026-08-12, real bug caught live):
  // this dropdown used to render as a normal position:absolute child of
  // .ge-search-wrap, nested inside .ge-header. Its own z-index:100 only
  // ever applied WITHIN that ancestor's local stacking context — it had
  // no way to out-rank a sibling element with its own explicit stacking
  // context, which is exactly what the sticky-header-clone portal (see
  // useStickyTableHeader) is: a fixed-position, explicitly z-indexed
  // child of body. Since .ge-header itself has no elevated z-index of
  // its own, the whole dropdown painted BELOW the sticky clone regardless
  // of its nested z-index number. Portaling this to body too puts both
  // in the same top-level stacking context, where the actual z-index
  // values (9999 vs 10) finally get compared correctly.
  const searchWrapRef = useRef(null);
  const [dropPos, setDropPos] = useState(null);
  useEffect(() => {
    if (!showDrop) { setDropPos(null); return; }
    const update = () => {
      const r = searchWrapRef.current?.getBoundingClientRect();
      if (r) setDropPos({top:r.bottom+4, left:r.left, width:r.width});
    };
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, [showDrop]);
  // "Press S or /" is a real, useful hint with a physical keyboard
  // attached (desktop) — meaningless on a touchscreen, where there's
  // nothing to press but the input itself. matchMedia mirrors the same
  // ~700px breakpoint the mobile-drawer CSS already uses elsewhere.
  const isNarrow = typeof window !== 'undefined' && window.matchMedia?.('(max-width: 700px)').matches;
  const searchPlaceholder = isNarrow ? 'Tap to search' : 'Search any item — or press S or / to focus here';
  const pickRandom = () => {
    const seen = new Set();
    const BORING_ONLY = new Set(['misc', 'low_tier', 'materials']);
    const pool = items.filter(it => {
      if (it.untradeable || (!it.high && !it.low)) return false;
      if (seen.has(it.id)) return false;
      seen.add(it.id);
      const cats = it.categories || [];
      const hasInterestingCat = cats.some(c => !BORING_ONLY.has(c));
      const hasVolume = (it.volume || 0) > 5000;
      const hasPrice  = (it.high || it.low || 0) > 10000;
      return hasInterestingCat || (hasVolume && hasPrice);
    });
    if (!pool.length) return;
    onSelect(pool[Math.floor(Math.random() * pool.length)]);
  };
  return h('div', {className:'ge-search-wrap', ref:searchWrapRef},
    h('input', {
      className:'ge-search-input',
      placeholder:searchPlaceholder,
      value:s.query, ref:s.ref,
      onChange:e=>s.setQuery(e.target.value),
      onFocus:()=>s.setFocused(true),
      onBlur:()=>setTimeout(()=>s.setFocused(false),150),
      onKeyDown:e=>s.onKey(e, it=>{onSelect(it); s.setQuery('');}),
    }),
    !s.query && h('button', {
      onClick: pickRandom,
      title: "I'm feeling lucky. You might not be.",
      style:{
        position:'absolute', right:8, top:'50%', transform:'translateY(-50%)',
        background:'transparent', border:'none', cursor:'pointer',
        fontSize:15, color:T.textDim, padding:'2px 4px', lineHeight:1,
        transition:'color 0.15s',
      },
      onMouseEnter: e => e.currentTarget.style.color = T.goldBright,
      onMouseLeave: e => e.currentTarget.style.color = T.textDim,
    }, '🎲'),
    s.query && h('button',{className:'ge-search-clear',onClick:()=>s.setQuery('')},'x'),
    showDrop && dropPos && createPortal(
      h('div',{className:'ge-search-results', style:{position:'fixed', top:dropPos.top, left:dropPos.left, width:dropPos.width, right:'auto', zIndex:9999}},
        s.results.map((it,i) =>
          h('div',{
            key:it.id,
            className:'ge-result-item'+(i===s.focusIdx?' focused':''),
            onMouseDown:()=>{onSelect(it); s.setQuery('');}
          },
            h('div',{className:'ge-result-name'},it.name),
            it.high && h('div',{className:'ge-result-price'},fmt.gp(it.high)+'gp'),
            h(LivePriceLine, {liveBuy: it.liveBuy, liveSell: it.liveSell}),
            it.categories&&it.categories[0]&&h('div',{className:'ge-result-category'},CAT_LABEL[it.categories[0]]||it.categories[0])
          )
        )
      ),
      document.body
    )
  );
}

/* ─── Price trend badges ─────────────────────────────────────── */
// Chart analysis (Ben, 2026-10-08) — phase 1: trend vs market + where the
// price sits in its 1-year range. Each reading carries its own track record
// on this item's history (backend getChartAnalysis); "Reliable" only when it
// clearly beat the item's base rate (binomial p < 0.01), otherwise shown
// greyed as "Weak" with the numbers. Summary line always visible; click to
// expand.
// Ask about this item (Ben, 2026-10-09) — fill-in-the-blank questions,
// answered by the backend askItem() from saved price history. Answers are
// exact counts and dates. Recent answers stay listed per item this session.
const ASK_PERIODS = [['90d', 'last 90 days'], ['1y', 'last year'], ['3y', 'last 3 years'], ['all', 'all history']];
const ASK_MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'].map((m, i) => [String(i + 1), m]);
// Each question: sentence parts — strings, or {f: field, kind, opts}.
const ASK_QUESTIONS = [
  {type:'level', group:'Price levels', label:'How often within / above / below X% of a price?', defaults:{mode:'within', pct:5, period:'1y'},
    parts:['How often has it been', {f:'mode', kind:'select', opts:[['within','within'],['above','above'],['below','below']]}, {f:'pct', kind:'num'}, '% of', {f:'price', kind:'gp'}, 'in the', {f:'period', kind:'select', opts:ASK_PERIODS}, '?']},
  {type:'alch', group:'Price levels', label:'How often near its alch floor?', defaults:{pct:3, period:'3y'},
    parts:['How often has it been within', {f:'pct', kind:'num'}, '% of its alch floor in the', {f:'period', kind:'select', opts:ASK_PERIODS}, '?']},
  {type:'last', group:'Price levels', label:'When was it last above / below a price?', defaults:{mode:'below'},
    parts:['When was it last', {f:'mode', kind:'select', opts:[['above','at or above'],['below','at or below']]}, {f:'price', kind:'gp'}, '?']},
  {type:'stay', group:'Price levels', label:'Once past a price, how long did it stay?', defaults:{mode:'below', period:'3y'},
    parts:['Once it went', {f:'mode', kind:'select', opts:[['below','below'],['above','above']]}, {f:'price', kind:'gp'}, ', how long did it stay there? (', {f:'period', kind:'select', opts:ASK_PERIODS}, ')']},
  {type:'recover', group:'Price levels', label:'After dropping below a price, how long to get back?', defaults:{period:'3y'},
    parts:['After dropping below', {f:'price', kind:'gp'}, ', how long until it got back? (', {f:'period', kind:'select', opts:ASK_PERIODS}, ')']},
  {type:'moves', group:'Moves', label:'How often did it move X%+ in a week / month?', defaults:{pct:10, window:'week', period:'3y'},
    parts:['How often did it move', {f:'pct', kind:'num'}, '%+ in a', {f:'window', kind:'select', opts:[['week','week'],['month','month']]}, 'over the', {f:'period', kind:'select', opts:ASK_PERIODS}, '?']},
  {type:'extremes', group:'Moves', label:'Biggest rise and biggest drop', defaults:{window:'month', period:'all'},
    parts:['Biggest rise and drop over a', {f:'window', kind:'select', opts:[['week','week'],['month','month'],['year','year']]}, 'in', {f:'period', kind:'select', opts:ASK_PERIODS}]},
  {type:'month', group:'Moves', label:'Does it usually rise or fall in a given month?', defaults:{month:String(new Date().getMonth() + 1)},
    parts:['Does it usually rise or fall in', {f:'month', kind:'select', opts:ASK_MONTHS}, '?']},
  {type:'date', group:'Time', label:'What was it on a date?', defaults:{date:new Date(Date.now() - 365 * 86400000).toISOString().slice(0, 10)},
    parts:['What was it on', {f:'date', kind:'date'}, '?']},
  {type:'average', group:'Time', label:'Average price over a period', defaults:{period:'90d'},
    parts:['Average price over the', {f:'period', kind:'select', opts:ASK_PERIODS}]},
  {type:'thisMonth', group:'Time', label:'This month vs the same month in past years', defaults:{},
    parts:['How does this month compare with the same days in past years?']},
  {type:'dxp', group:'Events', label:'What does it do around Double XP?', defaults:{},
    parts:['What does it do before, during and after Double XP weekends?']},
  {type:'update', group:'Events', label:'What did it do after a game update?', defaults:{},
    parts:['What did it do after', {f:'eventId', kind:'event'}, '?']},
  {type:'volume', group:'Volume', label:'How often was daily volume above X?', defaults:{period:'1y'},
    parts:['How often was daily volume', {f:'volume', kind:'gp', placeholder:'e.g. 10k'}, 'or more in the', {f:'period', kind:'select', opts:ASK_PERIODS}, '?']},
  {type:'volumeNow', group:'Volume', label:'Is it more traded than usual right now?', defaults:{},
    parts:['Is it more traded than usual this week?']},
  {type:'flip', group:'Flipping', label:'Would a buy at X and sell at Y have filled?', defaults:{},
    parts:['Would a buy at', {f:'buy', kind:'gp'}, 'and a sell at', {f:'sell', kind:'gp'}, 'both have filled in the same week?']},
];
const _askHistory = new Map(); // itemId -> [{label, lines}] — session only

function AskItem({item}) {
  const [open, setOpen] = useState(false);
  const [qType, setQType] = useState('level');
  const [params, setParams] = useState(ASK_QUESTIONS[0].defaults);
  const [fillKey, setFillKey] = useState(0);       // remounts GpInputs after a quick fill
  const [answer, setAnswer] = useState(null);
  const [busy, setBusy] = useState(false);
  const [events, setEvents] = useState([]);
  const [extra, setExtra] = useState(null);         // {alchFloor, typical} for quick fill
  const [recent, setRecent] = useState([]);
  useEffect(() => { setAnswer(null); setRecent(_askHistory.get(item?.id) || []); setExtra(null); }, [item?.id]);
  useEffect(() => {
    if (!open || !item?.id) return;
    if (!events.length) window.genius?.getEvents?.().then(ev => setEvents((ev || []).filter(e => e.milestones?.some(m => m.type === 'release')))).catch(() => {});
    if (!extra) window.genius?.getChartAnalysis(item.id).then(a => setExtra({alchFloor: a?.alch?.floor, typical: a?.typical})).catch(() => setExtra({}));
  }, [open, item?.id]);
  if (!item || item.untradeable) return null;
  const q = ASK_QUESTIONS.find(x => x.type === qType);
  const pick = t => { setQType(t); setParams({...ASK_QUESTIONS.find(x => x.type === t).defaults}); setAnswer(null); };
  const set = (f, v) => setParams(p => ({...p, [f]: v}));
  const priceField = q.parts.find(pt => pt.kind === 'gp' && pt.f !== 'volume')?.f;
  const quick = v => { if (priceField && v > 0) { set(priceField, Math.round(v)); setFillKey(k => k + 1); } };
  const ask = async () => {
    setBusy(true);
    const res = await window.genius?.askItem(item.id, {type: qType, ...params}).catch(e => ({error: String(e.message || e)}));
    setBusy(false); setAnswer(res);
    if (res && !res.error) {
      const entry = {label: q.label, lines: res.lines};
      const next = [entry, ...(_askHistory.get(item.id) || [])].slice(0, 5);
      _askHistory.set(item.id, next); setRecent(next);
    }
  };
  const ctl = {background:'rgba(255,255,255,0.04)', border:`1px solid ${T.border}`, borderRadius:3, color:T.text, fontSize:11, padding:'2px 4px'};
  const field = (pt, i) => {
    const v = params[pt.f];
    if (pt.kind === 'select') return h('select', {key:i, value:v ?? '', onChange:e => set(pt.f, e.target.value), style:ctl}, pt.opts.map(([val, lbl]) => h('option', {key:val, value:val}, lbl)));
    if (pt.kind === 'num') return h('input', {key:i, type:'number', min:0, value:v ?? '', onChange:e => set(pt.f, e.target.value), style:{...ctl, width:44}});
    if (pt.kind === 'date') return h('input', {key:i, type:'date', value:v ?? '', onChange:e => set(pt.f, e.target.value), style:ctl});
    if (pt.kind === 'event') return h('select', {key:i, value:v ?? '', onChange:e => set(pt.f, e.target.value), style:{...ctl, maxWidth:180}},
      h('option', {value:''}, 'pick an update…'), events.map(e => h('option', {key:e.id, value:e.id}, e.name)));
    return h('span', {key:i + ':' + fillKey, style:{display:'inline-block', width:90, verticalAlign:'middle'}},
      h(GpInput, {value:v ?? '', placeholder:pt.placeholder || 'e.g. 33k', onChange:val => set(pt.f, val), style:{...ctl, width:'100%'}}));
  };
  const groups = [...new Set(ASK_QUESTIONS.map(x => x.group))];
  const qf = (label, v) => v > 0 && h('span', {onClick:() => quick(v), style:{cursor:'pointer', color:T.gold, textDecoration:'underline dotted', marginRight:8}}, label);

  return h('div', {style:{marginTop:6, border:`1px solid ${T.borderDim}`, borderRadius:4, background:'rgba(255,255,255,0.02)'}},
    h('div', {onClick:() => setOpen(v => !v), title:'Ask a question about this item’s price history',
      style:{padding:'5px 8px', fontSize:11, color:T.text, cursor:'pointer', display:'flex', alignItems:'center', gap:6}},
      h('span', {style:{color:T.gold, fontWeight:600}}, '❓ Ask about this item'),
      h('span', {style:{color:T.textDim}}, `${ASK_QUESTIONS.length} questions`),
      h('span', {style:{marginLeft:'auto', color:T.textDim}}, open ? '▴' : '▾')),
    open && h('div', {style:{padding:'0 8px 8px', fontSize:11}},
      h('select', {value:qType, onChange:e => pick(e.target.value), style:{...ctl, width:'100%', padding:'4px'}},
        groups.map(g => h('optgroup', {key:g, label:g}, ASK_QUESTIONS.filter(x => x.group === g).map(x => h('option', {key:x.type, value:x.type}, x.label))))),
      h('div', {style:{marginTop:8, lineHeight:2.1, color:T.text}},
        q.parts.map((pt, i) => typeof pt === 'string' ? h('span', {key:i}, ' ' + pt + ' ') : field(pt, i))),
      priceField && h('div', {style:{fontSize:10, color:T.textDim, marginTop:2}}, 'Quick fill: ',
        qf('today’s price', item.high || item.low), qf('alch floor', extra?.alchFloor),
        qf('typical low', extra?.typical?.lo), qf('typical high', extra?.typical?.hi)),
      h('button', {className:'ge-btn', onClick:ask, disabled:busy, style:{marginTop:8, padding:'3px 14px', fontSize:12}}, busy ? 'Working…' : 'Ask'),
      answer && h('div', {style:{marginTop:10, padding:'6px 8px', borderLeft:`2px solid ${answer.error ? T.red : T.gold}`, background:'rgba(201,168,76,0.05)', lineHeight:1.5}},
        answer.error ? h('div', {style:{color:T.red}}, answer.error)
          : [...answer.lines.map((l, i) => h('div', {key:i, style:{color: i ? T.textDim : T.text}}, l)),
             h('div', {key:'src', style:{fontSize:10, color:T.textDim, marginTop:4, fontStyle:'italic'}}, `Daily GE guide prices up to ${answer.asOf}${qType === 'flip' ? ' (flip uses live prices)' : ''}.`)]),
      recent.length > 1 && h('div', {style:{marginTop:10}},
        h('div', {style:{fontSize:10, color:T.textDim, textTransform:'uppercase', letterSpacing:'0.05em'}}, 'Recent questions'),
        recent.slice(1).map((r, i) => { const t = r.lines.filter(l => !/:$/.test(l) && !/ — released /.test(l)).join(' '); return h('div', {key:i, title:r.lines.join(' '), style:{fontSize:10, color:T.textDim, marginTop:3}}, `· ${r.label} — ${t.length > 150 ? t.slice(0, 147) + '…' : t}`); }))));
}

// Phone <-> PC sync over home Wi-Fi (Ben, 2026-11-02). The PC shows a QR and
// lists paired phones; the phone scans it (or types it) and syncs.
const SYNC_ERRORS = {
  unreachable: "Couldn't reach your PC. Is GEnius open on it, on the same Wi-Fi? If the PC's address changed, pair again.",
  no_reply: "Couldn't reach your PC. Check the address, and that it's on the same Wi-Fi.",
  not_pairing: 'Your PC is not showing a code right now, or it expired. Start pairing on the PC again.',
  bad_code: "That code doesn't match. Check it against your PC.",
  not_paired: 'This phone is no longer paired with your PC. Pair again.',
  clock: "This phone's clock and your PC's are too far apart.",
  suspicious: 'Stopped: this sync would have removed much of your portfolio. Nothing was changed. Check your data, then use Replace with PC data if the PC is right.',
  out_of_step: 'This phone and your PC have lost track of each other (a restored backup can do this). Nothing was changed. Use Replace with PC data to start over from the PC.',
  hub_failed: 'Your PC could not read its data, so nothing was changed.',
};
const syncErrorText = e => SYNC_ERRORS[e] || String(e);
const syncWhen = t => t ? new Date(t).toLocaleString(undefined, {month:'short', day:'numeric', hour:'numeric', minute:'2-digit'}) : 'never';

function SyncHub({toast}) {
  const [devices, setDevices] = useState([]);
  const [conflicts, setConflicts] = useState([]);
  const [pair, setPair] = useState(null);
  const load = async () => {
    setDevices(await window.genius.syncListDevices() || []);
    setConflicts(await window.genius.syncGetConflicts() || []);
  };
  useEffect(() => { load(); }, []);
  useEffect(() => {
    if (!pair) return;
    // Close the code once it's used or expired.
    const t = setInterval(async () => {
      const list = await window.genius.syncListDevices() || [];
      if (list.some(d => d.pairedAt > pair.startedAt)) { setPair(null); setDevices(list); toast('Phone paired','success'); }
      else if (Date.now() > pair.expires) setPair(null);
    }, 2000);
    return () => clearInterval(t);
  }, [pair]);
  const start = async () => {
    const r = await window.genius.syncStartPairing();
    if (r?.error) { toast(r.error,'error'); return; }
    setPair({...r, startedAt: Date.now()});
  };
  return h('div', null,
    pair
      ? h('div', {style:{marginBottom:12}},
          h('img', {src:pair.qr, alt:'Pairing QR code', width:260, height:260, style:{display:'block', borderRadius:4, marginBottom:8}}),
          h('div', {style:{fontSize:12, color:T.textDim, lineHeight:1.6}},
            'In GEnius on your phone: Settings → Phone sync → Scan QR code. Or type it in:', h('br'),
            'PC address ', h('b', {style:{color:T.text}}, pair.host), ' · code ', h('b', {style:{color:T.text}}, pair.code), h('br'),
            pair.otherHosts.length ? 'If that address fails, try: ' + pair.otherHosts.join(', ') : null, pair.otherHosts.length ? h('br') : null,
            'Windows may ask to allow GEnius through the firewall. Allow it on private networks. This code lasts 2 minutes.'),
          h('button', {className:'ge-btn', style:{marginTop:8}, onClick:()=>{ window.genius.syncCancelPairing(); setPair(null); }}, 'Cancel'))
      : h('button', {className:'ge-btn gold', onClick:start}, '📱 Pair a phone'),
    devices.length > 0 && h('div', {style:{marginTop:12}},
      devices.map(d => h('div', {key:d.id, style:{display:'flex', alignItems:'center', gap:10, fontSize:12, padding:'4px 0'}},
        h('span', {style:{flex:1}}, d.name, h('span', {style:{color:T.textDim}}, ' · last sync ', syncWhen(d.lastSyncAt))),
        h('button', {className:'ge-btn', onClick:async()=>{
          if (!confirm('Unpair ' + d.name + '? It keeps its data but stops syncing.')) return;
          await window.genius.syncUnpairDevice(d.id); load();
        }}, 'Unpair')))),
    conflicts.length > 0 && h('div', {style:{marginTop:12}},
      h('div', {style:{fontSize:12, color:T.gold, marginBottom:4}}, 'Changed on both devices. The PC version was kept; check these:'),
      conflicts.slice(0, 20).map((c, i) => h('div', {key:i, style:{fontSize:11, color:T.textDim, lineHeight:1.6}},
        syncWhen(c.at), ' · ', c.name || c.kind, ' · ', c.field, ': kept ', String(c.kept), ', phone had ', String(c.other))),
      h('button', {className:'ge-btn', style:{marginTop:6}, onClick:async()=>{ await window.genius.syncClearConflicts(); load(); }}, 'Clear list')));
}

function SyncPhone({toast}) {
  const [status, setStatus] = useState(null);
  const [typing, setTyping] = useState(false);
  const [host, setHost] = useState('');
  const [code, setCode] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const load = async () => setStatus(await window.genius.syncStatus());
  useEffect(() => { load(); }, []);
  const sync = async (opts) => {
    setBusy(true); setError(null);
    const r = await window.genius.syncNow(opts);
    setBusy(false); await load();
    if (r?.error) setError(syncErrorText(r.error));
    else toast(r.changed ? 'Synced with your PC' : 'Already up to date','success');
  };
  const pairWith = async p => {
    setBusy(true); setError(null);
    const r = await window.genius.syncPair(p);
    setBusy(false);
    if (r?.error) { setError(syncErrorText(r.error)); return; }
    setTyping(false); await load();
    toast('Paired with your PC','success');
    await sync();
  };
  const scan = async () => {
    setError(null);
    try {
      const r = await window.genius.syncScan();
      if (r?.host) await pairWith(r);
      else if (r?.error) setError(r.error);
    } catch { setError('The scanner did not open. You can type the code instead.'); }
  };
  if (!status) return null;
  const pairing = h('div', null,
    h('div', {style:{display:'flex', gap:8, flexWrap:'wrap'}},
      h('button', {className:'ge-btn gold', disabled:busy, onClick:scan}, '📷 Scan QR code'),
      h('button', {className:'ge-btn', onClick:()=>setHost(host || ' ')}, 'Type it in')),
    host !== '' && h('div', {style:{marginTop:10, display:'flex', flexDirection:'column', gap:8, maxWidth:280}},
      h('input', {className:'ge-input', placeholder:'PC address, like 192.168.1.5', value:host.trim(), onChange:e=>setHost(e.target.value.trim() || ' ')}),
      h('input', {className:'ge-input', placeholder:'Code', value:code, onChange:e=>setCode(e.target.value.toUpperCase())}),
      h('button', {className:'ge-btn gold', disabled:busy || !host.trim() || !code, onClick:()=>pairWith({host:host.trim(), code})}, 'Pair')));
  return h('div', null,
    status.paired
      ? h('div', null,
          h('div', {style:{fontSize:12, color:T.textDim, marginBottom:8}}, 'Paired with your PC (', status.host, ') · last sync ', syncWhen(status.lastSyncAt)),
          h('div', {style:{display:'flex', gap:8, flexWrap:'wrap'}},
            h('button', {className:'ge-btn gold', disabled:busy, onClick:()=>sync()}, busy ? 'Syncing…' : '🔄 Sync now'),
            h('button', {className:'ge-btn', onClick:()=>setTyping(!typing)}, 'Pair again'),
            h('button', {className:'ge-btn', disabled:busy, onClick:()=>{
              if (confirm("Replace this phone's portfolio, alerts, watchlists, notes and reminders with your PC's? A backup is saved first.")) sync({startOver:true});
            }}, 'Replace with PC data'),
            h('button', {className:'ge-btn', onClick:async()=>{
              if (!confirm('Unpair from your PC? This phone keeps its data but stops syncing.')) return;
              await window.genius.syncUnpair(); load();
            }}, 'Unpair')),
          typing && h('div', {style:{marginTop:10}}, pairing))
      : pairing,
    error && h('div', {style:{fontSize:12, color:T.red, marginTop:8, lineHeight:1.5}}, error));
}

function UpdateRiskSettings() {
  const [s, setS] = useState(null);
  useEffect(() => { window.genius?.getUpdateRiskSettings?.().then(setS).catch(() => {}); }, []);
  if (!s) return null;
  const toggle = key => { const next = {...s, [key]: !s[key]}; setS(next); window.genius.setUpdateRiskSettings(next); };
  const row = (key, label, disabled) => h('label', {style:{display:'flex', gap:8, alignItems:'center', fontSize:12, padding:'3px 0', opacity:disabled?0.5:1}},
    h('input', {type:'checkbox', checked:!!s[key], disabled, onChange:()=>toggle(key)}), label);
  return h('div', {style:{marginBottom:20}},
    h('div', {className:'ge-section-head'}, 'Upcoming update alerts'),
    h('div', {style:{fontSize:11, color:T.textDim, marginBottom:8, lineHeight:1.5}},
      'Notifies you when an upcoming update may affect your items. These are warnings about what may change, not advice. The list stays on the Portfolio tab either way.'),
    row('enabled', 'Notify me about items I hold'),
    row('includeWatched', 'Also notify for my Watchlist and DXP watchlist', !s.enabled));
}

// Settings > Google Drive sync (Ben, 2026-11-10): sync through one file in the
// user's own Drive, so the phone stays in step away from home. Desktop for now.
function CloudSyncSettings({toast}) {
  const [st, setSt] = useState(null);
  const [busy, setBusy] = useState(false);
  const load = () => window.genius.cloudStatus().then(setSt).catch(() => {});
  useEffect(() => { if (window.genius?.cloudStatus) load(); }, []);
  if (!window.genius?.cloudStatus || !st) return null;
  const run = async (fn, okMsg) => { setBusy(true); try { const r = await fn(); if (r?.error) toast(r.error === 'suspicious' ? 'Stopped: this sync would have removed most of your portfolio. Nothing was changed.' : r.error === 'not_configured' ? 'Google Drive sync is not set up yet' : 'Google Drive: ' + r.error, 'error'); else if (okMsg) toast(typeof okMsg === 'function' ? okMsg(r) : okMsg, 'success'); } finally { setBusy(false); load(); } };
  const last = st.last ? new Date(st.last.at).toLocaleString(undefined, {month:'short', day:'numeric', hour:'numeric', minute:'2-digit'}) : 'never';
  return h('div', {style:{marginBottom:20}},
    h('div', {className:'ge-section-head'}, 'Google Drive sync'),
    h('div', {style:{fontSize:11, color:T.textDim, marginBottom:10, lineHeight:1.5}},
      'Keeps your portfolio, alerts, watchlists, notes, reminders and shorthands in step through one file in your own Google Drive, so it works away from home too. GEnius can only see that one file, not the rest of your Drive. Syncs after every fetch.'),
    !st.configured ? h('div', {style:{fontSize:12, color:T.textDim}}, 'Not set up yet: GEnius needs a Google sign-in key first (see GOOGLE_DRIVE_SETUP.md).')
    : !st.connected ? h('button', {className:'ge-btn gold', disabled:busy, onClick:() => run(() => window.genius.cloudConnect(), r => 'Connected' + (r.email ? ' as ' + r.email : ''))}, busy ? 'Waiting for Google sign-in in your browser…' : 'Connect Google Drive')
    : h('div', null,
        h('div', {style:{fontSize:12, color:T.text, marginBottom:6}}, '✓ Connected', st.email ? ' as ' + st.email : '', h('span', {style:{color:T.textDim}}, ' · last synced ' + last + (st.last?.conflicts ? ' · ' + st.last.conflicts + ' conflict(s), the cloud copy was kept' : ''))),
        h('label', {style:{display:'flex', alignItems:'center', gap:6, fontSize:12, marginBottom:8, cursor:'pointer'}},
          h('input', {type:'checkbox', checked:st.enabled, onChange:e => run(() => window.genius.cloudSetEnabled(e.target.checked))}), 'Sync automatically after each fetch'),
        h('div', {style:{display:'flex', gap:8, flexWrap:'wrap'}},
          h('button', {className:'ge-btn gold', disabled:busy, onClick:() => run(() => window.genius.cloudSyncNow(), r => r.changed ? 'Synced: this PC was updated' : r.uploaded ? 'Synced: your changes were saved to Drive' : 'Already in step')}, busy ? 'Syncing…' : 'Sync now'),
          h('button', {className:'ge-btn', disabled:busy, title:'Make the cloud copy match this PC exactly (other devices take it on their next sync)', onClick:() => { if (confirm('Replace the Google Drive copy with this PC\'s data?')) run(() => window.genius.cloudSyncNow({startOver:true}), 'The cloud copy now matches this PC'); }}, 'Use this PC\'s data'),
          h('button', {className:'ge-btn', disabled:busy, title:'Replace this PC\'s data with the cloud copy (a backup is saved first)', onClick:() => { if (confirm('Replace this PC\'s data with the Google Drive copy? A backup is saved first.')) run(() => window.genius.cloudSyncNow({useCloud:true}), 'This PC now matches the cloud copy'); }}, 'Use the cloud copy'),
          h('button', {className:'ge-btn', disabled:busy, onClick:() => { if (confirm('Disconnect Google Drive? Your data stays on this PC and in Drive.')) run(() => window.genius.cloudDisconnect(), 'Disconnected'); }}, 'Disconnect'))));
}

function SyncSettings({toast}) {
  const role = window.genius?.syncRole;
  if (!role) return null;
  return h('div', {style:{marginBottom:20}},
    h('div', {className:'ge-section-head'}, 'Phone sync'),
    h('div', {style:{fontSize:11, color:T.textDim, marginBottom:12, lineHeight:1.5}},
      'Keeps your portfolio, alerts, watchlists, notes, reminders and shorthands the same on your phone and PC, directly over your home Wi-Fi. No account, no server. GEnius must be open on the PC. Your data is saved as a backup before a sync changes anything.'),
    role === 'hub' ? h(SyncHub, {toast}) : h(SyncPhone, {toast}));
}

// Restore from a daily auto-backup (Ben, 2026-10-11). Lists the backups in
// autobackups/ with what each holds; restoring first saves the current data
// as a "pre-restore" snapshot (listed here too), so any restore can be
// undone. Reloads the window afterwards so every tab picks up the data.
function AutoBackupRestore({toast}) {
  const [list, setList] = useState(null);
  const [busy, setBusy] = useState(null);
  const load = () => window.genius?.listAutoBackups?.().then(l => setList(l || [])).catch(() => setList([]));
  const restore = async b => {
    const when = b.backedUpAt ? new Date(b.backedUpAt).toLocaleString() : b.file;
    if (!window.confirm(`Restore the backup from ${when}?\n\nYour watchlist, portfolio, alerts, notes, reminders and settings will be replaced with that backup's copy. Your current data is saved first as a "pre-restore" backup, so you can undo this.`)) return;
    setBusy(b.file);
    const res = await window.genius?.restoreAutoBackup(b.file).catch(e => ({error: String(e.message || e)}));
    setBusy(null);
    if (res?.error) { toast('Restore failed: ' + res.error, 'error'); return; }
    toast('Backup restored — reloading', 'success');
    setTimeout(() => window.location.reload(), 800);
  };
  const c = b => [`${b.counts.watchlist} watchlist`, b.counts.positions != null ? `${b.counts.positions} positions` : 'no portfolio',
    b.counts.alerts != null ? `${b.counts.alerts} alerts` : 'no alerts', b.counts.reminders ? `${b.counts.reminders} reminders` : null, b.counts.notes ? `${b.counts.notes} notes` : null].filter(Boolean).join(' · ');
  return h('div', {style:{marginTop:10}},
    list == null
      ? h('button', {className:'ge-btn', onClick:load}, '↺ Restore daily backup')
      : h('div', {style:{border:`1px solid ${T.borderDim}`, borderRadius:4, padding:8}},
          h('div', {style:{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:6}},
            h('span', {style:{fontSize:12, color:T.gold}}, 'Daily backups'),
            h('span', {style:{fontSize:11, color:T.textDim, cursor:'pointer'}, onClick:() => setList(null)}, '✕ close')),
          h('div', {style:{fontSize:11, color:T.textDim, marginBottom:8, lineHeight:1.5}},
            'GEnius saves one automatically each day (kept 15 days). Restoring saves your current data first, so it can be undone.'),
          !list.length && h('div', {style:{fontSize:11, color:T.textDim}}, 'No backups yet.'),
          list.map(b => h('div', {key:b.file, style:{display:'flex', alignItems:'center', gap:8, padding:'5px 0', borderTop:`1px solid ${T.borderDim}`}},
            h('div', {style:{flex:1, minWidth:0}},
              h('div', {style:{fontSize:12, color:T.text}}, (b.backedUpAt ? new Date(b.backedUpAt).toLocaleString() : b.file) + (b.kind === 'pre-restore' ? '  (saved before a restore)' : '')),
              h('div', {style:{fontSize:10, color:T.textDim}}, c(b))),
            h('button', {className:'ge-btn', disabled:!!busy, onClick:() => restore(b), style:{fontSize:11, padding:'2px 10px'}}, busy === b.file ? 'Restoring…' : 'Restore')))));
}

// Exact alch-line history text — counts, never rounded percentages
// (Ben, 2026-10-09: "100% of days" was false; it had dipped below).
function alchHistory(al) {
  if (!al || al.days == null) return '';
  if (!al.belowDays) return `Never below it in the last 3 years (${al.days.toLocaleString()} days).`;
  const lo = al.lowest;
  if (lo && lo.gap >= -0.035) return `Sits right on it: dipped under on ${al.belowDays.toLocaleString()} of ${al.days.toLocaleString()} days in the last 3 years, but never more than ${Math.abs(lo.gap * 100).toFixed(1)}% below.`;
  return `Below it on ${al.belowDays.toLocaleString()} of ${al.days.toLocaleString()} days in the last 3 years`
    + (lo ? ` (lowest: ${Math.round(lo.price).toLocaleString()}gp, ${Math.abs(lo.gap * 100).toFixed(1)}% below, on ${lo.date})` : '') + '.';
}

function ChartAnalysis({item}) {
  const [data, setData] = useState(null);
  const [open, setOpen] = useState(false);
  useEffect(() => {
    setData(null);
    if (!item?.id || item.untradeable) return;
    let stale = false;
    window.genius?.getChartAnalysis(item.id).then(r => { if (!stale) setData(r || {status:'error', readings:[]}); })
      .catch(() => { if (!stale) setData({status:'error', readings:[]}); });
    return () => { stale = true; };
  }, [item?.id]);
  if (!item || item.untradeable || !data) return null;
  if (data.status !== 'ok') {
    const why = {illiquid:'the guide price rarely changes for this item', not_enough_history:'not enough price history yet', stale_history:'price history is still updating'}[data.status] || 'no data';
    const al = data.alch;
    return h('div', {style:{marginTop:6}},
      h('div', {style:{fontSize:10, color:T.textDim, fontStyle:'italic'}}, `🔍 Analysis unavailable — ${why}.`),
      al && h('div', {style:{fontSize:11, color:T.text, marginTop:4}},
        h('span', {style:{color:'#b388ff'}}, `${al.kind === 'floor' ? 'Alch floor' : 'Alch value'} ${Math.round(al.floor).toLocaleString()}gp`),
        al.days ? h('span', {style:{color:T.textDim}}, ' — ' + alchHistory(al)) : null));
  }
  const pct = v => (v > 0 ? '+' : '') + v.toFixed(1) + '%';
  const share = t => Math.round(t.share * 100) + '%';
  const trend = data.readings.find(r => r.key === 'trend');
  const range = data.readings.find(r => r.key === 'range');
  const summary = [];
  if (trend) summary.push(trend.dir === 'up' ? '📈 Rising vs market' : trend.dir === 'down' ? '📉 Falling vs market' : '➖ In line with market');
  const typ = data.typical;
  if (typ) summary.push(typ.current > typ.hi ? 'above typical range' : typ.current < typ.lo ? 'below typical range' : 'in typical range');
  else if (range) summary.push(range.zone === 'high' ? 'near 1-year high' : range.zone === 'low' ? 'near 1-year low' : `${Math.round(range.pct)}% of 1-year range`);
  const lv = data.levels, dip = data.dip;
  const nearSup = lv?.reliable && lv.list.find(l => l.kind === 'support');
  if (nearSup) summary.push('above tested support');
  if (data.alch?.kind === 'floor' && data.alch.gapPct < 10) summary.push(data.alch.gapPct < -0.5 ? 'below alch floor' : data.alch.gapPct < 3 ? 'at alch floor' : 'near alch floor');
  const spk = data.spike, volD = data.volume;
  if (volD?.ratio7 >= 2 || volD?.ratio7 <= 0.5) summary.push(`volume ${volD.ratio7.toFixed(1)}× normal`);
  const nReliable = data.readings.filter(r => r.track && r.track.strength !== 'weak').length + (lv?.reliable && lv.list.length ? 1 : 0) + (dip?.reliable || dip?.opposite ? 1 : 0) + (spk?.opposite ? 1 : 0);
  if (trend?.track?.strength === 'opposite') summary.push('rises/drops like this tend to reverse');
  const anyReliable = nReliable > 0;

  const badge = t => {
    if (!t) return null;
    if (t.strength === 'opposite') return h('span', {
      title: 'Clearly did the OPPOSITE of this pattern on this item’s history — unlikely to be chance.',
      style:{fontSize:9, padding:'1px 5px', borderRadius:3, marginLeft:6, textTransform:'uppercase', letterSpacing:'0.05em', color:T.gold, border:`1px solid ${T.gold}`}}, t.label || 'Opposite');
    const rel = t.strength === 'reliable';
    return h('span', {
      title: rel ? 'Held up clearly more often than this item does anyway — unlikely to be chance.'
                 : 'Has not reliably held up on this item\'s history (too few past cases, or no better than what it does anyway). Treat as a description, not a prediction.',
      style:{fontSize:9, padding:'1px 5px', borderRadius:3, marginLeft:6, textTransform:'uppercase', letterSpacing:'0.05em',
        color: rel ? T.green : T.textDim, border:`1px solid ${rel ? T.green : T.border}`}}, rel ? 'Reliable' : 'Weak');
  };
  const row = (title, t, record) => h('div', {style:{marginTop:8, opacity: t && t.strength === 'weak' ? 0.75 : 1}},
    h('div', {style:{fontSize:12, color:T.text}}, title, badge(t)),
    record && h('div', {style:{fontSize:11, color:T.textDim, marginTop:2, lineHeight:1.45}}, record));

  const trendRow = trend && row(
    trend.dir === 'flat' ? `Moving with the market: ${pct(trend.rel30)} vs market over 30 days`
      : `${trend.dir === 'up' ? 'Rising' : 'Falling'} vs market: ${pct(trend.rel30)} over 30 days` + (trend.rel90 != null ? ` (90 days: ${pct(trend.rel90)})` : ''),
    trend.track && (trend.track.strength === 'opposite' ? {...trend.track, label:'Tends to reverse'} : trend.track),
    trend.track && (trend.track.n
      ? `After similar ${trend.dir === 'up' ? 'rises' : 'drops'}, it kept ${trend.dir === 'up' ? 'rising' : 'falling'} the next month ${trend.track.k} of ${trend.track.n} times (${share(trend.track)}). It ${trend.dir === 'up' ? 'rises' : 'falls'} in ${Math.round(trend.track.base * 100)}% of months anyway.`
      : 'No similar moves in its history to compare against.'));
  const rangeRow = range && (!typ || range.zone !== 'middle') && row(
    `${range.zone === 'high' ? 'Near its 1-year high' : range.zone === 'low' ? 'Near its 1-year low' : 'Mid-range'}: ${Math.round(range.pct)}% of the way from ${fmt.gp(range.lo)} to ${fmt.gp(range.hi)}gp`,
    range.track && (range.track.strength === 'opposite' ? {...range.track, label:'Tends to keep going'} : range.track),
    range.track && (range.track.n
      ? `Past times it sat this ${range.zone}, it moved back ${range.zone === 'high' ? 'down' : 'up'} (vs market) within 30 days ${range.track.k} of ${range.track.n} times (${share(range.track)}). It ${range.zone === 'high' ? 'falls' : 'rises'} in ${Math.round(range.track.base * 100)}% of months anyway.`
      : 'It hasn\'t sat this ' + range.zone + ' before with enough history to compare.'));

  return h('div', {style:{marginTop:8, border:`1px solid ${T.borderDim}`, borderRadius:4, background:'rgba(255,255,255,0.02)'}},
    h('div', {
      onClick: () => setOpen(v => !v),
      title: 'Click for the full analysis',
      style:{padding:'5px 8px', fontSize:11, color:T.text, cursor:'pointer', display:'flex', alignItems:'center', gap:6, flexWrap:'wrap'},
    },
      h('span', {style:{color:T.gold, fontWeight:600}}, '🔍 Analysis'),
      h('span', null, summary.join(' · ')),
      anyReliable && h('span', {style:{color:T.green, fontSize:10}}, `● ${nReliable} reliable`),
      h('span', {style:{marginLeft:'auto', color:T.textDim}}, open ? '▴' : '▾')),
    open && h('div', {style:{padding:'0 8px 8px'}},
      typ && row(`Typical range: ${fmt.gp(typ.lo)} – ${fmt.gp(typ.hi)}gp`, null,
        `Where it spent 80% of the last year. Now ${typ.current > typ.hi ? `above it (${fmt.gp(typ.current)}gp)` : typ.current < typ.lo ? `below it (${fmt.gp(typ.current)}gp)` : `${Math.round(typ.pct)}% of the way up`}. A description, not a prediction.`),
      lv && (lv.reliable && lv.list.length
        ? row('Tested price levels', {strength:'reliable'},
            h('div', null,
              [...lv.list].sort((a, b) => b.price - a.price).map((l, i) => h('div', {key:i}, h('span', {style:{color: l.kind === 'support' ? T.green : T.red}}, `${l.kind === 'support' ? 'Support' : 'Resistance'} ${Math.round(l.price).toLocaleString()}gp`),
                ` — held ${l.held} of ${l.touches} times (last turned ${l.lastSwing})`)),
              h('div', {style:{marginTop:3}}, `Across all its levels: held ${lv.held} of ${lv.n} times; random prices held ${Math.round(lv.base * 100)}%. Drawn on the full chart.`)))
        : h('div', {style:{marginTop:8, fontSize:11, color:T.textDim, lineHeight:1.45}},
            lv.n ? `No reliable floors or ceilings: its past turning points held ${Math.round(lv.held / lv.n * 100)}% of the time, about the same as random prices (${Math.round(lv.base * 100)}%).`
                 : 'No repeated turning points to test.')),
      data.alch && row(`${data.alch.kind === 'floor' ? 'Alch floor' : 'Alch value line'}: ${Math.round(data.alch.floor).toLocaleString()}gp`, null,
        `The break-even for High Alchemy: high alch ${data.alch.alch.toLocaleString()} − nature rune ${data.alch.nature.toLocaleString()}. Buying below it and alching makes a profit. Now ${Math.abs(data.alch.gapPct) < 0.5 ? 'right at it' : `${Math.abs(data.alch.gapPct).toFixed(1)}% ${data.alch.gapPct < 0 ? 'below' : 'above'} it`}. `
        + (data.alch.kind === 'floor' ? `Acts as a floor for this item. ${alchHistory(data.alch)}`
          : data.alch.kind === 'below' ? `Not a floor for this item — it usually sits below it, which makes it profitable to alch. ${alchHistory(data.alch)}`
          : data.alch.kind === 'mixed' ? `Only a partial floor. ${alchHistory(data.alch)}`
          : 'Not enough history to say whether it acts as a floor.')
        + ' Moves with the nature rune price.'),
      dip?.reliable && row(`Recovers from ~${dip.size}% dips`, {strength:'reliable'},
        `Climbed back ${Math.round(dip.size / (1 - dip.size / 100))}%+ within 30 days ${dip.k} of ${dip.n} times` + (dip.medianDays ? ` (usually in ~${dip.medianDays} days)` : '') + `. On other days when it was just as jumpy, it climbed that much ${Math.round(dip.base * 100)}% of the time.`),
      data.tick && data.tick.pct >= 2 && h('div', {style:{marginTop:8, padding:'6px 8px', borderLeft:`2px solid ${T.textDim}`, fontSize:11, color:T.textDim, lineHeight:1.45}},
        `Cheap item: 1gp is ${data.tick.pct.toFixed(1)}% of the price, so percentages move in big steps` + (data.tick.was30 ? ` (30 days ago it was ${data.tick.was30}gp, now ${data.tick.price}gp)` : '') + '. Moves under 2gp are ignored here.'),
      dip?.opposite && !dip.reliable && row(`Dips of ~${dip.size}% tend to keep going`, {strength:'opposite', label:'Opposite'},
        `After drops like this it climbed back ${Math.round(dip.size / (1 - dip.size / 100))}%+ within 30 days only ${dip.k} of ${dip.n} times. On other days when it was just as jumpy, it climbed that much ${Math.round(dip.base * 100)}% of the time. This is common on the GE: about half of all items keep falling after dips rather than bouncing back.`),
      spk?.opposite && row('Jumps tend to stick', {strength:'opposite', label:'Opposite'},
        (spk.activeNow ? `It jumped ${spk.p7.toFixed(1)}% this week. ` : '') + `After jumps of 10%+ in a week, it fell back 5%+ (vs market) within a month only ${spk.k} of ${spk.n} times. On other days when it was just as jumpy, it fell that much ${Math.round(spk.base * 100)}% of the time.`),
      // "Jumps tend to fade" removed 2026-10-09: failed the out-of-sample
      // check (badges from pre-Oct-2024 data held on only 42% of items after).
      volD && row(`Volume this week: ${volD.ratio7.toFixed(1)}× normal`, null,
        `About ${fmt.gp(Math.round(volD.week))} a day, vs ${fmt.gp(Math.round(volD.normal))} normally (the 2 months before). A description, not a signal.`),
      volD?.notes?.length > 0 && volD.notes.map(nt => h('div', {key:nt.key, style:{marginTop:8, padding:'6px 8px', borderLeft:`2px solid ${T.gold}`, background:'rgba(201,168,76,0.06)', fontSize:11, color:T.text, lineHeight:1.45}},
        h('div', {style:{fontSize:9, color:T.gold, textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:2}}, 'Chart myth check'),
        nt.text)),
      trendRow, rangeRow,
      h('div', {style:{fontSize:10, color:T.textDim, marginTop:10, lineHeight:1.4, fontStyle:'italic'}},
        `Based on daily GE guide prices since ${data.since}, compared with the overall market (150 most-traded items). Past cases are checked once a month so one move isn't counted many times. Not financial advice — a description of this item's past behaviour.`)));
}

function PriceTrendBadges({itemId, currentPrice, onOpenChart, untradeable}) {
  const [trends, setTrends] = useState(null);

  useEffect(() => {
    if (!itemId || !currentPrice) return;
    // Untradeable items (Invention components, combo potions) have no
    // WeirdGloop GE history — getItemHistory returns null for these
    // immediately (see api.js). Fall back to GEnius's own daily price
    // snapshots, the only real history these items ever get. Also used
    // as a fallback for tradeable items still mid-backfill, same merge
    // philosophy as ChartModal's recent-range view.
    (untradeable ? Promise.resolve(null) : window.genius?.getItemHistory(itemId))
      .then(history => (history && history.length >= 2) ? history : window.genius?.getPriceSnapshots(itemId))
      .then(history => {
      if (!history || history.length < 2) return;
      const getTs = p => typeof p.timestamp==='number' ? p.timestamp*(p.timestamp<1e12?1000:1) : new Date(p.timestamp).getTime();
      const sorted = [...history].sort((a,b) => getTs(a) - getTs(b));
      // Use the most recent history point as reference so data lag doesn't kill 7d
      const latestTs = getTs(sorted[sorted.length - 1]);
      const calc = (days) => {
        const cutoff = latestTs - days*24*60*60*1000;
        const pt = sorted.find(p => getTs(p) >= cutoff);
        if (!pt || !pt.price) return null;
        const chg = ((currentPrice - pt.price) / pt.price) * 100;
        const gp  = Math.round(currentPrice - pt.price);
        return {chg: Math.round(chg*100)/100, gp};
      };
      setTrends({d7:calc(7), d30:calc(30), d90:calc(90)});
    });
  }, [itemId, currentPrice, untradeable]);

  if (!trends) return null;
  const entries = [
    ['7d',  trends.d7],
    ['30d', trends.d30],
    ['90d', trends.d90],
  ].filter(([,v]) => v != null);
  if (!entries.length) return null;

  return h('div', {style:{marginTop:8, display:'flex', gap:6, flexWrap:'wrap'}},
    entries.map(([label, {chg, gp}]) =>
      h('div', {
        key:label,
        onClick: onOpenChart,
        style:{
          cursor:'pointer', padding:'3px 8px', borderRadius:3, fontSize:10,
          background:'rgba(0,0,0,0.25)', border:`1px solid ${T.border}`,
          display:'flex', flexDirection:'column', alignItems:'center', gap:1
        },
        title:`Click to open chart`
      },
        h('span', {style:{color:T.textDim, fontSize:9}}, label),
        h('span', {className:pctClass(chg)}, (chg>0?'+':'')+chg.toFixed(2)+'%'),
        h('span', {className:pctClass(gp), style:{fontSize:9}}, (gp>0?'+':'')+fmt.gp(gp)+'gp')
      )
    )
  );
}

/* ─── Detail panel ───────────────────────────────────────────── */
function RecipeSection({item, allItems}) {
  const recipe = COMBINATION_RECIPES.find(r => r.name.toLowerCase() === item.name.toLowerCase());
  if (!recipe) return null;

  const findIngItem = name => {
    const lower = name.toLowerCase();
    // Try exact match first
    let it = (allItems||[]).find(i => i.name.toLowerCase() === lower);
    if (it) return it;
    // Try stripping dose suffix e.g. "Elder overload potion (6)" → "Elder overload potion"
    const stripped = lower.replace(/\s*\(\d+\)\s*$/, '').trim();
    return (allItems||[]).find(i => i.name.toLowerCase() === stripped) || null;
  };

  const rows = recipe.ingredients.map(ing => {
    const ingItem = findIngItem(ing.name);
    const price = ingItem ? liveBuyOf(ingItem) : null;
    return {...ing, price, isUntrade: ingItem?.untradeable};
  });

  const total = rows.every(r => r.price != null) ? rows.reduce((s,r) => s + r.price * r.qty, 0) : null;
  const doses = recipe.name.match(/\((\d)\)/)?.[1] || 4;

  return h('div',{style:{marginTop:16, borderTop:`1px solid ${T.border}`, paddingTop:12}},
    h('div',{style:{fontSize:11, fontWeight:'bold', color:T.textDim, letterSpacing:'0.05em', marginBottom:8}}, 'RECIPE'),
    rows.map(ing =>
      h('div',{key:ing.name, style:{display:'flex', justifyContent:'space-between', alignItems:'center',
        padding:'4px 0', borderBottom:`1px solid ${T.borderDim}`, fontSize:12}},
        h('div',{style:{display:'flex', alignItems:'center', gap:5}},
          h('span',{style:{
            fontSize:9, padding:'1px 4px', borderRadius:2,
            background: ing.isUntrade ? 'rgba(255,180,0,0.08)' : 'rgba(201,168,76,0.1)',
            border:`1px solid ${ing.isUntrade ? 'rgba(255,180,0,0.25)' : 'rgba(201,168,76,0.2)'}`,
            color: ing.isUntrade ? T.gold : T.textDim
          }}, ing.isUntrade ? 'made' : 'GE'),
          h('span',{style:{color:T.text}}, ing.qty > 1 ? `${ing.qty}× ${ing.name}` : ing.name)
        ),
        h('span',{style:{color: ing.price != null ? T.textBright : T.textDim}},
          ing.price != null ? fmt.gp(ing.price * ing.qty)+' gp' : '—')
      )
    ),
    h('div',{style:{display:'flex', justifyContent:'space-between', padding:'6px 0 0',
      fontSize:12, fontWeight:'bold', color:T.gold}},
      h('span',null,'Total'),
      h('span',null, total != null ? fmt.gp(total)+' gp' : '—')
    ),
    total != null && h('div',{style:{fontSize:11, color:T.textDim, marginTop:4}},
      `Per dose: ${fmt.gp(Math.round(total / doses))} gp`)
  );
}

function BigMacLine({price, bondGP, isLive}) {
  const [pos, setPos] = useState(null);
  const macs = getBigMacs(price, bondGP);
  if (!macs) return null;
  return h('div', {
    style:{fontSize:11, color:T.textDim, cursor:'help', marginTop:8, display:'inline-block'},
    onMouseMove: e => setPos({x: e.clientX, y: e.clientY}),
    onMouseLeave: () => setPos(null),
  },
    '≈ ', macs,
    pos && createPortal(h('div', {style:{
      position:'fixed', left:pos.x + 12, top:pos.y + 12, zIndex:9999,
      background:T.panel, border:`1px solid ${T.border}`, borderRadius:4,
      padding:'5px 8px', fontSize:11, color:T.textDim, maxWidth:180, lineHeight:1.5,
      pointerEvents:'none', boxShadow:'0 2px 8px rgba(0,0,0,0.5)',
    }}, `Based on the item's ${isLive ? 'live' : 'GE guide'} price (${fmt.gp(price)}gp), the live bond price (${fmt.gp(bondGP)}gp = ${BOND_USD} USD) and the Big Mac index (${BIGMAC_USD} USD)`), document.body)
  );
}

// Automated read of the item's live flip margin — same math/thresholds
// as the Flips tab (computeFlipStats), surfaced here too since "it never
// hurts to have some extra data" even though FlipCalculator right below
// already lets you punch in your own numbers manually. When the item
// doesn't currently qualify for the Flips leaderboard, shows why instead
// of just staying silent about it.
function FlipMarginBlock({item}) {
  const stats = useMemo(() => computeFlipStats(item), [item]);
  return h('div', {style:{marginTop:16, borderTop:`1px solid ${T.border}`, paddingTop:12}},
    h('div', {style:{fontSize:11, fontWeight:'bold', color:T.textDim, letterSpacing:'0.05em', marginBottom:8}}, 'FLIP MARGIN'),
    !stats.qualifies
      ? h('div', {style:{fontSize:11, color:T.textDim, fontStyle:'italic'}}, stats.disqualifyReason || 'No live flip data available for this item.')
      : h('div', null,
          h('div', {style:{display:'flex', gap:6, fontSize:11, marginBottom:6}},
            h('div', {style:{flex:1, background:'rgba(0,0,0,0.2)', borderRadius:3, padding:'5px 8px'}},
              h('div', {style:{color:T.textDim, marginBottom:2}}, 'Margin/item'),
              h('div', {style:{color:T.gold, fontWeight:'bold'}}, fmt.gp(stats.margin)+'gp')
            ),
            h('div', {style:{flex:1, background:'rgba(0,0,0,0.2)', borderRadius:3, padding:'5px 8px'}},
              h('div', {style:{color:T.textDim, marginBottom:2}}, 'ROI'),
              h('div', {style:{color: stats.roiPct>=5 ? T.green : T.text, fontWeight:'bold'}}, stats.roiPct.toFixed(2)+'%')
            ),
            h('div', {style:{flex:1, background:'rgba(0,0,0,0.2)', borderRadius:3, padding:'5px 8px'}},
              h('div', {style:{color:T.textDim, marginBottom:2}}, 'Profit (buy limit)'),
              h('div', {style:{color:T.goldBright, fontWeight:'bold'}}, fmt.gp(stats.profitForLimit)+'gp')
            ),
          ),
          h('div', {style:{fontSize:10, color:T.textDim, fontStyle:'italic'}}, 'This item currently qualifies for the Flips leaderboard — same numbers shown there.')
        )
  );
}

function FlipCalculator({item, onAddToPortfolio, livePrice}) {
  // Live instant-buy/instant-sell (when available) is fresher than
  // item.high/item.low (15-min gazbot dump) — prefer it as the starting
  // point, but the fields still stay user-editable either way.
  const buyPrice  = livePrice?.low  ?? (item.low  || item.high || 0);
  const sellPrice = livePrice?.high ?? (item.high || item.low  || 0);
  const [buy,  setBuy]  = useState(buyPrice);
  const [sell, setSell] = useState(sellPrice);
  const [qty,  setQty]  = useState(1);

  useEffect(() => {
    setBuy(livePrice?.low ?? (item.low || item.high || 0));
    setSell(livePrice?.high ?? (item.high || item.low || 0));
  }, [item.id, livePrice]);

  const tax       = sell - applyTax(sell);
  const netSell   = sell - tax;
  const profit    = (netSell - buy) * qty;
  const investment = buy * qty;
  const roi       = investment > 0 ? (profit / investment) * 100 : 0;
  const profitColor = profit > 0 ? T.green : profit < 0 ? T.red : T.textDim;

  const inputStyle = {
    background:'rgba(0,0,0,0.25)', border:`1px solid ${T.border}`, borderRadius:3,
    color:T.text, fontSize:12, padding:'4px 6px', width:'100%', boxSizing:'border-box',
  };
  const labelStyle = {fontSize:10, color:T.textDim, marginBottom:3, textTransform:'uppercase', letterSpacing:'0.05em'};

  return h('div', {style:{marginTop:16, borderTop:`1px solid ${T.border}`, paddingTop:12}},
    h('div', {style:{fontSize:11, fontWeight:'bold', color:T.textDim, letterSpacing:'0.05em', marginBottom:8}}, 'MARGIN CALCULATOR'),
    h('div', {style:{display:'flex', gap:6, marginBottom:8}},
      h('div', {style:{flex:1}},
        h('div', {style:labelStyle}, 'Buy Price'),
        h('input', {type:'number', value:buy, min:0, onChange:e=>setBuy(+e.target.value||0), style:inputStyle})
      ),
      h('div', {style:{flex:1}},
        h('div', {style:labelStyle}, 'Sell Price'),
        h('input', {type:'number', value:sell, min:0, onChange:e=>setSell(+e.target.value||0), style:inputStyle})
      ),
      h('div', {style:{flex:'0 0 70px'}},
        h('div', {style:labelStyle}, 'Quantity'),
        h('input', {type:'number', value:qty, min:1, max:item.limit||99999, onChange:e=>setQty(Math.max(1,+e.target.value||1)), style:inputStyle})
      ),
    ),
    h('div', {style:{display:'flex', gap:6, fontSize:11}},
      h('div', {style:{flex:1, background:'rgba(0,0,0,0.2)', borderRadius:3, padding:'5px 8px'}},
        h('div', {style:{color:T.textDim, marginBottom:2}}, 'Investment'),
        h('div', {style:{color:T.textBright, fontWeight:'bold'}}, fmt.gp(investment)+'gp')
      ),
      h('div', {style:{flex:1, background:'rgba(0,0,0,0.2)', borderRadius:3, padding:'5px 8px'}},
        h('div', {style:{color:T.textDim, marginBottom:2}}, 'GE Tax'),
        h('div', {style:{color:T.textDim}}, fmt.gp(tax * qty)+'gp')
      ),
      h('div', {style:{flex:1, background:'rgba(0,0,0,0.2)', borderRadius:3, padding:'5px 8px'}},
        h('div', {style:{color:T.textDim, marginBottom:2}}, 'Profit'),
        h('div', {style:{color:profitColor, fontWeight:'bold'}}, (profit >= 0 ? '+' : '') + fmt.gp(profit)+'gp')
      ),
      h('div', {style:{flex:1, background:'rgba(0,0,0,0.2)', borderRadius:3, padding:'5px 8px'}},
        h('div', {style:{color:T.textDim, marginBottom:2}}, 'ROI'),
        h('div', {style:{color:profitColor, fontWeight:'bold'}}, roi.toFixed(2)+'%')
      ),
    ),
    onAddToPortfolio && h('button', {
      className:'ge-btn gold',
      style:{fontSize:11, padding:'3px 10px', marginTop:6},
      onClick: () => onAddToPortfolio({item_name: item.name, cost_basis: String(buy), quantity: String(qty)}),
      title: 'Log this buy to your portfolio'
    }, '+ Log to Portfolio')
  );
}

// Same breakdown math as ScoreBreakdown (Opportunities tab) — duplicated
// rather than shared since that component renders as a <tr> (meant to sit
// inside the score table) and this one is a floating popup anchored off a
// click, same interaction pattern as the Dashboard's Market Weather/
// Sector Heat Map info popups. Keep the actual point math in sync with
// run.js's real score calculation if that ever changes.
function ScoreInfoPopup({item, onClose, pos}) {
  const price   = item.high || item.low || 0;
  const chg     = item.change_1d;
  const vol     = item.volume || 0;
  const avg     = item.avgVolume || 0;
  const sigs    = item.signals || [];
  const alch    = item.alch || 0;
  const nature  = item.natureRunePrice || 0;

  const pctFactor = chg != null ? Math.min(1, Math.abs(chg) / 20) : 0;
  const gpFactor  = chg != null ? Math.min(1, (Math.abs(chg) / 100 * price) / 100000) : 0;
  const momPts    = chg != null ? Math.round(40 * Math.sqrt(pctFactor * gpFactor) * 10) / 10 : 0;

  const volRatio  = avg > 0 ? vol / avg : 0;
  const volPts    = avg > 0 && volRatio > 0 ? Math.round(Math.min(30, (volRatio - 1) / 2 * 30) * 10) / 10 : 0;

  let sigPts = 0;
  if (sigs.includes('SURGE') || sigs.includes('DUMP')) sigPts += 20;
  if (sigs.includes('ACCUMULATION') || sigs.includes('DISTRIBUTION')) sigPts += 10;
  if (sigs.includes('FRENZY')) sigPts += 10;

  const alchBuy = liveBuyOf(item) || 0;
  const alchProfit = alch && alchBuy && nature ? alch - alchBuy - nature : 0;
  const alchPts    = alchProfit > 0 ? Math.round(Math.min(10, alchProfit / alchBuy * 100) * 10) / 10 : 0;

  const rowStyle = {display:'flex', justifyContent:'space-between', alignItems:'baseline', padding:'3px 0', gap:10};
  const ptsStyle = pts => ({fontSize:12, fontWeight:'bold', color: pts > 0 ? T.green : T.textDim, flexShrink:0});

  return h('div', {
    onClick: e => e.stopPropagation(),
    style:{
      position:'fixed', left:pos.left, zIndex:9999, width:300,
      // bottom-anchored (grows upward) when flipped above the click
      // point, top-anchored (grows downward) otherwise — either way,
      // maxHeight + overflowY:auto guarantees it fits on screen without
      // needing to predict the real content height in advance.
      ...(pos.bottom != null ? {bottom:pos.bottom} : {top:pos.top}),
      maxHeight:pos.maxHeight, overflowY:'auto',
      background:T.panel2, border:`1px solid ${T.borderGold}`, borderRadius:6,
      boxShadow:'0 4px 16px rgba(0,0,0,0.6)', padding:'10px 12px',
    },
  },
    h('div', {style:{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:6}},
      h('div', {style:{fontSize:11, color:T.gold, textTransform:'uppercase', letterSpacing:'0.06em'}}, 'Opportunity Score'),
      h('span', {onClick:onClose, style:{cursor:'pointer', color:T.textDim, fontSize:13}}, '✕'),
    ),
    h('div', {style:{fontSize:11, color:T.textDim, lineHeight:1.5, marginBottom:8}},
      'A 0-100 ranking of how much is happening with this item right now — combines price momentum, trading volume vs. its own average, active signals, and alch profit margin.'
    ),
    [
      ['Price momentum', momPts, chg != null ? `${chg > 0 ? '+' : ''}${chg.toFixed(2)}%` : 'No price data'],
      ['Volume', volPts, avg > 0 ? `${volRatio.toFixed(1)}× average` : 'No avg volume yet'],
      ['Signal bonus', sigPts, sigPts > 0 ? sigs.filter(s => ['SURGE','DUMP','ACCUMULATION','DISTRIBUTION','FRENZY'].includes(s)).join(', ') : 'No qualifying signals'],
      ['Alch profit', alchPts, alchProfit > 0 ? `+${fmt.gp(Math.round(alchProfit))}gp margin` : 'No alch profit'],
    ].map(([label, pts, sub]) => h('div', {key:label, style:rowStyle},
      h('div', null,
        h('div', {style:{fontSize:11}}, label),
        h('div', {style:{fontSize:10, color:T.textDim}}, sub),
      ),
      h('div', {style:ptsStyle(pts)}, pts > 0 ? `+${pts}` : '0')
    ))
  );
}

// One button in the item panel instead of separate Alert/Remind buttons —
// Ben: the two-button header row was overflowing/getting cut off on
// narrower panel widths. A single button opening a pill-tab popup (default
// Alert, switch to Reminder) fits the same functionality into far less
// header-row space.
function QuickAlertPopup({item, pos, onClose, onSaveAlert, onSaveReminder, toast}) {
  const [mode, setMode] = useState('alert');
  const [condition, setCondition] = useState('above');
  const [price, setPrice] = useState('');
  const [pct, setPct] = useState('');
  const [signalType, setSignalType] = useState('SURGE');
  const [dueDate, setDueDate] = useState('');
  const [message, setMessage] = useState('');

  const needsPrice  = ['above','below','live_above','live_below'].includes(condition);
  const needsPct    = ['pct_up','pct_down','score_above','stopped_falling'].includes(condition);
  const needsSignal = condition === 'signal';

  const saveAlert = async () => {
    if (needsPrice  && !price)  { toast('Enter a price','error'); return; }
    if (needsPct    && !pct)    { toast('Enter a % value','error'); return; }
    const a = {
      id: Date.now().toString(), item_name: item.name, condition,
      price: needsPrice ? Number(price) : 0, pct: needsPct ? Number(pct) : 0,
      signal_type: signalType, active: false,
    };
    await window.genius?.saveAlert(a);
    onSaveAlert(a);
    toast('Alert saved','success');
    onClose();
  };
  const saveReminder = async () => {
    if (!dueDate) { toast('Pick a date','error'); return; }
    if (!message)  { toast('Enter a reminder message','error'); return; }
    const r = { id: Date.now().toString(), itemName: item.name, dueDate, message, fired: false };
    await window.genius?.saveReminder(r);
    onSaveReminder(r);
    toast('Reminder saved','success');
    onClose();
  };

  const pillStyle = active => ({
    flex:1, textAlign:'center', padding:'5px 0', fontSize:12, cursor:'pointer', borderRadius:4,
    background: active ? 'rgba(201,168,76,0.15)' : 'transparent',
    color: active ? T.gold : T.textDim,
    border: `1px solid ${active ? T.borderGold : T.border}`,
  });

  return h('div', {
    onClick: e => e.stopPropagation(),
    style:{
      position:'fixed', left:pos.left, zIndex:9999, width:260,
      ...(pos.bottom != null ? {bottom:pos.bottom} : {top:pos.top}),
      maxHeight:pos.maxHeight, overflowY:'auto',
      background:T.panel2, border:`1px solid ${T.borderGold}`, borderRadius:6,
      boxShadow:'0 4px 16px rgba(0,0,0,0.6)', padding:'10px 12px',
    },
  },
    h('div',{style:{display:'flex',gap:4,marginBottom:10}},
      h('div',{style:pillStyle(mode==='alert'),   onClick:()=>setMode('alert')},   '🔔 Alert'),
      h('div',{style:pillStyle(mode==='reminder'),onClick:()=>setMode('reminder')},'◷ Reminder'),
    ),
    mode==='alert' ? h('div',{style:{display:'flex',flexDirection:'column',gap:8}},
      h('select',{className:'ge-input',value:condition,onChange:e=>setCondition(e.target.value)},
        ALERT_CONDITIONS.map(c => h('option',{key:c.value,value:c.value},c.label))
      ),
      needsPrice && h(GpInput,{value:price, placeholder:'e.g. 500m', onChange:setPrice}),
      needsPct && h('div',{style:{display:'flex',alignItems:'center',gap:6}},
        h('input',{className:'ge-input',type:'number',min:0,max:condition==='score_above'?100:undefined,step:condition==='score_above'?1:0.1,value:pct,
          onChange:e=>setPct(e.target.value),placeholder: condition==='score_above' ? 'e.g. 70' : 'e.g. 5', style:{width:80}}),
        condition!=='score_above' && h('span',{style:{color:T.textDim,fontSize:12}},'%')
      ),
      needsSignal && h('select',{className:'ge-input',value:signalType,onChange:e=>setSignalType(e.target.value)},
        ALERT_SIGNALS.map(s => h('option',{key:s,value:s},s))
      ),
      h('button',{className:'ge-btn gold',onClick:saveAlert},'Add alert')
    ) : h('div',{style:{display:'flex',flexDirection:'column',gap:8}},
      h('input',{className:'ge-input', type:'date', value:dueDate, onChange:e=>setDueDate(e.target.value)}),
      h('textarea',{className:'ge-input', rows:2, value:message, onChange:e=>setMessage(e.target.value), placeholder:'e.g. Buy before the event ends'}),
      h('button',{className:'ge-btn gold',onClick:saveReminder},'Add reminder')
    )
  );
}

function DetailPanel({item, watchlist, onToggleWatch, onToggleHide, hiddenItems, onClose, onCategoryChange, notes, onSaveNote, allItems, dateFormat, onAddToPortfolio, panelWidth, populatedHistoryIds, devMode, onSelectItem, onSaveAlert, onSaveReminder, toast}) {
  // Item risk, worked out only for the item you open (one year of its saved prices).
  const [riskDays, setRiskDays] = useState(null);
  useEffect(() => {
    let stale = false;
    setRiskDays(null);
    if (item?.id && !item.untradeable) loadDailyPrices(item.id).then(d => { if (!stale) setRiskDays(d); }).catch(() => {});
    return () => { stale = true; };
  }, [item?.id]);
  const itemRisk = riskDays ? positionRisk(null, item, riskDays, Date.now() - 365 * 86400000) : null;
  const updateRisksForPanel = useUpdateRisks();
  const [chartOpen, setChartOpen]     = useState(false);
  const [chartDxpMode, setChartDxpMode] = useState(false);
  const [imageOpen, setImageOpen]     = useState(false);
  const [wikiStats, setWikiStats]     = useState(null);
  const [statsLoading, setStatsLoading] = useState(false);
  // "Moves with" (similar items) — click-to-load, reset per item.
  const [similar, setSimilar] = useState(null);
  useEffect(() => { setSimilar(null); }, [item?.id]);
  // Drop sources — deliberately NOT auto-fetched like wikiStats above.
  // Ben: this is a click-to-check lookup for unusual items, not something
  // that should fire a wiki request on every item click.
  const [dropSources, setDropSources] = useState(null); // null = not fetched, {sources:[...]} once loaded
  const [quickAlertPos, setQuickAlertPos] = useState(null); // null = closed, {left,top,...} once open
  const [dropSourcesLoading, setDropSourcesLoading] = useState(false);
  // "Turns into" — unlike Drop sources above, this IS auto-fetched on open
  // (Ben's ask, 2026-08-02): a much lighter page than a full drop table, and
  // useful often enough (grimy->clean herbs, raw->cooked food, augmenting
  // ingredients, etc.) that a click-first gate would just be an extra step
  // most people take anyway. Prices are never cached across opens — the
  // wiki page structure is stable but prices change constantly, so this
  // refetches (and the backend recomputes prices fresh) every time.
  const [products, setProducts] = useState(null); // null = not loaded yet, {products:[]} once loaded
  const [productSort, setProductSort] = useState(null); // null = backend's own order; {key, dir} once a header's clicked
  const toggleProductSort = key => setProductSort(s => ({key, dir: s && s.key===key ? -s.dir : -1}));
  const productSortArrow = key => productSort && productSort.key===key ? (productSort.dir>0?' ↑':' ↓') : '';
  const [scoreInfoPos, setScoreInfoPos] = useState(null); // null = closed, {left,top} once open
  const [iconUrl, setIconUrl]         = useState(null);
  const [livePrice, setLivePrice]     = useState(null); // null = not loaded yet, {} = loaded but no data
  const [editingCats, setEditingCats] = useState(false);
  const [draftCats, setDraftCats]     = useState([]);
  const [savingCats, setSavingCats]   = useState(false);
  const [noteText, setNoteText]       = useState('');
  // Discord feedback (RWBY Rose, 2026-06-28): list views should keep the
  // abbreviated "1.0K gp" style (scanning a table of dozens of rows), but
  // the single-item detail panel benefits from the exact figure — small
  // enough numbers that "1.0K" hides whether something is 950 or 1,049gp,
  // which matters when deciding whether a trade is actually worth it.
  // Toggle rather than a hard switch, since both views have a real use.
  const [fullPrice, setFullPrice] = useState(() => {
    try { return localStorage.getItem('genius_detail_full_price') === '1'; } catch { return false; }
  });
  const toggleFullPrice = () => setFullPrice(v => {
    const next = !v;
    try { localStorage.setItem('genius_detail_full_price', next ? '1' : '0'); } catch {}
    return next;
  });
  const gpFmt = n => (n == null ? '—' : fullPrice ? n.toLocaleString() : fmt.gp(n));

  useEffect(() => {
    if (!item) return;
    setWikiStats(null);
    setStatsLoading(true);
    setDropSources(null);
    setDropSourcesLoading(false);
    setProducts(null);
    setProductSort(null);
    if (!item.untradeable) {
      window.genius?.getItemProducts(item.name).then(res => {
        setProducts(res || {products:[]});
      }).catch(() => setProducts({products:[]}));
    }
    setEditingCats(false);
    setDraftCats(item.categories || []);
    setNoteText((notes && notes[item.id]) || '');
    setChartDxpMode(false);
    window.genius?.getItemStats(item.name).then(stats => {
      setWikiStats(stats);
      setStatsLoading(false);
    }).catch(() => setStatsLoading(false));
    // Real icon URL resolved backend-side via the wiki's own API
    // (icons.js) — falls back to the old first-word-capitalized filename
    // guess only for items the cache hasn't backfilled yet (or genuinely
    // has no wiki image), so nothing regresses mid-backfill.
    if (item.iconUrl) {
      setIconUrl(item.iconUrl);
    } else {
      const wikiName = item.name.split(' ').map((w,i) => i===0 ? w.charAt(0).toUpperCase()+w.slice(1) : w).join('_');
      setIconUrl(`https://runescape.wiki/images/${encodeURIComponent(wikiName)}.png`);
    }
    setLivePrice(null);
    if (!item.untradeable) {
      window.genius?.getLiveItemPrice(item.id).then(price => {
        setLivePrice(price || {});
      }).catch(() => setLivePrice({}));
    }
  }, [item?.id]);

  const saveCats = async () => {
    setSavingCats(true);
    const ov = await window.genius?.getOverrides() || {};
    ov[item.name.toLowerCase()] = draftCats;
    const res = await window.genius?.saveOverrides(ov);
    setSavingCats(false);
    if (res?.success) {
      setEditingCats(false);
      onCategoryChange && onCategoryChange(item.name, draftCats);
    }
  };

  if (!item) return null;
  const inWatch = watchlist.includes(item.id);
  const chg = item.change_1d;
  const sparkColor = chg != null && chg < 0 ? T.red : T.green;
  const [sparkHistory, setSparkHistory] = useState([]);
  // Food heal amount (wiki Food table) — null for non-food.
  const [foodHeal, setFoodHeal] = useState(null);
  useEffect(() => { setFoodHeal(null); if (item?.name && !item.untradeable) window.genius?.getFoodHeal?.(item.name).then(setFoodHeal).catch(() => {}); }, [item?.id]);
  useEffect(() => {
    if (!item?.id) return;
    setSparkHistory([]);
    // No WeirdGloop history exists for untradeable items — getItemHistory
    // returns null for these immediately (see api.js) instead of ever
    // trying and failing. Fall back to GEnius's own daily price
    // snapshots, same source the full chart modal already uses.
    (item.untradeable ? Promise.resolve(null) : window.genius?.getItemHistory(item.id))
      .then(hist => (hist && hist.length) ? hist : window.genius?.getPriceSnapshots(item.id))
      .then(hist => {
      if (!hist || !hist.length) return;
      const cutoff = Date.now() - 30 * 86400000;
      const pts = hist
        .filter(p => {
          const ts = typeof p.timestamp === 'number' ? p.timestamp * (p.timestamp < 1e12 ? 1000 : 1) : new Date(p.timestamp).getTime();
          return ts >= cutoff;
        })
        .map(p => p.price ?? p.high ?? p.low ?? 0)
        .filter(Boolean);
      setSparkHistory(pts);
    }).catch(() => {});
  }, [item.id, item.untradeable]);

  // Same outside-click/Escape dismiss pattern as the Dashboard's Market
  // Weather / Sector Heat Map info popups — both already stopPropagation
  // on clicks inside themselves, so a plain document-level listener only
  // ever fires for genuine outside clicks.
  useEffect(() => {
    if (!scoreInfoPos) return;
    const onClick = () => setScoreInfoPos(null);
    const onKey = e => { if (e.key === 'Escape') setScoreInfoPos(null); };
    document.addEventListener('click', onClick);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('click', onClick);
      document.removeEventListener('keydown', onKey);
    };
  }, [scoreInfoPos]);
  useEffect(() => {
    if (!quickAlertPos) return;
    const onClick = () => setQuickAlertPos(null);
    const onKey = e => { if (e.key === 'Escape') setQuickAlertPos(null); };
    document.addEventListener('click', onClick);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('click', onClick);
      document.removeEventListener('keydown', onKey);
    };
  }, [quickAlertPos]);

  const sortedProducts = (() => {
    if (!products || !products.products) return [];
    if (!productSort) return products.products; // backend's own order (wiki table order)
    const dir = productSort.dir;
    const getVal = productSort.key === 'name' ? p => p.name.toLowerCase() : p => p.profit;
    return [...products.products].sort((a, b) => {
      const av = getVal(a), bv = getVal(b);
      if (av == null && bv == null) return 0;
      if (av == null) return 1;  // unknown profit always sorts last regardless of direction
      if (bv == null) return -1;
      if (typeof av === 'string') return av.localeCompare(bv) * dir;
      return (av - bv) * dir;
    });
  })();

  const slotLabel = (slot) => {
    if (!slot) return null;
    const s = slot.toLowerCase();
    if (s.includes('2h') || s.includes('two')) return 'Two-handed';
    if (s.includes('off')) return 'Off-hand';
    if (s.includes('weapon') || s.includes('main')) return 'Main hand';
    return slot;
  };

  const itemUpdateRisks = updateRisksForPanel.filter(r => r.itemName.toLowerCase() === (item.name || '').toLowerCase());

  return h('div', {className:'detail-panel', style: panelWidth ? {width:panelWidth, minWidth:260} : undefined},
    chartOpen && h(ChartModal, {item, onClose:()=>{setChartOpen(false);setChartDxpMode(false);}, dateFormat, populatedHistoryIds, showDxpOverlay:chartDxpMode}),
    imageOpen && h(ImageModal, {name: item.name, detailUrl: item.iconDetailUrl, fallbackUrl: iconUrl, onClose:()=>setImageOpen(false)}),
    h('div', {className:'detail-top'},
      h('div', {className:'row-between', style:{marginBottom:6, flexWrap:'wrap', rowGap:6}},
        h('div', {className:'row', style:{gap:8, alignItems:'center', minWidth:0, overflow:'hidden', flex:'1 1 140px'}},
          iconUrl && h('img', {
            src: iconUrl,
            alt: '',
            onError: () => setIconUrl(null),
            onClick: () => setImageOpen(true),
            title: 'Click to enlarge',
            style: {width:32, height:32, imageRendering:'pixelated', flexShrink:0, cursor:'zoom-in'}
          }),
          h('div', {className:'detail-name', title:item.name, style:{overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}, item.name)
        ),
        h('div', {className:'row', style:{gap:4, flexWrap:'wrap', minWidth:0, maxWidth:'100%'}},
          h('button', {
            className:'star-btn',
            title: inWatch ? 'Remove from watchlist' : 'Add to watchlist',
            onClick: e => { e.stopPropagation(); onToggleWatch(item.id); },
            style: { display:'flex', alignItems:'center', gap:3, fontSize:13, color: inWatch ? T.goldBright : 'rgba(201,168,76,0.55)', border: `1px solid ${inWatch ? T.goldBright : 'rgba(201,168,76,0.3)'}`, borderRadius:4, padding:'3px 8px', background: inWatch ? 'rgba(201,168,76,0.12)' : 'none' }
          },
            h('span', {style:{fontSize:18, lineHeight:1}}, inWatch ? '★' : '☆'),
            h('span', null, inWatch ? 'Watching' : 'Watch')
          ),
          h('button', {
            className:'ge-btn',
            title: 'Hide this item from all tabs',
            style:{padding:'3px 5px', fontSize:11, color:T.textDim},
            onClick: () => onToggleHide && onToggleHide(item.id)
          }, '🚫 Hide'),
          onSaveAlert && h('button', {
            className:'ge-btn',
            title: 'Set an alert or reminder for this item',
            style:{padding:'3px 5px', fontSize:11},
            onClick: e => {
              e.stopPropagation();
              if (quickAlertPos) { setQuickAlertPos(null); return; }
              const r = e.currentTarget.getBoundingClientRect();
              const POPUP_WIDTH = 260, MARGIN = 8;
              let left = r.left;
              if (left + POPUP_WIDTH > window.innerWidth) left = Math.max(MARGIN, window.innerWidth - POPUP_WIDTH - MARGIN);
              const spaceBelow = window.innerHeight - r.bottom - MARGIN;
              const spaceAbove = r.top - MARGIN;
              const openUpward = spaceBelow < 260 && spaceAbove > spaceBelow;
              const maxHeight = Math.max(150, openUpward ? spaceAbove : spaceBelow);
              setQuickAlertPos({
                left,
                top: openUpward ? MARGIN : r.bottom + 6,
                bottom: openUpward ? (window.innerHeight - r.top + 6) : null,
                maxHeight,
              });
            }
          }, '🔔 Alert'),
          h('button', {className:'ge-btn', style:{padding:'3px 8px',fontSize:12}, onClick:onClose}, 'X')
        )
      ),
      itemUpdateRisks.length > 0 && h('div', {style:{margin:'6px 0', padding:'6px 8px', borderLeft:'3px solid '+T.gold, background:'rgba(201,168,76,0.08)', fontSize:11, lineHeight:1.45}},
        itemUpdateRisks.map(r => h('div', {key:r.key}, '⚠️ ', h('b', {style:{color:T.gold}}, r.updateTitle), r.when ? ' ('+r.when+')' : '', ': ', r.kind === 'mention' ? 'Mentioned: ' : '', r.effect))),
      item.categories && h('div', {className:'detail-cats'},
        item.categories.map(c => h('span',{key:c,className:'cat-tag'}, CAT_LABEL[c] || c)),
        !item.untradeable && h('span',{
          className:'cat-tag', title:'Edit categories',
          style:{cursor:'pointer',opacity:0.6,borderStyle:'dashed'},
          onClick:()=>setEditingCats(v=>!v)
        }, editingCats ? '✕ cancel' : '✎ edit')
      ),
      editingCats && h('div',{style:{padding:'6px 0 4px'}},
        CAT_GROUPS.map(group => h('div',{key:group.label, style:{marginBottom:8}},
          h('div',{style:{fontSize:9,color:T.textDim,textTransform:'uppercase',letterSpacing:'0.08em',marginBottom:4}}, group.label),
          h('div',{style:{display:'flex',flexWrap:'wrap',gap:4}},
            group.cats.map(c => {
              const active = draftCats.includes(c);
              return h('span',{key:c,
                onClick:()=>setDraftCats(prev=>prev.includes(c)?prev.filter(x=>x!==c):[...prev,c]),
                style:{fontSize:11,padding:'3px 8px',borderRadius:3,cursor:'pointer',userSelect:'none',
                  background: active ? T.gold : 'rgba(255,255,255,0.05)',
                  color: active ? '#1a1208' : T.textDim,
                  border:`1px solid ${active ? T.gold : T.border}`
                }
              }, CAT_LABEL[c] || c);
            })
          )
        )),
        h('button',{className:'ge-btn gold',style:{fontSize:11,padding:'3px 10px',marginTop:4},
          onClick:saveCats,disabled:savingCats},
          savingCats ? 'Saving…' : 'Save — takes effect on next Fetch Now')
      ),
      h('div', {className:'row', style:{alignItems:'baseline', gap:8}},
        h('div', {className:'detail-price'}, gpFmt(item.high||item.low)+' gp'),
        h('button', {
          className:'ge-btn', style:{fontSize:10, padding:'1px 7px'},
          title: fullPrice ? 'Showing exact gp — click for rounded' : 'Showing rounded gp — click for exact',
          onClick: toggleFullPrice,
        }, fullPrice ? 'Rounded Price' : 'Exact Price')
      ),
        item.untradeable
          ? h('div', {style:{marginTop:4}},
              h('div', null,
                h('span', {style:{fontSize:11, padding:'2px 7px', borderRadius:3, background:'rgba(255,180,0,0.15)', color:T.gold, border:`1px solid ${T.gold}`, fontWeight:600, letterSpacing:'0.04em'}}, 'UNTRADEABLE'),
                h('span', {style:{fontSize:11, color:T.textDim, marginLeft:8}}, 'Calculated production cost')
              ),
              // Untradeable items have no real GE change_1d (they're never
              // traded), but api.js's getData() computes an equivalent from
              // GEnius's own daily price snapshots — the same source the
              // chart already uses — so this can populate too, just derived
              // differently than a tradeable item's.
              item.change_1d != null && h('div', {className:pctClass(item.change_1d), style:{fontSize:12,marginTop:4}},
                fmt.pct(item.change_1d),
                item.high && h('span', {style:{fontSize:11, marginLeft:6, opacity:0.85}},
                  '(' + (item.change_1d > 0 ? '+' : '') + gpFmt(Math.round(item.high - (item.high / (1 + item.change_1d / 100)))) + 'gp)'
                )
              )
            )
          : item.change_1d != null && h('div', {className:pctClass(item.change_1d), style:{fontSize:12,marginTop:2}},
              fmt.pct(item.change_1d),
              item.high && h('span', {style:{fontSize:11, marginLeft:6, opacity:0.85}},
                '(' + (item.change_1d > 0 ? '+' : '') + gpFmt(Math.round(item.high - (item.high / (1 + item.change_1d / 100)))) + 'gp)'
              )
            ),
      // Live instant-buy/instant-sell prices from the wiki's real-time
      // prices API — fresher and per-price-timestamped, unlike item.high/
      // item.low above which come from the app's 15-min gazbot dump.
      !item.untradeable && livePrice && (livePrice.high != null || livePrice.low != null) && h('div', {
        style:{marginTop:8, padding:'6px 8px', background:'rgba(0,0,0,0.2)', borderRadius:4, fontSize:11}
      },
        h('div', {style:{color:T.textDim, fontSize:9, textTransform:'uppercase', letterSpacing:'0.05em', marginBottom:4}}, 'Live Price'),
        h('div', {className:'row', style:{gap:14}},
          livePrice.high != null && h('div', null,
            h('span', {style:{color:T.green}}, '● '),
            h('span', {style:{color:T.textDim}}, 'Buy '),
            h('span', {style:{color:T.text, fontWeight:600}}, gpFmt(livePrice.high)+'gp'),
            livePrice.highTime && h('span', {style:{color:T.textDim, marginLeft:6, fontSize:10}}, timeAgo(livePrice.highTime))
          ),
          livePrice.low != null && h('div', null,
            h('span', {style:{color:'#e08030'}}, '● '),
            h('span', {style:{color:T.textDim}}, 'Sell '),
            h('span', {style:{color:T.text, fontWeight:600}}, gpFmt(livePrice.low)+'gp'),
            livePrice.lowTime && h('span', {style:{color:T.textDim, marginLeft:6, fontSize:10}}, timeAgo(livePrice.lowTime))
          ),
        )
      )
    ),
    h('div', {className:'detail-body'},
      h('div', {className:'sparkline-wrap', onClick:()=>setChartOpen(true), title:'Click to enlarge'},
        h(SparklineSVG, {data:sparkHistory.length ? sparkHistory : [item.high||0, item.high||0], color:sparkColor, w:260, ht:52, showLabels:sparkHistory.length > 0}),
        h('span', {className:'sparkline-expand-hint'}, 'click to expand')
      ),
      !item.untradeable && h('div', {style:{display:'flex', gap:6, marginTop:4, marginBottom:2}},
        h('button', {
          onClick: () => { setChartDxpMode(true); setChartOpen(true); },
          title: 'View price chart with DXP event windows overlaid',
          style: {
            padding:'2px 10px', fontSize:11, cursor:'pointer', borderRadius:3,
            background: 'rgba(201,168,76,0.12)', border:`1px solid ${T.gold}`,
            color: T.gold, letterSpacing:'0.04em',
          },
        }, 'DXP')
      ),
      // Chart analysis sits right under the chart (Ben, 2026-10-09: it was
      // easy to miss lower down, half behind the panel's scroll arrows).
      h(ChartAnalysis, {item}),
      h(AskItem, {item}),
      item.untradeable
        ? [
            ['Production cost', gpFmt(item.high || item.low)+' gp'],
            item.rarity && ['Rarity', item.rarity[0].toUpperCase() + item.rarity.slice(1)],
          ].filter(Boolean).map(([l,v]) => h('div',{className:'stat-row',key:l},
            h('span',{className:'stat-lbl'},l),
            h('span',{className:'stat-val'},v)
          ))
        : [
            ['Price',         gpFmt(item.high || item.low)+' gp'],
            ['After 2% tax', item.low ? gpFmt(applyTax(item.low))+' gp' : '—'],
            // "950 + 8%" foods: also show the amount at 99 Constitution
            // (9,900 base LP) — Ben: most players are endgame with max HP.
            ...(foodHeal && !foodHeal.total && foodHeal.text ? (() => {
              const m = foodHeal.text.match(/^([0-9,]+)\s*\+\s*([0-9.]+)%$/);
              const at99 = m ? Number(m[1].replace(/,/g, '')) + Number(m[2]) / 100 * 9900 : null;
              const live = item.liveBuy != null ? item.liveBuy : null;
              const p = liveBuyOf(item);
              return [
                ['Heals', h('span', {title:'Life points healed (from the item\'s RuneScape Wiki page). The % part is of your max life points; the ≈ figure assumes 99 Constitution (9,900 base LP, no boosts).'},
                  foodHeal.text + ' LP' + (at99 ? ` (≈ ${Math.round(at99).toLocaleString()} at 99)` : ''))],
                ...(at99 && p ? [['Cost per LP', h('span', {title:`${live ? 'Live' : 'GE guide'} price ÷ ${Math.round(at99).toLocaleString()} LP (at 99 Constitution)`}, (p / at99).toFixed(2) + ' gp')]] : []),
              ];
            })() : []),
            ...(foodHeal && foodHeal.total ? (() => {
              const tot = foodHeal.total || foodHeal.use;
              const multi = foodHeal.use && foodHeal.total && foodHeal.total !== foodHeal.use;
              const healTxt = multi
                ? (foodHeal.over ? `${foodHeal.use.toLocaleString()} + ${foodHeal.over.toLocaleString()} over time` : `${foodHeal.use.toLocaleString()} per bite · ${foodHeal.total.toLocaleString()} total`)
                : `${tot.toLocaleString()} LP`;
              const live = item.liveBuy != null ? item.liveBuy : null;
              const p = liveBuyOf(item);
              return [
                ['Heals', h('span', {title:'Life points healed (RuneScape Wiki food table)'}, healTxt)],
                ['Cost per LP', h('span', {title:`${live ? 'Live' : 'GE guide'} price ÷ ${tot.toLocaleString()} total LP`}, p ? (p / tot).toFixed(2) + ' gp' : '—')],
              ];
            })() : []),
            ['Daily Change',  (() => {
              const price = item.high || item.low;
              const chg = item.change_1d;
              if (!price || chg == null) return '—';
              const prevPrice = price / (1 + chg / 100);
              const diff = Math.round(price - prevPrice);
              return h('span', {className: pctClass(diff)}, (diff > 0 ? '+' : '') + gpFmt(diff) + ' gp');
            })()],
            ['Live Daily Δ', h('span', {
              title: item.change_1d_live == null
                ? 'Not enough live trading in the last hour to compare with yesterday yet.'
                : 'Last hour\'s live buy/sell average vs yesterday\'s (from the RuneScape Wiki live prices), rather than the GE guide.'
            }, item.change_1d_live == null ? h('span',{style:{color:T.textDim, fontStyle:'italic'}},'Building up…') : h('span',{className:pctClass(item.change_1d_live)}, fmt.pct(item.change_1d_live)))],
            ['High alch',    item.alch ? gpFmt(item.alch)+' gp' : '—'],
            ['GE Limit',     item.limit ? item.limit.toLocaleString() : '—'],
          ].map(([l,v]) => h('div',{className:'stat-row',key:l},
            h('span',{className:'stat-lbl'},l),
            h('span',{className:'stat-val'},v)
          )),
      !item.untradeable && h('div', {className:'stat-row'},
        h('span',{className:'stat-lbl'},'Volume'),
        h('span',{className:'stat-val'}, h(VolDisplay,{volume:item.volume, avgVolume:item.avgVolume}))
      ),
      !item.untradeable && h('div', {className:'stat-row'},
        h('span',{className:'stat-lbl', style:{display:'flex', alignItems:'center', gap:5}},
          'Opportunity Score',
          h('span', {
            onClick: e => {
              e.stopPropagation();
              const POPUP_WIDTH = 300;
              const MARGIN = 8;
              if (!scoreInfoPos) {
                const r = e.currentTarget.getBoundingClientRect();
                let left = r.left;
                if (left + POPUP_WIDTH > window.innerWidth) left = Math.max(MARGIN, window.innerWidth - POPUP_WIDTH - MARGIN);
                // Don't guess a fixed popup height (got this wrong once
                // already — the real content, header + explanation +
                // 4 breakdown rows, is taller than a guessed number).
                // Instead pick whichever side has more room, and cap the
                // popup's own maxHeight to whatever that side actually
                // has (with internal scroll as a safety net) — this can
                // never run off-screen regardless of exact content height.
                const spaceBelow = window.innerHeight - r.bottom - MARGIN;
                const spaceAbove = r.top - MARGIN;
                const openUpward = spaceBelow < 260 && spaceAbove > spaceBelow;
                const maxHeight = Math.max(150, openUpward ? spaceAbove : spaceBelow);
                setScoreInfoPos({
                  left,
                  top: openUpward ? MARGIN : r.bottom + 6,
                  bottom: openUpward ? (window.innerHeight - r.top + 6) : null,
                  maxHeight,
                });
              } else {
                setScoreInfoPos(null);
              }
            },
            title:'What does this score mean?',
            style:{cursor:'pointer', fontSize:9, color:T.textDim, border:`1px solid ${T.textDim}`, borderRadius:'50%', width:12, height:12, display:'inline-flex', alignItems:'center', justifyContent:'center', flexShrink:0},
          }, '?'),
        ),
        h('span',{className:'stat-val'}, item.score != null
          ? h('span', null, item.score.toFixed(1), h('span',{style:{color:T.textDim,fontSize:10}}, '/100'))
          : '—')
      ),
      scoreInfoPos && createPortal(h(ScoreInfoPopup, {item, onClose:()=>setScoreInfoPos(null), pos:scoreInfoPos}), document.body),
      quickAlertPos && createPortal(h(QuickAlertPopup, {item, pos:quickAlertPos, onClose:()=>setQuickAlertPos(null), onSaveAlert, onSaveReminder, toast}), document.body),
      !item.untradeable && populatedHistoryIds && !populatedHistoryIds.has(item.id) && h('div',{
        style:{fontSize:10, color:T.textDim, fontStyle:'italic', marginTop:2, marginBottom:4}
      }, '📊 Price history still loading for this item — Volume avg and Daily Change will firm up once it finishes.'),
      !item.untradeable && item.signals&&item.signals.length>0 && h('div',{className:'signal-list'},
        item.signals.map(s=>h(SignalBadge,{key:s,signal:s}))
      ),
      !item.untradeable && itemRisk && h('div',{style:{marginTop:4, marginBottom:4}}, h(SignalBadge, itemRisk)),

      // Price trend badges from history
      item.id && h(PriceTrendBadges, {itemId: item.id, currentPrice: item.high||item.low, onOpenChart:()=>setChartOpen(true), untradeable: item.untradeable}),

      // Big Mac price conversion
      // Live prices (Ben, 2026-10-13): the GE guide can be far off — e.g.
      // new items listed at 115m while trading at ~1.5b. Mid of live
      // instant-buy/sell, falling back to the guide when there's no live data.
      !item.untradeable && h(BigMacLine, (() => {
        const live = it => it && (it.liveBuy != null && it.liveSell != null ? (it.liveBuy + it.liveSell) / 2 : (it.liveBuy ?? it.liveSell));
        const bond = (allItems||[]).find(it => it.name === 'Bond');
        const p = live(item), b = live(bond);
        return { price: p || item.high || item.low, bondGP: b || bond?.high || 0, isLive: !!p };
      })()),

      // Examine text — use dump data first, fall back to wiki fetch
      statsLoading && !item.examine && h('div',{style:{marginTop:12,fontSize:11,color:T.textDim}},'Loading item info...'),
      h('div',{style:{marginTop:12,padding:'8px 10px',background:'rgba(0,0,0,0.2)',borderRadius:4,fontSize:11,color:T.textDim,fontStyle:'italic',lineHeight:1.5}},
        (() => {
          const txt = item.examine || wikiStats?.examine;
          if (txt) return ['"', txt, '"'];
          if (statsLoading) return null;
          return '"This item is so boring that not even the API has a description for it."';
        })()
      ),

      // Market Personality
      !item.untradeable && h('div', {style:{marginTop:10, padding:'8px 10px', background:'rgba(0,0,0,0.15)', borderRadius:4, borderLeft:`2px solid ${T.borderDim}`, fontSize:11, color:T.textDim, lineHeight:1.5}},
        h('span', {style:{color:T.gold, fontWeight:'bold', marginRight:6}}, '◈'),
        getMarketPersonality(item)
      ),

      // Equipment stats table
      wikiStats?.isGear && h('div',{style:{marginTop:12}},
        h('div',{style:{fontSize:11,fontWeight:'bold',color:T.gold,textTransform:'uppercase',letterSpacing:1,marginBottom:6}},
          'Combat Stats'
        ),
        h('table',{style:{width:'100%',borderCollapse:'collapse',fontSize:11}},
          h('tbody',null,
            // Requirements / Tier / Class / Slot row
            wikiStats.tier && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Tier'),
              h('td',{style:{color:T.gold,textAlign:'right',padding:'3px 0'}}, wikiStats.tier)
            ),
            wikiStats.combatClass && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Class'),
              h('td',{style:{color:T.gold,textAlign:'right',padding:'3px 0'}}, wikiStats.combatClass)
            ),
            wikiStats.slot && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Slot'),
              h('td',{style:{color:T.gold,textAlign:'right',padding:'3px 0'}}, slotLabel(wikiStats.slot) || wikiStats.slot)
            ),
            wikiStats.type && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Type'),
              h('td',{style:{color:T.gold,textAlign:'right',padding:'3px 0'}}, wikiStats.type)
            ),
            // Separator
            h('tr',null, h('td',{colSpan:2, style:{padding:'4px 0'}},
              h('div',{style:{borderTop:`1px solid ${T.border}`,margin:'2px 0'}})
            )),
            // Offensive stats
            wikiStats.damage && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Damage'),
              h('td',{style:{color:T.green,textAlign:'right',padding:'3px 0'}}, wikiStats.damage)
            ),
            wikiStats.accuracy && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Accuracy'),
              h('td',{style:{color:T.green,textAlign:'right',padding:'3px 0'}}, wikiStats.accuracy)
            ),
            wikiStats.style && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Style'),
              h('td',{style:{color:T.gold,textAlign:'right',padding:'3px 0'}}, wikiStats.style)
            ),
            wikiStats.speed && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Speed'),
              h('td',{style:{color:T.gold,textAlign:'right',padding:'3px 0'}}, wikiStats.speed)
            ),
            wikiStats.range && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Range'),
              h('td',{style:{color:T.gold,textAlign:'right',padding:'3px 0'}}, wikiStats.range)
            ),
            // Defensive stats
            (wikiStats.armour || wikiStats.lp || wikiStats.prayer) && h('tr',null,
              h('td',{colSpan:2, style:{padding:'4px 0'}},
                h('div',{style:{borderTop:`1px solid ${T.border}`,margin:'2px 0'}})
              )
            ),
            wikiStats.armour && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Armour'),
              h('td',{style:{color:T.blue,textAlign:'right',padding:'3px 0'}}, wikiStats.armour)
            ),
            wikiStats.lp && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Life Points'),
              h('td',{style:{color:T.blue,textAlign:'right',padding:'3px 0'}}, wikiStats.lp)
            ),
            wikiStats.prayer && h('tr',null,
              h('td',{style:{color:T.textDim,padding:'3px 0'}}, 'Prayer'),
              h('td',{style:{color:T.blue,textAlign:'right',padding:'3px 0'}}, wikiStats.prayer)
            ),
          )
        )
      ),

      h('div',{style:{marginTop:12, display:'flex', gap:6, flexWrap:'wrap'}},
        h('button',{
          className:'ge-btn',
          style:{fontSize:11, padding:'3px 10px'},
          onClick:()=>{
            const url = `https://runescape.wiki/w/${encodeURIComponent(item.name.replace(/ /g,'_'))}`;
            window.genius?.openExternal(url);
          }
        },'📖 RS Wiki'),
        !item.untradeable && h('button',{
          className:'ge-btn',
          style:{fontSize:11, padding:'3px 10px'},
          disabled: dropSourcesLoading,
          title:'Fetch where this item drops from, straight from the RS Wiki — not saved, just a quick lookup',
          onClick:()=>{
            if (dropSourcesLoading) return;
            setDropSourcesLoading(true);
            window.genius?.getDropSources(item.name).then(res => {
              setDropSources(res || {sources:[]});
              setDropSourcesLoading(false);
            }).catch(() => { setDropSources({sources:[]}); setDropSourcesLoading(false); });
          }
        }, dropSourcesLoading ? '⏳ Loading…' : '🐲 Drop sources'),
        !item.untradeable && h('button',{
          className:'ge-btn',
          style:{fontSize:11, padding:'3px 10px'},
          title:'Items whose prices have historically moved together with this one (beyond the overall market)',
          onClick:()=>{
            setSimilar('loading');
            window.genius?.getSimilarItems(item.id).then(r => setSimilar(r || {together:[], opposite:[]})).catch(() => setSimilar({together:[], opposite:[]}));
          }
        }, similar === 'loading' ? '⏳ Loading…' : '🔗 Moves with')
      ),

      similar && similar !== 'loading' && h('div', {style:{marginTop:8}},
        similar.pending ? h('div', {style:{fontSize:11, color:T.textDim, fontStyle:'italic'}}, 'Still building the comparison table in the background. Try again in a few minutes.')
        : similar.tooFlat ? h('div', {style:{fontSize:11, color:T.textDim, fontStyle:'italic'}}, 'This item\'s price barely moves week to week, so there\'s nothing reliable to compare.')
        : h('div', null,
            h('div', {style:{fontSize:10, color:T.textDim, marginBottom:4}}, 'Weekly price moves over the last two years, after removing the overall market\'s move. Some matches are coincidence: treat these as leads to check, not proof.'),
            similar.together.length === 0 ? h('div', {style:{fontSize:11, color:T.textDim, fontStyle:'italic'}}, 'Nothing moves closely with it.')
            : similar.together.map(o => h('div', {key:o.id, style:{display:'flex', justifyContent:'space-between', fontSize:11, padding:'2px 0'}},
                h('span', {style:{color:T.gold, cursor:'pointer'}, onClick:() => { const it = (allItems || []).find(i => i.id === o.id); it && onSelectItem && onSelectItem(it); }}, o.name),
                h('span', {style:{color:T.green}, title:`Correlation ${o.corr.toFixed(2)} over ${o.weeks} weeks`}, Math.round(o.corr * 100) + '% match'))),
            similar.opposite.length > 0 && h('div', {style:{fontSize:10, color:T.textDim, margin:'6px 0 2px'}}, 'Tends to move opposite:'),
            similar.opposite.map(o => h('div', {key:o.id, style:{display:'flex', justifyContent:'space-between', fontSize:11, padding:'2px 0'}},
              h('span', {style:{color:T.gold, cursor:'pointer'}, onClick:() => { const it = (allItems || []).find(i => i.id === o.id); it && onSelectItem && onSelectItem(it); }}, o.name),
              h('span', {style:{color:T.red}, title:`Correlation ${o.corr.toFixed(2)} over ${o.weeks} weeks`}, Math.round(-o.corr * 100) + '% opposite'))))),

      dropSources && h('div', {style:{marginTop:8}},
        dropSources.sources.length === 0
          ? h('div', {style:{fontSize:11, color:T.textDim, fontStyle:'italic'}}, 'No monster drop sources listed on the wiki page — probably bought, made, or otherwise not a drop.')
          : h('table', {style:{width:'100%', borderCollapse:'collapse', fontSize:11}},
              h('thead', null, h('tr', null,
                h('th', {style:{textAlign:'left', color:T.textDim, fontWeight:'normal', padding:'2px 4px 4px 0', borderBottom:`1px solid ${T.border}`}}, 'Source'),
                h('th', {style:{textAlign:'right', color:T.textDim, fontWeight:'normal', padding:'2px 4px 4px', borderBottom:`1px solid ${T.border}`}}, 'Qty'),
                h('th', {style:{textAlign:'right', color:T.textDim, fontWeight:'normal', padding:'2px 0 4px 4px', borderBottom:`1px solid ${T.border}`}}, 'Rarity'),
              )),
              h('tbody', null, dropSources.sources.map((s,i) => h('tr', {key:i},
                h('td', {style:{padding:'3px 4px 3px 0', color:T.text}}, s.source),
                h('td', {style:{padding:'3px 4px', textAlign:'right', color:T.textDim}}, s.quantity || '—'),
                h('td', {style:{padding:'3px 0 3px 4px', textAlign:'right', color:T.gold}}, s.rarity || '—'),
              )))
            ),
        dropSources.totalCount > dropSources.sources.length && h('div', {
          style:{fontSize:10, color:T.textDim, fontStyle:'italic', marginTop:4},
        }, `+ ${dropSources.totalCount - dropSources.sources.length} more sources — see full list on the wiki`)
      ),

      products && products.products.length > 0 && h('div', {style:{marginTop:12}},
        h('div', {className:'ge-section-head'}, 'Turns Into'),
        h('table', {style:{width:'100%', borderCollapse:'collapse', fontSize:11}},
          h('thead', null, h('tr', null,
            h('th', {
              onClick:()=>toggleProductSort('name'), style:{textAlign:'left', color:T.textDim, fontWeight:'normal', padding:'2px 4px 4px 0', borderBottom:`1px solid ${T.border}`, cursor:'pointer', userSelect:'none'},
              title:'Sort by name — click again to reverse',
            }, 'Product'+productSortArrow('name')),
            h('th', {style:{textAlign:'right', color:T.textDim, fontWeight:'normal', padding:'2px 4px 4px', borderBottom:`1px solid ${T.border}`}}, 'Cost'),
            h('th', {
              onClick:()=>toggleProductSort('profit'), style:{textAlign:'right', color:T.textDim, fontWeight:'normal', padding:'2px 0 4px 4px', borderBottom:`1px solid ${T.border}`, cursor:'pointer', userSelect:'none'},
              title:'Sort by profit/loss — click again to reverse',
            }, 'Profit'+productSortArrow('profit')),
          )),
          h('tbody', null, sortedProducts.map((p,i) => {
            const matched = allItems && allItems.find(it => it.name.toLowerCase() === p.name.toLowerCase());
            return h('tr', {key:i},
              h('td', {
                style:{padding:'3px 4px 3px 0', color: matched ? T.gold : T.text, cursor: matched ? 'pointer' : 'default', textDecoration: matched ? 'underline dotted' : 'none'},
                onClick: matched ? () => onSelectItem && onSelectItem(matched) : undefined,
                title: (matched ? 'Open in item lookup\n' : '') + p.materials.map(m => `${m.qty} × ${m.name}${m.unitPrice!=null ? ` (${m.unitPrice.toLocaleString()}gp ea)` : ' (price unknown)'}`).join('\n'),
              }, p.name),
              h('td', {style:{padding:'3px 4px', textAlign:'right', color:T.textDim}}, p.hasUnknownCost ? '—' : p.cost.toLocaleString()),
              h('td', {style:{padding:'3px 0 3px 4px', textAlign:'right', color: p.profit == null ? T.textDim : (p.profit >= 0 ? T.green : T.red)}},
                p.profit == null ? '—' : `${p.profit >= 0 ? '+' : ''}${p.profit.toLocaleString()}gp`
              ),
            );
          }))
        ),
        h('div', {style:{fontSize:10, color:T.textDim, fontStyle:'italic', marginTop:4}},
          'Cost/profit cross-reference GEnius\'s own live buy/sell prices, not the wiki\'s own (usually stale or missing) GE price column. Excludes purely cosmetic recolors/augments.'
        ),
        products.totalCount > products.products.length && h('div', {
          style:{fontSize:10, color:T.textDim, fontStyle:'italic', marginTop:2},
        }, `+ ${products.totalCount - products.products.length} more products — see full list on the wiki`)
      ),

      h(RecipeSection, {item, allItems}),

      !item.untradeable && h(FlipMarginBlock, {item}),
      !item.untradeable && h(FlipCalculator, {item, onAddToPortfolio, livePrice}),

      h('div',{style:{marginTop:16, borderTop:`1px solid ${T.border}`, paddingTop:12}},
        h('div',{style:{fontSize:11, fontWeight:'bold', color:T.textDim, letterSpacing:'0.05em', marginBottom:6}}, 'NOTES'),
        h('textarea',{
          value: noteText,
          onChange: e => setNoteText(e.target.value),
          onBlur: () => onSaveNote && onSaveNote(item.id, noteText),
          placeholder: 'Personal notes on this item…',
          rows: 4,
          style:{
            width:'100%', boxSizing:'border-box', resize:'vertical',
            background:'rgba(0,0,0,0.2)', border:`1px solid ${T.border}`,
            borderRadius:3, color:T.text, fontSize:12, padding:'6px 8px',
            fontFamily:'inherit', lineHeight:1.5,
          }
        }),
        noteText && h('div',{style:{fontSize:10,color:T.textDim,marginTop:3,textAlign:'right'}},'Auto-saved on blur')
      )
    )
  );
}

// Shared column logic for every resizable table in the app: drag-to-resize
// on the column dividers AND drag-to-reorder on the header cells, both
// persisted per-table in localStorage (widths at storageKey, order at
// storageKey+'_order'). Widths live in a <colgroup>; resize handles are
// absolutely-positioned overlay spans so the divider is grabbable at any row.
//
// HANDLE POSITIONING (the old "sliding columns" bug): handle positions used
// to be computed from the *stored* widths (cumulative sum), assuming each
// column renders at exactly its stored width. They don't always — padding,
// content overflow, and UI-scale rounding all make rendered widths drift
// from stored ones, so handles ended up floating over the wrong columns and
// dragging one resized a column you weren't visually touching. Now positions
// come from the real DOM: cumulative th.offsetWidth, which is in logical
// (pre-transform) px, so it stays correct at any UI Scale, and a
// ResizeObserver on the table re-measures whenever the rendered layout
// actually changes (also covers the old mount-timing bug where the one-shot
// measurement ran before the table existed).
//
// visibleCols (optional): the subset of defaultWidths keys the table is
// currently rendering (e.g. ItemTable hides its `signals` column on some
// tabs). Order state always tracks the FULL key set; rendering/measuring
// filter down to the visible ones.
// Hand-built tables (no useTableColumns) mark which columns to hide at
// phone width by table class: 1-based column positions. Keep the item name
// plus the one or two numbers that table exists to show.
const PHONE_HIDE_COLS = {
  'pt-flips':     [2, 3, 4, 6, 7, 9],     // keep Item, Margin/item, Realistic profit, ★
  'pt-flagged':   [2, 3, 4, 5],           // keep Item, Why it's flagged
  'pt-portfolio': [2, 5, 6, 7],           // keep Item, Price/value, P&L, actions
  'pt-money':     [2, 3, 4, 5, 7],        // keep Item, Margin, Profit per limit (+ any after)
  'pt-movers':    [2, 4],                 // keep Item, Now, Change, ★
  'pt-opps':      [4, 5, 6, 7, 8],        // keep the first three
  'pt-score':     [3, 5, 6],              // keep Item, Score, Change
  'pt-realized':  [2, 3],                 // keep Item, Realized P&L, % of total
  'pt-closed':    [2, 3, 5, 6],           // keep Item, Avg return, Total P&L
};
function phoneHideCols() {
  return Object.entries(PHONE_HIDE_COLS).map(([cls, cols]) =>
    cols.map(c => `.${cls} > * > tr > :nth-child(${c}):not([colspan])`).join(', ') + ' { display: none; }'
  ).join(' ');
}

// Phone-width screens (same 700px breakpoint as the drawer CSS; desktop's
// window can't get this narrow). Tables there show only their phoneCols
// and lay out automatically instead of using the desktop column widths —
// the rest of each row is one tap away in the item panel.
const IS_PHONE = typeof window !== 'undefined' && !!window.matchMedia?.('(max-width: 700px)').matches;

function useTableColumns(storageKey, defaultWidths, visibleCols, phoneCols) {
  const defaultOrder = Object.keys(defaultWidths);
  const orderKey = storageKey + '_order';
  const loadWidths = () => {
    try { return {...defaultWidths, ...JSON.parse(localStorage.getItem(storageKey)||'{}')}; }
    catch { return {...defaultWidths}; }
  };
  const loadOrder = () => {
    // Saved order survives column additions/removals across versions:
    // unknown keys are dropped, new keys are appended in default position.
    try {
      const saved = JSON.parse(localStorage.getItem(orderKey)||'null');
      if (Array.isArray(saved)) {
        const valid = saved.filter(k => defaultOrder.includes(k));
        const missing = defaultOrder.filter(k => !valid.includes(k));
        if (valid.length) return [...valid, ...missing];
      }
    } catch {}
    return [...defaultOrder];
  };
  const [colWidths, setColWidths] = useState(loadWidths);
  const [colOrderFull, setColOrderFull] = useState(loadOrder);
  const colWidthsRef = useRef(colWidths);
  colWidthsRef.current = colWidths;
  // MachineCalculators swaps storageKey per machine — reload when it changes
  // (useState initializers only run on first mount).
  const mountedKeyRef = useRef(storageKey);
  useEffect(() => {
    if (mountedKeyRef.current === storageKey) return;
    mountedKeyRef.current = storageKey;
    setColWidths(loadWidths());
    setColOrderFull(loadOrder());
    // eslint-disable-next-line
  }, [storageKey]);

  let colOrder = visibleCols ? colOrderFull.filter(k => visibleCols.includes(k)) : colOrderFull;
  const phone = IS_PHONE && phoneCols;
  if (phone) colOrder = phoneCols.filter(k => colOrder.includes(k));

  // Callback ref (not a plain useRef) so mounting the wrap div triggers a
  // re-measure — a plain ref changing .current re-runs nothing.
  const [wrapNode, setWrapNode] = useState(null);
  const tableWrapRef = useCallback(node => setWrapNode(node), []);
  const [handleLefts, setHandleLefts] = useState({});
  const [handleTop, setHandleTop] = useState(0);

  useEffect(() => {
    if (!wrapNode) return;
    const measure = () => {
      const ths = wrapNode.querySelectorAll('thead th');
      if (!ths.length) return;
      const lefts = {};
      let cumulative = 0;
      // On-screen th order matches colOrder (tables render from it).
      colOrder.forEach((k, i) => {
        const th = ths[i];
        if (!th) return;
        cumulative += th.offsetWidth;
        if (i < colOrder.length - 1) lefts[k] = cumulative;
      });
      setHandleLefts(lefts);
      // The wrapper also holds the tab's description and toolbar, so the handles
      // start at the header row or their lines run up through those.
      setHandleTop(ths[0].getBoundingClientRect().top - wrapNode.getBoundingClientRect().top + wrapNode.scrollTop);
    };
    measure();
    window.addEventListener('resize', measure);
    let ro = null;
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(measure);
      const table = wrapNode.querySelector('table');
      if (table) ro.observe(table);
    }
    return () => {
      window.removeEventListener('resize', measure);
      if (ro) ro.disconnect();
    };
    // eslint-disable-next-line
  }, [colWidths, colOrderFull, visibleCols && visibleCols.join(','), wrapNode]);

  const startColResize = (key) => e => {
    e.preventDefault();
    e.stopPropagation();
    const startW = colWidthsRef.current[key] || 110;
    const startX = e.clientX;
    // offsetWidth is in local (pre-transform) px; getBoundingClientRect is in
    // viewport (post-transform) px. The ratio gives the CSS scale factor so
    // that mouse delta (viewport px) converts correctly to column width (logical px).
    const scaleFactor = wrapNode && wrapNode.offsetWidth
      ? wrapNode.getBoundingClientRect().width / wrapNode.offsetWidth
      : 1;
    const onMove = me => {
      const w = Math.max(40, Math.round(startW + (me.clientX - startX) / scaleFactor));
      colWidthsRef.current = {...colWidthsRef.current, [key]: w};
      setColWidths(colWidthsRef.current);
    };
    const onUp = () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
      try { localStorage.setItem(storageKey, JSON.stringify(colWidthsRef.current)); } catch {}
    };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };

  const overlayHandle = key => handleLefts[key]
    ? h('span', {
        key,
        onMouseDown: startColResize(key),
        className: 'col-resize-handle',
        style:{
          position:'absolute', top: handleTop, bottom:0,
          left: handleLefts[key] - 4,
          width:8, cursor:'col-resize', zIndex:10,
        },
      })
    : null;

  // ── Header drag-to-reorder ──
  const dragKeyRef = useRef(null);
  const [dropTarget, setDropTarget] = useState(null);
  const moveCol = (from, to) => {
    setColOrderFull(prev => {
      if (from === to || !prev.includes(from) || !prev.includes(to)) return prev;
      const insertAt = prev.indexOf(to);
      const next = prev.filter(k => k !== from);
      next.splice(insertAt, 0, from);
      try { localStorage.setItem(orderKey, JSON.stringify(next)); } catch {}
      return next;
    });
  };
  const reorderProps = key => ({
    draggable: true,
    onDragStart: e => {
      dragKeyRef.current = key;
      e.dataTransfer.effectAllowed = 'move';
      try { e.dataTransfer.setData('text/plain', key); } catch {}
    },
    onDragOver: e => {
      if (dragKeyRef.current && dragKeyRef.current !== key) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        setDropTarget(t => t === key ? t : key);
      }
    },
    onDragLeave: () => setDropTarget(t => t === key ? null : t),
    onDrop: e => {
      e.preventDefault();
      const from = dragKeyRef.current;
      dragKeyRef.current = null;
      setDropTarget(null);
      if (from && from !== key) moveCol(from, key);
    },
    onDragEnd: () => { dragKeyRef.current = null; setDropTarget(null); },
    className: dropTarget === key ? 'col-drop-target' : undefined,
  });

  // th(key, props, ...children): renders a header cell with reorder
  // drag-and-drop wired in, merging the table's own props (sort onClick,
  // titles, styles) on top.
  const th = (key, props, ...children) => {
    const rp = reorderProps(key);
    const merged = {...(props||{}), ...rp, key};
    if (props && props.className) merged.className = props.className + (rp.className ? ' ' + rp.className : '');
    merged.style = {userSelect:'none', ...(props && props.style)};
    return h('th', merged, ...children);
  };

  // colgroup() + handles(): the two order-dependent bits every table needs.
  const colgroup = () => phone ? null : h('colgroup', null,
    colOrder.map(k => h('col', {key:k, style:{width: colWidths[k]}}))
  );
  const handles = () => phone ? [] : colOrder.slice(0, -1).map(k => overlayHandle(k));

  return { colWidths, displayWidths: colWidths, tableWrapRef, overlayHandle, colOrder, colgroup, handles, th };
}
// Back-compat alias — call sites migrated to useTableColumns, kept so any
// stragglers fail loudly in review rather than silently at runtime.
const useResizableColumns = useTableColumns;

/* ─── Item table ─────────────────────────────────────────────── */
const DEFAULT_COL_WIDTHS = {name:340, high:110, gapPct:90, spread:110, change_1d:110, volume:140, signals:160, star:30};
const ITEM_TABLE_VISIBLE = ['name','high','change_1d','volume','signals','star'];
const ITEM_TABLE_VISIBLE_NO_SIGNALS = ITEM_TABLE_VISIBLE.filter(k => k !== 'signals');
// Same gap% math as the backend's OVERPRICED/UNDERPRICED check and the
// Opportunities tab's dedicated tables — recomputed client-side so this
// column can sort by exact magnitude, not persisted on the item.
function itemGapPct(it) {
  const ge = it.high || it.low || 0;
  const liveRef = (it.liveBuy != null && it.liveSell != null) ? (it.liveBuy + it.liveSell) / 2 : (it.liveBuy ?? it.liveSell);
  if (!ge || !liveRef) return 0;
  return ((ge - liveRef) / liveRef) * 100;
}
// Same math as the backend's WIDE_SPREAD check (run.js) — instabuy minus
// instasell, as both a flat gp amount and a % of instasell. Ben: the
// WIDE_SPREAD drill-down showed B:/S: prices but made you do the
// subtraction yourself to see the actual spread that triggered the flag.
function itemSpreadGp(it) {
  if (it.liveBuy == null || it.liveSell == null) return 0;
  return it.liveBuy - it.liveSell;
}
function itemSpreadPct(it) {
  if (it.liveBuy == null || it.liveSell == null || !it.liveSell) return 0;
  return (itemSpreadGp(it) / it.liveSell) * 100;
}
// Mirrors run.js's isLiveTrusted (same constants) — the liquidity gate
// still applies no matter what % threshold the user picks below, since it
// exists to filter out single-fluke-trade noise, not to control
// selectivity. Only the % cutoff itself is user-adjustable.
const LIVE_LIQUID_MIN_UNITS = 3, LIVE_LIQUID_MIN_TURNOVER_GP = 25000, LIVE_SANITY_BAND = 5, LIVE_PRICE_EXEMPT_GP = 1000000;
function isLiveTrustedClient(it, ge) {
  if (ge >= LIVE_PRICE_EXEMPT_GP) return true;
  const liveRef = (it.liveBuy != null && it.liveSell != null) ? (it.liveBuy + it.liveSell) / 2 : (it.liveBuy ?? it.liveSell);
  if (!liveRef || liveRef <= 0) return false;
  if ((it.liveUnits || 0) >= LIVE_LIQUID_MIN_UNITS && (it.liveTurnover || 0) >= LIVE_LIQUID_MIN_TURNOVER_GP) return true;
  const ratio = Math.max(ge, liveRef) / Math.min(ge, liveRef);
  return ratio <= LIVE_SANITY_BAND;
}
const DISCREPANCY_MIN_GP = 1000; // same absolute-gp floor as the backend, not user-adjustable
function overpricedUnderpricedLists(items, thresholdPct) {
  const overpriced = [], underpriced = [];
  for (const it of items) {
    const ge = it.high || it.low || 0;
    if (!ge) continue;
    if (it.liveBuy == null && it.liveSell == null) continue;
    if (!isLiveTrustedClient(it, ge)) continue;
    const liveRef = (it.liveBuy != null && it.liveSell != null) ? (it.liveBuy + it.liveSell) / 2 : (it.liveBuy ?? it.liveSell);
    if (!liveRef || liveRef <= 0) continue;
    const gapGp = Math.abs(ge - liveRef);
    if (gapGp < DISCREPANCY_MIN_GP) continue;
    const pct = itemGapPct(it);
    if (pct >= thresholdPct) overpriced.push(it);
    else if (pct <= -thresholdPct) underpriced.push(it);
  }
  overpriced.sort((a,b) => itemGapPct(b) - itemGapPct(a));
  underpriced.sort((a,b) => itemGapPct(a) - itemGapPct(b));
  return {overpriced, underpriced};
}

// Native `position: sticky` on <thead>/<th> renders reliably broken in this
// Electron/Chromium build — verified extensively (per-cell sticky, whole-
// thead sticky, opaque backgrounds, taller padding, will-change, paint
// containment/isolation all still left stale row pixels ghosting through
// the header on scroll, confirmed live on the user's own screen, not just
// a screenshot-tool artifact). This hook drives a JS-synced clone instead:
// track the real thead's viewport position and, once it would scroll above
// the nearest `.content` scroll container's top edge, render a fixed-
// position clone (see ItemTable's render) that tracks the real header's
// left/width/top via getBoundingClientRect on every scroll/resize tick.
// Long explanation paragraphs: on a phone, show 3 lines plus a More/Less
// toggle (only when the text actually runs past 3 lines) so the table
// below isn't pushed off-screen. Desktop renders the plain div as before.
// Phones have no hover, so title= tooltips were unreachable. Tapping an
// element whose tooltip IS its purpose (no click action of its own: "?"
// icons, labels, badges) shows the text; long-pressing anything with a
// tooltip (buttons included) shows it without triggering the button.
function TouchTooltips() {
  const [tip, setTip] = useState(null); // {text, x, y}
  useEffect(() => {
    let timer = null, longFired = false;
    const titled = el => el && el.closest && el.closest('[title]');
    // React click handlers aren't visible on the element, so a pointer
    // cursor is the tell for clickable divs/cards.
    const interactive = el => !!(el.closest('button, a, input, select, textarea, label, [role=button], tr, .nav-btn') || getComputedStyle(el).cursor === 'pointer');
    const show = (el, x, y) => setTip({text: el.getAttribute('title'), x, y});
    const onStart = e => {
      longFired = false;
      const el = titled(e.target); if (!el) return;
      const t = e.touches[0];
      timer = setTimeout(() => { longFired = true; show(el, t.clientX, t.clientY); }, 500);
    };
    const cancel = () => clearTimeout(timer);
    const onClick = e => {
      if (longFired) { e.preventDefault(); e.stopPropagation(); longFired = false; return; }
      const el = titled(e.target);
      if (el && !interactive(e.target)) { show(el, e.clientX, e.clientY); return; }
      setTip(null);
    };
    document.addEventListener('touchstart', onStart, {passive: true});
    document.addEventListener('touchend', cancel);
    document.addEventListener('touchmove', cancel, {passive: true});
    document.addEventListener('click', onClick, true);
    return () => {
      document.removeEventListener('touchstart', onStart);
      document.removeEventListener('touchend', cancel);
      document.removeEventListener('touchmove', cancel);
      document.removeEventListener('click', onClick, true);
    };
  }, []);
  if (!tip || !tip.text) return null;
  const top = tip.y > window.innerHeight / 2 ? null : tip.y + 16;
  const bottom = top == null ? window.innerHeight - tip.y + 16 : null;
  return createPortal(h('div', {
    onClick: () => setTip(null),
    style:{position:'fixed', left:12, right:12, top, bottom, zIndex:1000, padding:'10px 12px',
      background:T.panel2, border:'1px solid '+T.borderGold, borderRadius:4, color:T.text,
      fontSize:12, lineHeight:1.5, boxShadow:'0 4px 16px rgba(0,0,0,0.7)', whiteSpace:'pre-line'},
  }, tip.text), document.body);
}

// Mobile only: how GEnius keeps checking prices while it isn't on screen
// (Ben, 2026-10-15: "let the user pick between the permanent notification
// or slower alerts").
function BackgroundModeSetting({toast}) {
  const [st, setSt] = useState(null);
  const [busy, setBusy] = useState(false);
  useEffect(() => { window.genius.getLiveMonitoring().then(setSt).catch(() => setSt({enabled:false})); }, []);
  const choose = async on => {
    setBusy(true);
    try { setSt(await window.genius.setLiveMonitoring(on)); }
    catch (e) { toast("Couldn't change background mode: " + e.message, 'error'); }
    setBusy(false);
  };
  const opt = (on, title, desc) => h('label', {className:'row', style:{gap:8, cursor:'pointer', alignItems:'flex-start', marginBottom:8, opacity: busy ? 0.6 : 1}},
    h('input', {type:'radio', name:'bgmode', checked: !!(st && st.enabled) === on, disabled: busy || !st, onChange: () => choose(on), style:{marginTop:3}}),
    h('div', null, h('div', null, title), h('div', {style:{fontSize:11, color:T.textDim, lineHeight:1.5}}, desc)));
  return h('div', {style:{marginBottom:20}},
    h('div', {className:'ge-section-head'}, 'Background checking'),
    opt(false, 'Battery saver (default)', 'Android checks your price alerts in the background whenever it allows, usually every 1 to 4 hours (longer with Battery Saver on). No permanent notification.'),
    opt(true, 'Live monitoring', 'GEnius keeps fetching on your normal schedule while it\'s closed, so alerts arrive within minutes. Shows a permanent notification; you can hide it in Android settings (GEnius → Notifications → Live monitoring) without muting alerts. Uses more battery. Swiping GEnius away from recent apps stops it.'),
    st && st.enabled && !st.running && h('div', {style:{fontSize:11, color:T.red}}, 'Live monitoring is on but not running. Try switching it off and on again.'));
}

// Mobile only (Ben, 2026-10-18): notifications during these hours still
// appear, but silently (no sound or vibration), without needing Do Not
// Disturb, which would also silence real emergencies.
function QuietHoursSetting() {
  const [q, setQ] = useState(null);
  useEffect(() => { window.genius.getQuietHours().then(setQ).catch(() => {}); }, []);
  const save = patch => { const next = {...q, ...patch}; setQ(next); window.genius.setQuietHours(patch).catch(() => {}); };
  if (!q) return null;
  const timeInput = key => h('input', {type:'time', className:'ge-input', value:q[key], disabled:!q.enabled,
    onChange: e => e.target.value && save({[key]: e.target.value}), style:{width:110}});
  return h('div', {style:{marginBottom:20}},
    h('div', {className:'ge-section-head'}, 'Quiet hours'),
    h('label', {className:'row', style:{gap:8, cursor:'pointer', marginBottom:8}},
      h('input', {type:'checkbox', checked:!!q.enabled, onChange: e => save({enabled: e.target.checked})}),
      h('span', null, 'Silence GEnius notifications overnight')),
    h('div', {style:{display:'flex', alignItems:'center', gap:8, flexWrap:'wrap', opacity: q.enabled ? 1 : 0.5}},
      h('span', {style:{fontSize:12, color:T.textDim}}, 'From'), timeInput('start'),
      h('span', {style:{fontSize:12, color:T.textDim}}, 'to'), timeInput('end')),
    h('div', {style:{fontSize:11, color:T.textDim, marginTop:6, lineHeight:1.5}},
      'Alerts and digests still arrive and show in your notifications, just without sound or vibration. Only affects GEnius, so calls and other apps still get through.'));
}

function PhoneFold({style, children}) {
  const [open, setOpen] = useState(false);
  const [long, setLong] = useState(false);
  const ref = useRef(null);
  useEffect(() => { const el = ref.current; if (el) setLong(el.scrollHeight > el.clientHeight + 2); });
  if (!IS_PHONE) return h('div', {style}, children);
  return h('div', {style, onClick: () => (long || open) && setOpen(o => !o)},
    h('div', {ref, style: open ? null : {display:'-webkit-box', WebkitLineClamp:3, WebkitBoxOrient:'vertical', overflow:'hidden'}}, children),
    (long || open) && h('div', {style:{color:T.gold, fontSize:11, marginTop:3, cursor:'pointer'}}, open ? 'Show less ▴' : 'More ▾'));
}

function useStickyTableHeader(wrapRef, theadRef) {
  const [state, setState] = useState({pinned:false, top:0, left:0, width:0});
  useEffect(() => {
    const wrap = wrapRef.current;
    const thead = theadRef.current;
    if (!wrap || !thead) return;
    const scrollEl = wrap.closest('.content');
    if (!scrollEl) return;
    let raf = null;
    const update = () => {
      raf = null;
      const contentRect = scrollEl.getBoundingClientRect();
      const theadRect = thead.getBoundingClientRect();
      const wrapRect = wrap.getBoundingClientRect();
      const pinned = theadRect.top < contentRect.top;
      setState(s => (s.pinned===pinned && s.top===contentRect.top && s.left===wrapRect.left && s.width===wrapRect.width)
        ? s : {pinned, top:contentRect.top, left:wrapRect.left, width:wrapRect.width});
    };
    const onScroll = () => { if (raf==null) raf = requestAnimationFrame(update); };
    update();
    scrollEl.addEventListener('scroll', onScroll, {passive:true});
    window.addEventListener('resize', onScroll);
    return () => {
      scrollEl.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      if (raf!=null) cancelAnimationFrame(raf);
    };
  }, [wrapRef, theadRef]);
  return state;
}

function ItemTable({items, selected, onSelect, watchlist = [], onToggleWatch = () => {}, onToggleHide, onAddCompare, description, showSignals, showGapPct, showSpread}) {
  // watchlist/onToggleWatch are read unconditionally below (star column
  // renders for every row, no matter the call site) — Opportunities'
  // signal-filtered table called this without passing either, so
  // watchlist.includes(...) threw on the very first row and crashed the
  // whole render with no error boundary to catch it (reported as "blank
  // page with no way to get back"). Defaulting here means a call site
  // that forgets these props degrades to an inert star instead of a
  // crash, regardless of which tab calls it next.
  const [sort, setSort] = useState({key: showGapPct ? 'gapPct' : showSpread ? 'spread' : 'name', dir: (showGapPct || showSpread) ? -1 : 1});
  const [ctxMenu, setCtxMenu] = useState(null); // {x, y, item}
  const visibleCols = useMemo(() => {
    const base = showSignals ? ITEM_TABLE_VISIBLE : ITEM_TABLE_VISIBLE_NO_SIGNALS;
    if (!showGapPct && !showSpread) return base;
    const i = base.indexOf('high');
    const extra = showGapPct ? 'gapPct' : 'spread';
    return [...base.slice(0, i+1), extra, ...base.slice(i+1)];
  }, [showSignals, showGapPct, showSpread]);
  const cols = useTableColumns('genius_col_widths', DEFAULT_COL_WIDTHS, visibleCols,
    ['name', 'high', showGapPct ? 'gapPct' : showSpread ? 'spread' : 'change_1d']);
  const theadRef = useRef(null);
  // cols.tableWrapRef is a callback ref (useCallback), not a useRef object —
  // it has no .current to read, so the sticky-header hook needs its own
  // real ref on the same DOM node, merged in via setWrapRefs below.
  const wrapRef = useRef(null);
  const setWrapRefs = node => { wrapRef.current = node; cols.tableWrapRef(node); };
  const stickyHeader = useStickyTableHeader(wrapRef, theadRef);

  const openCtx = (e, it) => {
    e.preventDefault();
    e.stopPropagation();
    const x = Math.min(e.clientX, window.innerWidth  - 180);
    const y = Math.min(e.clientY, window.innerHeight - 160);
    setCtxMenu({x, y, item: it});
  };
  const closeCtx = () => setCtxMenu(null);

  const [multiSelect, setMultiSelect] = useState(new Set());
  const toggleMulti = (id) => setMultiSelect(prev => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });
  const clearMulti = () => setMultiSelect(new Set());

  useEffect(() => {
    // preventDefault() here (even though Escape has no real default browser
    // action to prevent) is what lets the Android back-button handler in
    // bridge.js tell whether this consumed the back press, via its
    // dispatchEvent() return value — see that file's comment.
    const onKey = e => { if (e.key === 'Escape' && multiSelect.size) { e.preventDefault(); clearMulti(); } };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [multiSelect]);

  const [minPrice, setMinPrice] = useState(0);
  const [customVal, setCustomVal] = useState('');
  const [showCustom, setShowCustom] = useState(false);

  const isLarge = items.length > 300;
  const FILTER_OPTIONS = [
    {label:'All',   value:0},
    {label:'1K+',   value:1000},
    {label:'10K+',  value:10000},
    {label:'100K+', value:100000},
    {label:'1M+',   value:1000000},
    {label:'Custom',value:'custom'},
  ];

  const handleFilterClick = opt => {
    if (opt.value === 'custom') {
      setShowCustom(true);
    } else {
      setShowCustom(false);
      setCustomVal('');
      setMinPrice(opt.value);
    }
  };

  const handleCustomApply = () => {
    const parsed = parseGP(customVal);
    if (typeof parsed === 'number' && parsed > 0) setMinPrice(parsed);
  };

  const activeFilter = showCustom ? 'custom' : minPrice;

  const filtered = useMemo(() => {
    if (!minPrice) return items;
    return items.filter(it => (it.high || it.low || 0) >= minPrice);
  }, [items, minPrice]);

  // Which number is bold/primary in the Price column — GE (gazbot dump,
  // the "official" listed price) or Live (real instant-buy/sell). Shared
  // across every table via localStorage, same pattern as the Detail
  // Panel's fullPrice toggle, rather than resetting per-tab. Declared here
  // (moved up from further below) because the sort logic right after this
  // needs it too — referencing priceMode before this existed threw a
  // "Cannot access before initialization" TDZ error on every render,
  // crashing any tab that uses ItemTable (Cosmetics, Melee, Magic, etc,
  // not just Market) to a blank screen. Confirmed for real (Ben,
  // 2026-07-29): reproduced by switching to the Cosmetics tab.
  const [priceMode, setPriceMode] = useState(() => {
    try { return localStorage.getItem('genius_price_col_mode') === 'live' ? 'live' : 'ge'; } catch { return 'ge'; }
  });
  const togglePriceMode = e => {
    e.stopPropagation(); // don't also trigger the column sort click
    setPriceMode(m => {
      const next = m === 'ge' ? 'live' : 'ge';
      try { localStorage.setItem('genius_price_col_mode', next); } catch {}
      return next;
    });
  };

  // The "high" column shows either the GE dump price or live buy/sell,
  // whichever priceMode is active (see the header/cell rendering below) —
  // sorting has to follow the SAME value that's actually on screen, or a
  // "Live Price ↓" sort silently orders by the GE price instead. Confirmed
  // for real (Ben, 2026-07-29): Snowball Pet Token (live ~381M) sorted
  // above Aurora Trail aura override token (live ~1.3B) because Snowball's
  // GE-dump price happened to be higher, even though the column was
  // showing and labeled "Live Price."
  const sortValue = (it, key) => {
    if (key === 'high' && priceMode === 'live') return it.liveBuy ?? it.liveSell ?? it.high ?? it.low ?? 0;
    if (key === 'gapPct') return itemGapPct(it);
    if (key === 'spread') return itemSpreadPct(it);
    return it[key] ?? 0;
  };
  const sorted = useMemo(() => {
    return [...filtered].sort((a,b) => {
      const av=sortValue(a,sort.key), bv=sortValue(b,sort.key);
      return typeof av==='string' ? av.localeCompare(bv)*sort.dir : (av-bv)*sort.dir;
    });
  }, [filtered, sort, priceMode]);

  const tog = key => setSort(s=>({key,dir:s.key===key?-s.dir:1}));
  const arr = key => sort.key===key?(sort.dir>0?' ↑':' ↓'):'';
  if (!items.length) return h('div',{className:'empty'},h('div',{className:'icon'},'◎'),h('p',null,'No items in this category yet.'));
  const thFor = k => {
    switch (k) {
      case 'name':      return cols.th(k, {onClick:()=>tog('name')}, 'Item'+arr('name'));
      case 'high':      return cols.th(k, {onClick:()=>tog('high')},
        (priceMode==='ge' ? 'GE Price' : 'Live Price')+arr('high'),
        h('button', {
          onClick: togglePriceMode,
          title: priceMode==='ge' ? 'Showing GE (listed) price — click to show live buy/sell instead' : 'Showing live buy/sell — click to show GE (listed) price instead',
          style: {marginLeft:6, fontSize:9, padding:'1px 5px', cursor:'pointer', borderRadius:3, border:`1px solid ${T.border}`, background:T.panel, color:T.textDim, textTransform:'none', letterSpacing:0, fontWeight:'normal'}
        }, '⇄')
      );
      case 'change_1d': return cols.th(k, {onClick:()=>tog('change_1d')}, 'Change'+arr('change_1d'));
      case 'volume':    return cols.th(k, {onClick:()=>tog('volume')}, 'Volume'+arr('volume'));
      case 'signals':   return cols.th(k, null, 'Signals');
      case 'star':      return cols.th(k, {style:{width:30}}, null);
      case 'gapPct':    return cols.th(k, {onClick:()=>tog('gapPct')}, 'Gap %'+arr('gapPct'));
      case 'spread':    return cols.th(k, {onClick:()=>tog('spread')}, 'Spread'+arr('spread'));
      default:          return cols.th(k, null, null);
    }
  };
  const tdFor = (k, it) => {
    switch (k) {
      case 'name': return h('td', {key:k}, h('div',{style:{display:'flex', alignItems:'center', justifyContent:'space-between'}},
        h('span',null, it.name),
        SHOW_THUMBNAILS && h(ItemThumb,{name:it.name}),
      ));
      case 'gapPct': {
        const g = itemGapPct(it);
        return h('td', {key:k, style:{color: g >= 0 ? '#ef9a9a' : '#81c784'}}, (g >= 0 ? '+' : '') + g.toFixed(1) + '%');
      }
      case 'spread': {
        if (it.liveBuy == null || it.liveSell == null) return h('td', {key:k, style:{color:T.textDim}}, '—');
        return h('td', {key:k, style:{color:'#bdbdbd'}},
          fmt.gp(itemSpreadGp(it))+'gp',
          h('div',{className:'vol-avg'}, itemSpreadPct(it).toFixed(1)+'%')
        );
      }
      case 'high': {
        const hasLive = it.liveBuy != null || it.liveSell != null;
        if (priceMode === 'live' && hasLive) {
          return h('td', {key:k},
            h('div', {style:{display:'flex', gap:6, fontSize:11}},
              it.liveBuy  != null && h('span', null, h('span',{style:{color:T.green}},'B '), fmt.gp(it.liveBuy)+'gp'),
              it.liveSell != null && h('span', null, h('span',{style:{color:'#e08030'}},'S '), fmt.gp(it.liveSell)+'gp'),
            ),
            h('div', {className:'vol-avg'}, 'GE '+fmt.gp(it.high||it.low)+'gp'),
          );
        }
        return h('td', {key:k, style:{color:T.gold}}, fmt.gp(it.high||it.low)+'gp',
          h(LivePriceLine, {liveBuy:it.liveBuy, liveSell:it.liveSell}));
      }
      case 'change_1d': return h('td', {key:k}, h(ChangeDisplay,{change_1d:it.change_1d, price:it.high||it.low}));
      case 'volume': return h('td', {key:k}, h(VolDisplay,{volume:it.volume, avgVolume:it.avgVolume}));
      case 'signals': return h('td', {key:k}, h('div',{style:{display:'flex',flexWrap:'wrap',gap:3}},
        (it.signals||[]).map(s=>h(SignalBadge,{key:s,signal:s}))
      ));
      case 'star': return h('td', {key:k, onClick:e=>{e.stopPropagation(); onToggleWatch(it.id);}, style:{textAlign:'center',padding:'6px 6px'}},
        h('button',{className:'star-btn'},
          h('span',{className:watchlist.includes(it.id)?'star-on':'star-off'}, watchlist.includes(it.id)?'★':'☆')
        )
      );
      default: return h('td', {key:k}, null);
    }
  };

  return h('div',{className:'ge-table-wrap', style:{position:'relative'}, ref:setWrapRefs, onClick: ctxMenu ? closeCtx : undefined},
    stickyHeader.pinned && createPortal(
      h('div', {className:'ge-sticky-header-clone', style:{top:stickyHeader.top, left:stickyHeader.left, width:stickyHeader.width}},
        h('table',{className:'ge-table', style:{tableLayout:'fixed', width:'max-content'}},
          cols.colgroup(),
          h('thead',null,h('tr',null, cols.colOrder.map(k => thFor(k))))
        )
      ),
      document.body
    ),
    cols.handles(),
    ctxMenu && createPortal(h('div', {
      style:{
        position:'fixed', zIndex:9999, left:ctxMenu.x, top:ctxMenu.y,
        background:T.panel2, border:`1px solid ${T.borderGold}`, borderRadius:4,
        minWidth:170, boxShadow:'0 4px 16px rgba(0,0,0,0.6)', overflow:'hidden',
      },
      onClick: e => e.stopPropagation(),
    },
      [
        {
          label: watchlist.includes(ctxMenu.item.id) ? '★ Unwatch' : '☆ Watch',
          action: () => { onToggleWatch(ctxMenu.item.id); closeCtx(); },
          color: T.gold,
        },
        {
          label: '📋 Copy price',
          action: () => {
            const price = ctxMenu.item.high || ctxMenu.item.low;
            navigator.clipboard?.writeText(String(price));
            closeCtx();
          },
        },
        {
          label: '🔗 Open on wiki',
          action: () => {
            const slug = ctxMenu.item.name.replace(/ /g, '_');
            window.genius?.openExternal(`https://runescape.wiki/w/${encodeURIComponent(slug)}`);
            closeCtx();
          },
        },
        {
          label: '⇌ Add to compare',
          action: () => { onAddCompare && onAddCompare(ctxMenu.item); closeCtx(); },
        },
        {
          label: '🚫 Hide item',
          action: () => { onToggleHide && onToggleHide(ctxMenu.item.id); closeCtx(); },
          color: T.textDim,
        },
      ].map((opt, i) => h('div', {
        key: i,
        onClick: opt.action,
        style:{
          padding:'8px 14px', cursor:'pointer', fontSize:13,
          color: opt.color || T.text,
          borderBottom: i < 3 ? `1px solid ${T.borderDim}` : 'none',
        },
        onMouseEnter: e => e.currentTarget.style.background = T.panel,
        onMouseLeave: e => e.currentTarget.style.background = 'transparent',
      }, opt.label))
    ), document.body),
    description && h('div',{style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, description),
    h('div',{style:{display:'flex', alignItems:'center', gap:8, padding:'6px 10px', borderBottom:`1px solid ${T.border}`, fontSize:11, flexWrap:'wrap'}},
      h('span',{style:{color:T.textDim}}, `${sorted.length}${minPrice?` of ${items.length}`:''} items`),
      isLarge && h('span',{style:{color:T.textDim, marginLeft:'auto'}}, 'Min price:'),
      isLarge && FILTER_OPTIONS.map(opt =>
        h('button',{
          key: opt.value,
          onClick: () => handleFilterClick(opt),
          style:{
            padding:'2px 8px', fontSize:10, cursor:'pointer', borderRadius:3,
            background: activeFilter===opt.value ? 'rgba(201,168,76,0.2)' : 'transparent',
            border: `1px solid ${activeFilter===opt.value ? T.gold : T.border}`,
            color: activeFilter===opt.value ? T.goldBright : T.textDim,
          }
        }, opt.label)
      ),
      isLarge && showCustom && h('div',{style:{display:'flex', gap:4, alignItems:'center'}},
        h('input',{
          className:'ge-input',
          style:{width:90, padding:'2px 6px', fontSize:11},
          placeholder:'e.g. 500k',
          value:customVal,
          onChange:e=>setCustomVal(e.target.value),
          onKeyDown:e=>e.key==='Enter'&&handleCustomApply(),
          autoFocus:true,
        }),
        h('button',{
          className:'ge-btn',
          style:{padding:'2px 8px', fontSize:10},
          onClick:handleCustomApply
        },'Apply')
      )
    ),
    multiSelect.size > 0 && h('div', {style:{
      display:'flex', alignItems:'center', gap:8, padding:'6px 12px',
      background:T.panel2, borderBottom:`1px solid ${T.borderGold}`,
      fontSize:12,
    }},
      h('span',{style:{color:T.gold, fontWeight:'bold'}}, `${multiSelect.size} selected`),
      h('button',{className:'ge-btn',style:{padding:'2px 10px',fontSize:11},
        onClick:()=>{ onToggleHide&&onToggleHide([...multiSelect]); clearMulti(); }
      }, '🚫 Hide all'),
      h('button',{className:'ge-btn',style:{padding:'2px 10px',fontSize:11},
        onClick:()=>{ multiSelect.forEach(id=>onToggleWatch(id)); clearMulti(); }
      }, '★ Watch all'),
      onAddCompare && h('button',{className:'ge-btn',style:{padding:'2px 10px',fontSize:11},
        onClick:()=>{
          sorted.filter(it=>multiSelect.has(it.id)).slice(0,4).forEach(it=>onAddCompare(it));
          clearMulti();
        }
      }, '⇌ Compare all'),
      h('button',{className:'ge-btn',style:{padding:'2px 10px',fontSize:11},onClick:clearMulti},'✕ Clear')
    ),
    h('table',{className:'ge-table', style:{tableLayout:'fixed', width:'max-content'}},
      cols.colgroup(),
      h('thead',{ref:theadRef},h('tr',null, cols.colOrder.map(k => thFor(k)))),
      h('tbody',null, sorted.map(it =>
        h('tr',{
          key:it.id, 'data-item-id':it.id,
          className: multiSelect.has(it.id) ? 'selected multi-selected' : selected?.id===it.id ? 'selected' : '',
          onClick: e => {
            if (e.ctrlKey || e.metaKey) { e.preventDefault(); toggleMulti(it.id); }
            else { clearMulti(); onSelect(it); }
          },
          onContextMenu: e => openCtx(e, it),
        }, cols.colOrder.map(k => tdFor(k, it)))
      ))
    )
  );
}

// Module-level, not nested inside DashboardTab — it used to be defined
// inside DashboardTab's render body, which meant React saw a brand-new
// component type every time DashboardTab re-rendered (e.g. on a routine
// data refresh) and force-unmounted/remounted every card, wiping its
// `pos` (tooltip position) state mid-hover. That's what made the
// tooltip seem to randomly snap shut almost immediately — nothing
// wrong with the hover logic itself, the component just kept getting
// thrown away underneath it.
function SectorCard({sector, onClick}) {
  const [pos, setPos] = useState(null);
  const {score, label, emoji, count, surge, dump, frenzy, active, avgChg} = sector;
  const heat = score >= 72 ? {color:'#ff6b35', label:'🔥 Hot'}
             : score >= 55 ? {color:'#ffd700', label:'🟡 Warm'}
             : score >= 40 ? {color:T.green,   label:'🟢 Active'}
             : score >= 25 ? {color:T.textDim,  label:'⬜ Quiet'}
             :               {color:T.red,      label:'🔴 Cold'};
  const tip = [
    `${count} ${count === 1 ? 'item' : 'items'} tracked`,
    active != null ? `${active} with price movement today` : null,
    surge  ? `${surge} surging`  : null,
    dump   ? `${dump} dumping`   : null,
    frenzy ? `${frenzy} in frenzy` : null,
    avgChg != null ? `Avg change: ${avgChg >= 0 ? '+' : ''}${avgChg.toFixed(2)}%` : null,
    `Heat score reflects price momentum, opportunity scores, and signal activity across all items in this sector.`,
  ].filter(Boolean).join(' · ');

  return h('div', {
    onClick,
    style:{
      background:T.panel, border:`1px solid ${T.border}`, borderRadius:4,
      padding:'8px 10px', flex:'1 1 130px', minWidth:130,
      cursor:'pointer', position:'relative',
      borderLeft:`3px solid ${heat.color}`,
      transition:'border-color 0.15s',
    },
    onMouseEnter: e => e.currentTarget.style.borderColor = heat.color,
    onMouseLeave: e => { e.currentTarget.style.borderColor = T.border; setPos(null); },
    onMouseMove: e => setPos({x: e.clientX, y: e.clientY}),
  },
    h('div', {style:{display:'flex', alignItems:'center', gap:5, marginBottom:4}},
      h('span', {style:{fontSize:14}}, emoji),
      h('span', {style:{fontSize:11, fontWeight:'bold', color:T.textBright}}, label),
    ),
    h('div', {style:{fontSize:10, color:heat.color}}, heat.label),
    pos && createPortal(h('div', {style:{
      position:'fixed', left: Math.min(pos.x + 12, window.innerWidth - 260), zIndex:9999,
      top: pos.y + 16 + 120 > window.innerHeight ? pos.y - 120 : pos.y + 16,
      background:T.panel2, border:`1px solid ${T.border}`, borderRadius:4,
      padding:'8px 10px', fontSize:11, color:T.textDim, maxWidth:250, lineHeight:1.6,
      pointerEvents:'none', boxShadow:'0 4px 16px rgba(0,0,0,0.6)',
    }},
      h('div', {style:{color:T.textBright, fontWeight:'bold', marginBottom:4}}, `${emoji} ${label}`),
      tip
    ), document.body)
  );
}

/* ─── Dashboard tab ──────────────────────────────────────────── */
const TOP_MOVERS_WINDOWS = [
  {days:7,   label:'Last 7 Days'},
  {days:30,  label:'Last Month'},
  {days:90,  label:'Last 3 Months'},
  {days:180, label:'Last 6 Months'},
];
const TOP_MOVERS_PILLS = [
  {key:'ge_rise',   label:'GE Market ↑', source:'ge',   dir:'rise'},
  {key:'ge_fall',   label:'GE Market ↓', source:'ge',   dir:'fall'},
  {key:'live_rise', label:'Live Trade ↑', source:'live', dir:'rise'},
  {key:'live_fall', label:'Live Trade ↓', source:'live', dir:'fall'},
];

// Inline expandable Dashboard section, not a modal — Ben: "there's no
// reason to make anyone change to a new page ... we could just scroll
// down their normal page." Two genuinely different data sources shown
// side by side: Jagex's own official GE Top 100 (their listed price,
// averaged over the period, capped by their own daily-change rules) vs.
// GEnius's own real-time equivalent (live instant buy/sell right now vs.
// a real history point N days back) — the two lists are expected to
// differ, sometimes a lot, since one is measuring a slow official number
// and the other measures what's actually fillable right now.
// Jagex's own price columns ("1,580", "606", "3.4m", "52.4k") into a plain
// number, so the GP Change column can be sorted numerically instead of
// only ever showing Jagex's own default (percentage) order.
function parseGpString(str) {
  if (str == null) return 0;
  const s = String(str).replace(/,/g, '').trim();
  const m = s.match(/^([\d.]+)\s*([kmb])?$/i);
  if (!m) return parseFloat(s) || 0;
  const n = parseFloat(m[1]);
  const mult = {k:1e3, m:1e6, b:1e9}[m[2]?.toLowerCase()] || 1;
  return n * mult;
}

// Compact Dashboard teaser (Ben, 2026-08-13): the full accordion moved to
// its own tab (TopMoversTab) since it was capped at 30/100 rows and buried
// behind a click — undersold a feature Ben wants prominent. This keeps a
// quick glance on the Dashboard (top 5 GE Market risers) with a link to
// the real thing, same pattern as the Watchlist/Portfolio teaser cards.
function TopMoversSection({items, officialTop100, onSelect, onNavigate}) {
  const itemById = useMemo(() => {
    const m = new Map();
    for (const it of items) if (it.id != null) m.set(it.id, it);
    return m;
  }, [items]);

  const topRises = useMemo(() => {
    const win = officialTop100?.byWindow?.[7];
    return (win?.rises || []).slice(0, 5);
  }, [officialTop100]);

  return h('div', {style:{marginBottom:20}},
    h('div', {style:{fontSize:11, fontWeight:'bold', letterSpacing:'0.08em', textTransform:'uppercase', color:T.textDim, borderBottom:`1px solid ${T.borderDim}`, paddingBottom:4, marginBottom:10, cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'space-between'}, onClick:()=>onNavigate&&onNavigate('top_movers'), title:'Go to Top Movers'},
      h('span', null, '🏆 Top Movers'),
      h('span', {style:{fontSize:11, color:T.gold, fontWeight:'normal'}}, 'View all →')),
    topRises.length === 0
      ? h('div', {style:{fontSize:12, color:T.textDim, padding:'8px 0'}}, 'No data available yet.')
      : topRises.map(r => {
          const it = itemById.get(r.id);
          return h('div', {
            key:r.id, className:'row', style:{justifyContent:'space-between', padding:'4px 0', cursor: it?'pointer':'default', borderBottom:`1px solid ${T.borderDim}`},
            onClick:()=>it && onSelect(it),
          },
            h('span', {style:{color: it ? T.textBright : T.textDim, fontSize:12}}, r.name),
            h('span', {style:{color:T.green, fontSize:12, fontWeight:'bold'}}, '+'+r.pct.toFixed(1)+'%'),
          );
        })
  );
}


// Full-page version of TopMoversSection (Ben, 2026-08-13): the Dashboard
// accordion was capped at 30 of the 100 rows even expanded, and buried
// behind a click — undersold a feature Ben specifically wants to put in
// front of people. This shows the real full 100, sortable, no cap.
function TopMoversTab({items, officialTop100, onSelect, watchlist, onToggleWatch, description}) {
  const [pill, setPill] = useState('ge_rise');
  const [windowDays, setWindowDays] = useState(7);
  const [liveCache, setLiveCache] = useState({});
  const [liveLoading, setLiveLoading] = useState(false);
  const [sort, setSort] = useState({key:'pct', dir:-1});
  const tog = key => setSort(s => ({key, dir: s.key===key ? -s.dir : (key==='name' ? 1 : -1)}));
  const arr = key => sort.key===key ? (sort.dir>0?' ▲':' ▼') : '';

  const pillDef = TOP_MOVERS_PILLS.find(p => p.key === pill);

  useEffect(() => {
    setSort({key:'pct', dir: pillDef.dir==='rise' ? -1 : 1});
  }, [pill]);

  useEffect(() => {
    if (pillDef.source !== 'live' || liveCache[windowDays]) return;
    setLiveLoading(true);
    window.genius?.getRealTimeMovers?.(windowDays)
      .then(res => { if (res) setLiveCache(c => ({...c, [windowDays]: res})); })
      .catch(() => {})
      .finally(() => setLiveLoading(false));
  }, [pillDef.source, windowDays]);

  const itemById = useMemo(() => {
    const m = new Map();
    for (const it of items) if (it.id != null) m.set(it.id, it);
    return m;
  }, [items]);

  let rows = [];
  if (pillDef.source === 'ge') {
    const win = officialTop100?.byWindow?.[windowDays];
    rows = (win ? (pillDef.dir === 'rise' ? win.rises : win.falls) : []).map(r => ({
      id: r.id, name: r.name, startDisplay: r.startPrice, endDisplay: r.endPrice, pct: r.pct,
      gpDisplay: r.gpChange != null ? (r.pct>=0?'+':'-')+r.gpChange+'gp' : '—',
      gpChangeRaw: (r.pct>=0?1:-1) * parseGpString(r.gpChange),
    }));
  } else {
    const win = liveCache[windowDays];
    rows = (win ? (pillDef.dir === 'rise' ? win.rises : win.falls) : []).map(r => ({
      id: r.id, name: r.name, startDisplay: fmt.gp(r.startPrice)+'gp', endDisplay: fmt.gp(r.currentPrice)+'gp', pct: r.pct,
      gpDisplay: (r.pct>=0?'+':'-')+fmt.gp(Math.abs(r.currentPrice-r.startPrice))+'gp',
      gpChangeRaw: r.currentPrice - r.startPrice,
    }));
  }
  rows = [...rows].sort((a,b) => {
    if (sort.key === 'name') return a.name.localeCompare(b.name) * sort.dir;
    const av = sort.key==='gp' ? a.gpChangeRaw : a.pct;
    const bv = sort.key==='gp' ? b.gpChangeRaw : b.pct;
    return (av - bv) * sort.dir;
  });

  return h('div', {style:{padding:'4px 0'}},
    description && h('div', {style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, description),
    h('div', {style:{padding:'14px'}},
      h('div', {style:{fontSize:11, color:T.textDim, fontStyle:'italic', marginBottom:12, lineHeight:1.4}},
        'GE Market is Jagex\'s own official Top 100, sourced straight from their site. Live Trade is GEnius\'s own version using real instant buy/sell instead of their slower official price — expect the two lists to differ.'
      ),
      h('div', {style:{display:'flex', gap:10, marginBottom:12, flexWrap:'wrap', alignItems:'center', justifyContent:'space-between'}},
        h('div', {className:'row', style:{gap:6, flexWrap:'wrap'}},
          TOP_MOVERS_PILLS.map(p => h('button', {
            key:p.key,
            className:'ge-btn'+(pill===p.key?' gold':''),
            style:{fontSize:11, padding:'4px 10px'},
            onClick:()=>setPill(p.key),
          }, p.label))
        ),
        h('div', {className:'row', style:{gap:6, flexWrap:'wrap'}},
          TOP_MOVERS_WINDOWS.map(w => h('button', {
            key:w.days,
            className:'ge-btn'+(windowDays===w.days?' gold':''),
            style:{fontSize:11, padding:'4px 10px'},
            onClick:()=>setWindowDays(w.days),
          }, w.label))
        ),
      ),
      pillDef.source==='live' && liveLoading && !liveCache[windowDays]
        ? h('div', {style:{padding:20, textAlign:'center', color:T.textDim, fontSize:12}}, 'Computing real-time movers from local price history…')
        : rows.length === 0
          ? h('div', {style:{padding:20, textAlign:'center', color:T.textDim, fontSize:12}}, 'No data for this period yet.')
          : h('div', {className:'ge-table-wrap'},
              h('table', {className:'ge-table pt-movers'},
                h('thead', null, h('tr', null,
                  h('th', {onClick:()=>tog('name'), style:{cursor:'pointer'}}, 'Item'+arr('name')), h('th', null, 'Start'), h('th', null, 'Now'),
                  h('th', {onClick:()=>tog('gp'), style:{cursor:'pointer'}}, 'GP Change'+arr('gp')), h('th', {onClick:()=>tog('pct'), style:{cursor:'pointer'}}, 'Change'+arr('pct')),
                  h('th', {style:{width:30}}, null),
                )),
                h('tbody', null, rows.map(r => {
                  const it = itemById.get(r.id);
                  return h('tr', {
                    key:r.id,
                    style:{cursor: it ? 'pointer' : 'default'},
                    onClick: () => it && onSelect(it),
                  },
                    h('td', null, h('div', {className:'row', style:{gap:6, alignItems:'center'}},
                      it && it.iconUrl && h('img', {src:it.iconUrl, style:{width:18,height:18,objectFit:'contain'}}),
                      h('span', {style:{color: it ? T.textBright : T.textDim}}, r.name),
                    )),
                    h('td', null, r.startDisplay),
                    h('td', null, r.endDisplay),
                    h('td', {style:{color: r.pct >= 0 ? T.green : T.red}}, r.gpDisplay),
                    h('td', {style:{color: r.pct >= 0 ? T.green : T.red, fontWeight:'bold'}}, (r.pct>=0?'+':'')+r.pct.toFixed(1)+'%'),
                    it && h('td', {onClick:e=>{e.stopPropagation(); onToggleWatch(it.id);}, style:{textAlign:'center'}},
                      h('button',{className:'star-btn'},
                        h('span',{className:watchlist.includes(it.id)?'star-on':'star-off'}, watchlist.includes(it.id)?'★':'☆')
                      )
                    ),
                  );
                }))
              )
            )
    )
  );
}

function DashboardTab({items, indexes, selected, onSelect, watchlist, onToggleWatch, onToggleHide, onAddCompare, description, alerts, portfolio, onNavigate, news, overpricedThreshold=30, officialTop100}) {
  const [activeSignal, setActiveSignal] = useState(null);
  const [activeIndexId, setActiveIndexId] = useState(null);
  const [activeSector, setActiveSector] = useState(null);
  const [newsExpanded, setNewsExpanded] = useState(true);
  const [expandedArticle, setExpandedArticle] = useState(null);
  const [signalTrend, setSignalTrend] = useState(null);
  const [signalWindow, setSignalWindow] = useState('today');
  useEffect(() => { setSignalWindow('today'); }, [activeSignal]);
  useEffect(() => {
    const limits = {};
    items.forEach(it => { if (it.id && it.limit) limits[it.id] = it.limit; });
    window.genius?.getSignalTrend?.(limits).then(setSignalTrend).catch(() => {});
  }, [items]);

  // Backspace backs out of a drill-down view (signal / index / sector)
  useEffect(() => {
    const onKey = e => {
      if (e.key !== 'Backspace') return;
      const tag = document.activeElement?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      if (document.activeElement?.isContentEditable) return;
      if (activeSignal) { e.preventDefault(); setActiveSignal(null); }
      else if (activeIndexId) { e.preventDefault(); setActiveIndexId(null); }
      else if (activeSector) { e.preventDefault(); setActiveSector(null); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [activeSignal, activeIndexId, activeSector]);
  const tradeableItems = useMemo(() => items.filter(it => !it.untradeable), [items]);

  const risers  = useMemo(() => [...tradeableItems].filter(it => (it.change_1d||0) > 0 && it.high > 1000)
    .sort((a,b) => (b.change_1d||0)-(a.change_1d||0)).slice(0,6), [tradeableItems]);
  const fallers = useMemo(() => [...tradeableItems].filter(it => (it.change_1d||0) < 0 && it.high > 1000)
    .sort((a,b) => (a.change_1d||0)-(b.change_1d||0)).slice(0,6), [tradeableItems]);
  const volume  = useMemo(() => [...tradeableItems]
    .filter(it => it.signals && (it.signals.includes('FRENZY') || it.signals.includes('HIGH_VOL')))
    .sort((a,b) => {
      const ra = a.volume && a.avgVolume ? a.volume/a.avgVolume : 0;
      const rb = b.volume && b.avgVolume ? b.volume/b.avgVolume : 0;
      return rb - ra;
    }).slice(0,6), [tradeableItems]);

  // OVERPRICED/UNDERPRICED are recomputed client-side against the user's
  // threshold setting (Settings > Overpriced/Underpriced threshold) rather
  // than read off the backend's fixed-20% signal tag — everywhere these
  // two show up (this pill count, the drill-down list, Hall of Shame/Glory
  // below) stays consistent with whatever the user has it set to.
  const {overpriced: opList, underpriced: upList} = useMemo(
    () => overpricedUnderpricedLists(tradeableItems, overpricedThreshold), [tradeableItems, overpricedThreshold]);

  const signalCounts = useMemo(() => {
    const counts = {SURGE:0,DUMP:0,ACCUMULATION:0,DISTRIBUTION:0,FRENZY:0,HIGH_VOL:0,MANIPULATED:0,OVERPRICED:0,UNDERPRICED:0,WIDE_SPREAD:0};
    for (const it of tradeableItems) {
      for (const s of (it.signals||[])) { if (s in counts && s !== 'OVERPRICED' && s !== 'UNDERPRICED') counts[s]++; }
    }
    counts.OVERPRICED = opList.length;
    counts.UNDERPRICED = upList.length;
    return counts;
  }, [tradeableItems, opList, upList]);

  const rising  = tradeableItems.filter(it => (it.change_1d||0) > 0).length;
  const falling = tradeableItems.filter(it => (it.change_1d||0) < 0).length;

  // Personal — watchlist movers
  const watchlistItems = useMemo(() => items.filter(it => watchlist.includes(it.id)), [items, watchlist]);
  const watchlistMovers = useMemo(() =>
    [...watchlistItems].filter(it => it.change_1d != null)
      .sort((a,b) => Math.abs(b.change_1d||0) - Math.abs(a.change_1d||0))
      .slice(0, 6),
  [watchlistItems]);

  // Personal — portfolio
  const positions = portfolio?.positions || [];
  const openPositions = positions.filter(p => p.status !== 'sold');
  const {totalInvested, totalCurrent, unrealizedPL, unrealizedPct} = useMemo(() => {
    let inv = 0, cur = 0;
    for (const pos of openPositions) {
      const it = items.find(i => i.name.toLowerCase() === (pos.item_name||'').toLowerCase());
      const price = liveSellOf(it) || 0;
      inv += pos.cost_basis * pos.quantity;
      cur += price * pos.quantity;
    }
    const pl = cur - inv;
    const pct = inv > 0 ? (pl / inv) * 100 : 0;
    return {totalInvested:inv, totalCurrent:cur, unrealizedPL:pl, unrealizedPct:pct};
  }, [openPositions, items]);

  // Personal — alerts
  const alertCount = (alerts||[]).length;
  const triggeredAlerts = useMemo(() => (alerts||[]).filter(a => {
    const it = items.find(i => i.name.toLowerCase() === (a.item_name||'').toLowerCase());
    if (!it) return false;
    const price = it.high || it.low || 0;
    if (a.condition === 'above') return price >= a.price;
    if (a.condition === 'below') return price <= a.price;
    if (a.condition === 'live_above' || a.condition === 'live_below') {
      const liveRef = it.liveBuy ?? it.liveSell;
      if (liveRef == null) return false;
      return a.condition === 'live_above' ? liveRef >= a.price : liveRef <= a.price;
    }
    if (a.condition === 'signal') return (it.signals||[]).includes(a.signal);
    return false;
  }), [alerts, items]);

  // Market stats — total GP traded, items tracked
  const marketStats = useMemo(() => {
    const totalGP = tradeableItems.reduce((s, it) => s + ((it.high || it.low || 0) * (it.volume || 0)), 0);
    const itemsTraded = tradeableItems.filter(it => (it.volume || 0) > 0).length;
    const itemsTracked = tradeableItems.length;
    return { totalGP, itemsTraded, itemsTracked };
  }, [tradeableItems]);

  // Item of the Day — seeded by date so it's the same for everyone all day
  const itemOfTheDay = useMemo(() => {
    const pool = tradeableItems.filter(it => it.high || it.low);
    if (!pool.length) return null;
    const today = new Date();
    const seed  = today.getFullYear() * 10000 + (today.getMonth()+1) * 100 + today.getDate();
    const idx   = seed % pool.length;
    return pool[idx];
  }, [tradeableItems]);

  // Mood of the Market
  const mood = useMemo(() => getMarketWeather(tradeableItems), [tradeableItems]);
  const [showWeatherLegend, setShowWeatherLegend] = useState(false);
  const [showHeatmapLegend, setShowHeatmapLegend] = useState(false);
  const [heatmapLegendPos, setHeatmapLegendPos] = useState(null);

  // Dismiss the Weather/Heatmap legend popovers on outside click or Escape —
  // neither had ANY way to close except the explicit X (Ben, 2026-07-16:
  // "small GUI thing... would be nice to not HAVE to X out"). Both popovers
  // already call e.stopPropagation() on clicks inside themselves, so a
  // plain document-level click listener only ever fires for genuine
  // outside clicks — no ref/portal-boundary bookkeeping needed.
  useEffect(() => {
    if (!showWeatherLegend && !showHeatmapLegend) return;
    const onClick = () => { setShowWeatherLegend(false); setShowHeatmapLegend(false); };
    const onKey = e => { if (e.key === 'Escape') { setShowWeatherLegend(false); setShowHeatmapLegend(false); } };
    document.addEventListener('click', onClick);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('click', onClick);
      document.removeEventListener('keydown', onKey);
    };
  }, [showWeatherLegend, showHeatmapLegend]);

  // Hall of Shame / Hall of Glory — split 2026-08-03 (Ben): "Most
  // Volatile" ranked purely by |change_1d|, so a huge PUMP scored
  // identically to a crash and landed it under "Shame" even though
  // booming in price is a good outcome for anyone holding it. Moved to
  // its own positive section (renamed "Wildest Ride" so "volatile"'s
  // risk-flavored connotation doesn't linger), paired with two new
  // genuinely-positive entries; Shame gets "Most Overpriced" in its
  // place — a real warning (GE-listed price sitting 20%+ above live),
  // not just a big number.
  // Ben, 2026-08-09: change_1d% alone stopped being a useful "how dramatic
  // was this" ranking once the stale-data bug got fixed — real daily
  // moves cluster tight against Jagex's own GE price-cap (checked
  // directly: 95th percentile 4.99%, 99th 5.19%, most items never clear
  // 5% at all), so "Biggest Crash" was just picking whichever item
  // happened to sit at that same ~5% ceiling, not anything actually
  // notable. Ranking by real gp lost/gained instead — a 5% move on a
  // 100M item is a real story, a 5% move on a 50gp item isn't, same
  // logic SURGE/DUMP's own absChgGp floor already uses.
  const gpChange = it => (it.change_1d||0) / 100 * (it.high || it.low || 0);
  // Ben, 2026-08-09: "for thoroughness" — show the live buy/sell-based
  // daily change alongside the GE-price one, since they can genuinely
  // diverge (that's the whole point of OVERPRICED/UNDERPRICED). null
  // until ~20h of live snapshots have accumulated for that item.
  const liveChangeStat = it => {
    if (it.change_1d_live == null) return null;
    // Same price basis run.js's computeLiveChange1d itself used (liveBuy,
    // falling back to GE price) — matches the % exactly instead of
    // guessing at a different reference point for the gp figure.
    const liveRefPrice = it.liveBuy ?? it.high ?? it.low ?? 0;
    const liveGpChange = it.change_1d_live / 100 * liveRefPrice;
    const sign = it.change_1d_live >= 0 ? '+' : '';
    return `Live: ${sign}${fmt.gp(liveGpChange)}gp (${sign}${it.change_1d_live.toFixed(2)}%)`;
  };
  const hallOfShame = useMemo(() => {
    const priced = tradeableItems.filter(it => (it.high || it.low) > 10000 && it.change_1d != null);
    const biggestCrash = [...priced].sort((a,b) => gpChange(a) - gpChange(b))[0];
    const biggestDump  = [...priced].filter(it => (it.signals||[]).includes('DUMP'))
      .sort((a,b) => {
        const ra = a.volume && a.avgVolume ? a.volume/a.avgVolume : 0;
        const rb = b.volume && b.avgVolume ? b.volume/b.avgVolume : 0;
        return rb - ra;
      })[0];
    const overpriced  = opList[0];
    const manipulated  = [...priced].filter(it => (it.signals||[]).includes('MANIPULATED'))
      .sort((a,b) => Math.abs(b.change_1d||0) - Math.abs(a.change_1d||0))[0];

    // 90th percentile of real gp swings among priced items (checked
    // directly), same "evidence not a guess" approach as the % floor this
    // replaced — below this it's not really worth calling out.
    const GP_CHANGE_NOTABLE_FLOOR = 500000;
    const entries = [];
    if (biggestCrash && gpChange(biggestCrash) < -GP_CHANGE_NOTABLE_FLOOR)
      entries.push({ icon:'📉', title:'Biggest Crash', item: biggestCrash, stat: fmt.gp(gpChange(biggestCrash))+'gp ('+(biggestCrash.change_1d).toFixed(2)+'%) today', liveStat: liveChangeStat(biggestCrash) });
    if (biggestDump && biggestDump !== biggestCrash)
      entries.push({ icon:'🚮', title:'Heaviest Dump', item: biggestDump,  stat: (biggestDump.change_1d||0).toFixed(2)+'% on '+(biggestDump.volume&&biggestDump.avgVolume?(biggestDump.volume/biggestDump.avgVolume).toFixed(1)+'x avg vol':'high volume'), liveStat: liveChangeStat(biggestDump) });
    if (overpriced)
      entries.push({ icon:'🏷️', title:'Most Overpriced', item: overpriced, stat: `GE price ${overpricedThreshold}%+ above real live buy/sell` });
    if (manipulated)
      entries.push({ icon:'🎭', title:'Probably Manipulated', item: manipulated, stat: Math.abs(manipulated.change_1d||0).toFixed(2)+'% move on tiny buy limit' });
    return entries;
  }, [tradeableItems, opList, overpricedThreshold]);

  const hallOfGlory = useMemo(() => {
    const priced = tradeableItems.filter(it => (it.high || it.low) > 10000 && it.change_1d != null);
    const bestGainer = [...priced].sort((a,b) => gpChange(b) - gpChange(a))[0];
    const wildestRide = [...priced].filter(it => (it.signals||[]).includes('FRENZY'))
      .sort((a,b) => Math.abs(b.change_1d||0) - Math.abs(a.change_1d||0))[0];
    const hiddenGem = upList[0];

    const GP_CHANGE_NOTABLE_FLOOR = 500000;
    const entries = [];
    if (bestGainer && gpChange(bestGainer) > GP_CHANGE_NOTABLE_FLOOR)
      entries.push({ icon:'📈', title:'Best Gainer', item: bestGainer, stat: '+'+fmt.gp(gpChange(bestGainer))+'gp (+'+(bestGainer.change_1d).toFixed(2)+'%) today', liveStat: liveChangeStat(bestGainer) });
    if (wildestRide && wildestRide !== bestGainer)
      entries.push({ icon:'🎢', title:'Wildest Ride', item: wildestRide, stat: Math.abs(wildestRide.change_1d||0).toFixed(2)+'% swing today', liveStat: liveChangeStat(wildestRide) });
    if (hiddenGem)
      entries.push({ icon:'💎', title:'Hidden Gem', item: hiddenGem, stat: 'Real live price well above the GE listing' });
    return entries;
  }, [tradeableItems, upList]);

  // Sector Heat Map
  const SECTORS = [
    {label:'Melee',       cats:['melee'],                          emoji:'⚔️'},
    {label:'Ranged',      cats:['ranged','ammo'],                   emoji:'🏹'},
    {label:'Magic',       cats:['magic','runes'],                  emoji:'🔮'},
    {label:'Necromancy',  cats:['necromancy'],                     emoji:'💀'},
    {label:'Herblore',    cats:['herblore'],                       emoji:'⚗️'},
    {label:'PVM Supplies',cats:['supplies'],                       emoji:'🛡️'},
    {label:'Boss Drops',  cats:['boss'],                           emoji:'🐉'},
    {label:'Rares',       cats:['rares'],                          emoji:'🎩'},
    {label:'Skilling',    cats:['mining','artisan','farming','archaeology'], emoji:'⛏️'},
    {label:'Prayer',      cats:['prayer'],                         emoji:'🦴'},
    {label:'Summoning',   cats:['summoning'],                      emoji:'🐾'},
    {label:'Invention',   cats:['invention'],                      emoji:'⚙️'},
    {label:'Treasure Trails', cats:['treasure_trails'],            emoji:'📦'},
  ];

  const sectorHeat = useMemo(() => {
    return SECTORS.map(sector => {
      const catSet = new Set(sector.cats);
      const members = tradeableItems.filter(it =>
        (it.categories||[]).some(c => catSet.has(c)) && (it.high || it.low)
      );
      if (!members.length) return {...sector, score:0, count:0, surge:0, dump:0, active:0};

      const surge  = members.filter(it => (it.signals||[]).includes('SURGE')).length;
      const dump   = members.filter(it => (it.signals||[]).includes('DUMP')).length;
      const frenzy = members.filter(it => (it.signals||[]).includes('FRENZY')).length;
      const active = members.filter(it => (it.change_1d||0) !== 0).length;

      const avgChg = members.reduce((s,it) => s + (it.change_1d||0), 0) / members.length;
      const avgOpp = members.reduce((s,it) => s + (it.score||0), 0) / members.length;

      // Heat score: blend momentum + opportunity + signal activity
      const momentumScore = Math.max(0, Math.min(100, 50 + avgChg * 4));
      const signalScore   = Math.min(100, ((surge + frenzy * 2) / Math.max(members.length, 1)) * 1000);
      const score = momentumScore * 0.5 + signalScore * 0.3 + avgOpp * 0.2;

      return {...sector, score, count:members.length, surge, dump, frenzy, active, avgChg, members};
    });
  }, [tradeableItems]);

  const sectionStyle = {marginBottom:20};
  const headingStyle = {fontSize:11, fontWeight:'bold', letterSpacing:'0.08em', textTransform:'uppercase',
    color:T.textDim, borderBottom:`1px solid ${T.borderDim}`, paddingBottom:4, marginBottom:10};
  const cardRowStyle = {display:'flex', flexWrap:'wrap', gap:8};

  // Index card
  const IndexCard = ({idx}) => {
    const up = idx.direction === 'up';
    const dn = idx.direction === 'down';
    const chgColor = up ? T.green : dn ? T.red : T.textDim;
    const arrow = up ? '▲' : dn ? '▼' : '●';
    const sign = idx.change > 0 ? '+' : '';
    const def = INDEXES.find(d => d.name === idx.name);
    return h('div', {
      onClick: () => def && setActiveIndexId(def.id),
      style:{
        background:T.panel, border:`1px solid ${T.border}`, borderRadius:4,
        padding:'10px 14px', minWidth:150, flex:'1 1 140px',
        cursor: def ? 'pointer' : 'default', transition:'border-color 0.15s',
      },
      onMouseEnter: e => { if (def) e.currentTarget.style.borderColor = T.gold+'88'; },
      onMouseLeave: e => { e.currentTarget.style.borderColor = T.border; },
    },
      h('div', {style:{fontSize:11, color:T.textDim, marginBottom:4}}, idx.name),
      h('div', {style:{fontSize:18, fontWeight:'bold', color:T.textBright, marginBottom:2}},
        idx.value.toFixed(2)),
      h('div', {style:{fontSize:12, color:chgColor}},
        `${arrow} ${sign}${idx.change.toFixed(2)}`)
    );
  };

  // Mini item row
  const MiniRow = ({it, showChange}) => {
    const price = it.high || it.low;
    const chg = it.change_1d;
    return h('div', {
      style:{display:'flex', alignItems:'center', justifyContent:'space-between',
        padding:'5px 8px', borderRadius:3, cursor:'pointer',
        background: selected?.id===it.id ? T.panel2 : 'transparent'},
      onClick: () => onSelect(it),
    },
      h('div', {style:{fontSize:12, color:T.text, flex:1, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}, it.name),
      h('div', {style:{display:'flex', flexDirection:'column', alignItems:'flex-end', marginLeft:8}},
        h('div', {style:{fontSize:12, color:T.textDim, whiteSpace:'nowrap'}}, fmt.gp(price)+'gp'),
        h(LivePriceLine, {liveBuy: it.liveBuy, liveSell: it.liveSell}),
      ),
      showChange && chg != null && h('div', {
        style:{fontSize:11, color: chg>0?T.green:T.red, marginLeft:8, minWidth:46, textAlign:'right'}
      }, (chg>0?'+':'')+chg.toFixed(2)+'%')
    );
  };

  // Signal pill
  const SIG_COLORS = {
    SURGE:{bg:'#1a3a1a',border:'#4caf50',text:'#4caf50'},
    DUMP:{bg:'#3a1a1a',border:'#e53935',text:'#e53935'},
    SPIKE:{bg:'#14261a',border:'#4caf50',text:'#81c784'},
    SLUMP:{bg:'#2a1414',border:'#e53935',text:'#ef9a9a'},
    ACCUMULATION:{bg:'#1a2a3a',border:'#64b5f6',text:'#64b5f6'},
    DISTRIBUTION:{bg:'#2a1a3a',border:'#ce93d8',text:'#ce93d8'},
    FRENZY:{bg:'#3a2a0a',border:'#ffd700',text:'#ffd700'},
    HIGH_VOL:{bg:'#2a2a1a',border:'#c9a84c',text:'#c9a84c'},
    OVERPRICED:{bg:'#3a1a1a',border:'#ef9a9a',text:'#ef9a9a'},
    UNDERPRICED:{bg:'#1a3a1a',border:'#81c784',text:'#81c784'},
    WIDE_SPREAD:{bg:'#2a2a2a',border:'#bdbdbd',text:'#bdbdbd'},
  };
  const SignalPill = ({signal, count}) => {
    const c = SIG_COLORS[signal] || {bg:T.panel,border:T.border,text:T.text};
    const active = activeSignal === signal;
    const trend = signalTrend?.counts?.[signal];
    return h('div', {
      onClick: () => setActiveSignal(s => s === signal ? null : signal),
      title: trend ? `Past ${trend.length} days: ${trend.join(', ')}` : undefined,
      style:{
        background: active ? c.border : c.bg,
        border:`1px solid ${c.border}`, borderRadius:4,
        padding:'6px 12px', display:'flex', flexDirection:'column', alignItems:'center',
        minWidth:90, flex:'1 1 80px', cursor:'pointer',
        transition:'background 0.15s',
      }
    },
      h('div', {style:{fontSize:18, fontWeight:'bold', color: active ? T.bg : c.text}}, count),
      h('div', {style:{fontSize:10, color: active ? T.bg : c.text, opacity: active ? 1 : 0.8, marginTop:2}}, signal),
      trend && h('div', {style:{display:'flex', alignItems:'flex-end', gap:2, marginTop:5, height:16}},
        trend.map((v,i) => {
          const max = Math.max(...trend, 1);
          const isToday = i === trend.length - 1;
          return h('div', {key:i, style:{
            width:5, height: Math.max(2, (v/max)*16),
            background: isToday ? (active ? T.bg : c.text) : (active ? `${T.bg}99` : `${c.text}55`),
            borderRadius:1,
          }, title:`${v}`});
        })
      )
    );
  };

  // Signal drill-down view
  if (activeSignal) {
    const todayItems = activeSignal === 'OVERPRICED' ? opList
      : activeSignal === 'UNDERPRICED' ? upList
      : tradeableItems.filter(it => (it.signals||[]).includes(activeSignal));
    const weekEntries = signalTrend?.itemIds?.[activeSignal] || [];
    const lastDayIdx = signalTrend ? signalTrend.days.length - 1 : 0;
    const weekItems = signalWindow === '7d'
      ? (() => {
          const byId = new Map();
          weekEntries.forEach(e => byId.set(String(e.id), e.lastDayIdx));
          todayItems.forEach(it => byId.set(String(it.id), lastDayIdx)); // today's live signals always count
          return [...byId.entries()].map(([id, idx]) => {
            const it = tradeableItems.find(t => String(t.id) === id);
            return it ? {...it, _lastDayIdx: idx} : null;
          }).filter(Boolean);
        })()
      : [];
    const sigItems = (signalWindow === '7d' ? weekItems : todayItems)
      .sort((a,b) => {
        if (signalWindow === '7d') {
          const da = a._lastDayIdx ?? 0, db = b._lastDayIdx ?? 0;
          if (da !== db) return db - da;
        }
        if (activeSignal === 'DUMP') return (a.change_1d||0) - (b.change_1d||0);
        if (activeSignal === 'SURGE') return (b.change_1d||0) - (a.change_1d||0);
        const ra = a.volume && a.avgVolume ? a.volume/a.avgVolume : 0;
        const rb = b.volume && b.avgVolume ? b.volume/b.avgVolume : 0;
        return rb - ra;
      });
    const c = SIG_COLORS[activeSignal] || {bg:T.panel, border:T.border, text:T.text};
    return h('div', {style:{display:'flex', flexDirection:'column', height:'100%'}},
      h('div', {style:{display:'flex', alignItems:'center', gap:10, padding:'10px 14px', borderBottom:`1px solid ${T.border}`, flexShrink:0}},
        h('button', {className:'ge-btn', style:{padding:'3px 10px', fontSize:12}, onClick:()=>setActiveSignal(null)}, '← Back'),
        h('div', {style:{fontSize:12, fontWeight:'bold', color:c.text, letterSpacing:'0.08em'}}, activeSignal),
        h('div', {style:{fontSize:11, color:T.textDim}}, `${sigItems.length} items`),
        h('div', {style:{display:'flex', gap:4, marginLeft:'auto'}},
          ['today','7d'].map(w => h('button', {
            key:w,
            onClick:()=>setSignalWindow(w),
            style:{
              padding:'3px 10px', fontSize:11, cursor:'pointer', borderRadius:3,
              background: signalWindow===w ? 'rgba(201,168,76,0.2)' : 'transparent',
              border:`1px solid ${signalWindow===w ? T.gold : T.border}`,
              color: signalWindow===w ? T.goldBright : T.textDim,
            }
          }, w==='today' ? 'Today' : 'Last 7 Days'))
        )
      ),
      SIGNAL_INFO[activeSignal] && h('div', {style:{
        padding:'8px 14px', fontSize:11, color:T.textDim, fontStyle:'italic', lineHeight:1.5,
        borderBottom:`1px solid ${T.borderDim}`, flexShrink:0,
      }}, SIGNAL_INFO[activeSignal] + (signalWindow==='7d' ? ' Showing any item that triggered this in the last 7 days.' : '')),
      h('div', {style:{flex:1, overflowY:'auto'}},
        h(ItemTable, {items:sigItems, selected, onSelect, watchlist, onToggleWatch, onToggleHide, onAddCompare,
          showGapPct: activeSignal === 'OVERPRICED' || activeSignal === 'UNDERPRICED',
          showSpread: activeSignal === 'WIDE_SPREAD'})

      )
    );
  }

  // Index drill-down view
  if (activeIndexId) {
    const def = INDEXES.find(d => d.id === activeIndexId);
    const itemById = {};
    items.forEach(it => { itemById[it.id] = it; });
    const indexItems = def ? def.items.map(d => itemById[d.id]).filter(Boolean) : [];
    const withChange = indexItems.filter(it => it.change_1d != null);
    const avgChange = withChange.length ? withChange.reduce((s,it) => s+it.change_1d, 0) / withChange.length : null;
    return h('div', {style:{display:'flex', flexDirection:'column', height:'100%'}},
      h('div', {style:{display:'flex', alignItems:'center', gap:10, padding:'10px 14px', borderBottom:`1px solid ${T.border}`, flexShrink:0}},
        h('button', {className:'ge-btn', style:{padding:'3px 10px', fontSize:12}, onClick:()=>setActiveIndexId(null)}, '← Back'),
        h('div', {style:{fontSize:12, fontWeight:'bold', color:T.goldBright, letterSpacing:'0.08em'}}, def?.name),
        avgChange != null && h('div', {style:{fontSize:12, color: avgChange >= 0 ? T.green : T.red}},
          (avgChange >= 0 ? '▲ +' : '▼ ') + avgChange.toFixed(2) + '% avg today'),
        h('div', {style:{fontSize:11, color:T.textDim, marginLeft:'auto'}},
          `${indexItems.length} / ${def?.items.length || 0} items tracked`),
      ),
      h('div', {style:{flex:1, overflowY:'auto'}},
        h(ItemTable, {items:indexItems, selected, onSelect, watchlist, onToggleWatch, onToggleHide, onAddCompare})
      )
    );
  }

  // Sector drill-down view
  if (activeSector) {
    const {label, emoji, members, surge, dump, frenzy, active, count} = activeSector;
    const HEAT_SIGNALS = new Set(['SURGE','FRENZY','DUMP','MANIPULATED']);
    const sorted = [...(members||[])]
      .filter(it => (it.signals||[]).some(s => HEAT_SIGNALS.has(s)))
      .sort((a,b) => {
        const order = ['FRENZY','SURGE','DUMP','MANIPULATED'];
        const aTop = order.find(s => (a.signals||[]).includes(s)) || 'ZZZ';
        const bTop = order.find(s => (b.signals||[]).includes(s)) || 'ZZZ';
        if (aTop !== bTop) return order.indexOf(aTop) - order.indexOf(bTop);
        return Math.abs(b.change_1d||0) - Math.abs(a.change_1d||0);
      });
    const stats = [surge && `${surge} surging`, dump && `${dump} dumping`, frenzy && `${frenzy} in frenzy`].filter(Boolean).join(', ');
    return h('div', {style:{display:'flex', flexDirection:'column', height:'100%'}},
      h('div', {style:{display:'flex', alignItems:'center', gap:10, padding:'10px 14px', borderBottom:`1px solid ${T.border}`, flexShrink:0}},
        h('button', {className:'ge-btn', style:{padding:'3px 10px', fontSize:12}, onClick:()=>setActiveSector(null)}, '← Back'),
        h('span', {style:{fontSize:16}}, emoji),
        h('div', {style:{fontSize:12, fontWeight:'bold', color:T.goldBright, letterSpacing:'0.08em'}}, label),
        stats && h('div', {style:{fontSize:11, color:T.textDim}}, stats),
        h('div', {style:{fontSize:11, color:T.textDim, marginLeft:'auto'}}, `${sorted.length} ${sorted.length === 1 ? 'item' : 'items'} with active signals (${count} in sector)`),
      ),
      sorted.length === 0
        ? h('div', {style:{padding:20, fontSize:12, color:T.textDim}}, 'No items with active surge, dump, frenzy, or manipulated signals in this sector right now.')
        : h('div', {style:{flex:1, overflowY:'auto'}},
            h(ItemTable, {items:sorted, selected, onSelect, watchlist, onToggleWatch, onToggleHide, onAddCompare, showSignals:true})
          )
    );
  }

  return h('div', {style:{padding:'12px 14px'}},
    description && h('div', {style:{padding:'4px 0 12px', fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5, borderBottom:`1px solid ${T.borderDim}`, marginBottom:16}}, description),

    // ── Mood + Item of the Day ───────────────────────────────────
    h('div', {className:'dash-mood-row', style:{display:'flex', gap:8, marginBottom:20}},

      // Mood of the Market
      mood && h('div', {
        title: mood.tip,
        style:{
          background:T.panel, border:`1px solid ${T.border}`, borderRadius:4,
          padding:'10px 14px', flex:'0 0 auto', cursor:'default',
          display:'flex', alignItems:'center', gap:10, position:'relative',
        }
      },
        h('div', {style:{fontSize:28, lineHeight:1}}, mood.emoji),
        h('div', null,
          h('div', {style:{display:'flex', alignItems:'center', gap:5}},
            h('div', {style:{fontSize:10, color:T.textDim, textTransform:'uppercase', letterSpacing:'0.08em', marginBottom:2}}, 'Market Weather'),
            h('span', {
              onClick: e => { e.stopPropagation(); setShowWeatherLegend(s => !s); },
              title:'See all possible Market Weather statuses',
              style:{cursor:'pointer', fontSize:10, color:T.textDim, border:`1px solid ${T.textDim}`, borderRadius:'50%', width:13, height:13, display:'inline-flex', alignItems:'center', justifyContent:'center', marginBottom:2},
            }, '?'),
          ),
          h('div', {style:{fontSize:13, fontWeight:'bold', color:T.textBright}}, mood.label),
        ),
        showWeatherLegend && h('div', {
          onClick: e => e.stopPropagation(),
          style:{
            position:'absolute', top:'100%', left:0, marginTop:6, zIndex:50, width:320,
            background:T.panel2, border:`1px solid ${T.borderGold}`, borderRadius:6,
            boxShadow:'0 4px 16px rgba(0,0,0,0.6)', padding:'10px 12px',
          },
        },
          h('div', {style:{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8}},
            h('div', {style:{fontSize:11, color:T.gold, textTransform:'uppercase', letterSpacing:'0.06em'}}, 'All Market Weather statuses'),
            h('span', {onClick:()=>setShowWeatherLegend(false), style:{cursor:'pointer', color:T.textDim, fontSize:13}}, '✕'),
          ),
          MARKET_WEATHER_LEGEND.map(w => h('div', {key:w.label, style:{display:'flex', gap:8, alignItems:'flex-start', padding:'6px 0', borderTop:`1px solid ${T.borderDim}`}},
            h('div', {style:{fontSize:18, lineHeight:1.3}}, w.emoji),
            h('div', null,
              h('div', {style:{fontSize:12, color: w.label===mood.label ? T.goldBright : T.textBright, fontWeight:'bold'}}, w.label, w.label===mood.label && h('span', {style:{color:T.textDim, fontWeight:'normal'}}, ' (current)')),
              h('div', {style:{fontSize:11, color:T.textDim, lineHeight:1.4}}, w.tip),
            ),
          )),
        ),
      ),

      // Item of the Day
      itemOfTheDay && h('div', {
        onClick: () => onSelect(itemOfTheDay),
        style:{
          background:T.panel, border:`1px solid ${T.border}`, borderRadius:4,
          padding:'10px 14px', flex:'1 1 0', cursor:'pointer',
          transition:'border-color 0.15s',
        },
        onMouseEnter: e => e.currentTarget.style.borderColor = T.gold+'88',
        onMouseLeave: e => e.currentTarget.style.borderColor = T.border,
      },
        h('div', {style:{fontSize:10, color:T.textDim, textTransform:'uppercase', letterSpacing:'0.08em', marginBottom:4}}, "Item of the Day"),
        h('div', {style:{display:'flex', justifyContent:'space-between', alignItems:'baseline', gap:8}},
          h('div', {style:{fontSize:13, fontWeight:'bold', color:T.textBright, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}, itemOfTheDay.name),
          h('div', {style:{fontSize:12, color:T.gold, flexShrink:0}}, fmt.gp(itemOfTheDay.high||itemOfTheDay.low)+'gp'),
        ),
        h('div', {style:{fontSize:11, color:T.textDim, marginTop:4, fontStyle:'italic', lineHeight:1.4,
          overflow:'hidden', display:'-webkit-box', WebkitLineClamp:2, WebkitBoxOrient:'vertical'}},
          (() => {
            const txt = itemOfTheDay.examine;
            if (txt) return `"${txt}"`;
            return '"This item is so boring that not even the API has a description for it."';
          })()
        )
      ),
    ),

    // ── Market Stats ─────────────────────────────────────────────
    h('div', {style:{display:'flex', gap:8, marginBottom:20}},
      [
        ['💰', fmt.gp(marketStats.totalGP)+'gp', 'GP traded today'],
        ['📦', marketStats.itemsTraded.toLocaleString(), 'items with volume'],
        ['📊', marketStats.itemsTracked.toLocaleString(), 'items tracked'],
      ].map(([icon, val, label]) =>
        h('div', {key:label, style:{
          flex:'1 1 0', background:T.panel, border:`1px solid ${T.border}`, borderRadius:4,
          padding:'8px 12px', display:'flex', alignItems:'center', gap:8,
        }},
          h('span', {style:{fontSize:18}}, icon),
          h('div', null,
            h('div', {style:{fontSize:13, fontWeight:'bold', color:T.textBright}}, val),
            h('div', {style:{fontSize:10, color:T.textDim, marginTop:1}}, label),
          )
        )
      )
    ),

    h(UpdateRisksBar, {scope:'yours'}),
    h(AlmanacFlagsBar),
    h(ComingUpSection, {onNavigate, onOpen: url => window.genius?.openExternal(url)}),
    h(TopMoversSection, {items, officialTop100, onSelect, onNavigate}),

    // ── News Item Mentions ───────────────────────────────────────
    (() => {
      const now = new Date();
      const dow = now.getDay();
      const daysToMon = dow === 0 ? 6 : dow - 1;
      const lastMon = new Date(now); lastMon.setDate(now.getDate() - daysToMon); lastMon.setHours(0,0,0,0);
      const twoMonsAgo = new Date(lastMon); twoMonsAgo.setDate(lastMon.getDate() - 7);
      const recentNews = (news||[]).filter(n =>
        n.source === 'RS3 News' &&
        n.date && new Date(n.date) >= twoMonsAgo &&
        ((n.mentions&&n.mentions.length) || (n.impact_items&&n.impact_items.length))
      );
      if (!recentNews.length) return null;
      return h('div', {style:sectionStyle},
        h('div', {style:{...headingStyle, display:'flex', alignItems:'center', justifyContent:'space-between', cursor:'pointer'},
          onClick:()=>setNewsExpanded(e=>!e)},
          h('div', {style:{display:'flex', alignItems:'center', gap:8}},
            h('span', null, 'Recent Updates · Items'),
            h('span', {style:{fontSize:12, color:T.textDim}}, newsExpanded ? '▲' : '▼'),
          ),
          h('span', {
            style:{fontSize:11, color:T.textDim, fontWeight:'normal'},
            onClick: e => { e.stopPropagation(); onNavigate&&onNavigate('news'); },
          }, '→ News tab'),
        ),
        newsExpanded && recentNews.map((n,i) => {
          const isOpen = expandedArticle === i;
          return h('div', {key:i, style:{borderTop:`1px solid ${T.borderDim}`}},
            h('div', {
              style:{display:'flex', alignItems:'center', justifyContent:'space-between', padding:'8px 12px 8px 0', cursor:'pointer', gap:8},
              onClick:()=>setExpandedArticle(isOpen ? null : i),
            },
              h('div', {style:{display:'flex', alignItems:'center', gap:8, minWidth:0, flex:1}},
                h('span', {style:{fontSize:10, color:T.textDim, flexShrink:0}}, n.date),
                h('span', {style:{fontSize:12, color:T.text, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}, n.title),
                n.update_type && h('span', {style:{
                  fontSize:9, padding:'1px 6px', borderRadius:2, flexShrink:0,
                  background:'rgba(201,168,76,0.12)', border:`1px solid rgba(201,168,76,0.25)`,
                  color:T.gold, textTransform:'uppercase', letterSpacing:'0.05em',
                }}, n.update_type),
              ),
              h('span', {style:{color:T.text, flexShrink:0, fontSize:18, minWidth:20, textAlign:'center', lineHeight:1}}, isOpen ? '▾' : '›'),
            ),
            isOpen && h('div', {style:{paddingBottom:10}},
              (n.mentions&&n.mentions.length) > 0 && h('div', {style:{marginBottom:8}},
                h('div', {style:{fontSize:9, color:T.textDim, textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:4}}, 'Mentioned'),
                h('div', {style:{display:'flex', flexWrap:'wrap', gap:4}},
                  n.mentions.map(m => {
                    const it = items.find(it2 => it2.name.toLowerCase()===m.toLowerCase());
                    return h('span', {key:m, className:'news-tag',
                      style:{cursor:it?'pointer':'default', color:T.gold},
                      onClick: it ? ()=>onSelect(it) : undefined,
                    }, m);
                  })
                )
              ),
              (n.impact_items&&n.impact_items.length) > 0 && h('div', null,
                h('div', {style:{fontSize:9, color:T.textDim, textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:4}}, 'Likely affected'),
                h('div', {style:{display:'flex', flexWrap:'wrap', gap:4}},
                  n.impact_items.map(m => {
                    const it = items.find(it2 => it2.name.toLowerCase()===m.name.toLowerCase());
                    const chgColor = (m.change_1d||0) > 0 ? T.green : (m.change_1d||0) < 0 ? T.red : T.textDim;
                    return h('span', {key:m.name, className:'news-tag',
                      style:{cursor:it?'pointer':'default', color:T.textDim},
                      onClick: it ? ()=>onSelect(it) : undefined,
                    },
                      m.name,
                      m.change_1d != null && h('span', {style:{color:chgColor, marginLeft:4}},
                        (m.change_1d>0?'+':'')+m.change_1d.toFixed(1)+'%')
                    );
                  })
                )
              ),
            ),
          );
        }),
      );
    })(),

    // ── Sector Heat Map ──────────────────────────────────────────
    h('div', {style:{...sectionStyle, position:'relative'}},
      h('div', {style:{display:'flex', alignItems:'center', gap:5}},
        h('div', {style:headingStyle}, 'Sector Heat Map'),
        h('span', {
          onClick: e => {
            e.stopPropagation();
            // Anchored popup near a heading that can sit anywhere on a
            // scrollable page — a plain position:absolute (downward-only)
            // got clipped by the viewport bottom when this section was
            // near the top of a tall page. Measuring the icon's real
            // screen position and flipping the popup above it when there
            // isn't ~340px of room below fixes that, same idea as the
            // SectorCard hover tooltip's viewport-aware placement above.
            const POPUP_HEIGHT = 340;
            if (!showHeatmapLegend) {
              const r = e.currentTarget.getBoundingClientRect();
              const openUpward = r.bottom + POPUP_HEIGHT > window.innerHeight;
              setHeatmapLegendPos({
                left: r.left,
                top: openUpward ? Math.max(8, r.top - POPUP_HEIGHT) : r.bottom + 6,
              });
            }
            setShowHeatmapLegend(s => !s);
          },
          title:'What does this heat map show?',
          style:{cursor:'pointer', fontSize:10, color:T.textDim, border:`1px solid ${T.textDim}`, borderRadius:'50%', width:13, height:13, display:'inline-flex', alignItems:'center', justifyContent:'center'},
        }, '?'),
      ),
      showHeatmapLegend && heatmapLegendPos && createPortal(h('div', {
        onClick: e => e.stopPropagation(),
        style:{
          position:'fixed', left:heatmapLegendPos.left, top:heatmapLegendPos.top, zIndex:9999, width:340,
          background:T.panel2, border:`1px solid ${T.borderGold}`, borderRadius:6,
          boxShadow:'0 4px 16px rgba(0,0,0,0.6)', padding:'10px 12px',
        },
      },
        h('div', {style:{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8}},
          h('div', {style:{fontSize:11, color:T.gold, textTransform:'uppercase', letterSpacing:'0.06em'}}, 'Sector Heat Map'),
          h('span', {onClick:()=>setShowHeatmapLegend(false), style:{cursor:'pointer', color:T.textDim, fontSize:13}}, '✕'),
        ),
        h('div', {style:{fontSize:11, color:T.textDim, lineHeight:1.6, marginBottom:8}},
          'Each tile is a category of items (Melee, Magic, Herblore, etc.) colored by how much is happening in it right now — price momentum, opportunity scores, and active signals (Surge, Dump, Frenzy) across every item in that category. Click a tile to see exactly which items in it currently have an active signal.'
        ),
        [
          {c:'#ff6b35', l:'🔥 Hot — score 72+, the most active sector right now'},
          {c:'#ffd700', l:'🟡 Warm — score 55-71'},
          {c:T.green,   l:'🟢 Active — score 40-54'},
          {c:T.textDim, l:'⬜ Quiet — score 25-39'},
          {c:T.red,     l:'🔴 Cold — score under 25, barely moving'},
        ].map(t => h('div', {key:t.l, style:{display:'flex', gap:6, alignItems:'center', fontSize:11, color:T.textDim, padding:'2px 0'}},
          h('span', {style:{width:8, height:8, borderRadius:'50%', background:t.c, flexShrink:0}}),
          t.l
        )),
      ), document.body),
      h('div', {style:{display:'flex', flexWrap:'wrap', gap:6}},
        sectorHeat.map(sector => h(SectorCard, {key:sector.label, sector, onClick:()=>setActiveSector(sector)}))
      )
    ),

    // ── Personal command center ──────────────────────────────────

    // Watchlist movers
    h('div', {style:sectionStyle},
      h('div', {style:{...headingStyle, cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'space-between'}, onClick:()=>onNavigate&&onNavigate('watchlist'), title:'Go to Watchlist'},
        h('span', null, 'Your Watchlist'),
        h('span', {style:{fontSize:11, color:T.gold, fontWeight:'normal'}}, 'View all →')),
      watchlistItems.length === 0
        ? h('div', {style:{fontSize:12, color:T.textDim, padding:'8px 0'}},
            'No items watched yet. Star any item to track it here.')
        : watchlistMovers.length === 0
          ? h('div', {style:{fontSize:12, color:T.textDim, padding:'8px 0'}}, 'No price movement on watched items today.')
          : watchlistMovers.map(it => h(MiniRow, {key:it.id, it, showChange:true}))
    ),

    // Portfolio snapshot
    openPositions.length > 0 && h('div', {style:sectionStyle},
      h('div', {style:{...headingStyle, cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'space-between'}, onClick:()=>onNavigate&&onNavigate('portfolio'), title:'Go to Portfolio'},
        h('span', null, 'Portfolio'),
        h('span', {style:{fontSize:11, color:T.gold, fontWeight:'normal'}}, 'View all →')),
      h('div', {style:{display:'flex', flexWrap:'wrap', gap:8}},
        h('div', {onClick:()=>onNavigate&&onNavigate('portfolio'), style:{background:T.panel, border:`1px solid ${T.border}`, borderRadius:4, padding:'10px 14px', flex:'1 1 120px', cursor:'pointer'}},
          h('div', {style:{fontSize:16, fontWeight:'bold', color:T.textBright}}, fmt.gp(totalCurrent)+'gp'),
          h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, `Current Value (${openPositions.length} positions)`)),
        h('div', {onClick:()=>onNavigate&&onNavigate('portfolio'), style:{background:T.panel, border:`1px solid ${T.border}`, borderRadius:4, padding:'10px 14px', flex:'1 1 120px', cursor:'pointer'}},
          h('div', {style:{fontSize:16, fontWeight:'bold', color: unrealizedPL >= 0 ? T.green : T.red}},
            (unrealizedPL >= 0 ? '+' : '') + fmt.gp(unrealizedPL) + 'gp'),
          h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}},
            `Unrealized P&L (${unrealizedPct >= 0 ? '+' : ''}${unrealizedPct.toFixed(1)}%)`))
      )
    ),

    // Alerts status
    alertCount > 0 && h('div', {style:sectionStyle},
      h('div', {style:headingStyle}, 'Alerts'),
      h('div', {style:{display:'flex', flexWrap:'wrap', gap:8}},
        h('div', {style:{background:T.panel, border:`1px solid ${T.border}`, borderRadius:4, padding:'10px 14px', flex:'1 1 120px'}},
          h('div', {style:{fontSize:16, fontWeight:'bold', color:T.textBright}}, alertCount),
          h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, 'Alerts Set')),
        triggeredAlerts.length > 0 && h('div', {style:{background:T.panel, border:`1px solid ${T.gold}`, borderRadius:4, padding:'10px 14px', flex:'1 1 120px'}},
          h('div', {style:{fontSize:16, fontWeight:'bold', color:T.gold}}, triggeredAlerts.length),
          h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, 'Conditions Met'))
      ),
      triggeredAlerts.length > 0 && h('div', {style:{marginTop:8}},
        triggeredAlerts.slice(0,3).map(a =>
          h('div', {key:a.id, style:{fontSize:12, color:T.gold, padding:'3px 0'}},
            `⚡ ${a.item_name} — ${['above','live_above'].includes(a.condition) ? 'above' : ['below','live_below'].includes(a.condition) ? 'below' : 'signal'} ${a.price ? fmt.gp(a.price)+'gp' : a.signal||''}`)
        )
      )
    ),

    h('div', {style:{borderTop:`1px solid ${T.borderDim}`, marginBottom:16}}),

    // Market indexes
    indexes.length > 0 && h('div', {style:sectionStyle},
      h('div', {style:headingStyle}, 'Market Indexes'),
      h('div', {style:cardRowStyle},
        indexes.map(idx => h(IndexCard, {key:idx.name, idx}))
      )
    ),

    // Stat pills
    h('div', {style:sectionStyle},
      h('div', {style:headingStyle}, 'Market Pulse'),
      h('div', {style:{display:'flex', flexWrap:'wrap', gap:8}},
        h('div', {style:{background:T.panel, border:`1px solid ${T.border}`, borderRadius:4, padding:'10px 14px', flex:'1 1 120px'}},
          h('div', {style:{fontSize:18, fontWeight:'bold', color:T.textBright}}, tradeableItems.length.toLocaleString()),
          h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, 'Items Tracked')),
        h('div', {style:{background:T.panel, border:`1px solid ${T.border}`, borderRadius:4, padding:'10px 14px', flex:'1 1 120px'}},
          h('div', {style:{fontSize:18, fontWeight:'bold', color:T.green}}, rising.toLocaleString()),
          h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, 'Rising Today')),
        h('div', {style:{background:T.panel, border:`1px solid ${T.border}`, borderRadius:4, padding:'10px 14px', flex:'1 1 120px'}},
          h('div', {style:{fontSize:18, fontWeight:'bold', color:T.red}}, falling.toLocaleString()),
          h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, 'Falling Today'))
      )
    ),

    // Active signals
    h('div', {style:sectionStyle},
      h('div', {style:headingStyle}, 'Active Signals'),
      h('div', {style:{display:'flex', flexWrap:'wrap', gap:8}},
        Object.entries(signalCounts).map(([sig, cnt]) => h(SignalPill, {key:sig, signal:sig, count:cnt}))
      )
    ),

    // Top movers
    h('div', {style:{display:'flex', gap:16, flexWrap:'wrap', marginBottom:20}},
      h('div', {style:{flex:'1 1 200px', minWidth:200}},
        h('div', {style:headingStyle}, 'Top Gainers'),
        risers.length
          ? risers.map(it => h(MiniRow, {key:it.id, it, showChange:true}))
          : h('div', {style:{fontSize:12, color:T.textDim, padding:'8px 0'}}, 'No data yet')
      ),
      h('div', {style:{flex:'1 1 200px', minWidth:200}},
        h('div', {style:headingStyle}, 'Top Losers'),
        fallers.length
          ? fallers.map(it => h(MiniRow, {key:it.id, it, showChange:true}))
          : h('div', {style:{fontSize:12, color:T.textDim, padding:'8px 0'}}, 'No data yet')
      )
    ),

    // Volume anomalies
    volume.length > 0 && h('div', {style:sectionStyle},
      h('div', {style:headingStyle}, 'Volume Anomalies'),
      volume.map(it => h(MiniRow, {key:it.id, it, showChange:false}))
    ),

    // Hall of Shame
    hallOfShame.length > 0 && h('div', {style:sectionStyle},
      h('div', {style:headingStyle}, '🏛️ Hall of Shame'),
      h('div', {style:{display:'flex', flexDirection:'column', gap:6}},
        hallOfShame.map((entry, i) =>
          h('div', {
            key:i,
            onClick: () => onSelect(entry.item),
            style:{
              display:'flex', alignItems:'center', gap:10,
              padding:'8px 10px', borderRadius:4, cursor:'pointer',
              background:T.panel, border:`1px solid ${T.border}`,
              borderLeft:`3px solid ${T.red}`,
              transition:'border-color 0.15s',
            },
            onMouseEnter: e => e.currentTarget.style.borderColor = T.red,
            onMouseLeave: e => e.currentTarget.style.borderColor = T.border,
          },
            h('div', {style:{fontSize:20, flexShrink:0}}, entry.icon),
            h('div', {style:{flex:1, minWidth:0}},
              h('div', {style:{fontSize:10, color:T.red, fontWeight:'bold', textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:2}}, entry.title),
              h('div', {style:{fontSize:12, color:T.textBright, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}, entry.item.name),
              h('div', {style:{fontSize:11, color:T.textDim}}, entry.stat),
              entry.liveStat && h('div', {style:{fontSize:10, color:T.textDim, fontStyle:'italic'}}, entry.liveStat),
            ),
            h('div', {style:{flexShrink:0, textAlign:'right'}},
              h('div', {style:{fontSize:12, color:T.red, fontWeight:'bold'}}, fmt.gp(entry.item.high || entry.item.low)+'gp'),
              h(LivePriceLine, {liveBuy: entry.item.liveBuy, liveSell: entry.item.liveSell}),
            ),
          )
        )
      )
    ),

    // Hall of Glory
    hallOfGlory.length > 0 && h('div', {style:sectionStyle},
      h('div', {style:headingStyle}, '🏆 Hall of Glory'),
      h('div', {style:{display:'flex', flexDirection:'column', gap:6}},
        hallOfGlory.map((entry, i) =>
          h('div', {
            key:i,
            onClick: () => onSelect(entry.item),
            style:{
              display:'flex', alignItems:'center', gap:10,
              padding:'8px 10px', borderRadius:4, cursor:'pointer',
              background:T.panel, border:`1px solid ${T.border}`,
              borderLeft:`3px solid ${T.green}`,
              transition:'border-color 0.15s',
            },
            onMouseEnter: e => e.currentTarget.style.borderColor = T.green,
            onMouseLeave: e => e.currentTarget.style.borderColor = T.border,
          },
            h('div', {style:{fontSize:20, flexShrink:0}}, entry.icon),
            h('div', {style:{flex:1, minWidth:0}},
              h('div', {style:{fontSize:10, color:T.green, fontWeight:'bold', textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:2}}, entry.title),
              h('div', {style:{fontSize:12, color:T.textBright, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}}, entry.item.name),
              h('div', {style:{fontSize:11, color:T.textDim}}, entry.stat),
              entry.liveStat && h('div', {style:{fontSize:10, color:T.textDim, fontStyle:'italic'}}, entry.liveStat),
            ),
            h('div', {style:{flexShrink:0, textAlign:'right'}},
              h('div', {style:{fontSize:12, color:T.green, fontWeight:'bold'}}, fmt.gp(entry.item.high || entry.item.low)+'gp'),
              h(LivePriceLine, {liveBuy: entry.item.liveBuy, liveSell: entry.item.liveSell}),
            ),
          )
        )
      )
    )
  );
}

/* ─── Compare tab ────────────────────────────────────────────── */
function CompareTab({compareList, onRemove, onClear, allItems, description, userShorthands}) {
  const [search, setSearch] = useState('');
  const [searchResults, setSearchResults] = useState([]);

  // Shorthand-aware, same as the main search bar/Monster Lookup/Alerts
  // (see resolveShorthand) — previously a plain substring filter, so
  // typing a shorthand like a monster/item abbreviation here just came up
  // empty instead of expanding like it does everywhere else in the app.
  const handleSearch = e => {
    const q = e.target.value;
    setSearch(q);
    if (q.length < 2) { setSearchResults([]); return; }
    const resolved = resolveShorthand(q, userShorthands || {});
    if (resolved) {
      const seen = new Set();
      const out = [];
      for (const name of resolved) {
        const ql = name.toLowerCase();
        allItems
          .filter(it => it.name.toLowerCase().includes(ql) && !seen.has(it.id))
          .forEach(it => { seen.add(it.id); out.push(it); });
      }
      setSearchResults(out.slice(0, 8));
      return;
    }
    const ql = q.toLowerCase();
    setSearchResults(allItems.filter(it => it.name.toLowerCase().includes(ql)).slice(0, 8));
  };

  const ROWS = [
    {label: 'Price',    render: it => fmt.gp(it.high||it.low)+'gp', color: it => T.gold, live: true},
    {label: 'Change',   render: it => it.change_1d != null ? (it.change_1d>0?'+':'')+it.change_1d.toFixed(2)+'%' : '—',
                        color:  it => it.change_1d == null ? T.textDim : it.change_1d>0 ? T.green : T.red},
    {label: 'Volume',   render: it => it.volume ? fmt.gp(it.volume) : '—', color: () => T.text},
    {label: 'Avg Vol',  render: it => it.avgVolume ? fmt.gp(it.avgVolume) : '—', color: () => T.textDim},
    {label: 'Vol Ratio',render: it => it.volume&&it.avgVolume ? (it.volume/it.avgVolume).toFixed(2)+'×' : '—',
                        color:  it => {
                          if (!it.volume||!it.avgVolume) return T.textDim;
                          const r = it.volume/it.avgVolume;
                          return r>=2.5?T.gold:r>=1.5?T.green:r<=0.5?T.red:T.text;
                        }},
    {label: 'Alch',     render: it => it.alch ? fmt.gp(it.alch)+'gp' : '—', color: () => T.textDim},
    {label: 'Score',    render: it => it.score != null ? h('span', null, h('span', null, it.score.toFixed(1)), h('span', {style:{color:T.textDim, fontSize:10}}, '/100')) : '—',
                        color:  it => {
                          const s = it.score||0;
                          return s>=70?T.green:s>=40?T.gold:T.textDim;
                        }},
    {label: 'Buy Limit',render: it => it.limit ? it.limit.toLocaleString() : '—', color: () => T.textDim},
    {label: 'Signals',  render: null, color: () => T.text},
  ];

  const colW = compareList.length === 0 ? 0 : Math.floor(80 / compareList.length);

  return h('div', {style:{display:'flex',flexDirection:'column',height:'100%'}},
    description && h('div',{style:{padding:'8px 14px',borderBottom:`1px solid ${T.border}`,fontSize:12,color:T.textDim,fontStyle:'italic',lineHeight:1.5}}, description),

    // Search bar to add items
    h('div',{style:{padding:'8px 12px',borderBottom:`1px solid ${T.border}`,display:'flex',alignItems:'center',gap:8,flexWrap:'wrap'}},
      h('span',{style:{fontSize:11,color:T.textDim}},'Add item:'),
      h('div',{style:{position:'relative',flex:'1',maxWidth:280}},
        h('input',{className:'ge-input',placeholder:'Search item name...',value:search,
          onChange:handleSearch, style:{width:'100%'}}),
        searchResults.length>0 && h('div',{style:{
          position:'absolute',top:'100%',left:0,right:0,zIndex:100,
          background:T.panel2,border:`1px solid ${T.borderGold}`,borderRadius:4,maxHeight:200,overflowY:'auto'
        }},
          searchResults.map(it => h('div',{
            key:it.id,
            style:{padding:'6px 10px',cursor:'pointer',fontSize:12,color:T.text},
            onMouseEnter:e=>e.currentTarget.style.background=T.panel,
            onMouseLeave:e=>e.currentTarget.style.background='transparent',
            onClick:()=>{
              if (compareList.length>=4){return;}
              if (!compareList.find(c=>c.id===it.id)) {
                compareList.push(it);
                // trigger re-render via onRemove pattern — handled in App
                onRemove({...it, _add:true});
              }
              setSearch(''); setSearchResults([]);
            }
          }, it.name))
        )
      ),
      compareList.length>0&&h('button',{className:'ge-btn',style:{fontSize:11,padding:'3px 8px'},onClick:onClear},'Clear all'),
      h('span',{style:{fontSize:11,color:T.textDim}}, `${compareList.length}/4 items`)
    ),

    compareList.length === 0
      ? h('div',{className:'empty'},
          h('div',{className:'icon'},'⇌'),
          h('p',null,'Search for items above, or right-click any item and choose Compare.')
        )
      : h('div',{style:{overflowX:'auto',flex:1}},
          h('table',{className:'ge-table',style:{tableLayout:'fixed',width:'100%'}},
            h('thead',null,
              h('tr',null,
                h('th',{style:{width:'20%'}},'Stat'),
                compareList.map(it=>h('th',{key:it.id,style:{width:`${colW}%`}},
                  h('div',{style:{display:'flex',alignItems:'center',justifyContent:'space-between',gap:4}},
                    h('span',{style:{overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}},it.name),
                    h('button',{
                      style:{background:'none',border:'none',color:T.textDim,cursor:'pointer',fontSize:12,flexShrink:0},
                      onClick:()=>onRemove(it)
                    },'×')
                  )
                ))
              )
            ),
            h('tbody',null,
              ROWS.map(row=>h('tr',{key:row.label},
                h('td',{style:{color:T.textDim,fontSize:11,fontWeight:'bold'}},row.label),
                compareList.map(it=>h('td',{key:it.id},
                  row.render === null
                    ? h('div',{style:{display:'flex',flexWrap:'wrap',gap:2}},
                        (it.signals||[]).map(s=>h(SignalBadge,{key:s,signal:s}))
                      )
                    : h('span',{style:{color:row.color(it)}}, row.render(it)),
                  row.live && h(LivePriceLine, {liveBuy: it.liveBuy, liveSell: it.liveSell}),
                ))
              ))
            )
          )
        )
  );
}

/* ─── Tab views ──────────────────────────────────────────────── */
function WatchlistTab({items, removedItems, watchlist, selected, onSelect, onToggleWatch, description, devMode}) {
  const updateRisks = useUpdateRisks();
  // Three-pill Normal/DXP/Seasonal switcher — no longer dev-mode gated
  // (Ben, 2026-07-29: "those should not be behind dev mode, my apologies").
  const [view, setView] = useState('normal');
  const [seasonalEvent, setSeasonalEvent] = useState('christmas');
  const [dxpWatchlist, setDxpWatchlist] = useState([]);
  useEffect(() => { window.genius?.getDxpWatchlist?.().then(list => setDxpWatchlist(list || [])); }, []);
  const toggleDxpWatch = id => {
    const sid = String(id);
    setDxpWatchlist(prev => {
      const next = prev.includes(sid) ? prev.filter(x=>x!==sid) : [...prev, sid];
      window.genius?.setDxpWatchlist?.(next);
      return next;
    });
  };

  const activeList   = view === 'dxp' ? dxpWatchlist : watchlist;
  const activeToggle = view === 'dxp' ? toggleDxpWatch : onToggleWatch;
  // Watched items Jagex removed from the GE stay listed (last price, labelled)
  // instead of silently vanishing.
  const watched      = [...items, ...(removedItems || [])].filter(it => activeList.map(String).includes(String(it.id)));

  // ── Seasonal view helpers ────────────────────────────────────────────────
  const seasonalRows = view === 'seasonal'
    ? SEASONAL_ITEM_DATA.filter(r => r.event === seasonalEvent && !r.noSignal && !r.archived)
    : [];
  const seasonalTierLabel = r => {
    if (r.n === 1 || r.confidence == null) return {label:'Speculative', color:T.textDim};
    if (r.roundTrip) return {label:'Round-trip', color:T.green};
    return {label:'Drop-only', color:T.textDim};
  };

  return h('div', null,
    h(UpdateRisksBar, {scope:'watched'}),
    h(AlmanacFlagsBar, {scope:'watched'}),
    description && h('div', {style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, description),

    // ── Mode pills ──────────────────────────────────────────────────────────
    h('div', {style:{display:'flex', alignItems:'center', gap:8, padding:'10px 14px', borderBottom:`1px solid ${T.border}`, flexWrap:'wrap'}},
      ['normal','dxp','seasonal'].map(v => h('button', {
        key: v,
        onClick: () => setView(v),
        style: {
          padding:'4px 12px', fontSize:11, borderRadius:4, cursor:'pointer',
          border:`1px solid ${view===v ? T.gold : T.borderDim}`,
          background: view===v ? 'rgba(201,168,76,0.15)' : 'transparent',
          color: view===v ? T.goldBright : T.textDim,
        }
      }, v === 'normal' ? 'Normal' : v === 'dxp' ? 'DXP' : 'Seasonal')),
      h('span', {
        title:'Three separate lists. Normal drives the digest notification. DXP drives Almanac buy/sell alerts. Seasonal shows all researched items for the chosen event with live prices — not a pinned list, just a live price monitor for the full seasonal dataset.',
        style:{cursor:'help', fontSize:11, color:T.textDim, border:`1px solid ${T.textDim}`, borderRadius:'50%', width:16, height:16, display:'inline-flex', alignItems:'center', justifyContent:'center'},
      }, '?'),
    ),

    // ── Seasonal sub-event pills ────────────────────────────────────────────
    view === 'seasonal' && h('div', {style:{display:'flex', gap:6, padding:'8px 14px', borderBottom:`1px solid ${T.border}`, flexWrap:'wrap'}},
      SEASONAL_EVENTS.filter(ev => ev.confidence !== 'insufficient').map(ev =>
        h('button', {
          key: ev.id,
          onClick: () => setSeasonalEvent(ev.id),
          style: {
            padding:'3px 10px', fontSize:11, borderRadius:4, cursor:'pointer',
            border:`1px solid ${seasonalEvent===ev.id ? T.gold : T.borderDim}`,
            background: seasonalEvent===ev.id ? 'rgba(201,168,76,0.12)' : 'transparent',
            color: seasonalEvent===ev.id ? T.goldBright : T.textDim,
          }
        }, `${ev.emoji} ${ev.name}`)
      )
    ),

    // ── Seasonal grid ───────────────────────────────────────────────────────
    view === 'seasonal' && (
      seasonalRows.length === 0
        ? h('div', {className:'empty'}, h('p', null, 'No research data for this event.'))
        : h('div', {className:'offer-grid'},
            seasonalRows.map(res => {
              const liveItem = items.find(it => it.name?.toLowerCase() === res.name.toLowerCase());
              const price    = liveItem?.high || liveItem?.low;
              const tier     = seasonalTierLabel(res);
              return h('div', {
                key: res.name,
                className: 'offer-slot',
                title: res.strategy || undefined,
                onClick: liveItem ? () => onSelect(liveItem) : undefined,
                style: liveItem ? {} : {cursor:'default', opacity:0.6},
              },
                h('div', {className:'offer-slot-name'}, res.name),
                price
                  ? h('div', {className:'offer-slot-price'}, fmt.gp(price) + 'gp')
                  : h('div', {className:'offer-slot-price', style:{color:T.textDim}}, 'No price'),
                liveItem && h(LivePriceLine, {liveBuy: liveItem.liveBuy, liveSell: liveItem.liveSell}),
                price
                  ? h('div', {className:'offer-slot-change ' + pctClass(liveItem.change_1d)}, h(ChangeDisplay, {change_1d:liveItem.change_1d, price}))
                  : h('div', {className:'offer-slot-change'}),
                h('div', {style:{display:'flex', gap:4, flexWrap:'wrap', marginTop:4}},
                  h('span', {
                    title: tier.label === 'Round-trip'
                      ? 'Confirmed pattern: buy the in-event dip, then sell after it recovers post-event — a full profitable round trip in the research.'
                      : tier.label === 'Drop-only'
                      ? 'Only the price drop during the event is confirmed — no reliable recovery afterward, so this is a "buy cheap to use" item, not a flip.'
                      : 'Not enough years of data yet to confirm a repeatable pattern — treat this one as a guess.',
                    style:{
                      fontSize:9, padding:'1px 5px', borderRadius:3, cursor:'help',
                      border:`1px solid ${tier.color}`, color:tier.color,
                    },
                  }, tier.label),
                  res.duringPct != null && h('span', {
                    title:'Deepest discount from the pre-event baseline price seen during the event (the buy point).',
                    style:{
                      fontSize:9, padding:'1px 5px', borderRadius:3, cursor:'help',
                      border:`1px solid ${res.duringPct > 0 ? T.green : T.red}`,
                      color: res.duringPct > 0 ? T.green : T.red,
                    },
                  }, res.duringPct > 0 ? `▲${res.duringPct}%` : `▼${Math.abs(res.duringPct)}%`),
                  res.recoveryPct != null && h('span', {
                    title:'How much it climbed back up after the event, measured from the in-event low (the sell point) — not from the original pre-event price.',
                    style:{
                      fontSize:9, padding:'1px 5px', borderRadius:3, cursor:'help',
                      border:`1px solid ${T.green}`, color:T.green,
                    },
                  }, `+${res.recoveryPct}%`),
                ),
              );
            })
          )
    ),

    // ── Normal / DXP grid ───────────────────────────────────────────────────
    view !== 'seasonal' && (
      !watched.length
        ? h('div', {className:'empty'},
            h('div', {className:'icon'}, '★'),
            h('p', null, view === 'dxp' ? 'No items pinned to the DXP watchlist yet.' : 'Your watchlist is empty.'),
            h('div', {style:{fontSize:12, color:T.textDim, marginTop:8, lineHeight:1.7, maxWidth:340, textAlign:'center'}},
              view === 'dxp'
                ? h('span', null, 'Pin items from inside the Almanac\'s Confirmed/Negligible/Speculative/Recommendations tables.')
                : h('span', null,
                    'Browse any category tab and click the ★ on an item to add it here.', h('br', null),
                    'Watched items show live prices and signals all in one place.'
                  )
            )
          )
        : h('div', {className:'offer-grid'},
            watched.map(it =>
              h('div', {key:it.id, className:'offer-slot', onClick:()=>onSelect(it), style: it.removedFromGe ? {opacity:0.6} : undefined},
                h('div', {className:'offer-slot-name'}, it.name,
                  updateRisks.some(r => r.itemName.toLowerCase() === it.name.toLowerCase()) && h('span', {title:'An upcoming update may affect this item. See the list above.', style:{marginLeft:5}}, '⚠️')),
                it.removedFromGe && h(RemovedFromGeTag, {item: it}),
                h('div', {className:'offer-slot-price'}, fmt.gp(it.high||it.low)+'gp'),
                !it.removedFromGe && h(LivePriceLine, {liveBuy: it.liveBuy, liveSell: it.liveSell}),
                !it.removedFromGe && h('div', {className:'offer-slot-change '+pctClass(it.change_1d)}, h(ChangeDisplay, {change_1d:it.change_1d, price:it.high||it.low})),
                h('div', {className:'offer-slot-star'},
                  h('button', {
                    className:'star-btn',
                    onClick: e => { e.stopPropagation(); activeToggle(it.id); }
                  }, h('span', {className:'star-on'}, '★'))
                ),
                !it.removedFromGe && it.signals && it.signals.map(s => h(SignalBadge, {key:s, signal:s, style:{marginTop:4, marginRight:2}}))
              )
            )
          )
    ),
  );
}

