function RecipePane({allItems}) {
  const [expanded, setExpanded] = useState(null);

  const findItem = name => {
    const lower = name.toLowerCase();
    return allItems.find(it => it.name.toLowerCase() === lower);
  };

  const getPrice = name => {
    const it = findItem(name);
    if (!it) return null;
    return liveBuyOf(it);
  };

  const calcTotal = ingredients => {
    let total = 0;
    for (const ing of ingredients) {
      const p = getPrice(ing.name);
      if (p == null) return null;
      total += p * ing.qty;
    }
    return total;
  };

  return h('div', {style:{padding:'0 0 12px'}},
    COMBINATION_RECIPES.map(recipe => {
      const isOpen   = expanded === recipe.name;
      const total    = calcTotal(recipe.ingredients);
      const wikiItem = findItem(recipe.name);
      const wikiCost = wikiItem ? liveBuyOf(wikiItem) : null;
      const doses    = recipe.name.match(/\((\d)\)/)?.[1] || 4;

      return h('div', {key:recipe.name, style:{borderBottom:`1px solid ${T.borderDim}`}},
        h('div', {
          style:{display:'flex', justifyContent:'space-between', alignItems:'center',
            padding:'10px 14px', cursor:'pointer', userSelect:'none'},
          onClick: () => setExpanded(isOpen ? null : recipe.name)
        },
          h('div', null,
            h('div', {style:{fontSize:13, color:T.textBright, fontWeight:600}}, recipe.name),
            total != null
              ? h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}},
                  'Calculated cost: ',
                  h('span', {style:{color:T.gold}}, fmt.gp(total) + ' gp'))
              : h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, 'Some prices unavailable')
          ),
          h('span', {style:{fontSize:11, color:T.textDim}}, isOpen ? '▼' : '▶')
        ),

        isOpen && h('div', {style:{padding:'0 14px 12px'}},
          h('div', {style:{fontSize:10, color:T.textDim, letterSpacing:'0.06em', marginBottom:8}}, 'INGREDIENTS'),
          recipe.ingredients.map(ing => {
            const price = getPrice(ing.name);
            const ingItem = findItem(ing.name);
            const isUntrade = ingItem?.untradeable;
            return h('div', {key:ing.name,
              style:{display:'flex', justifyContent:'space-between', alignItems:'center',
                padding:'5px 0', borderBottom:`1px solid ${T.borderDim}`, fontSize:12}},
              h('div', {style:{display:'flex', alignItems:'center', gap:6}},
                h('span', {style:{
                  fontSize:10, padding:'1px 5px', borderRadius:2,
                  background: isUntrade ? 'rgba(255,180,0,0.08)' : 'rgba(201,168,76,0.1)',
                  border: `1px solid ${isUntrade ? 'rgba(255,180,0,0.25)' : 'rgba(201,168,76,0.2)'}`,
                  color: isUntrade ? T.gold : T.textDim
                }}, isUntrade ? 'made' : 'GE'),
                h('span', {style:{color:T.text}}, ing.qty > 1 ? `${ing.qty}× ${ing.name}` : ing.name)
              ),
              h('span', {style:{color: price != null ? T.textBright : T.textDim}},
                price != null ? fmt.gp(price * ing.qty) + ' gp' : '—')
            );
          }),

          h('div', {style:{display:'flex', justifyContent:'space-between', padding:'8px 0 0',
            fontSize:13, fontWeight:600, color:T.gold}},
            h('span', null, 'Total'),
            h('span', null, total != null ? fmt.gp(total) + ' gp' : '—')
          ),

          (total != null || wikiCost != null) && h('div', {
            style:{display:'flex', gap:16, marginTop:8, paddingTop:8,
              borderTop:`1px solid ${T.borderDim}`, fontSize:11, color:T.textDim}},
            wikiCost && h('span', null, 'Wiki cost: ', h('span',{style:{color:T.textBright}}, fmt.gp(wikiCost)+'gp')),
            total != null && h('span', null, 'Per dose: ', h('span',{style:{color:T.textBright}}, fmt.gp(Math.round(total/doses))+'gp'))
          )
        )
      );
    })
  );
}

function SplitTab({items, selected, onSelect, watchlist, onToggleWatch, onToggleHide, onAddCompare, description, splitLabel, showMachines, allItems, onNavigate}) {
  const [view, setView] = useState('items');
  const tradeableItems    = useMemo(() => (items||[]).filter(it => !it.untradeable), [items]);
  const untradeableItems  = useMemo(() => (items||[]).filter(it =>  it.untradeable), [items]);
  const displayItems = view === 'items' ? tradeableItems : untradeableItems;
  return h('div', null,
    description && h('div', {style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, description),
    (untradeableItems.length > 0 || showMachines) && h('div', {style:{display:'flex', gap:6, padding:'8px 12px', borderBottom:`1px solid ${T.border}`}},
      h('button', {className: view==='items' ? 'ge-btn gold' : 'ge-btn', onClick:()=>setView('items')},
        `Items (${tradeableItems.length})`),
      untradeableItems.length > 0 && h('button', {className: view==='split' ? 'ge-btn gold' : 'ge-btn', onClick:()=>setView('split')},
        `${splitLabel} (${untradeableItems.length})`),
      showMachines && h('button', {className: view==='machines' ? 'ge-btn gold' : 'ge-btn', onClick:()=>setView('machines')},
        'Machines')
    ),
    // Invention's Items pill also carries the "make it yourself" calculators
    // (Tight springs, Enchanted notepaper) above the item table.
    view === 'items' && showMachines && h(InventionCraftCalc, {items: allItems || items}),
    view === 'machines' ? h(MachineCalculators, {items: allItems || items, onSelect, onNavigate}) : h(ItemTable, {items:displayItems, selected, onSelect, watchlist, onToggleWatch, onToggleHide, onAddCompare})
  );
}

// ─── Invention machine profit calculators ──────────────────────────────────
// Real conversion rates, machine-charge costs, and throughput pulled from the
// RS Wiki (runescape.wiki/w/Plank_maker_(machine), Automatic_hide_tanner,
// Optimised_hide_tanner, Partial_potion_producer_DX — checked 2026-06-29).
// All three machines convert raw material -> processed material 1:1 (no
// chance of failure), so profit per item is just
// outputPrice - inputPrice - extraInputCost - chargeCost. A divine charge
// costs 72,099gp for 3,000 machine charge -> 24.03gp/charge — the cheapest
// charge source and what these numbers assume. Hourly/Daily use the
// upgraded machine variant's throughput (high-capacity plank maker, DX
// potion producer, optimised hide tanner) since that's what most players
// actually run at scale.
// Deliberately NOT including "via sawmill/portable/tannery" NPC-service
// comparison columns — couldn't find RS3-specific (not OSRS, which has a
// separate economy) fee numbers confirmed for those, and fabricating exact
// gp figures would be worse than leaving them out.
// Was a hardcoded 24.03gp/charge snapshot, silently drifting out of sync
// with the real market (Ben, 2026-10-01: caught a ~3% gap against the
// live-computed rate while checking Hide Tanner profit). 1 Divine charge
// gives 3,000 machine charges to a portable (runescape.wiki/w/Divine_charge,
// confirmed — that ratio itself doesn't change, only the gp side does), so
// the real per-charge cost is just the item's own live price divided by
// that fixed count — computed fresh every time from `items` instead of a
// number that was only ever accurate the day someone set it.
const MACHINE_CHARGES_PER_DIVINE_CHARGE = 3000;
function machineChargeGpRate(items) {
  const dc = (items || []).find(it => it.name && it.name.toLowerCase() === 'divine charge');
  const price = liveBuyOf(dc) || 0;
  // Divine charge hidden or unpriced — fall back to the last known rate
  // rather than 0, which would make every machine look like free profit.
  return price > 0 ? price / MACHINE_CHARGES_PER_DIVINE_CHARGE : FALLBACK_GP_PER_MACHINE_CHARGE;
}
const FALLBACK_GP_PER_MACHINE_CHARGE = 24.03;
