/* ─── Expensive tab ───────────────────────────────────────────── */
function ExpensiveTab({items, selected, onSelect, watchlist, onToggleWatch, threshold, description}) {
  const [sort, setSort] = useState({key:'high', dir:-1});

  // Same localStorage key ItemTable uses for its own GE/Live price toggle —
  // shared state, so flipping it here (or anywhere else) stays consistent
  // across the whole app instead of each table remembering its own mode.
  const [priceMode, setPriceMode] = useState(() => {
    try { return localStorage.getItem('genius_price_col_mode') === 'live' ? 'live' : 'ge'; } catch { return 'ge'; }
  });
  const togglePriceMode = e => {
    e.stopPropagation();
    setPriceMode(m => {
      const next = m === 'ge' ? 'live' : 'ge';
      try { localStorage.setItem('genius_price_col_mode', next); } catch {}
      return next;
    });
  };

  const expThreshold = Number(threshold) || 500000000;

  const expItems = useMemo(() => {
    return items.filter(it => (it.high || it.low || 0) >= expThreshold);
  }, [items, expThreshold]);

  const sortValue = (it, key) => {
    if (key === 'high' && priceMode === 'live') return it.liveBuy ?? it.liveSell ?? it.high ?? it.low ?? 0;
    return it[key] ?? 0;
  };
  const sorted = useMemo(() => {
    return [...expItems].sort((a,b) => {
      if (sort.key === 'name') return sort.dir * a.name.localeCompare(b.name);
      const av = sortValue(a, sort.key), bv = sortValue(b, sort.key);
      return sort.dir * (av < bv ? -1 : av > bv ? 1 : 0);
    });
  }, [expItems, sort, priceMode]);

  const Th = ({k, label}) => h('th', {
    style:{cursor:'pointer', userSelect:'none'},
    onClick: () => setSort(s => ({key:k, dir: s.key===k ? -s.dir : -1}))
  }, label + (sort.key===k ? (sort.dir>0 ? ' ↑' : ' ↓') : ''));

  if (!expItems.length) return h('div', {className:'empty-state'},
    h('div', {style:{fontSize:32, marginBottom:8}}, '💎'),
    h('div', null, `No items at or above ${fmt.gp(expThreshold)}gp.`),
    h('div', {style:{fontSize:11, color:T.textDim, marginTop:4}}, 'Adjust the threshold in Settings.')
  );

  return h('div', {className:'tab-content'},
    description && h('div',{style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, description),
    h('div', {style:{padding:'8px 12px', fontSize:11, color:T.textDim, borderBottom:`1px solid ${T.border}`, display:'flex', gap:16}},
      h('span', null, `${expItems.length} items at or above ${fmt.gp(expThreshold)}gp`),
      h('span', {style:{color:T.textDim, fontSize:10}}, 'Adjust threshold in Settings')
    ),
    h('table', {className:'ge-table'},
      h('thead', null,
        h('tr', null,
          h(Th, {k:'name',      label:'Item'}),
          h('th', {style:{cursor:'pointer', userSelect:'none'}, onClick: () => setSort(s => ({key:'high', dir: s.key==='high' ? -s.dir : -1}))},
            (priceMode==='ge' ? 'GE Price' : 'Live Price') + (sort.key==='high' ? (sort.dir>0 ? ' ↑' : ' ↓') : ''),
            h('button', {
              onClick: togglePriceMode,
              title: priceMode==='ge' ? 'Showing GE (listed) price — click to show live buy/sell instead' : 'Showing live buy/sell — click to show GE (listed) price instead',
              style: {marginLeft:6, fontSize:9, padding:'1px 5px', cursor:'pointer', borderRadius:3, border:`1px solid ${T.border}`, background:'rgba(255,255,255,0.05)', color:T.textDim}
            }, '⇄')
          ),
          h(Th, {k:'change_1d', label:'24h'}),
          h(Th, {k:'volume',    label:'Volume'}),
          h('th', null, '')
        )
      ),
      h('tbody', null, sorted.map(it => {
        const hasLive = it.liveBuy != null || it.liveSell != null;
        const priceCell = (priceMode === 'live' && hasLive)
          ? h('td', {key:'p'},
              h('div', {style:{display:'flex', gap:6, fontSize:11}},
                it.liveBuy  != null && h('span', null, h('span',{style:{color:T.green}},'B '), fmt.gp(it.liveBuy)+'gp'),
                it.liveSell != null && h('span', null, h('span',{style:{color:'#e08030'}},'S '), fmt.gp(it.liveSell)+'gp'),
              ),
              h('div', {className:'vol-avg'}, 'GE '+fmt.gp(it.high||it.low)+'gp'),
            )
          : h('td', {key:'p', style:{color:T.gold}}, fmt.gp(it.high||it.low)+'gp', h(LivePriceLine, {liveBuy: it.liveBuy, liveSell: it.liveSell}));
        return h('tr', {key:it.id, 'data-item-id':it.id,
          className: selected?.id===it.id ? 'selected' : '',
          onClick: () => onSelect(it)
        },
          h('td', null, it.name),
          priceCell,
          h('td',null,h(ChangeDisplay,{change_1d:it.change_1d,price:it.high||it.low})),
          h('td', null, h(VolDisplay, {volume:it.volume, avgVolume:it.avgVolume})),
          h('td', null,
            h('button', {
              className:'star-btn',
              onClick: e => { e.stopPropagation(); onToggleWatch(it.id); }
            }, h('span', {className: watchlist.includes(it.id)?'star-on':'star-off'},
              watchlist.includes(it.id)?'★':'☆'
            ))
          )
        );
      }))
    )
  );
}

/* ─── Alch tab ────────────────────────────────────────────────── */
const ALCH_DEFAULT_COL_WIDTHS = {name:280, high:110, limit:90, afterTax:110, alch:110, alchProfit:140, alchemiserProfit:170, star:30};

function AlchTab({items, selected, onSelect, watchlist, onToggleWatch, description}) {
  const [sort, setSort] = useState({key:'alchProfit', dir:-1});
  const cols = useTableColumns('genius_alch_col_widths', ALCH_DEFAULT_COL_WIDTHS, null, ['name', 'high', 'alchProfit']);

const natureRunePrice = useMemo(() => {
    const nr = items.find(it => it.natureRunePrice);
    return nr ? nr.natureRunePrice : 0;
  }, [items]);

  const divineChargePrice = useMemo(() => {
    const dc = items.find(it => it.name && it.name.toLowerCase() === 'divine charge');
    return liveBuyOf(dc) || 0;
  }, [items]);

  const chargePerItem = divineChargePrice ? Math.round(divineChargePrice / 500) : 0;

  const alchItems = useMemo(() => {
    return items
      .filter(it => it.signals && it.signals.includes('ALCH'))
      .map(it => {
        const price = liveBuyOf(it) || 0;
        const alch = it.alch || 0;
        const afterTax = applyTax(price);
        const alchProfit = alch - price - natureRunePrice;
        const alchemiserProfit = alch - price - natureRunePrice - chargePerItem;
        return {...it, price, afterTax, alchProfit, alchemiserProfit};
      });
  }, [items, natureRunePrice, chargePerItem]);

  const Th = ({k, label}) => h('th', {
    className:'sortable', style:{cursor:'pointer', userSelect:'none'},
    onClick: () => setSort(s => ({key:k, dir: s.key===k ? -s.dir : -1}))
  }, label + (sort.key===k ? (sort.dir>0 ? ' ↑' : ' ↓') : ''));

  const sorted = useMemo(() => {
    return [...alchItems].sort((a,b) => {
      if (sort.key === 'name') {
        return sort.dir * a.name.localeCompare(b.name);
      }
      // 'high' displays whichever price is active (see the header/cell
      // toggle) — sort has to follow the same value shown, or a "Live
      // Price" sort would silently order by the GE price underneath.
      const av = sort.key === 'high' ? a.price : (a[sort.key] ?? 0);
      const bv = sort.key === 'high' ? b.price : (b[sort.key] ?? 0);
      return sort.dir * (av < bv ? -1 : av > bv ? 1 : 0);
    });
  }, [alchItems, sort]);

  const descStrip = description && h('div',{style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, description);

  if (!alchItems.length) return h('div', null,
    descStrip,
    h('div', {className:'empty-state'},
      h('div', {style:{fontSize:32, marginBottom:8}}, '🔥'),
      h('div', null, 'No alch opportunities right now.'),
      h('div', {style:{fontSize:11, color:T.textDim, marginTop:4}}, 'Items appear here when their alch value exceeds GE sell price (after 2% tax) plus the cost of a nature rune.')
    )
  );

  return h('div', {className:'tab-content'},
    descStrip,
    h('div', {style:{padding:'8px 12px', fontSize:11, color:T.textDim, borderBottom:`1px solid ${T.border}`, display:'flex', gap:16}},
      h('span', null, `${alchItems.length} item${alchItems.length!==1?'s':''} worth alching`),
      natureRunePrice ? h('span', null, `Nature rune: ${fmt.gp(natureRunePrice)}gp`) : null,
      divineChargePrice ? h('span', null, `Divine charge: ${fmt.gp(divineChargePrice)}gp (${fmt.gp(chargePerItem)}gp/item)`) : null
    ),
    h('div', {className:'ge-table-wrap', style:{position:'relative'}, ref:cols.tableWrapRef},
    cols.handles(),
    h('table', {className:'ge-table', style:{tableLayout:'fixed', width:'max-content'}},
      cols.colgroup(),
      h('thead', null,
        h('tr', null, cols.colOrder.map(k => {
          const sortTh = (label) => cols.th(k, {
            className:'sortable', style:{cursor:'pointer'},
            onClick: () => setSort(s => ({key:k, dir: s.key===k ? -s.dir : -1})),
          }, label + (sort.key===k ? (sort.dir>0 ? ' ↑' : ' ↓') : ''));
          switch (k) {
            case 'name':       return sortTh('Item');
            case 'high':       return cols.th(k, {onClick:()=>setSort(s => ({key:'high', dir: s.key==='high' ? -s.dir : -1}))},
              'Live Price' + (sort.key==='high' ? (sort.dir>0 ? ' ↑' : ' ↓') : '')
            );
            case 'limit':      return sortTh('Buy Limit');
            case 'afterTax':   return sortTh('After Tax');
            case 'alch':       return sortTh('Alch Value');
            case 'alchProfit': return sortTh('Manual Profit');
            case 'alchemiserProfit': return cols.th(k, {
              className:'sortable', style:{cursor:'pointer'},
              onClick: () => setSort(s => ({key:k, dir: s.key===k ? -s.dir : -1})),
            },
              'Alchemiser Profit' + (sort.key===k ? (sort.dir>0 ? ' ↑' : ' ↓') : ''),
              h('span', {
                title:'The Alchemiser device cannot hold items worth more than 500,000gp. Items above that threshold can\'t be alchemised this way, regardless of profit.',
                style:{marginLeft:5, color:T.textDim, cursor:'help', fontSize:11, border:`1px solid ${T.textDim}`, borderRadius:'50%', width:14, height:14, display:'inline-flex', alignItems:'center', justifyContent:'center'},
              }, '?')
            );
            case 'star': return cols.th(k, {style:{width:30}}, null);
            default:     return cols.th(k, null, null);
          }
        }))
      ),
      h('tbody', null, sorted.map(it =>
        h('tr', {key:it.id, 'data-item-id':it.id,
          className: selected?.id===it.id ? 'selected' : '',
          onClick: () => onSelect(it)
        }, cols.colOrder.map(k => {
          switch (k) {
            case 'name': return h('td', {key:k}, it.name);
            case 'high': {
              const hasLive = it.liveBuy != null || it.liveSell != null;
              if (hasLive) {
                return h('td', {key:k},
                  h('div', {style:{display:'flex', gap:6, fontSize:11}},
                    it.liveBuy  != null && h('span', null, h('span',{style:{color:T.green}},'B '), fmt.gp(it.liveBuy)+'gp'),
                    it.liveSell != null && h('span', null, h('span',{style:{color:'#e08030'}},'S '), fmt.gp(it.liveSell)+'gp'),
                  ),
                  h('div', {className:'vol-avg'}, 'GE '+fmt.gp(it.high||it.low)+'gp'),
                );
              }
              return h('td', {key:k, style:{color:T.gold}}, fmt.gp(it.high||it.low)+'gp',
                h(LivePriceLine, {liveBuy:it.liveBuy, liveSell:it.liveSell}));
            }
            case 'limit': return h('td', {key:k, style:{color:T.textDim}}, it.limit ? fmt.gp(it.limit) : '—');
            case 'afterTax': return h('td', {key:k, style:{color:T.textDim}}, fmt.gp(it.afterTax)+'gp');
            case 'alch': return h('td', {key:k, style:{color:'#ce93d8'}}, fmt.gp(it.alch)+'gp');
            case 'alchProfit': return h('td', {key:k, style:{color: it.alchProfit > 0 ? T.green : T.red}},
              (it.alchProfit > 0 ? '+' : '') + fmt.gp(it.alchProfit)+'gp'
            );
            case 'alchemiserProfit': return it.price > 500000
              ? h('td', {key:k, style:{color:T.textDim}, title:'Over the Alchemiser\'s 500,000gp item value limit'}, 'N/A')
              : h('td', {key:k, style:{color: it.alchemiserProfit > 0 ? T.green : T.red}},
                  (it.alchemiserProfit > 0 ? '+' : '') + fmt.gp(it.alchemiserProfit)+'gp'
                );
            case 'star': return h('td', {key:k},
              h('button', {
                className:'star-btn',
                onClick: e => { e.stopPropagation(); onToggleWatch(it.id); }
              }, h('span', {className: watchlist.includes(it.id)?'star-on':'star-off'},
                watchlist.includes(it.id)?'★':'☆'
              ))
            );
            default: return h('td', {key:k}, null);
          }
        }))
      ))
    )
    )
  );
}

/* ─── Sidebar order editor ────────────────────────────────────── */
function SidebarOrderEditor({navItems, order, onChange}) {
  const ordered = useMemo(() => {
    if (!order || !order.length) return navItems;
    const byId = Object.fromEntries(navItems.map(n => [n.id, n]));
    const known = order.map(id => byId[id]).filter(Boolean);
    const newOnes = navItems.filter(n => !order.includes(n.id));
    return [...known, ...newOnes];
  }, [navItems, order]);

  const [dragIdx, setDragIdx] = useState(null);
  const [overIdx, setOverIdx] = useState(null);

  const onDrop = (idx) => {
    if (dragIdx === null) return;
    const arr = [...ordered];
    const [moved] = arr.splice(dragIdx, 1);
    arr.splice(idx, 0, moved);
    onChange(arr.map(n => n.id));
    setDragIdx(null); setOverIdx(null);
  };

  return h('div', null,
    ordered.map((item, idx) =>
      h('div', {
        key: item.id, draggable: true,
        className: 'drag-item' + (overIdx === idx ? ' drag-over' : ''),
        onDragStart: () => setDragIdx(idx),
        onDragOver:  e => { e.preventDefault(); setOverIdx(idx); },
        onDrop:      () => onDrop(idx),
        onDragEnd:   () => { setDragIdx(null); setOverIdx(null); },
        style: { opacity: dragIdx === idx ? 0.4 : 1 }
      },
        h('span', {style:{color:T.textDim, fontSize:14}}, '⠿'),
        h('span', {style:{fontSize:13}}, item.icon),
        h('span', {style:{fontSize:12, color:T.text}}, item.label)
      )
    )
  );
}

/* ─── GP input with K/M/B shorthand ──────────────────────────── */
// Price target backtesting (Ben, 2026-10-06): under any price target
// (alert threshold, Portfolio target/stop-loss, Buy Planner max price),
// how often the item actually traded there over the past year and when it
// last did. Daily prices from saved history + GEnius's own snapshots, one
// price per day. `direction` is 'above' (target is a high to reach) or
// 'below' (a low to reach / a floor).
const _oddsCache = new Map(); // itemId -> {at, days:[{ts, price}]} for this session
async function loadDailyPrices(itemId) {
  const hit = _oddsCache.get(itemId);
  if (hit && Date.now() - hit.at < 10 * 60000) return hit.days;
  const [hist, snaps] = await Promise.all([
    window.genius?.getItemHistoryLocal(itemId).catch(() => null),
    window.genius?.getPriceSnapshots(itemId).catch(() => null),
  ]);
  const byDay = new Map();
  for (const pt of [...(hist || []), ...(snaps || [])]) {
    if (!pt.price) continue;
    const ts = pt.timestamp > 1e12 ? pt.timestamp : pt.timestamp * 1000;
    const day = Math.floor(ts / 86400000);
    const prev = byDay.get(day);
    if (!prev || ts > prev.ts) byDay.set(day, {ts, price: pt.price});
  }
  const days = [...byDay.values()].sort((a, b) => a.ts - b.ts);
  _oddsCache.set(itemId, {at: Date.now(), days});
  return days;
}

// Live (instant-buy/sell) daily averages from the wiki's live price API —
// only goes back to late July 2026, but it's what offers actually fill at:
// a buy offer fills against instant-sells, a sell offer against instant-buys.
const _liveOddsCache = new Map();
async function loadLiveDaily(itemId) {
  const hit = _liveOddsCache.get(itemId);
  if (hit && Date.now() - hit.at < 10 * 60000) return hit.days;
  const ts = await window.genius?.getItemLiveTimeseries(itemId, '1y').catch(() => null);
  const days = (ts || []).filter(p => p.instabuy != null || p.instasell != null);
  _liveOddsCache.set(itemId, {at: Date.now(), days});
  return days;
}

function PriceTargetOdds({items, itemName, target, direction}) {
  const [days, setDays] = useState(null);
  const [live, setLive] = useState(null);
  const item = useMemo(() => (items || []).find(i => i.name.toLowerCase() === String(itemName || '').toLowerCase()), [items, itemName]);
  const t = Number(target) || 0;
  useEffect(() => {
    if (!item || item.untradeable) { setDays(null); return; }
    let stale = false;
    loadDailyPrices(item.id).then(d => { if (!stale) setDays(d); });
    loadLiveDaily(item.id).then(d => { if (!stale) setLive(d); });
    return () => { stale = true; };
  }, [item?.id]);
  if (!item || !(t > 0) || !days || days.length < 7) return null;

  // Live line: buy-side targets vs the day's average instant-sell price
  // (what buy offers fill at), sell-side vs average instant-buy.
  let liveLine = null;
  const liveKey = direction === 'below' ? 'instasell' : 'instabuy';
  const liveDays = (live || []).filter(p => p[liveKey] != null);
  if (liveDays.length >= 7) {
    const lHits = p => direction === 'below' ? p[liveKey] <= t : p[liveKey] >= t;
    const lPct = liveDays.filter(lHits).length / liveDays.length * 100;
    let lLast = null;
    for (let i = liveDays.length - 1; i >= 0; i--) if (lHits(liveDays[i])) { lLast = liveDays[i]; break; }
    const lAgo = lLast ? Math.floor((Date.now() - lLast.timestamp) / 86400000) : null;
    const lSince = new Date(liveDays[0].timestamp).toLocaleDateString(undefined, {month:'short', day:'numeric'});
    const lColor = lPct >= 25 ? T.green : lPct >= 5 ? T.gold : T.red;
    liveLine = h('div', {title:`Daily average ${direction === 'below' ? 'instant-sell' : 'instant-buy'} price from the live price API: what ${direction === 'below' ? 'buy' : 'sell'} offers actually fill at. Data starts ${lSince}.`},
      '⚡ Live: ', h('span', {style:{color:lColor}}, `${lPct < 1 && lPct > 0 ? '<1' : Math.round(lPct)}% of days`),
      ` since ${lSince} · `, lLast == null ? 'not yet' : lAgo <= 1 ? 'last: today' : `last: ${lAgo} days ago (${fmt.gp(Math.round(lLast[liveKey]))}gp)`);
  }

  const hits = p => direction === 'below' ? p.price <= t : p.price >= t;
  const yearAgo = Date.now() - 365 * 86400000;
  const year = days.filter(d => d.ts >= yearAgo);
  const pctYear = year.length ? year.filter(hits).length / year.length * 100 : null;
  let last = null;
  for (let i = days.length - 1; i >= 0; i--) if (hits(days[i])) { last = days[i]; break; }
  const daysAgo = last ? Math.floor((Date.now() - last.ts) / 86400000) : null;
  const sinceLabel = new Date(days[0].ts).toLocaleDateString(undefined, {month:'short', year:'numeric'});
  const word = direction === 'below' ? 'at or below' : 'at or above';
  const lastText = last == null ? `never since ${sinceLabel}`
    : daysAgo <= 1 ? 'last: today' : `last: ${daysAgo} days ago (${fmt.gp(last.price)}gp)`;
  const color = pctYear == null ? T.textDim : pctYear >= 25 ? T.green : pctYear >= 5 ? T.gold : T.red;
  return h('div', {style:{fontSize:11, color:T.textDim, marginTop:4, lineHeight:1.5}},
    h('div', {title:`Share of days in the past year the GE guide price was ${word} ${t.toLocaleString()}gp, from saved price history.`},
      '📊 GE: ', h('span', {style:{color}}, pctYear == null ? '—' : `${pctYear < 1 && pctYear > 0 ? '<1' : Math.round(pctYear)}% of days`),
      ` ${word} this in the past year · ${lastText}`),
    liveLine);
}

function GpInput({value, onChange, placeholder, style}) {
  const [raw, setRaw] = useState(value ? String(value) : '');

  useEffect(() => {
    // Sync if parent value changes externally (e.g. edit mode)
    if (value !== undefined && value !== '' && value !== null) {
      setRaw(String(value));
    }
  }, []);

  const parsed = parseGP(raw);
  const preview = (raw.length > 0 && typeof parsed === 'number' && String(parsed) !== raw)
    ? fmt.gp(parsed) + 'gp'
    : null;

  const handleChange = e => {
    const v = e.target.value;
    setRaw(v);
    const p = parseGP(v);
    onChange(typeof p === 'number' ? p : v);
  };

  const handleBlur = () => {
    const p = parseGP(raw);
    if (typeof p === 'number') {
      setRaw(String(p));
      onChange(p);
    }
  };

  return h('div', {style:{position:'relative'}},
    h('input', {
      className:'ge-input', type:'text', placeholder: placeholder || '0',
      value: raw, onChange: handleChange, onBlur: handleBlur,
      style: {...(style||{}), paddingRight: preview ? 60 : undefined}
    }),
    preview && h('span', {style:{
      position:'absolute', right:8, top:'50%', transform:'translateY(-50%)',
      fontSize:10, color:T.gold, pointerEvents:'none', whiteSpace:'nowrap'
    }}, preview)
  );
}

/* ─── Quantity input with K/M/B shorthand ─────────────────────── */
function QtyInput({value, onChange, placeholder, min, max, style}) {
  const [raw, setRaw] = useState(value != null ? String(value) : '');

  useEffect(() => {
    if (value != null && value !== '') setRaw(String(value));
  }, []);

  const parsed = parseGP(raw);
  const preview = (raw.length > 0 && typeof parsed === 'number' && String(parsed) !== raw)
    ? fmt.gp(parsed)
    : null;

  const handleChange = e => {
    const v = e.target.value;
    setRaw(v);
    const p = parseGP(v);
    if (typeof p === 'number') {
      const clamped = Math.round(Math.max(min ?? 1, max != null ? Math.min(p, max) : p));
      onChange(clamped);
    }
  };

  const handleBlur = () => {
    const p = parseGP(raw);
    if (typeof p === 'number') {
      const clamped = Math.round(Math.max(min ?? 1, max != null ? Math.min(p, max) : p));
      setRaw(String(clamped));
      onChange(clamped);
    }
  };

  return h('div', {style:{position:'relative'}},
    h('input', {
      className:'ge-input', type:'text', placeholder: placeholder || '0',
      value: raw, onChange: handleChange, onBlur: handleBlur,
      style: {...(style||{}), paddingRight: preview ? 50 : undefined}
    }),
    preview && h('span', {style:{
      position:'absolute', right:8, top:'50%', transform:'translateY(-50%)',
      fontSize:10, color:T.gold, pointerEvents:'none', whiteSpace:'nowrap'
    }}, preview)
  );
}

/* ─── Item autocomplete ───────────────────────────────────────── */
function ItemAutocomplete({items, value, onChange, placeholder, userShorthands}) {
  const [query, setQuery] = useState(value||'');
  const [open, setOpen] = useState(false);

  useEffect(() => { setQuery(value||''); }, [value]);

  // Same shorthand resolution as the main search bar (GESearchBar/
  // useSearch) — this input previously did a plain substring match
  // only, so typing a shorthand like "FSOA" here (Alerts, Reminders,
  // Portfolio) came up empty even though it works fine in the main
  // search bar. A shorthand can expand to several terms (e.g. ZGS ->
  // both godswords), so results are merged and deduped by item id.
  const filtered = useMemo(() => {
    if (!query || query.length < 2) return [];
    const resolved = resolveShorthand(query, userShorthands || {});
    const terms = resolved || [query];
    const q0 = query.toLowerCase();
    const seen = new Set();
    const out = [];
    for (const term of terms) {
      const q = term.toLowerCase();
      for (const it of items) {
        if (seen.has(it.id)) continue;
        if (it.name.toLowerCase().includes(q) || it.name.toLowerCase().includes(q0)) {
          seen.add(it.id);
          out.push(it);
        }
      }
    }
    return out.slice(0, 25);
  }, [items, query, userShorthands]);

  return h('div', {style:{position:'relative'}},
    h('input', {
      className:'ge-input',
      value: query,
      placeholder: placeholder || 'Search item...',
      autoComplete: 'off',
      onChange: e => { setQuery(e.target.value); onChange(e.target.value); setOpen(true); },
      onFocus:  () => setOpen(true),
      onBlur:   () => setTimeout(() => setOpen(false), 150),
      style: {marginBottom: 0}
    }),
    open && filtered.length > 0 && h('div', {style:{
      position:'absolute', top:'100%', left:0, right:0, zIndex:200,
      background:T.panel, border:`1px solid ${T.border}`, borderRadius:3,
      maxHeight:200, overflowY:'auto', boxShadow:'0 4px 16px rgba(0,0,0,0.6)'
    }},
      filtered.map(it =>
        h('div', {
          key:it.id,
          style:{padding:'6px 10px', cursor:'pointer', fontSize:12, borderBottom:`1px solid ${T.borderDim}`, display:'flex', justifyContent:'space-between', alignItems:'center'},
          onMouseDown: () => { setQuery(it.name); onChange(it.name); setOpen(false); }
        },
          h('span', {style:{color:T.text}}, it.name),
          h('span', {style:{color:T.textDim, fontSize:10}}, fmt.gp(it.high||it.low)+'gp')
        )
      )
    )
  );
}

/* ─── Position modal ──────────────────────────────────────────── */
function PositionModal({items, position, onSave, onClose, userShorthands}) {
  const todayStr = (d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`)(new Date()); // local date, not UTC
  const blank = { id:Date.now().toString(), item_name:'', quantity:'', cost_basis:'',
    target_price:'', target_profit_pct:'', stop_loss:'', status:'open', created_at:new Date().toISOString(), date_opened: todayStr };
  const [form, setForm] = useState(position ? {...position,
    target_price: position.target_price||'',
    stop_loss: position.stop_loss||'',
    target_profit_pct: position.target_profit_pct||'',
    date_opened: position.date_opened || (position.created_at ? position.created_at.slice(0,10) : todayStr),
  } : blank);
  const [createAlert, setCreateAlert] = useState(false);
  // Same per-item/total-sale toggle as SellModal (Ben, 2026-07-31) — total
  // mode writes the derived per-item price straight into form.sold_price
  // as you type, so handleSave never needs to know which mode was used.
  const [soldPriceMode, setSoldPriceMode] = useState('perItem');
  const [soldTotalPrice, setSoldTotalPrice] = useState('');
  const set = k => e => setForm(f => ({...f, [k]:e.target.value}));
  const totalCost = form.quantity && form.cost_basis ? Number(form.quantity) * Number(form.cost_basis) : 0;

  // Escape still closes it — only the backdrop-click was the problem
  // (silently discarding in-progress input from a stray click), Escape is
  // an explicit, deliberate "get me out of here" the same way Cancel is.
  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const handleSave = () => {
    if (!form.item_name || !form.quantity || !form.cost_basis) return;
    const payload = {...form,
      quantity: Number(form.quantity),
      cost_basis: Number(form.cost_basis),
      target_price: form.target_price ? Number(form.target_price) : null,
      stop_loss: form.stop_loss ? Number(form.stop_loss) : null,
      target_profit_pct: form.target_profit_pct ? Number(form.target_profit_pct) : null,
    };
    if (form.status === 'sold' && form.sold_price) {
      const sq = Number(form.sold_quantity || form.quantity);
      const sp = Number(form.sold_price);
      payload.sold_price = sp;
      payload.sold_quantity = sq;
      // Keep quantity in sync with sold_quantity — a sold position's
      // quantity is supposed to always equal what was actually sold (see
      // sellPosition() in api.js). Editing sold_quantity here without
      // also updating quantity let the two silently drift apart, which
      // corrupted anything summing quantity directly (e.g. the Realized
      // P&L by Item breakdown) — caught for real (Ben, 2026-07-30): a
      // Dragon dart tip lot's quantity (3,148) and sold_quantity (3,461)
      // disagreed by exactly 313 after an edit.
      payload.quantity = sq;
      payload.realized_pl = saleNet(sp, sq) - Number(form.cost_basis) * sq;
    }
    onSave(payload, createAlert);
  };

  // No backdrop-click-to-close here (unlike most modals) — this one holds
  // in-progress form input (buy/sell/edit fields), and a stray click just
  // outside the box while typing was silently discarding whatever had been
  // entered so far. Confirmed for real (Ben, 2026-07-29): kept closing it
  // by accident while entering position data. Closing now requires the X
  // or Cancel button, an explicit action instead of an easy misclick.
  return h('div', {className:'modal-overlay'},
    h('div', {className:'modal'},
      h('div', {className:'modal-header'},
        h('div', {className:'detail-name', style:{fontSize:15}}, position ? 'Edit Position' : 'Add Position'),
        h('button', {className:'ge-btn', style:{padding:'2px 8px'}, onClick:onClose}, 'X')
      ),
      h('div', {className:'modal-body'},
        h('label', {className:'form-lbl'}, 'Item Name'),
        h(ItemAutocomplete, {
          items,
          value: form.item_name,
          onChange: name => setForm(f=>({...f, item_name:name})),
          placeholder: 'Search item...',
          userShorthands,
        }),
        h('div', {style:{marginBottom:12}}),

        h('div', {className:'form-grid-2'},
          h('div', null, h('label',{className:'form-lbl'},'Quantity'),
            h(QtyInput,{value:form.quantity, placeholder:'e.g. 100k', min:1, onChange:v=>setForm(f=>({...f,quantity:v}))})),
          h('div', null, h('label',{className:'form-lbl'},'Cost Basis (per item)'),
            h(GpInput,{value:form.cost_basis, placeholder:'Price paid each', onChange:v=>setForm(f=>({...f,cost_basis:v}))}))
        ),

        totalCost > 0 && h('div', {style:{fontSize:11,color:T.textDim,marginBottom:12}},
          `Total cost: ${fmt.gp(totalCost)}gp`),

        // Sold-position correction — the whole reason to click into a closed
        // position instead of just viewing it (Ben's ask, 2026-07-29): fixing
        // a wrong sale entry used to mean Reopen -> re-Sell just to correct
        // one typo'd price. Realized P/L recomputes live as these change,
        // using the same net = price*qty*0.98 formula sellPosition() itself
        // uses, so the preview always matches what actually gets saved.
        form.status === 'sold' && h('div', {style:{marginBottom:12}},
          h('div', {className:'ge-section-head'}, 'Sold Details'),
          h('div', {style:{display:'flex', gap:4, marginBottom:8}},
            ['perItem','total'].map(m => h('button', {
              key:m, onClick:()=>setSoldPriceMode(m),
              style:{
                padding:'3px 10px', fontSize:10, cursor:'pointer', borderRadius:3,
                background: soldPriceMode===m ? 'rgba(201,168,76,0.2)' : 'transparent',
                border: `1px solid ${soldPriceMode===m ? T.gold : T.border}`,
                color: soldPriceMode===m ? T.goldBright : T.textDim,
              }
            }, m==='perItem' ? 'Price per item' : 'Total sale price'))
          ),
          h('div', {className:'form-grid-2'},
            soldPriceMode === 'total'
              ? h('div', null, h('label',{className:'form-lbl'},'Total Sale Price'),
                  h(GpInput,{value:soldTotalPrice, placeholder:'Total gp received', onChange:v=>{
                    setSoldTotalPrice(v);
                    const q = Number(form.sold_quantity || form.quantity) || 0;
                    setForm(f=>({...f, sold_price: q > 0 ? Math.round((Number(v)||0)/q) : f.sold_price}));
                  }}))
              : h('div', null, h('label',{className:'form-lbl'},'Sold Price (per item)'),
                  h(GpInput,{value:form.sold_price||'', placeholder:'Price sold each', onChange:v=>setForm(f=>({...f,sold_price:v}))})),
            h('div', null, h('label',{className:'form-lbl'},'Sold Quantity'),
              h(QtyInput,{value:form.sold_quantity||form.quantity, placeholder:'Qty sold', min:1, onChange:v=>setForm(f=>({...f,sold_quantity:v}))})),
          ),
          soldPriceMode === 'total' && form.sold_price > 0 && h('div', {style:{fontSize:11, color:T.textDim, marginTop:4}},
            `= ${fmt.gp(form.sold_price)}gp per item`
          ),
          (form.sold_price && (form.sold_quantity||form.quantity)) && (() => {
            const sq = Number(form.sold_quantity||form.quantity), sp = Number(form.sold_price);
            const net = saleNet(sp, sq);
            const pl = net - Number(form.cost_basis||0) * sq;
            return h('div', {style:{fontSize:11,color:T.textDim,marginTop:6}},
              'Realized P/L: ', h('span',{style:{color: pl>=0?T.green:T.red, fontWeight:'bold'}}, (pl>=0?'+':'')+fmt.gp(pl)+'gp'));
          })(),
        ),

        h('div', {className:'form-grid-2', style:{marginBottom:12}},
          h('div', null,
            h('label',{className:'form-lbl'},'Date Opened'),
            h('div', {style:{display:'flex', gap:6, alignItems:'center'}},
              h('input',{className:'ge-input', id:'date-opened-input', type:'date', value:form.date_opened, onChange:set('date_opened'), style:{flex:1}}),
              h('button', {
                className:'ge-btn',
                style:{padding:'4px 8px', fontSize:14},
                title:'Pick a date',
                onClick: () => { const el = document.getElementById('date-opened-input'); el && (el.showPicker ? el.showPicker() : el.click()); },
              }, '📅')
            )
          )
        ),

        h('div', {className:'ge-section-head'}, 'Optional Targets'),
        h('div', {className:'form-grid-3'},
          h('div', null, h('label',{className:'form-lbl'},'Target Price'),
            h(GpInput,{value:form.target_price, placeholder:'Exit price', onChange:v=>setForm(f=>({...f,target_price:v}))}),
            h(PriceTargetOdds,{items, itemName:form.item_name, target:form.target_price, direction:'above'})),
          h('div', null, h('label',{className:'form-lbl'},'Target Profit %'),
            h('input',{className:'ge-input',type:'number',placeholder:'e.g. 15',value:form.target_profit_pct,onChange:set('target_profit_pct')})),
          h('div', null, h('label',{className:'form-lbl'},'Stop-Loss Price'),
            h(GpInput,{value:form.stop_loss, placeholder:'Floor price', onChange:v=>setForm(f=>({...f,stop_loss:v}))}),
            h(PriceTargetOdds,{items, itemName:form.item_name, target:form.stop_loss, direction:'below'}))
        ),

        form.target_price && h('label', {className:'row', style:{gap:8,marginBottom:12,cursor:'pointer',fontSize:11}},
          h('input',{type:'checkbox',checked:createAlert,onChange:e=>setCreateAlert(e.target.checked)}),
          h('span',null,'Create GE alert when target price is reached')
        ),

        h('div', {style:{display:'flex',gap:8,justifyContent:'flex-end',marginTop:8}},
          h('button',{className:'ge-btn',onClick:onClose},'Cancel'),
          h('button',{className:'ge-btn gold',onClick:handleSave}, position?'Update':'Add Position')
        )
      )
    )
  );
}

/* ─── Sell modal ──────────────────────────────────────────────── */
function SellModal({position, item, onSell, onClose}) {
  // Per-item vs. total-sale-price toggle (Ben, 2026-07-31): the GE itself
  // shows an average price per item on the sale summary screen, but
  // logging a position still meant manually dividing that back out by
  // hand every time — annoying for e.g. converting 25k Incandescent
  // energy into Divine charges and selling the batch as one lump sum.
  // Both inputs are kept in their own state (not derived from each
  // other) so toggling back and forth doesn't lose what you typed due to
  // rounding.
  const [priceMode, setPriceMode] = useState('perItem'); // 'perItem' | 'total' | 'alch'
  const [sellPrice, setSellPrice] = useState(position.currentPrice || '');
  const [totalPrice, setTotalPrice] = useState('');
  const [qty, setQty] = useState(position.quantity);
  const q = Number(qty);
  // High alch (Ben, 2026-10-26): no GE tax, one nature rune per cast, so the
  // "price" is the alch value minus a nature rune. Offered when the item has one.
  const alchValue = item?.alch || 0;
  const naturePrice = item?.natureRunePrice || 0;
  const alchNet = Math.max(0, alchValue - naturePrice);
  const isAlch = priceMode === 'alch';
  const sp = isAlch ? alchNet
    : priceMode === 'total'
    ? (q > 0 ? Math.round((Number(totalPrice) || 0) / q) : 0)
    : (typeof sellPrice === 'number' ? sellPrice : Number(sellPrice) || 0);
  const gross = isAlch ? alchValue * q : sp * q;
  const net   = isAlch ? alchNet * q : saleNet(sp, q);
  const tax   = isAlch ? 0 : gross - net;
  const cost  = position.cost_basis * q;
  const pl    = net - cost;

  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  // No backdrop-click-to-close here (unlike most modals) — this one holds
  // in-progress form input (buy/sell/edit fields), and a stray click just
  // outside the box while typing was silently discarding whatever had been
  // entered so far. Confirmed for real (Ben, 2026-07-29): kept closing it
  // by accident while entering position data. Closing now requires the X
  // or Cancel button, an explicit action instead of an easy misclick.
  return h('div', {className:'modal-overlay'},
    h('div', {className:'modal'},
      h('div', {className:'modal-header'},
        h('div', {className:'detail-name', style:{fontSize:15}}, `${isAlch ? 'Alch' : 'Sell'}: ${position.item_name}`),
        h('button', {className:'ge-btn', style:{padding:'2px 8px'}, onClick:onClose}, 'X')
      ),
      h('div', {className:'modal-body'},
        h('div', {style:{display:'flex', gap:4, marginBottom:10}},
          ['perItem','total', ...(alchValue > 0 ? ['alch'] : [])].map(m => h('button', {
            key:m, onClick:()=>setPriceMode(m),
            style:{
              padding:'3px 10px', fontSize:10, cursor:'pointer', borderRadius:3,
              background: priceMode===m ? 'rgba(201,168,76,0.2)' : 'transparent',
              border: `1px solid ${priceMode===m ? T.gold : T.border}`,
              color: priceMode===m ? T.goldBright : T.textDim,
            }
          }, m==='perItem' ? 'Price per item' : m==='total' ? 'Total sale price' : 'High alch'))
        ),
        h('div', {className:'form-grid-2'},
          isAlch
            ? h('div', null, h('label',{className:'form-lbl'},'Alch value (per item)'),
                h('div', {style:{fontSize:13, color:T.gold, padding:'6px 0'}},
                  `${fmt.gp(alchValue)}gp − ${fmt.gp(naturePrice)}gp nature rune = ${fmt.gp(alchNet)}gp`))
          : priceMode === 'total'
            ? h('div', null, h('label',{className:'form-lbl'},'Total Sale Price'),
                h(GpInput,{value:totalPrice, onChange:v=>setTotalPrice(v), placeholder:'Total gp received'}))
            : h('div', null, h('label',{className:'form-lbl'},'Sell Price (per item)'),
                h(GpInput,{value:sellPrice, onChange:v=>setSellPrice(v), placeholder:'Sell price'})),
          h('div', null, h('label',{className:'form-lbl'},`Quantity (max ${position.quantity})`),
            h(QtyInput,{value:qty, min:1, max:position.quantity, onChange:v=>setQty(v)}))
        ),

        priceMode === 'total' && sp > 0 && h('div', {style:{fontSize:11, color:T.textDim, marginBottom:12, marginTop:-6}},
          `= ${fmt.gp(sp)}gp per item`
        ),

        sp > 0 && h('div', {style:{background:'rgba(0,0,0,0.25)',borderRadius:4,padding:'10px',marginBottom:12}},
          h('div', {className:'ge-section-head', style:{fontSize:10,marginBottom:6}}, isAlch ? 'What if I alched now?' : 'What if I sold now?'),
          [[isAlch ? 'Alch Value' : 'Gross Sale Value', fmt.gp(gross)+'gp', null],
           isAlch ? ['Nature Runes', '-'+fmt.gp(naturePrice * q)+'gp', T.red] : ['GE Tax (2%)', '-'+fmt.gp(tax)+'gp', T.red],
           ['Net Proceeds',     fmt.gp(net)+'gp', null],
           ['Cost Basis',       '-'+fmt.gp(cost)+'gp', null],
           ['Net P&L',          (pl>=0?'+':'')+fmt.gp(pl)+'gp', pl>=0?T.green:T.red],
          ].map(([l,v,c])=>h('div',{key:l,style:{display:'flex',justifyContent:'space-between',fontSize:11,marginBottom:3}},
            h('span',{style:{color:T.textDim}},l),
            h('span',{style:{color:c||T.text}},v)
          ))
        ),

        h('div', {style:{display:'flex',gap:8,justifyContent:'flex-end'}},
          h('button',{className:'ge-btn',onClick:onClose},'Cancel'),
          h('button',{className:'ge-btn gold',disabled:!sp||sp<=0,
            onClick:()=>onSell({id:position.id,sell_price:sp,quantity:q, ...(isAlch ? {alch:true} : {})})
          }, isAlch ? 'Confirm Alch' : 'Confirm Sale')
        )
      )
    )
  );
}

// Looks up a known 1:1 Invention machine conversion (Plank Maker/Hide
// Tanner/Partial Potion Producer — see INVENTION_MACHINES above) for a
// given input item name, if one exists. Used by ConvertModal to auto-fill
// the output item and a real machine-charge cost instead of leaving Ben
// to type both in and compute the charge cost by hand — the exact
// reliability gap the Portfolio Convert action was built to close.
function findConversionRecipe(inputItemName, items) {
  const nameLower = (inputItemName || '').toLowerCase().trim();
  for (const machine of INVENTION_MACHINES) {
    const conv = machine.conversions.find(c => c.input.toLowerCase() === nameLower);
    if (conv) {
      return {
        machineLabel: machine.label,
        output: conv.output,
        costPerUnit: Math.round(machine.chargePerItem * machineChargeGpRate(items)),
      };
    }
  }
  return null;
}

function ConvertModal({position, allItems, onConvert, onClose, userShorthands, otherPositions = []}) {
  const [qty, setQty] = useState(position.quantity);
  // More inputs used up by the same conversion (Ben, 2026-10-26: bolt tips
  // + bolts fletched together). Each row: one of your other open positions
  // and how many of it go in.
  const [extraInputs, setExtraInputs] = useState([]);
  const addInput = () => {
    const free = otherPositions.find(p => !extraInputs.some(x => x.id === p.id));
    // Same amount as the main input by default (1 tip + 1 bolt = 1 tipped bolt).
    if (free) setExtraInputs(rows => [...rows, {id: free.id, qty: Math.min(free.quantity, Number(qty) || free.quantity)}]);
  };
  const setInput = (i, patch) => setExtraInputs(rows => rows.map((r, j) => j === i ? {...r, ...patch} : r));
  const removeInput = i => setExtraInputs(rows => rows.filter((_, j) => j !== i));
  const posById = id => otherPositions.find(p => p.id === id);
  const [outputName, setOutputName] = useState('');
  const [outputQty, setOutputQty] = useState('');
  const [extraCosts, setExtraCosts] = useState([{label:'', amount:''}]);
  // GpInput only reads its `value` prop into its own display state on
  // initial mount, not on every re-render (by design — otherwise it'd
  // stomp on whatever the user's actively typing). That means
  // useRecipe() setting extraCosts programmatically after the fields
  // already exist wouldn't visibly update the amount field even though
  // the real state was correct underneath. Bumping this on every
  // recipe-fill forces the GpInput row to remount and pick up the new
  // value fresh, same fix pattern as any other "controlled input needs a
  // hard reset" case.
  const [fillVersion, setFillVersion] = useState(0);

  const recipe = useMemo(() => findConversionRecipe(position.item_name, allItems), [position.item_name, allItems]);
  // BUG (Ben, 2026-09-15): "Use this" filled Output Quantity and the
  // recipe's charge-cost row as one-time snapshots of Quantity AT CLICK
  // TIME — neither stayed in sync if Quantity was edited afterward (a very
  // natural flow: click Use This to see the recipe, then dial in the real
  // quantity). Repro caught for real: converted 7,500 Eternal magic logs,
  // but the Plank Maker charge cost still read 17,668,800gp — 360.45/item
  // × 49,080 (the modal's own MAX), not × 7,500. Fixed by keeping both
  // fields "linked" to Quantity via the effect below until the user
  // manually edits either one directly, at which point that field stops
  // auto-tracking (their manual value is respected, not stomped on).
  const [outputQtyLinked, setOutputQtyLinked] = useState(false);
  const [costLinked, setCostLinked] = useState(false);

  const useRecipe = () => {
    if (!recipe) return;
    setOutputName(recipe.output);
    setOutputQty(String(qty));
    setExtraCosts([{label: `${recipe.machineLabel} charge cost`, amount: String(recipe.costPerUnit * Number(qty || 0))}]);
    setFillVersion(v => v + 1);
    setOutputQtyLinked(true);
    setCostLinked(true);
  };

  const addCostRow = () => { setExtraCosts(rows => [...rows, {label:'', amount:''}]); setCostLinked(false); };
  const removeCostRow = i => { setExtraCosts(rows => rows.filter((_,j)=>j!==i)); setCostLinked(false); };
  const setCostRow = (i, field, val) => { setExtraCosts(rows => rows.map((r,j) => j===i ? {...r, [field]:val} : r)); setCostLinked(false); };

  const q = Number(qty) || 0;

  useEffect(() => {
    if (!recipe) return;
    if (outputQtyLinked) setOutputQty(String(q));
    if (costLinked) {
      setExtraCosts([{label: `${recipe.machineLabel} charge cost`, amount: String(recipe.costPerUnit * q)}]);
      setFillVersion(v => v + 1);
    }
  }, [q]);
  const oq = Number(outputQty) || 0;
  const totalExtraCost = extraCosts.reduce((s,r) => s + (Number(r.amount) || 0), 0);
  const inputCostUsed = position.cost_basis * q + extraInputs.reduce((s, r) => {
    const p = posById(r.id);
    return s + (p ? p.cost_basis * Math.min(Number(r.qty) || 0, p.quantity) : 0);
  }, 0);
  const totalCost = inputCostUsed + totalExtraCost;
  const newCostBasis = oq > 0 ? Math.round(totalCost / oq) : 0;

  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  return h('div', {className:'modal-overlay'},
    h('div', {className:'modal'},
      h('div', {className:'modal-header'},
        h('div', {className:'detail-name', style:{fontSize:15}}, `Convert: ${position.item_name}`),
        h('button', {className:'ge-btn', style:{padding:'2px 8px'}, onClick:onClose}, 'X')
      ),
      h('div', {className:'modal-body'},
        recipe && h('div', {style:{marginBottom:12, padding:'8px 10px', background:'rgba(201,168,76,0.08)', border:`1px solid ${T.borderDim}`, borderRadius:4, display:'flex', alignItems:'center', justifyContent:'space-between', gap:10}},
          h('span', {style:{fontSize:11, color:T.textDim}}, `Known recipe: ${recipe.machineLabel} → ${recipe.output} (${fmt.gp(recipe.costPerUnit)}gp/item charge)`),
          h('button', {className:'ge-btn', style:{padding:'2px 8px', fontSize:11}, onClick:useRecipe}, 'Use this')
        ),
        h('div', {className:'form-grid-2'},
          h('div', null, h('label',{className:'form-lbl'},`Quantity to convert (max ${position.quantity})`),
            h(QtyInput,{value:qty, min:1, max:position.quantity, onChange:v=>setQty(v)})),
          h('div', null, h('label',{className:'form-lbl'},'Output item'),
            h(ItemAutocomplete,{items:allItems, value:outputName, onChange:setOutputName, placeholder:'Search item...', userShorthands}))
        ),
        h('div', {style:{marginBottom:12}},
          extraInputs.length > 0 && h('label',{className:'form-lbl'},'Also used up in this conversion'),
          extraInputs.map((r, i) => {
            const p = posById(r.id);
            return h('div', {key:i, style:{display:'flex', gap:6, marginBottom:6, alignItems:'center'}},
              h('select', {className:'ge-input', style:{flex:1}, value:r.id,
                onChange:e => { const np = posById(e.target.value); setInput(i, {id: e.target.value, qty: np ? Math.min(np.quantity, Number(qty) || np.quantity) : r.qty}); }},
                otherPositions.filter(o => o.id === r.id || !extraInputs.some(x => x.id === o.id)).map(o =>
                  h('option', {key:o.id, value:o.id}, `${o.item_name} (${o.quantity.toLocaleString()} @ ${fmt.gp(o.cost_basis)}gp)`))),
              h(QtyInput, {value:r.qty, min:1, max:p ? p.quantity : 1, onChange:v => setInput(i, {qty: v})}),
              h('button', {className:'ge-btn danger', style:{padding:'2px 8px', fontSize:11}, onClick:() => removeInput(i)}, '×'));
          }),
          otherPositions.length > extraInputs.length && h('button', {className:'ge-btn', style:{fontSize:11, padding:'3px 10px'}, onClick:addInput,
            title:'For conversions that use up more than one item, like bolt tips + bolts fletched together'}, '+ Add another input')
        ),
        h('div', {style:{marginBottom:12}},
          h('label',{className:'form-lbl'},'Output quantity'),
          h('input',{className:'ge-input', type:'number', min:1, value:outputQty, onChange:e=>{setOutputQty(e.target.value); setOutputQtyLinked(false);}, placeholder:'e.g. '+q, style:{width:120}})
        ),
        h('div', {style:{marginBottom:12}},
          h('label',{className:'form-lbl'},'Extra costs (machine charges, secondary ingredients, etc.)'),
          extraCosts.map((row,i) => h('div',{key:i, style:{display:'flex', gap:6, marginBottom:6, alignItems:'center'}},
            h('input',{className:'ge-input', style:{flex:1}, placeholder:'Label (optional)', value:row.label, onChange:e=>setCostRow(i,'label',e.target.value)}),
            h(GpInput,{key:`${i}-${fillVersion}`, value:row.amount, placeholder:'0gp', onChange:v=>setCostRow(i,'amount',v), style:{width:120}}),
            extraCosts.length>1 && h('button',{className:'ge-btn danger', style:{padding:'2px 8px', fontSize:11}, onClick:()=>removeCostRow(i)},'×')
          )),
          h('button',{className:'ge-btn', style:{fontSize:11, padding:'3px 10px'}, onClick:addCostRow}, '+ Add cost')
        ),

        oq > 0 && h('div', {style:{background:'rgba(0,0,0,0.25)',borderRadius:4,padding:'10px',marginBottom:12}},
          h('div', {className:'ge-section-head', style:{fontSize:10,marginBottom:6}}, 'Resulting position'),
          [['Input value used', fmt.gp(inputCostUsed)+'gp', null],
           ['Extra costs', fmt.gp(totalExtraCost)+'gp', null],
           ['New cost basis', fmt.gp(newCostBasis)+'gp / '+outputName, T.goldBright],
          ].map(([label,val,color],i) => h('div',{key:i,style:{display:'flex',justifyContent:'space-between',fontSize:12,marginBottom:i<2?4:0,color:color||T.text}},
            h('span',{style:{color:T.textDim}},label), h('span',null,val)
          ))
        ),

        h('div', {style:{display:'flex',gap:8,justifyContent:'flex-end'}},
          h('button',{className:'ge-btn',onClick:onClose},'Cancel'),
          h('button',{className:'ge-btn gold',disabled:!outputName||oq<=0||q<=0,
            onClick:()=>onConvert({id:position.id, quantity:q, outputItemName:outputName, outputQuantity:oq, extraCost:totalExtraCost,
              extraInputs: extraInputs.map(r => ({id: r.id, quantity: Number(r.qty) || 0}))})
          },'Confirm Conversion')
        )
      )
    )
  );
}

// Shows every tier in a ladder (Investor Tier / Trade Count), not just
// next/current/earned — the inline row only ever showed one tier ahead,
// with no way to see the full climb (Ben, 2026-07-30). `tiers` is in the
// same descending-threshold order as PORTFOLIO_TIERS/TRADE_COUNT_TIERS;
// `achievedIndex` is that same array's tierIndex (-1 if nothing earned
// yet) so this can mark earned/current/locked without recomputing it.
function TierLadderModal({title, tiers, achievedIndex, onClose}) {
  useEffect(() => {
    const onKey = e => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);

  const ascending = [...tiers].map((t, i) => ({...t, i})).reverse();

  return h('div', {className:'modal-overlay', onClick:e=>{if(e.target===e.currentTarget)onClose();}},
    h('div', {className:'modal', style:{maxWidth:420}},
      h('div', {className:'modal-header'},
        h('div', {className:'detail-name', style:{fontSize:15}}, title),
        h('button', {className:'ge-btn', style:{padding:'2px 8px'}, onClick:onClose}, 'X')
      ),
      h('div', {className:'modal-body', style:{maxHeight:480, overflowY:'auto'}},
        ascending.map(t => {
          const earned  = achievedIndex >= 0 && t.i > achievedIndex;
          const current = t.i === achievedIndex;
          const locked  = !earned && !current;
          return h('div', {key:t.label, style:{
            display:'flex', alignItems:'center', gap:10, padding:'8px 4px',
            borderBottom:`1px solid ${T.borderDim}`,
            opacity: locked ? 0.45 : 1,
          }},
            h('div', {style:{fontSize:20, filter:locked?'grayscale(1)':'none', minWidth:26, textAlign:'center'}}, t.icon),
            h('div', {style:{flex:1}},
              h('div', {style:{fontSize:12, fontWeight:'bold', color: current ? T.gold : T.text}}, t.label),
              h('div', {style:{fontSize:10, color:T.textDim}}, t.sub),
            ),
            current && h('span', {style:{fontSize:9, color:T.goldBright, border:`1px solid ${T.gold}`, borderRadius:3, padding:'1px 6px'}}, 'Current'),
            earned  && h('span', {style:{fontSize:12, color:T.green}}, '✓'),
          );
        })
      )
    )
  );
}

/* ─── Portfolio tab ───────────────────────────────────────────── */
// Position risk (Ben's friend's idea, 2026-11-04): how this item has behaved and how
// hard your stack would be to sell, never a forecast. The worst factor sets the level.
// Cut-offs measured once across ~3,000 items over a year (2026-11-04), aiming for the
// calmest third Low and the wildest 15% High. Spread's High is capped by hand at 40%
// (stale prices made the measured figure useless). Re-measure if the market shifts.
function positionRisk(quantity, item, days, heldSince) {
  const reasons = [];
  let level = 0;
  const add = (lvl, text) => { level = Math.max(level, lvl); reasons.push(text); };
  // No quantity means the item panel: how the item behaves, with no stack to judge.
  // Under 100gp a 1gp tick looks like a big % move, so swings don't raise the level.
  const cheap = (item.high || item.low || 0) < 100;
  if (quantity == null) {
    if (item.avgVolume > 0) add(0, `Trading: about ${Math.round(item.avgVolume).toLocaleString()} a day.`);
    else add(1, 'Trading: no volume data, so it could be hard to sell.');
  } else if (item.avgVolume > 0) {
    const d = quantity / item.avgVolume;
    add(d >= 5 ? 2 : d >= 1 ? 1 : 0, `Selling: your ${quantity.toLocaleString()} is ${d < 0.1 ? 'under 10% of' : d < 1 ? 'about ' + Math.round(d * 100) + '% of' : 'about ' + d.toFixed(1) + ' x'} a normal day's volume.`);
  } else add(1, 'Selling: no volume data, so it could be hard to sell.');
  if (item.liveBuy > 0 && item.liveSell > 0) {
    const s = (item.liveBuy - item.liveSell) / item.liveSell * 100;
    if (s < 0) reasons.push('Spread: live buy and sell prices don\'t line up right now, so this isn\'t counted.');
    else add(cheap ? 0 : s >= 40 ? 2 : s >= 25 ? 1 : 0, `Spread: live buy and sell are ${s.toFixed(1)}% apart.`);
  }
  // The whole time you've held it, and at least 90 days so a new buy still has context.
  const from = Math.min(Date.now() - 90 * 86400000, heldSince || Infinity);
  const spanDays = Math.round((Date.now() - from) / 86400000);
  const recent = (days || []).filter(x => x.ts >= from);
  if (recent.length >= 10) {
    let moves = 0, peak = 0, drop = 0;
    recent.forEach((x, i) => {
      if (i) moves += Math.abs(x.price - recent[i - 1].price) / recent[i - 1].price * 100;
      peak = Math.max(peak, x.price);
      drop = Math.max(drop, (peak - x.price) / peak * 100);
    });
    const swing = moves / (recent.length - 1);
    if (cheap) reasons.push('Under 100gp, so percent moves are mostly small ticks and do not count here.');
    add(cheap ? 0 : swing >= 1.8 ? 2 : swing >= 0.7 ? 1 : 0, `Swings: moves about ${swing.toFixed(1)}% on a typical day (${spanDays} days of GE prices).`);
    add(cheap ? 0 : drop >= 75 ? 2 : drop >= 45 ? 1 : 0, `Biggest drop: ${drop.toFixed(0)}% from a high in the last ${spanDays} days.`);
  } else if (quantity == null) return null; // Too little to say anything about the item alone.
  else reasons.push('Not enough price history to judge swings.');
  // Barely trading: a flat price means little, and you may not be able to sell.
  if (item.avgVolume > 0 && item.avgVolume < 20) add(1, 'Thin market: trades under 20 a day, so a steady price says little.');
  const name = ['Low', 'Medium', 'High'][level];
  return { signal: 'RISK_' + name.toUpperCase(), label: (quantity == null ? 'ITEM RISK: ' : 'POSITION RISK: ') + name.toUpperCase(),
    details: h('div', null, reasons.map((r, i) => h('div', {key:i, style:{marginBottom:3}}, r)),
      h('div', {style:{color:T.textDim, marginTop:4}}, 'About behaviour and selling, not where the price goes next.')) };
}

// Net worth over time (Ben, 2026-11-10): one point per day from net_worth.json,
// recorded after each fetch (open positions at live sell after tax, and cost).
function NetWorthChart() {
  const [open, setOpen] = useState(() => { try { return localStorage.getItem('genius_networth_open') !== '0'; } catch { return true; } });
  const [rows, setRows] = useState(null);
  const [hover, setHover] = useState(null);
  useEffect(() => {
    if (!window.genius?.getNetWorthHistory) return;
    (window.genius.recordNetWorth ? window.genius.recordNetWorth().catch(() => null) : Promise.resolve())
      .then(() => window.genius.getNetWorthHistory()).then(r => setRows(r || [])).catch(() => setRows([]));
  }, []);
  const toggle = () => setOpen(v => { try { localStorage.setItem('genius_networth_open', v ? '0' : '1'); } catch {} return !v; });
  if (!rows) return null;
  const w = 640, ht = 150, L = 60, R = 10;
  const last = rows[rows.length - 1];
  const vals = rows.flatMap(r => [r.value, r.cost]);
  const mn = Math.min(...vals), mx = Math.max(...vals), rng = (mx - mn) || 1;
  const x = i => L + (rows.length < 2 ? 0 : i / (rows.length - 1)) * (w - L - R);
  const y = v => ht - 10 - ((v - mn) / rng) * (ht - 24);
  const line = k => rows.map((r, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ',' + y(r[k]).toFixed(1)).join(' ');
  const first = rows[0];
  const change = rows.length > 1 && first.value ? (last.value / first.value - 1) * 100 : null;
  const hv = hover != null ? rows[hover] : null;
  return h('div', {style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`}},
    h('div', {style:{display:'flex', alignItems:'center', gap:8, cursor:'pointer'}, onClick:toggle},
      h('span', {style:{fontSize:11, color:T.textDim}}, open ? '▾' : '▸'),
      h('span', {style:{fontSize:11, fontWeight:'bold', color:T.gold, letterSpacing:'0.05em'}}, 'NET WORTH OVER TIME'),
      last && h('span', {style:{fontSize:11, color:T.text}}, fmt.gp(last.value) + 'gp'),
      change != null && h('span', {style:{fontSize:11, color: change >= 0 ? T.green : T.red}}, (change >= 0 ? '+' : '') + change.toFixed(1) + '% since ' + first.date)),
    open && (rows.length < 2
      ? h('div', {style:{fontSize:11, color:T.textDim, fontStyle:'italic', padding:'6px 0 2px 18px'}}, 'Started today. GEnius adds a point each day after a fetch, so the chart fills in from here.')
      : h('div', {style:{position:'relative'}},
          h('svg', {viewBox:`0 0 ${w} ${ht}`, style:{width:'100%', maxWidth:w, height:'auto', display:'block'},
            onMouseLeave:()=>setHover(null),
            onMouseMove:e => { const b = e.currentTarget.getBoundingClientRect(); const px = (e.clientX - b.left) / b.width * w; setHover(Math.max(0, Math.min(rows.length - 1, Math.round((px - L) / (w - L - R) * (rows.length - 1))))); }},
            [mx, (mx + mn) / 2, mn].map((v, i) => h('text', {key:i, x:L - 6, y:y(v) + 3, textAnchor:'end', fontSize:10, fill:T.textDim}, fmt.gp(v))),
            h('path', {d:line('cost'), fill:'none', stroke:T.textDim, strokeWidth:1.2, strokeDasharray:'4 3'}),
            h('path', {d:line('value'), fill:'none', stroke:T.gold, strokeWidth:2}),
            hv && h('line', {x1:x(hover), x2:x(hover), y1:4, y2:ht - 6, stroke:T.border})),
          h('div', {style:{fontSize:10, color:T.textDim, display:'flex', gap:12, paddingLeft:L}},
            hv ? h('span', null, `${hv.date}: worth ${fmt.gp(hv.value)}gp, cost ${fmt.gp(hv.cost)}gp, ${hv.positions} open positions`)
               : [h('span', {key:'a'}, h('span', {style:{color:T.gold}}, '━ '), 'What your open positions would sell for (live, after tax)'),
                  h('span', {key:'b'}, '┅ What you paid for them')]))));
}

// Settings > Background problems (Ben, 2026-11-10): the last 20 failures of work
// GEnius does on its own after fetches, which used to fail without a trace.
function BackgroundProblems({toast}) {
  const [list, setList] = useState(null);
  const load = () => window.genius?.getBackgroundErrors?.().then(r => setList(r || [])).catch(() => setList([]));
  useEffect(() => { load(); }, []);
  if (!window.genius?.getBackgroundErrors) return null;
  return h('div', {style:{marginBottom:20}},
    h('div', {className:'ge-section-head'}, 'Background problems'),
    h('div', {style:{fontSize:11, color:T.textDim, marginBottom:8, lineHeight:1.5}},
      'Work GEnius does by itself after each fetch: refreshing price history, rebuilding the Almanac, saving live prices. If any of it fails, it shows here, so a quiet failure can\'t go unnoticed.'),
    !list ? null : !list.length
      ? h('div', {style:{fontSize:12, color:T.green}}, '✓ No problems recorded.')
      : h('div', null,
          list.map((e, i) => h('div', {key:i, style:{fontSize:11, padding:'4px 0', borderBottom:`1px solid ${T.borderDim}`}},
            h('span', {style:{color:T.textDim, marginRight:8}}, new Date(e.at).toLocaleString()),
            h('span', {style:{color:'#e08030', marginRight:6}}, e.what + ':'),
            h('span', {style:{color:T.text}}, e.error))),
          h('button', {className:'ge-btn', style:{fontSize:11, padding:'3px 10px', marginTop:8}, onClick:async () => { await window.genius.clearBackgroundErrors(); load(); toast('Cleared', 'success'); }}, 'Clear')));
}

// Ctrl+K quick search (Ben, 2026-11-10): jump to any item, tab or Money Makers skill.
function QuickSearch({items, tabs, onTab, onItem}) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState('');
  const [sel, setSel] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    const key = e => {
      if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey && e.key.toLowerCase() === 'k') {
        e.preventDefault(); setOpen(true); setQ(''); setSel(0); setTimeout(() => ref.current?.focus(), 0);
      }
    };
    window.addEventListener('keydown', key);
    return () => window.removeEventListener('keydown', key);
  }, []);
  const results = useMemo(() => {
    const t = q.trim().toLowerCase();
    if (!t) return tabs.slice(0, 8).map(x => ({ kind:'Tab', label:x.label, go:() => onTab(x.id) }));
    const score = name => { const n = name.toLowerCase(); return n === t ? 0 : n.startsWith(t) ? 1 : n.includes(' ' + t) ? 2 : n.includes(t) ? 3 : 9; };
    const out = [];
    for (const x of tabs) { const sc = score(x.label); if (sc < 9) out.push({ kind:'Tab', label:x.label, sc, go:() => onTab(x.id) }); }
    for (const sk of MONEY_MAKER_SKILLS) { const sc = score(sk.label + ' money makers'); if (sc < 9) out.push({ kind:'Money Makers', label:sk.label, sc, go:() => { onTab('money_makers'); setTimeout(() => window.dispatchEvent(new CustomEvent('genius-money-skill', {detail:sk.key})), 50); } }); }
    for (const it of items) { const sc = score(it.name); if (sc < 9) out.push({ kind:'Item', label:it.name, sc: sc + 0.5, vol: it.volume || 0, go:() => onItem(it) }); }
    return out.sort((a, b) => a.sc - b.sc || (b.vol || 0) - (a.vol || 0)).slice(0, 12);
  }, [q, items, tabs]);
  if (!open) return null;
  const pick = r => { setOpen(false); r && r.go(); };
  return h('div', {style:{position:'fixed', inset:0, zIndex:99995, background:'rgba(0,0,0,0.45)', display:'flex', justifyContent:'center', alignItems:'flex-start', paddingTop:'12vh'}, onMouseDown:e => { if (e.target === e.currentTarget) setOpen(false); }},
    h('div', {style:{width:'min(560px, 92vw)', background:T.panel || T.bg, border:`1px solid ${T.gold}`, borderRadius:6, boxShadow:'0 10px 40px rgba(0,0,0,0.6)', overflow:'hidden'}},
      h('input', {ref, className:'ge-input', value:q, placeholder:'Jump to an item, tab or money maker…', style:{width:'100%', boxSizing:'border-box', fontSize:14, padding:'10px 12px', border:'none', borderBottom:`1px solid ${T.border}`, borderRadius:0},
        onChange:e => { setQ(e.target.value); setSel(0); },
        onKeyDown:e => {
          if (e.key === 'Escape') { e.preventDefault(); setOpen(false); }
          else if (e.key === 'ArrowDown') { e.preventDefault(); setSel(i => Math.min(results.length - 1, i + 1)); }
          else if (e.key === 'ArrowUp') { e.preventDefault(); setSel(i => Math.max(0, i - 1)); }
          else if (e.key === 'Enter') { e.preventDefault(); pick(results[sel]); }
        }}),
      h('div', {style:{maxHeight:'50vh', overflowY:'auto'}},
        results.length ? results.map((r, i) => h('div', {key:r.kind + r.label, onMouseEnter:() => setSel(i), onMouseDown:e => { e.preventDefault(); pick(r); },
          style:{display:'flex', justifyContent:'space-between', padding:'7px 12px', cursor:'pointer', fontSize:13, background: i === sel ? 'rgba(201,168,76,0.18)' : 'transparent', color:T.text}},
          h('span', null, r.label), h('span', {style:{fontSize:11, color:T.textDim}}, r.kind)))
        : h('div', {style:{padding:'10px 12px', fontSize:12, color:T.textDim}}, 'Nothing matches.')),
      h('div', {style:{fontSize:10, color:T.textDim, padding:'5px 12px', borderTop:`1px solid ${T.borderDim}`}}, '↑↓ to move · Enter to open · Esc to close')));
}

function PortfolioTab({items, removedItems, portfolio, onSavePosition, onDeletePosition, onSellPosition, onConvertPosition, onReopenPosition, onSelect, toast, devMode, userShorthands, dateFormat}) {
  // Same MM/DD/YYYY vs DD/MM/YYYY vs YYYY-MM-DD Settings preference the
  // chart already respects (Ben, 2026-09-09: "can we add dates to the
  // sales too" — the existing "Sold At / Converted" column was misnamed;
  // it only ever showed the sale price, never an actual date).
  const fmtPosDate = ts => {
    if (!ts) return '—';
    const d = new Date(ts);
    if (isNaN(d.getTime())) return '—';
    const fmtStr = dateFormat || 'MM/DD/YYYY';
    const M = d.getMonth()+1, D = d.getDate(), Y = d.getFullYear();
    if (fmtStr === 'DD/MM/YYYY') return `${D}/${M}/${Y}`;
    if (fmtStr === 'YYYY-MM-DD') return `${Y}-${String(M).padStart(2,'0')}-${String(D).padStart(2,'0')}`;
    return `${M}/${D}/${Y}`;
  };
  // Diversification suggestions pull real picks from the Almanac's
  // trade-idea engine — public since the Almanac itself went public
  // (v2.0.0). Fetches its own copy of the DXP intelligence data
  // independent of whether the Almanac tab has ever been opened this
  // session.
  const [dxpData, setDxpData] = useState(null);
  useEffect(() => { window.genius?.getDxpIntelligence?.().then(d => setDxpData(d || {})); }, []);
  const priceById = useMemo(() => {
    const m = {};
    items.forEach(it => { if (it.id) m[String(it.id)] = it; });
    return m;
  }, [items]);
  const [showModal,   setShowModal]   = useState(false);
  const [editPos,     setEditPos]     = useState(null);
  const [sellModal,   setSellModal]   = useState(null);
  const [convertModal, setConvertModal] = useState(null);
  const [showClosed,  setShowClosed]  = useState(true);
  // Closed Positions sort (Ben, 2026-10-16): click a header; again to reverse.
  const [closedSort, setClosedSort] = useState({key: 'date', dir: -1});
  const [ctxMenu,     setCtxMenu]     = useState(null); // {x, y, pos}
  const [allocView,   setAllocView]   = useState('item'); // 'item' | 'category'
  const [tierModal,   setTierModal]   = useState(null); // 'investor' | 'tradeCount' | null

  // Same shared GE/Live toggle as ItemTable/MarketTab/AlchTab/Monster
  // Live (what selling gets you) unless switched; saved separately from the
  // price toggle on other tabs.
  const [priceMode, setPriceMode] = useState(() => {
    try { return localStorage.getItem('genius_portfolio_price_mode') === 'ge' ? 'ge' : 'live'; } catch { return 'live'; }
  });
  const togglePriceMode = () => setPriceMode(m => {
    const next = m === 'ge' ? 'live' : 'ge';
    try { localStorage.setItem('genius_portfolio_price_mode', next); } catch {}
    return next;
  });

  const positions  = portfolio?.positions || [];
  const taxStats   = portfolio?.tax_stats  || {};

  const enriched = useMemo(() => positions.map(pos => {
    const item = items.find(it => it.name.toLowerCase() === (pos.item_name||'').toLowerCase());
    // What selling really gets you right now (Ben, 2026-11-03).
    const currentPrice = priceMode === 'live' ? (liveSellOf(item) || 0) : (item ? (item.high || item.low || 0) : 0);
    // Removed from the GE: worth 0 here (Ben, 2026-10-28: it can't be sold
    // any more, so -100% is honest), but labelled so it doesn't look like a bug.
    const removed = !item && (removedItems || []).find(it => it.name.toLowerCase() === (pos.item_name||'').toLowerCase());
    const currentValue = currentPrice * pos.quantity;
    const costValue    = pos.cost_basis * pos.quantity;
    const grossPL      = currentValue - costValue;
    const tax          = currentValue - saleNet(currentPrice, pos.quantity);
    const netPL        = grossPL - tax;
    const plPct        = costValue > 0 ? (grossPL / costValue) * 100 : 0;
    const targetDist   = pos.target_price ? pos.target_price - currentPrice : null;
    const stopDist     = pos.stop_loss    ? currentPrice - pos.stop_loss    : null;
    const category      = item?.categories?.[0] || 'misc';
    return {...pos, currentPrice, currentValue, costValue, grossPL, tax, netPL, plPct, targetDist, stopDist, category, removedItem: removed || null};
  }), [positions, items, removedItems, priceMode]);

  const openPos   = enriched.filter(p => p.status !== 'sold' && p.status !== 'converted');
  const closedPos = enriched.filter(p => p.status === 'sold' || p.status === 'converted');

  // Closed trades grouped by item (Ben, 2026-10-20): one row per item with
  // its totals, and a chevron to open the individual trades. Repeat trades
  // (shards, bombs) used to fill the list with near-identical rows.
  const tradeQty = p => p.status === 'converted' ? (p.converted_quantity || 0) : (p.sold_quantity || p.quantity || 0);
  const tradeDate = p => String(p.sold_at || p.converted_at || p.created_at || '');
  const tradeTax = p => p.status === 'converted' || p.sold_via === 'alch' ? 0 : (p.sold_price || 0) * tradeQty(p) - saleNet(p.sold_price || 0, tradeQty(p));
  const tradeCost = p => (p.cost_basis || 0) * tradeQty(p);
  const tradeReturn = p => p.status === 'converted' || !tradeCost(p) ? null : (p.realized_pl || 0) / tradeCost(p) * 100;
  const closedGroups = useMemo(() => {
    const by = {};
    for (const p of closedPos) (by[(p.item_name || '').toLowerCase()] ||= []).push(p);
    return Object.values(by).map(trades => {
      trades.sort((a, b) => tradeDate(b).localeCompare(tradeDate(a)));
      const sales = trades.filter(p => p.status !== 'converted');
      const cost = sales.reduce((t, p) => t + tradeCost(p), 0);
      const pl = sales.reduce((t, p) => t + (p.realized_pl || 0), 0);
      return { key: (trades[0].item_name || '').toLowerCase(), name: trades[0].item_name, trades, sales,
        qty: trades.reduce((t, p) => t + tradeQty(p), 0), pl,
        wins: sales.filter(p => (p.realized_pl || 0) > 0).length,
        ret: cost ? pl / cost * 100 : null,
        tax: sales.reduce((t, p) => t + tradeTax(p), 0),
        last: tradeDate(trades[0]) };
    });
  }, [closedPos]);
  const [openGroups, setOpenGroups] = useState({});
  const groupVal = (g, key) => {
    switch (key) {
      case 'item': return g.key;
      case 'qty':  return g.qty;
      case 'win':  return g.sales.length ? g.wins / g.sales.length : -1;
      case 'ret':  return g.ret ?? -Infinity;
      case 'tax':  return g.tax;
      case 'pl':   return g.pl;
      default:     return g.last;
    }
  };
  const sortedGroups = [...closedGroups].sort((a, b) => {
    const av = groupVal(a, closedSort.key), bv = groupVal(b, closedSort.key);
    const c = typeof av === 'string' ? av.localeCompare(bv) : av - bv;
    return c * closedSort.dir;
  });
  // Text columns start A-Z; numbers and dates start biggest/newest first.
  const toggleClosedSort = key => setClosedSort(s => s.key === key ? {key, dir: -s.dir} : {key, dir: key === 'item' ? 1 : -1});
  const closedTh = (key, label) => h('th', {onClick: () => toggleClosedSort(key), style:{cursor:'pointer'}},
    label + (closedSort.key === key ? (closedSort.dir > 0 ? ' ↑' : ' ↓') : ''));

  // Recovery numbers (Ben, 2026-10-06): for a losing position, the sell
  // price that breaks even after GE tax, how far away that is, and when the
  // item last actually traded at or above it (saved history + daily
  // snapshots). Turns "I hope it comes back" into something checkable.
  const breakEvenPrice = cost => {
    const untaxed = Math.ceil(cost);
    return untaxed < 50 ? untaxed : Math.ceil(cost / 0.98);
  };
  const losers = openPos.filter(p => p.netPL < 0 && p.currentPrice > 0);
  const losersKey = losers.map(p => p.id + ':' + breakEvenPrice(p.cost_basis)).join('|');
  const [lastSeen, setLastSeen] = useState({});
  useEffect(() => {
    let stale = false;
    (async () => {
      const out = {};
      for (const p of losers) {
        const it = items.find(i => i.name.toLowerCase() === (p.item_name || '').toLowerCase());
        if (!it) continue;
        const be = breakEvenPrice(p.cost_basis);
        const [hist, snaps] = await Promise.all([
          window.genius?.getItemHistoryLocal(it.id).catch(() => null),
          window.genius?.getPriceSnapshots(it.id).catch(() => null),
        ]);
        let last = null, first = null;
        for (const pt of [...(hist || []), ...(snaps || [])]) {
          const ts = pt.timestamp > 1e12 ? pt.timestamp : pt.timestamp * 1000;
          if (first == null || ts < first) first = ts;
          if (pt.price >= be && (last == null || ts > last)) last = ts;
        }
        out[p.id] = { last, first };
      }
      if (!stale) setLastSeen(out);
    })();
    return () => { stale = true; };
  }, [losersKey]);

  // "Since you bought it" (Ben, 2026-10-06): the price range an open
  // position has seen since its Date Opened — highest/lowest daily GE price,
  // the best net profit you could have taken (at that high, after tax), and
  // the worst point it's been underwater. Daily GE guide prices (history +
  // snapshots), so a brief intraday spike won't show.
  const openKey = openPos.map(p => p.id + ':' + (p.date_opened || p.created_at)).join('|');
  const [sinceBought, setSinceBought] = useState({});
  const [expandedItems, setExpandedItems] = useState(() => new Set());
  const [dailyById, setDailyById] = useState({});
  useEffect(() => {
    let stale = false;
    (async () => {
      const out = {}, daily = {};
      for (const p of openPos) {
        const it = items.find(i => i.name.toLowerCase() === (p.item_name || '').toLowerCase());
        if (!it || it.untradeable) continue;
        const allDays = await loadDailyPrices(it.id);
        daily[p.id] = allDays;
        const opened = new Date(p.date_opened || p.created_at).getTime();
        if (!opened) continue;
        const days = allDays.filter(d => d.ts >= opened - 86400000);
        if (!days.length) continue;
        let hi = days[0], lo = days[0];
        for (const d of days) { if (d.price > hi.price) hi = d; if (d.price < lo.price) lo = d; }
        out[p.id] = { hi, lo };
      }
      if (!stale) { setSinceBought(out); setDailyById(daily); }
    })();
    return () => { stale = true; };
  }, [openKey]);

  const sinceBoughtCell = pos => {
    const sb = sinceBought[pos.id];
    if (!sb) return h('td', {style:{color:T.textDim}}, '—');
    // Shown PER ITEM: a position stores one quantity + one average cost, not
    // when each unit was bought, so a "best total" would wrongly assume
    // today's full quantity was already held back then (Ben: had 200k
    // vulnerability bombs at the March high, not today's 300k). Totals stay
    // in the tooltip, labelled as using the current quantity.
    const cost = pos.cost_basis * pos.quantity;
    const bestPL = saleNet(sb.hi.price, pos.quantity) - cost;
    const worstPL = saleNet(sb.lo.price, pos.quantity) - cost;
    const bestEa = applyTax(sb.hi.price) - pos.cost_basis;
    const worstEa = applyTax(sb.lo.price) - pos.cost_basis;
    const d = x => new Date(x.ts).toLocaleDateString(undefined, {month:'short', day:'numeric'});
    return h('td', {title:`Since you bought (daily GE prices):\nHigh ${sb.hi.price.toLocaleString()}gp on ${d(sb.hi)}: ${bestEa >= 0 ? '+' : ''}${Math.round(bestEa).toLocaleString()}gp per item after tax (${bestPL >= 0 ? '+' : ''}${Math.round(bestPL).toLocaleString()}gp if you'd held your current quantity).\nLow ${sb.lo.price.toLocaleString()}gp on ${d(sb.lo)}: ${worstEa >= 0 ? '+' : ''}${Math.round(worstEa).toLocaleString()}gp per item (${worstPL >= 0 ? '+' : ''}${Math.round(worstPL).toLocaleString()}gp with your current quantity).`},
      // Condensed to one line (Ben, 2026-10-12: table scrolled sideways);
      // best/worst per item are in the tooltip above.
      h('div', {style:{fontSize:11, whiteSpace:'nowrap'}}, h('span', {style:{color:T.green}}, '▲ ' + fmt.gp(sb.hi.price)), ' ', h('span', {style:{color:T.red}}, '▼ ' + fmt.gp(sb.lo.price))));
  };

  const breakEvenCell = pos => {
    if (!(pos.currentPrice > 0)) return h('td', {style:{color:T.textDim}}, '—');
    if (pos.netPL >= 0) return h('td', {style:{color:T.textDim}, title:'Already at or above break-even after tax'}, '✓');
    const be = breakEvenPrice(pos.cost_basis);
    const needs = (be - pos.currentPrice) / pos.currentPrice * 100;
    const seen = lastSeen[pos.id];
    let seenText = '…';
    if (seen) {
      if (seen.last != null) {
        const days = Math.floor((Date.now() - seen.last) / 86400000);
        seenText = days < 1 ? 'last seen today' : days === 1 ? 'last seen yesterday' : `last seen ${days}d ago`;
      } else {
        seenText = seen.first ? `never reached since ${new Date(seen.first).toLocaleDateString(undefined, {month:'short', year:'numeric'})}` : 'no price history';
      }
    }
    return h('td', {title:`Sell at ${be.toLocaleString()}gp or more to break even after the 2% GE tax. Needs +${needs.toFixed(1)}% from now; ${seenText}.`},
      h('div', {style:{whiteSpace:'nowrap'}}, fmt.gp(be) + 'gp'),
      h('div', {style:{fontSize:10, whiteSpace:'nowrap'}}, h('span', {style:{color:T.red}}, '+' + needs.toFixed(1) + '%'), h('span', {style:{color:T.textDim}}, ' · ' + seenText.replace('last seen ', ''))));
  };

  // Same-item positions group under one row with a chevron (Ben, 2026-11-04). The
  // risk badge sits on the combined stack, since they'd all sell into one market.
  const posGroups = [...openPos.reduce((m, p) => { const k = (p.item_name || '').toLowerCase(); m.set(k, [...(m.get(k) || []), p]); return m; }, new Map()).values()];
  const heldSinceOf = p => dayStartMs(p.date_opened || p.created_at) || null;
  const heldText = ts => {
    if (!ts || !isFinite(ts)) return '—';
    const days = Math.floor((Date.now() - ts) / 86400000);
    return days === 0 ? 'Today' : days === 1 ? '1d' : days < 30 ? days + 'd' : days < 365 ? Math.floor(days / 30) + 'mo' : (days / 365).toFixed(1) + 'y';
  };
  const breakEvenOf = breakEvenPrice;
  const riskBadgeFor = list => {
    const first = list[0];
    const it = !first.removedItem && items.find(i => i.name.toLowerCase() === (first.item_name || '').toLowerCase());
    const days = dailyById[first.id];
    if (!it || !days) return null;
    const qty = list.reduce((sum, p) => sum + p.quantity, 0);
    const since = Math.min(...list.map(heldSinceOf).filter(Boolean));
    return h('div', {style:{marginTop:3}}, h(SignalBadge, positionRisk(qty, it, days, isFinite(since) ? since : null)));
  };
  const positionRow = (pos, child) =>
            h('tr',{key:pos.id},
              h('td',{
                style: {...(onSelect ? {cursor:'pointer', color:T.gold} : null), ...(child ? {paddingLeft:28, fontSize:'0.92em'} : null)},
                onClick: onSelect ? () => { const it = items.find(i => i.name.toLowerCase()===(pos.item_name||'').toLowerCase()); if(it) onSelect(it); } : null,
              }, pos.item_name,
                pos.planner_goal_id && h('span',{title:'Managed by the Buy Planner: quantity and cost are set from your planner totals, so manual edits here get overwritten on the next update.', style:{marginLeft:6, fontSize:9, letterSpacing:1, color:T.textDim, border:`1px solid ${T.borderDim}`, borderRadius:3, padding:'0 4px'}},'PLANNER'),
                pos.removedItem && h(RemovedFromGeTag, {item: pos.removedItem}),
                !child && riskBadgeFor([pos])),
              h('td',null, h('div',{style:{whiteSpace:'nowrap'}},pos.quantity.toLocaleString()), h('div',{style:{fontSize:10, color:T.textDim, whiteSpace:'nowrap'}},'@ '+fmt.gp(pos.cost_basis)+'gp')),
              h('td',null, h('div',{style:{whiteSpace:'nowrap'}},fmt.gp(pos.currentValue)+'gp'), h('div',{style:{fontSize:10, color:T.gold, whiteSpace:'nowrap'}},fmt.gp(pos.currentPrice)+'gp ea')),
              h('td',{className:pos.netPL>=0?'pct-up':'pct-down'}, h('div',{style:{whiteSpace:'nowrap'}},(pos.netPL>=0?'+':'')+fmt.gp(pos.netPL)+'gp'), h('div',{style:{fontSize:10, whiteSpace:'nowrap'}},fmt.pct(pos.plPct))),
              breakEvenCell(pos),
              sinceBoughtCell(pos),
              h('td',null,
                h('div',{style:{color:T.textDim, whiteSpace:'nowrap'}},(() => {
                  const d = pos.date_opened || pos.created_at;
                  if (!d) return '—';
                  const days = Math.floor((Date.now() - new Date(d).getTime()) / 86400000);
                  return days === 0 ? 'Today' : days === 1 ? '1d' : days < 30 ? `${days}d` : days < 365 ? `${Math.floor(days/30)}mo` : `${(days/365).toFixed(1)}y`;
                })()),
                pos.target_price ? h('div',{style:{fontSize:10, whiteSpace:'nowrap', color:pos.currentPrice>=pos.target_price?T.green:T.textDim}},'→ '+fmt.gp(pos.target_price)+'gp') : null),
              h('td',null,
                h('div',{style:{display:'flex',gap:3}},
                  h('button',{className:'ge-btn',title:'Edit',style:{padding:'2px 5px',fontSize:11},
                    onClick:()=>{setEditPos(pos);setShowModal(true);}},'✎'),
                  h('button',{className:'ge-btn',title:'Sell',style:{padding:'2px 6px',fontSize:10,borderColor:T.green},
                    onClick:()=>setSellModal({...pos, currentPrice:pos.currentPrice})},'Sell'),
                  h('button',{className:'ge-btn',title:'Convert into another item',style:{padding:'2px 5px',fontSize:11,borderColor:T.blue},
                    onClick:()=>setConvertModal(pos)},'⇄'),
                  h('button',{className:'ge-btn danger',title:'Delete position',style:{padding:'2px 5px',fontSize:11},
                    onClick:async()=>{if(confirm(`Delete position: ${pos.item_name}?`)){await onDeletePosition(pos.id);toast('Deleted','info');}}},'✕')
                )
              )
            );

  const totalInvested = openPos.reduce((s,p) => s+p.costValue, 0);
  const totalCurrent  = openPos.reduce((s,p) => s+p.currentValue, 0);
  const unrealizedPL  = totalCurrent - totalInvested;
  const unrealizedPct = totalInvested > 0 ? (unrealizedPL / totalInvested) * 100 : 0;
  const realizedPL    = closedPos.reduce((s,p) => s+(p.realized_pl||0), 0);

  const PORTFOLIO_TIERS = [
    { threshold: 100000e6, icon:'🐉', label:'100B Investor',  sub:'Generational wealth' },
    { threshold:  50000e6, icon:'🌌', label:'50B Investor',   sub:'Legendary wealth' },
    { threshold:  25000e6, icon:'👑', label:'25B Investor',   sub:'Elite investor' },
    { threshold:  10000e6, icon:'💠', label:'10B Investor',   sub:'Top tier trader' },
    { threshold:   5000e6, icon:'💎', label:'5B Investor',    sub:'Serious money' },
    { threshold:   2500e6, icon:'🏦', label:'2.5B Investor',  sub:'Institutional money' },
    { threshold:   1000e6, icon:'🥇', label:'1B Investor',    sub:'The billionaire club' },
    { threshold:    500e6, icon:'🦈', label:'500M Investor',  sub:'Big fish' },
    { threshold:    250e6, icon:'🐟', label:'250M Investor',  sub:'High-net-worth trader' },
    { threshold:    100e6, icon:'📈', label:'100M Investor',  sub:'Getting serious' },
    { threshold:     10e6, icon:'🌱', label:'10M Investor',   sub:'First steps' },
  ];

  const tierIndex = PORTFOLIO_TIERS.findIndex(t => totalCurrent >= t.threshold);
  const currentTier = tierIndex >= 0 ? PORTFOLIO_TIERS[tierIndex] : null;
  const nextTier    = tierIndex > 0  ? PORTFOLIO_TIERS[tierIndex - 1] : null;
  const earnedTiers = tierIndex >= 0 ? PORTFOLIO_TIERS.slice(tierIndex + 1) : [];

  // Trade-count tier ladder — same next/current/earned pattern as
  // Investor Tier above, added because the old "Trades Closed"/"10
  // Trades"/"100 Trades" milestones only ever showed what you'd already
  // hit, with no visibility into what's coming up next (Ben, 2026-07-30).
  // Full joke ladder is Ben's own (2026-07-30) — every label/threshold
  // below was picked by him, not invented here.
  const TRADE_COUNT_TIERS = [
    { threshold: 12345, icon:'🤪', label:"I Can't Count",           sub:'12,345 trades closed' },
    { threshold: 10000, icon:'💵', label:'Five Figures',            sub:'10,000 trades closed' },
    { threshold:  9001, icon:'📈', label:'Scouter Crushing',        sub:'9,001 trades closed' },
    { threshold:  8675, icon:'☎️', label:"Jenny, I Got Your Number", sub:'8,675 trades closed' },
    { threshold:  5000, icon:'🏛️', label:'Market Tycoon',           sub:'5,000 trades closed' },
    { threshold:  3141, icon:'🥧', label:'Irrational Humor, Again', sub:'3,141 trades closed' },
    { threshold:  2501, icon:'🎂', label:"Wait, No It's Not",       sub:'2,501 trades closed' },
    { threshold:  2500, icon:'💰', label:'Quarter Millionaire',     sub:'2,500 trades closed' },
    { threshold:  1337, icon:'💻', label:'Elite',                   sub:'1,337 trades closed' },
    { threshold:  1000, icon:'⚙️',  label:'Four Figure Club',        sub:'1,000 trades closed' },
    { threshold:   999, icon:'😅', label:'Just One More',           sub:'999 trades closed' },
    { threshold:   777, icon:'🎰', label:'Jackpot',                 sub:'777 trades closed' },
    { threshold:   666, icon:'😈', label:'The Root of All Evil',    sub:'666 trades closed' },
    { threshold:   500, icon:'🏭', label:'Half a Grand',            sub:'500 trades closed' },
    { threshold:   420, icon:'🌿', label:'Ranarr Dealer',           sub:'420 trades closed' },
    { threshold:   404, icon:'❓', label:'Trade Not Found',         sub:'404 trades closed' },
    { threshold:   333, icon:'👹', label:'Half Evil',               sub:'333 trades closed' },
    { threshold:   314, icon:'🥧', label:'Not That Kind of Pie',    sub:'314 trades closed' },
    { threshold:   250, icon:'📊', label:'Quarter K',               sub:'250 trades closed' },
    { threshold:   150, icon:'💼', label:"Every Day I'm Hustlin",   sub:'150 trades closed' },
    { threshold:   100, icon:'🔁', label:'Triple Digits',           sub:'100 trades closed' },
    { threshold:    75, icon:'📈', label:'Three Quarters',          sub:'75 trades closed' },
    { threshold:    68, icon:'🤏', label:'Too Little, Too Late?',   sub:'68 trades closed' },
    { threshold:    66, icon:'🛣️', label:'Get Your Kicks',          sub:'66 trades closed' },
    { threshold:    50, icon:'📊', label:'Fifty-Fifty',             sub:'50 trades closed' },
    { threshold:    42, icon:'🧠', label:'The Meaning of Life',     sub:'42 trades closed' },
    { threshold:    25, icon:'🌱', label:'Getting Started',         sub:'25 trades closed' },
    { threshold:    10, icon:'🔟', label:'Perfect 10',              sub:'10 trades closed' },
    { threshold:     5, icon:'✋', label:'I Got 5 On It',           sub:'5 trades closed' },
    { threshold:     1, icon:'1️⃣', label:'The Loneliest Number',    sub:'1 trade closed' },
  ];
  const tradeTierIndex = TRADE_COUNT_TIERS.findIndex(t => closedPos.length >= t.threshold);
  const currentTradeTier = tradeTierIndex >= 0 ? TRADE_COUNT_TIERS[tradeTierIndex] : null;
  const nextTradeTier    = tradeTierIndex > 0  ? TRADE_COUNT_TIERS[tradeTierIndex - 1] : (tradeTierIndex === -1 ? TRADE_COUNT_TIERS[TRADE_COUNT_TIERS.length - 1] : null);
  const earnedTradeTiers = tradeTierIndex >= 0 ? TRADE_COUNT_TIERS.slice(tradeTierIndex + 1) : [];

  const milestones = useMemo(() => {
    const ms = [];
    if (!closedPos.length) return ms;

    // Win/loss-shaped stats (Biggest Win/Loss, Flawless streak) need ONLY
    // real sales — a Convert never sets realized_pl at all (it's a cost-
    // basis carry-forward, not a close-out, see api.js's convertPosition),
    // so it read as an automatic 0/loss and silently cut real win streaks
    // short whenever a convert happened to sit in the middle of one (Ben,
    // 2026-08-13: "The 'hot streak' thing in portfolio... Converting broke
    // it" — confirmed, reported streak of 19 was being undercounted this
    // way). totalRealized still sums over closedPos (sold + converted) —
    // converts correctly contribute 0 there either way, so no bug to fix.
    const closedSales = closedPos.filter(p => p.status === 'sold');
    const profits = closedPos.map(p => p.realized_pl || 0);
    const salesProfits = closedSales.map(p => p.realized_pl || 0);
    const biggestWin  = salesProfits.length ? Math.max(...salesProfits) : 0;
    const biggestLoss = salesProfits.length ? Math.min(...salesProfits) : 0;
    const biggestWinPos  = closedSales.find(p => (p.realized_pl||0) === biggestWin);
    const biggestLossPos = closedSales.find(p => (p.realized_pl||0) === biggestLoss);
    const totalRealized  = profits.reduce((s,n) => s+n, 0);

    if (biggestWin > 0)  ms.push({ icon:'🏆', label:'Biggest Win',  value: '+'+fmt.gp(biggestWin)+'gp',  sub: biggestWinPos?.item_name || '' });
    if (biggestLoss < 0) ms.push({ icon:'💀', label:'Biggest Loss', value: fmt.gp(biggestLoss)+'gp',     sub: biggestLossPos?.item_name || '' });
    if (totalRealized >= 100e6) ms.push({ icon:'💰', label:'100m Club',   value: fmt.gp(totalRealized)+'gp total', sub: 'Total realized profit' });
    if (totalRealized >= 1e9)   ms.push({ icon:'💎', label:'Billionaire', value: fmt.gp(totalRealized)+'gp total', sub: 'Total realized profit' });
    // Trade count itself now has its own tier ladder (see
    // TRADE_COUNT_TIERS/currentTradeTier above) instead of living here as
    // flat one-off milestones.
    // Flawless — best streak of consecutive profitable SALES (converts
    // excluded, see above)
    let bestStreak = 0, currentStreak = 0;
    for (const p of closedSales) {
      if ((p.realized_pl||0) > 0) { currentStreak++; bestStreak = Math.max(bestStreak, currentStreak); }
      else currentStreak = 0;
    }
    const isCurrentlyFlawless = salesProfits.length > 0 && salesProfits.every(p => p > 0) && closedSales.length >= 5;
    if (bestStreak >= 5)
      ms.push({ icon:'✨', label:'Flawless', value: isCurrentlyFlawless ? closedSales.length+' for '+closedSales.length : 'Best streak: '+bestStreak, sub: isCurrentlyFlawless ? 'Every trade profitable' : 'Streak broken — best was '+bestStreak, dimmed: !isCurrentlyFlawless });
    return ms;
  }, [closedPos, totalCurrent]);

  // Consolation Prizes (Ben, 2026-10-02): the loss-side mirror of the
  // Achievements above, sparked by a 2.42B-unrealized Magic frame position
  // ("we should have added some achievements for GP losses, too").
  // Deliberately lives in its own panel rather than interrupting with
  // toasts — a notification roasting you the moment you take a loss is
  // funny once. Only badges derivable from data GEnius already stores
  // (closed trades, open positions' cost basis/open date, live prices) —
  // add-to-position history isn't tracked (a position is one quantity +
  // one cost basis), so "Catching Knives"/"Sunk Cost Fallacy"-style badges
  // are intentionally not here. Open positions with no current price are
  // excluded: an untracked item prices at 0, which would read as a fake
  // -100% and hand out Red Wedding/Stop the Count for free.
  const consolationPrizes = useMemo(() => {
    const out = [];
    const sales = closedPos.filter(p => p.status === 'sold');
    const pricedOpen = openPos.filter(p => p.currentPrice > 0);
    const plOf = p => p.realized_pl || 0;
    const saleCost = p => (p.cost_basis || 0) * (p.sold_quantity || p.quantity || 0);
    const daysHeld = p => Math.floor((Date.now() - dayStartMs(p.date_opened || p.created_at)) / 86400000);
    const losses = sales.filter(p => plOf(p) < 0);

    // Biggest single realized loss — highest tier earned only
    const worstSale = losses.reduce((w, p) => (!w || plOf(p) < plOf(w)) ? p : w, null);
    if (worstSale && plOf(worstSale) <= -1e9)
      out.push({ icon:'🎮', label:'Skill Issue', value: fmt.gp(plOf(worstSale))+'gp', sub: `${worstSale.item_name} — no explanation necessary` });
    else if (worstSale && plOf(worstSale) <= -100e6)
      out.push({ icon:'🧾', label:'Tax Write-Off', value: fmt.gp(plOf(worstSale))+'gp', sub: `${worstSale.item_name} — the accountant says it's fine` });

    // Worst streak of consecutive losing sales
    let worstStreak = 0, runStreak = 0;
    const salesBySellDate = [...sales].sort((a, b) => new Date(a.sold_at || a.date_opened || 0) - new Date(b.sold_at || b.date_opened || 0));
    for (const p of salesBySellDate) {
      if (plOf(p) < 0) { runStreak++; worstStreak = Math.max(worstStreak, runStreak); }
      else runStreak = 0;
    }
    if (worstStreak >= 3)
      out.push({ icon:'📉', label:'Statistically Impressive', value:'Worst streak: '+worstStreak, sub:'Consistency is a skill' });

    // Losses spread across many different items
    const lostItems = new Set(losses.map(p => p.item_name));
    if (lostItems.size >= 10)
      out.push({ icon:'🔬', label:'Market Research', value: lostItems.size+' items', sub:"You're not losing gp, you're gathering data" });

    // Lifetime gross realized losses
    const grossLosses = losses.reduce((s, p) => s + plOf(p), 0);
    if (grossLosses <= -500e6)
      out.push({ icon:'🧠', label:'GEnius Investor', value: fmt.gp(grossLosses)+'gp', sub:'Lifetime realized losses — the app turns its own name against you' });

    // Every open position red at once (min 5 so one item can't cheese it)
    if (pricedOpen.length >= 5 && pricedOpen.every(p => p.plPct < 0))
      out.push({ icon:'🩸', label:'Red Wedding', value: pricedOpen.length+' for '+pricedOpen.length, sub:'Every open position is in the red. Nobody survived' });

    // Big unrealized hole across the whole portfolio
    const pricedUnrealized = pricedOpen.reduce((s, p) => s + (p.currentValue - p.costValue), 0);
    if (pricedUnrealized <= -1e9)
      out.push({ icon:'🛑', label:'Stop the Count', value: fmt.gp(pricedUnrealized)+'gp', sub:'Unrealized. The counter has been unplugged' });

    // Held a loser for a long time
    const longHolds = pricedOpen.filter(p => p.plPct <= -10 && daysHeld(p) >= 90);
    if (longHolds.length) {
      const w = longHolds.reduce((a, p) => daysHeld(p) > daysHeld(a) ? p : a);
      out.push({ icon:'🕰️', label:"Now It's a Long-Term Investment", value: daysHeld(w)+' days', sub:`${w.item_name} — it's fine, it's a long-term hold` });
    }

    // Chain: It's Only a Loss If You Sell -> Narrator: He Sold
    const deepRed = pricedOpen.filter(p => p.plPct <= -50);
    if (deepRed.length) {
      const w = deepRed.reduce((a, p) => p.plPct < a.plPct ? p : a);
      out.push({ icon:'🙈', label:"It's Only a Loss If You Sell", value: w.plPct.toFixed(1)+'%', sub:`${w.item_name} — technically true` });
    }
    const soldDeep = losses.filter(p => saleCost(p) > 0 && plOf(p) / saleCost(p) <= -0.5);
    if (soldDeep.length) {
      const w = soldDeep.reduce((a, p) => plOf(p) < plOf(a) ? p : a);
      out.push({ icon:'🎙️', label:'Narrator: He Sold', value: fmt.gp(plOf(w))+'gp', sub:`${w.item_name} — it was only a loss once he sold` });
    }
    return out;
  }, [closedPos, openPos]);

  // Realized P&L grouped by item — a higher-level summary of the Closed
  // Positions table below (which is per-TRADE, not per-item), so "which
  // item has actually been making me money" doesn't require manually
  // adding up rows (Ben, 2026-07-30).
  const realizedByItem = useMemo(() => {
    if (!closedPos.length) return [];
    const map = {};
    for (const p of closedPos) {
      const key = p.item_name;
      if (!map[key]) map[key] = { name: key, trades: 0, qty: 0, pl: 0 };
      map[key].trades += 1;
      map[key].qty += (p.sold_quantity ?? p.quantity ?? 0);
      map[key].pl += (p.realized_pl || 0);
    }
    const rows = Object.values(map);
    const totalAbs = rows.reduce((s, r) => s + Math.abs(r.pl), 0);
    return rows
      .map(r => ({ ...r, pct: totalAbs > 0 ? (Math.abs(r.pl) / totalAbs) * 100 : 0 }))
      .sort((a, b) => b.pl - a.pl);
  }, [closedPos]);

  // Allocation by item
  const allocations = useMemo(() => {
    return openPos
      .filter(p => p.currentValue > 0)
      .map(p => ({
        name: p.item_name,
        val: p.currentValue,
        pct: totalCurrent > 0 ? (p.currentValue / totalCurrent) * 100 : 0,
        category: p.category,
      }))
      .sort((a, b) => b.val - a.val);
  }, [openPos, totalCurrent]);

  // Allocation by category — same idea as by-item, but grouped, so a
  // concentration warning can catch "all your eggs across 5 items that
  // are all secretly the same skill/category," not just one item.
  const ITEM_CONCENTRATION_WARN_PCT = 30;
  const CATEGORY_CONCENTRATION_WARN_PCT = 50;
  const categoryAllocations = useMemo(() => {
    const byCat = {};
    openPos.filter(p => p.currentValue > 0).forEach(p => {
      byCat[p.category] = (byCat[p.category] || 0) + p.currentValue;
    });
    return Object.entries(byCat)
      .map(([category, val]) => ({ category, val, pct: totalCurrent > 0 ? (val / totalCurrent) * 100 : 0 }))
      .sort((a, b) => b.val - a.val);
  }, [openPos, totalCurrent]);
  const topItemAlloc = allocations[0];
  const topCategoryAlloc = categoryAllocations[0];
  // Rares are an exception, not a diversification mistake — owning one
  // partyhat will always dwarf the rest of a portfolio by virtue of being
  // rare, not because the person failed to spread their capital around.
  // Warning about that every time would just be noise with no real action
  // to take, so skip it when the dominant holding is a rare.
  const dominatedByRare = topItemAlloc?.category === 'rares' || topCategoryAlloc?.category === 'rares';
  const concentrationWarning = !dominatedByRare && (
    (topItemAlloc && topItemAlloc.pct >= ITEM_CONCENTRATION_WARN_PCT)
    || (topCategoryAlloc && topCategoryAlloc.pct >= CATEGORY_CONCENTRATION_WARN_PCT)
  );

  // Real picks pulled from the Almanac's trade-idea engine, steered toward
  // categories the portfolio barely touches — the best payout candidate
  // currently dominating Recommendations might be the SAME category
  // that's already overweight here, which wouldn't help diversify at all.
  const UNDEREXPOSED_CATEGORY_PCT = 15;
  // High-tier combat gear (BIS-tier weapons/armour) tends to be extremely
  // volatile and trend gradually downward over time as supply builds up —
  // a real, repeating pattern, but the opposite of "stable thing to add to
  // a diversified portfolio." Even after the confidence-floor fix below,
  // Omni guard (necromancy, ~164M gp) still squeaked past at exactly the
  // 70% bar — Ben: "we should avoid suggesting high tier combat items,
  // they're generally extremely volatile and gradually decline over time."
  // Gating combat-style gear above a price floor specifically (rather than
  // banning the categories outright) keeps cheap/stable melee-etc. items
  // suggestible while excluding the expensive BIS-tier gear this is
  // actually about.
  const COMBAT_GEAR_CATEGORIES = new Set(['melee', 'ranged', 'magic', 'necromancy', 'hybrid']);
  const HIGH_TIER_COMBAT_PRICE_GP = 10_000_000;
  const diversificationSuggestions = useMemo(() => {
    if (!dxpData) return [];
    const overweightCategories = new Set(
      categoryAllocations.filter(c => c.pct >= UNDEREXPOSED_CATEGORY_PCT && c.category !== 'rares').map(c => c.category)
    );
    // Same "Confirmed" confidence bar as the main Almanac table (Ben caught
    // this: Elite Dracolich hauberk got suggested with only a bare 50%
    // directional majority — below the 70% bar that would normally tag it
    // Speculative — purely because its astronomical price x buy-limit made
    // its raw gp payout huge despite the weak signal. Ranking by gp payout
    // alone, with no confidence floor, let weak-but-expensive items crowd
    // out strong-but-cheap ones here specifically (the main Recommendations
    // tab already guards against this for the "safe" risk tolerance).
    const candidates = computeRecommendationCandidates(dxpData, priceById)
      .filter(r => !r.negligible && r.bestRatio >= ALMANAC_CONFIDENCE_THRESHOLD && !overweightCategories.has(r.category))
      .filter(r => !(COMBAT_GEAR_CATEGORIES.has(r.category) && r.price >= HIGH_TIER_COMBAT_PRICE_GP))
      .sort((a, b) => (b.trade.profitForLimit ?? -Infinity) - (a.trade.profitForLimit ?? -Infinity));
    // Best one per underexposed category, not just the top N overall —
    // otherwise this could still surface 5 picks from a single category.
    const seen = new Set();
    const picks = [];
    for (const r of candidates) {
      if (seen.has(r.category)) continue;
      seen.add(r.category);
      picks.push(r);
      if (picks.length >= 5) break;
    }
    return picks;
  }, [dxpData, priceById, categoryAllocations]);

  const handleSave = async (pos, createAlert) => {
    await onSavePosition(pos);
    if (createAlert && pos.target_price) {
      await window.genius?.saveAlert({id:`p-${pos.id}`, item_name:pos.item_name, condition:'above', price:pos.target_price});
    }
    if (pos.stop_loss) {
      await window.genius?.saveAlert({id:`sl-${pos.id}`, item_name:pos.item_name, condition:'below', price:pos.stop_loss});
    }
    setShowModal(false); setEditPos(null);
    toast(editPos ? 'Position updated' : 'Position added', 'success');
  };

  return h('div', {className:'tab-content'},

    h('div',{style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, TAB_DESCRIPTIONS.portfolio),

    // Overview
    h('div', {className:'overview-grid'},
      h('div',{className:'ov-card'}, h('div',{className:'ov-val'},fmt.gp(totalInvested)+'gp'), h('div',{className:'ov-lbl'},'Total Invested')),
      h('div',{className:'ov-card'}, h('div',{className:'ov-val'},fmt.gp(totalCurrent)+'gp'),  h('div',{className:'ov-lbl'},priceMode === 'live' ? 'Current Value (Live)' : 'Current Value (GE)')),
      h('div',{className:'ov-card'},
        h('div',{className:'ov-val '+(unrealizedPL>=0?'pct-up':'pct-down')},
          (unrealizedPL>=0?'+':'')+fmt.gp(unrealizedPL)+'gp'),
        h('div',{className:'ov-lbl', title:'Profit & Loss on positions you still hold — what you\'d gain or lose if you sold everything open right now. Not real until you actually sell.'},
          `Unrealized P&L (${unrealizedPct>=0?'+':''}${unrealizedPct.toFixed(1)}%)`)
      ),
      h('div',{className:'ov-card'},
        h('div',{className:'ov-val '+(realizedPL>=0?'pct-up':'pct-down')},
          (realizedPL>=0?'+':'')+fmt.gp(realizedPL)+'gp'),
        h('div',{className:'ov-lbl', title:'Profit & Loss already locked in from positions you\'ve actually sold, after GE tax.'},'Realized P&L')
      ),
    ),

    h(NetWorthChart, null),

    // Toolbar
    h('div',{style:{padding:'8px 12px',borderBottom:`1px solid ${T.border}`,display:'flex',justifyContent:'space-between',alignItems:'center'}},
      h('div', {style:{display:'flex', alignItems:'center', gap:10}},
        h('span',{style:{fontSize:12,color:T.textDim}},`${openPos.length} open position${openPos.length!==1?'s':''}`),
        h('button', {
          className:'ge-btn', style:{fontSize:11, padding:'3px 10px'},
          onClick: togglePriceMode,
          title: priceMode === 'ge' ? 'Valuing positions at the GE (listed) price. Click for live sell prices.' : 'Valuing positions at live sell prices. Click for the GE (listed) price.',
        }, priceMode === 'ge' ? 'GE Price' : 'Live Price'),
      ),
      h('button',{className:'ge-btn gold',onClick:()=>{setEditPos(null);setShowModal(true);}}, '+ Add Position')
    ),

    // Positions table
    openPos.length === 0
      ? h('div',{className:'empty-state'},
          h('div',{style:{fontSize:32,marginBottom:8}},'📊'),
          h('div',null,'No open positions.'),
          h('div',{style:{fontSize:12,color:T.textDim,marginTop:8,lineHeight:1.7,maxWidth:360,textAlign:'center'}},
            'Hit "+ Add Position" above to log a buy.',h('br',null),
            'GEnius will track live P&L, set target price alerts, and show your portfolio allocation.',h('br',null),
            'Sold positions move to the history section below.'
          )
        )
      : h('table',{className:'ge-table pt-portfolio'},
          h('thead',null, h('tr',null,
            h('th',null,'Item'), h('th',{title:'Quantity, and what you paid per item'},'Qty @ cost'),
            h('th',{title:(priceMode === 'live' ? 'Live sell' : 'GE (listed)') + ' price per item, and the whole position\'s value'}, priceMode === 'live' ? 'Price / value (Live)' : 'Price / value (GE)'),
            h('th',{title:'Profit & Loss — what you\'d actually pocket if you sold at the current price right now, after the 2% GE tax — and the same as a % of what you paid.'},'Net P&L'),
            h('th',{title:'The sell price that breaks even after GE tax, how far away it is, and when the item last traded that high'},'Break-even'),
            h('th',{title:'Highest and lowest daily GE price since you bought, the best profit you could have taken (after tax), and the worst point'},'Since bought'),
            h('th',{title:'How long you\'ve held it, and your target price'},'Held / target'), h('th',null,'')
          )),
          h('tbody',null, posGroups.flatMap(list => {
            if (list.length === 1) return [positionRow(list[0], false)];
            const name = list[0].item_name, key = name.toLowerCase(), open = expandedItems.has(key);
            const qty = list.reduce((s, p) => s + p.quantity, 0);
            const cost = list.reduce((s, p) => s + p.costValue, 0);
            const value = list.reduce((s, p) => s + p.currentValue, 0);
            const net = list.reduce((s, p) => s + p.netPL, 0);
            const price = list[0].currentPrice, avg = cost / qty;
            const be = breakEvenOf(avg);
            const ranges = list.map(p => sinceBought[p.id]).filter(Boolean);
            const toggle = () => setExpandedItems(s => { const n = new Set(s); n.has(key) ? n.delete(key) : n.add(key); return n; });
            return [h('tr',{key:'group:'+key, onClick:toggle, style:{cursor:'pointer'}},
              h('td',{style:{color:T.gold}}, h('span',{style:{display:'inline-block', width:14}}, open ? '▾' : '▸'), name,
                h('span',{style:{marginLeft:6, fontSize:10, color:T.textDim, whiteSpace:'nowrap'}}, list.length+' positions'), riskBadgeFor(list)),
              h('td',null, h('div',{style:{whiteSpace:'nowrap'}},qty.toLocaleString()), h('div',{style:{fontSize:10, color:T.textDim, whiteSpace:'nowrap'}},'avg @ '+fmt.gp(Math.round(avg))+'gp')),
              h('td',null, h('div',{style:{whiteSpace:'nowrap'}},fmt.gp(value)+'gp'), h('div',{style:{fontSize:10, color:T.gold, whiteSpace:'nowrap'}},fmt.gp(price)+'gp ea')),
              h('td',{className:net>=0?'pct-up':'pct-down'}, h('div',{style:{whiteSpace:'nowrap'}},(net>=0?'+':'')+fmt.gp(net)+'gp'), h('div',{style:{fontSize:10, whiteSpace:'nowrap'}},fmt.pct(cost > 0 ? (value - cost) / cost * 100 : 0))),
              net >= 0 || !(price > 0)
                ? h('td',{style:{color:T.textDim}}, net >= 0 ? '✓' : '—')
                : h('td',{title:`Across all ${list.length} positions, sell at ${be.toLocaleString()}gp or more to break even after the 2% GE tax.`}, h('div',{style:{whiteSpace:'nowrap'}},fmt.gp(be)+'gp'), h('div',{style:{fontSize:10, color:T.red, whiteSpace:'nowrap'}},'+'+((be - price) / price * 100).toFixed(1)+'%')),
              ranges.length
                ? h('td',null, h('div',{style:{fontSize:11, whiteSpace:'nowrap'}}, h('span',{style:{color:T.green}},'▲ '+fmt.gp(Math.max(...ranges.map(r => r.hi.price)))),' ',h('span',{style:{color:T.red}},'▼ '+fmt.gp(Math.min(...ranges.map(r => r.lo.price))))))
                : h('td',{style:{color:T.textDim}},'—'),
              h('td',{style:{color:T.textDim, whiteSpace:'nowrap'}}, heldText(Math.min(...list.map(heldSinceOf).filter(Boolean)))),
              h('td',null)),
              ...(open ? list.map(p => positionRow(p, true)) : [])];
          }))
        ),

    // Diversification warning — flags real concentration risk in tracked
    // capital, separate from the Almanac's own diversification logic in
    // Recommendations (that one shapes what gets suggested; this one
    // reacts to what you've actually already bought).
    totalCurrent > 0 && concentrationWarning && h('div',{style:{padding:'12px',marginTop:4,borderTop:`1px solid ${T.border}`}},
      h('div',{style:{fontSize:11, color:T.gold, border:`1px solid ${T.borderDim}`, borderRadius:4, padding:'8px 10px'}},
        '⚠ ', h('b',null,'Concentration risk: '),
        topItemAlloc && topItemAlloc.pct >= ITEM_CONCENTRATION_WARN_PCT && h('span', null,
          `${topItemAlloc.pct.toFixed(0)}% of your tracked portfolio is in ${topItemAlloc.name} alone. `
        ),
        topCategoryAlloc && topCategoryAlloc.pct >= CATEGORY_CONCENTRATION_WARN_PCT && h('span', null,
          `${topCategoryAlloc.pct.toFixed(0)}% is in ${CAT_LABEL[topCategoryAlloc.category] || topCategoryAlloc.category} items overall. `
        ),
        'A single item or category dropping hits you a lot harder than if this were spread out.'
      )
    ),

    // Diversification suggestions — dev-mode only. Uses the Almanac's
    // trade-idea engine to FIND worthwhile items in underexposed
    // categories, but deliberately doesn't show the DXP profit/timing
    // figures here — those imply a short-term flip, and Portfolio isn't
    // necessarily that (Ben: "the portfolio isn't always for short term
    // flips and trades... just some item suggestions"). Just the item and
    // category, nothing tying it to a buy/sell day.
    diversificationSuggestions.length > 0 && h('div',{style:{padding:'12px',marginTop:4,borderTop:`1px solid ${T.border}`}},
      h('div',{className:'ge-section-head'},'Diversification suggestions'),
      h('div',{style:{fontSize:11,color:T.textDim,fontStyle:'italic',marginBottom:8}},
        'Items worth a look in categories your portfolio barely touches — not financial advice, and not tied to any particular timing. Click one to check it out.'
      ),
      diversificationSuggestions.map(r => h('div',{
        key:r.id, style:{padding:'6px 0',borderBottom:`1px solid ${T.borderDim}`,cursor: onSelect?'pointer':'default'},
        onClick: onSelect ? ()=>onSelect(priceById[r.id]) : undefined,
      },
        h('div',{style:{color:T.gold,fontSize:12}},r.name),
        h('div',{style:{color:T.textDim,fontSize:10}},CAT_LABEL[r.category] || r.category),
      ))
    ),

    // Allocation — by item or by category, one section toggled by a button
    // rather than two separate always-visible blocks (Ben's ask, 2026-07-29:
    // they cover the same underlying gp, just grouped differently, so
    // showing both stacked was redundant scrolling for the same idea twice).
    totalCurrent > 0 && (allocations.length > 0 || categoryAllocations.length > 0) && h('div',{style:{padding:'12px',marginTop:4,borderTop:`1px solid ${T.border}`}},
      h('div',{style:{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}},
        h('div',{className:'ge-section-head',style:{margin:0}},'Portfolio Allocation'),
        h('div',{style:{display:'flex',gap:4}},
          ['item','category'].map(v => h('button',{
            key:v, onClick:()=>setAllocView(v),
            style:{
              padding:'2px 10px', fontSize:10, cursor:'pointer', borderRadius:3,
              background: allocView===v ? 'rgba(201,168,76,0.2)' : 'transparent',
              border: `1px solid ${allocView===v ? T.gold : T.border}`,
              color: allocView===v ? T.goldBright : T.textDim,
            }
          }, v==='item' ? 'By Item' : 'By Category'))
        )
      ),
      allocView === 'item' && allocations.map(({name,val,pct}) => {
        const allocItem = onSelect && items && items.find(i => i.name.toLowerCase() === name.toLowerCase());
        return h('div',{key:name,style:{marginBottom:8}},
          h('div',{style:{display:'flex',justifyContent:'space-between',fontSize:11,marginBottom:2}},
            h('span',{
              style:{color: allocItem ? T.gold : T.text, cursor: allocItem ? 'pointer' : 'default'},
              onClick: allocItem ? () => onSelect(allocItem) : undefined,
            },name),
            h('span',{style:{color:T.textDim}},`${fmt.gp(val)}gp (${pct.toFixed(1)}%)`)
          ),
          h('div',{className:'alloc-bar-bg'},
            h('div',{className:'alloc-bar-fg',style:{width:`${pct}%`}})
          )
        );
      }),
      allocView === 'category' && categoryAllocations.map(({category,val,pct}) =>
        h('div',{key:category,style:{marginBottom:8}},
          h('div',{style:{display:'flex',justifyContent:'space-between',fontSize:11,marginBottom:2}},
            h('span',{style:{color: pct >= CATEGORY_CONCENTRATION_WARN_PCT ? T.gold : T.text}}, CAT_LABEL[category] || category),
            h('span',{style:{color:T.textDim}},`${fmt.gp(val)}gp (${pct.toFixed(1)}%)`)
          ),
          h('div',{className:'alloc-bar-bg'},
            h('div',{className:'alloc-bar-fg',style:{width:`${pct}%`, background: pct >= CATEGORY_CONCENTRATION_WARN_PCT ? T.gold : undefined}})
          )
        )
      )
    ),

    // Tax tracking
    h('div',{style:{padding:'12px',borderTop:`1px solid ${T.border}`,marginTop:4}},
      h('div',{className:'ge-section-head'},'GE Tax Tracking'),
      h('div',{className:'overview-grid'},
        h('div',{className:'ov-card'},h('div',{className:'ov-val'},fmt.gp(taxStats.today_tax||0)+'gp'),h('div',{className:'ov-lbl'},'Tax Today')),
        h('div',{className:'ov-card'},h('div',{className:'ov-val'},fmt.gp(taxStats.week_tax||0)+'gp'),h('div',{className:'ov-lbl'},'Tax This Week')),
        h('div',{className:'ov-card'},h('div',{className:'ov-val'},fmt.gp(taxStats.month_tax||0)+'gp'),h('div',{className:'ov-lbl'},'Tax This Month')),
        h('div',{className:'ov-card'},h('div',{className:'ov-val'},fmt.gp(taxStats.lifetime_tax||0)+'gp'),h('div',{className:'ov-lbl'},'Lifetime Tax')),
      )
    ),

    // Closed positions
    currentTier && h('div',{style:{padding:'12px',borderTop:`1px solid ${T.border}`}},
      h('div',{style:{display:'flex',alignItems:'center',gap:6,marginBottom:8}},
        h('div',{className:'ge-section-head',style:{margin:0}},'Investor Tier'),
        h('span',{
          onClick:()=>setTierModal('investor'),
          title:'View all tiers',
          style:{cursor:'pointer', fontSize:11, color:T.textDim, border:`1px solid ${T.borderDim}`, borderRadius:'50%', width:16, height:16, display:'inline-flex', alignItems:'center', justifyContent:'center'},
        }, '≡'),
      ),
      h('div',{style:{display:'flex',flexWrap:'wrap',gap:8,alignItems:'flex-start'}},
        // Next tier — goal badge
        nextTier && h('div',{key:'next',title:`${nextTier.label} · ${nextTier.sub}`,style:{
          display:'flex',flexDirection:'column',alignItems:'center',gap:3,
          padding:'8px 12px',borderRadius:4,minWidth:68,
          border:`1px dashed ${T.borderDim}`,background:T.panel,opacity:0.6,
        }},
          h('div',{style:{fontSize:20,filter:'grayscale(1)'}},nextTier.icon),
          h('div',{style:{fontSize:11,fontWeight:'bold',color:T.textDim}},nextTier.label.replace(' Investor','')),
          h('div',{style:{fontSize:10,color:T.textDim}},'Next'),
        ),
        // Current tier — highlighted
        h('div',{key:'cur',title:`${currentTier.label} · ${currentTier.sub}`,style:{
          display:'flex',flexDirection:'column',alignItems:'center',gap:3,
          padding:'8px 12px',borderRadius:4,minWidth:68,
          border:`1.5px solid ${T.gold}`,background:`rgba(201,168,76,0.1)`,
        }},
          h('div',{style:{fontSize:20}},currentTier.icon),
          h('div',{style:{fontSize:11,fontWeight:'bold',color:T.gold}},currentTier.label.replace(' Investor','')),
          h('div',{style:{fontSize:10,color:T.goldBright}},'Current'),
        ),
        // Earned lower tiers — faded
        earnedTiers.map(t => h('div',{key:t.label,title:`${t.label} · ${t.sub}`,style:{
          display:'flex',flexDirection:'column',alignItems:'center',gap:3,
          padding:'8px 12px',borderRadius:4,minWidth:68,
          border:`1px solid ${T.borderDim}`,background:T.panel,opacity:0.55,
        }},
          h('div',{style:{fontSize:20}},t.icon),
          h('div',{style:{fontSize:11,fontWeight:'bold',color:T.text}},t.label.replace(' Investor','')),
        )),
      ),
      h('div',{style:{fontSize:11,color:T.textDim,marginTop:8}},
        currentTier.label+' · '+currentTier.sub+' · '+fmt.gp(totalCurrent)+'gp invested'
      ),
    ),

    currentTradeTier && h('div',{style:{padding:'12px',borderTop:`1px solid ${T.border}`}},
      h('div',{style:{display:'flex',alignItems:'center',gap:6,marginBottom:8}},
        h('div',{className:'ge-section-head',style:{margin:0}},'Trade Count'),
        h('span',{
          onClick:()=>setTierModal('tradeCount'),
          title:'View all tiers',
          style:{cursor:'pointer', fontSize:11, color:T.textDim, border:`1px solid ${T.borderDim}`, borderRadius:'50%', width:16, height:16, display:'inline-flex', alignItems:'center', justifyContent:'center'},
        }, '≡'),
      ),
      h('div',{style:{display:'flex',flexWrap:'wrap',gap:8,alignItems:'flex-start'}},
        nextTradeTier && h('div',{key:'next',title:`${nextTradeTier.label} · ${nextTradeTier.sub}`,style:{
          display:'flex',flexDirection:'column',alignItems:'center',gap:3,
          padding:'8px 12px',borderRadius:4,minWidth:68,
          border:`1px dashed ${T.borderDim}`,background:T.panel,opacity:0.6,
        }},
          h('div',{style:{fontSize:20,filter:'grayscale(1)'}},nextTradeTier.icon),
          h('div',{style:{fontSize:11,fontWeight:'bold',color:T.textDim}},nextTradeTier.label),
          h('div',{style:{fontSize:10,color:T.textDim}},'Next'),
        ),
        h('div',{key:'cur',title:`${currentTradeTier.label} · ${currentTradeTier.sub}`,style:{
          display:'flex',flexDirection:'column',alignItems:'center',gap:3,
          padding:'8px 12px',borderRadius:4,minWidth:68,
          border:`1.5px solid ${T.gold}`,background:`rgba(201,168,76,0.1)`,
        }},
          h('div',{style:{fontSize:20}},currentTradeTier.icon),
          h('div',{style:{fontSize:11,fontWeight:'bold',color:T.gold}},currentTradeTier.label),
          h('div',{style:{fontSize:10,color:T.goldBright}},'Current'),
        ),
        earnedTradeTiers.map(t => h('div',{key:t.label,title:`${t.label} · ${t.sub}`,style:{
          display:'flex',flexDirection:'column',alignItems:'center',gap:3,
          padding:'8px 12px',borderRadius:4,minWidth:68,
          border:`1px solid ${T.borderDim}`,background:T.panel,opacity:0.55,
        }},
          h('div',{style:{fontSize:20}},t.icon),
          h('div',{style:{fontSize:11,fontWeight:'bold',color:T.text}},t.label),
        )),
      ),
      h('div',{style:{fontSize:11,color:T.textDim,marginTop:8}},
        currentTradeTier.label+' · '+currentTradeTier.sub+' · '+closedPos.length.toLocaleString()+' trades closed'
      ),
    ),

    milestones.length > 0 && h('div',{style:{padding:'12px',borderTop:`1px solid ${T.border}`}},
      h('div',{className:'ge-section-head'},'Achievements'),
      h('div',{style:{display:'flex',flexWrap:'wrap',gap:8}},
        milestones.map((m,i) => h('div',{key:i,style:{
          display:'flex',flexDirection:'column',alignItems:'center',gap:3,
          padding:'8px 12px',borderRadius:4,minWidth:68,
          border:`1.5px solid ${m.dimmed ? T.borderDim : T.gold}`,
          background: m.dimmed ? T.panel : `rgba(201,168,76,0.1)`,
          opacity: m.dimmed ? 0.5 : 1,
        }},
          h('div',{style:{fontSize:20,filter:m.dimmed?'grayscale(1)':'none'}},m.icon),
          h('div',{style:{fontSize:11,fontWeight:'bold',color:m.dimmed?T.textDim:T.gold}},m.label),
          m.value && h('div',{style:{fontSize:12,fontWeight:'bold',color:m.dimmed?T.textDim:T.textBright,marginTop:1}},m.value),
          h('div',{style:{fontSize:10,color:T.textDim,marginTop:1,textAlign:'center'}},m.sub),
        ))
      )
    ),

    consolationPrizes.length > 0 && h('div',{style:{padding:'12px',borderTop:`1px solid ${T.border}`}},
      h('div',{className:'ge-section-head', title:'The loss-side Achievements. Earned the hard way.'},'Consolation Prizes'),
      h('div',{style:{display:'flex',flexWrap:'wrap',gap:8}},
        consolationPrizes.map((m,i) => h('div',{key:i,style:{
          display:'flex',flexDirection:'column',alignItems:'center',gap:3,
          padding:'8px 12px',borderRadius:4,minWidth:68,maxWidth:190,
          border:`1.5px solid ${T.red}`,
          background:'rgba(229,57,53,0.08)',
        }},
          h('div',{style:{fontSize:20}},m.icon),
          h('div',{style:{fontSize:11,fontWeight:'bold',color:T.red,textAlign:'center'}},m.label),
          m.value && h('div',{style:{fontSize:12,fontWeight:'bold',color:T.textBright,marginTop:1}},m.value),
          h('div',{style:{fontSize:10,color:T.textDim,marginTop:1,textAlign:'center'}},m.sub),
        ))
      )
    ),

    realizedByItem.length > 0 && h('div',{style:{padding:'12px',borderTop:`1px solid ${T.border}`}},
      h('div',{className:'ge-section-head'},'Realized P&L by Item'),
      h('div',{className:'ge-table-wrap'},
        h('table',{className:'ge-table pt-realized'},
          h('thead',null,h('tr',null,
            h('th',null,'Item'), h('th',null,'Trades'), h('th',null,'Qty'),
            h('th',null,'Realized P&L'),
            h('th',{title:'Share of total realized P&L (gains and losses both counted by size), so a big loss shows its real weight too.'},'% of total'),
          )),
          h('tbody',null, realizedByItem.map(r => h('tr',{
            key:r.name,
            onClick: onSelect ? () => { const it = items.find(i => i.name.toLowerCase()===r.name.toLowerCase()); if (it) onSelect(it); } : undefined,
            style:{cursor: onSelect ? 'pointer' : 'default'},
          },
            h('td',{style:{color:T.gold}},r.name),
            h('td',null,r.trades.toLocaleString()),
            h('td',null,r.qty.toLocaleString()),
            h('td',{className:r.pl>=0?'pct-up':'pct-down'},(r.pl>=0?'+':'')+fmt.gp(r.pl)+'gp'),
            h('td',{style:{color:T.textDim}},r.pct.toFixed(1)+'%'),
          )))
        )
      ),
      h('div',{style:{fontSize:11,color:T.textDim,marginTop:8,textAlign:'right'}},
        `${closedPos.length.toLocaleString()} closed trades total · `,
        h('span',{style:{color: realizedByItem.reduce((s,r)=>s+r.pl,0)>=0?T.green:T.red, fontWeight:'bold'}},
          (realizedByItem.reduce((s,r)=>s+r.pl,0)>=0?'+':'')+fmt.gp(realizedByItem.reduce((s,r)=>s+r.pl,0))+'gp'
        ),
      ),
    ),

    closedPos.length > 0 && h('div',{style:{padding:'12px',borderTop:`1px solid ${T.border}`}},
      h('div',{style:{display:'flex',justifyContent:'space-between',alignItems:'center',cursor:'pointer',marginBottom:showClosed?8:0},
        onClick:()=>setShowClosed(s=>!s)},
        h('div',{className:'ge-section-head',style:{margin:0}},`Closed Positions (${closedPos.length})`),
        h('span',{style:{color:T.textDim}},showClosed?'▲':'▼')
      ),
      showClosed && (() => {
        const pctTd = v => v == null ? h('td',{style:{color:T.textDim}},'—') : h('td',{className: v >= 0 ? 'pct-up' : 'pct-down'}, (v > 0 ? '+' : '') + v.toFixed(1) + '%');
        const plTd = v => h('td',{className: v >= 0 ? 'pct-up' : 'pct-down'}, (v >= 0 ? '+' : '') + fmt.gp(v) + 'gp');
        const thSort = (key, label, title) => h('th',{onClick:()=>toggleClosedSort(key), style:{cursor:'pointer'}, title},
          label + (closedSort.key === key ? (closedSort.dir > 0 ? ' ↑' : ' ↓') : ''));
        // Clicking a single trade edits it; right-click deletes, as before.
        const openTrade = pos => ({ onClick: e => { e.stopPropagation(); setEditPos(pos); setShowModal(true); },
          onContextMenu: e => { e.preventDefault(); e.stopPropagation(); setCtxMenu({x:e.clientX, y:e.clientY, pos}); } });
        const rows = [];
        for (const g of sortedGroups) {
          const many = g.trades.length > 1, open = many && openGroups[g.key];
          // One-trade items: the row IS the trade.
          const rowProps = many ? { onClick: () => setOpenGroups(o => ({...o, [g.key]: !o[g.key]})) } : openTrade(g.trades[0]);
          rows.push(h('tr',{key:'g_'+g.key, ...rowProps, style:{cursor:'pointer'}},
            h('td',null,
              h('span',{style:{display:'inline-block', width:16, color:T.textDim}}, many ? (open ? '▾' : '▸') : ''),
              g.name,
              h('span',{style:{marginLeft:8, fontSize:11, color:T.textDim}}, g.trades.length + ' trade' + (many ? 's' : ''))),
            h('td',null, g.qty.toLocaleString()),
            h('td',{style:{color:T.textDim}}, g.sales.length ? g.wins + ' of ' + g.sales.length : '—'),
            pctTd(g.ret),
            h('td',{style:{color:T.textDim}}, g.tax ? fmt.gp(g.tax) + 'gp' : '—'),
            h('td',{style:{color:T.textDim}}, fmtPosDate(g.last)),
            g.sales.length ? plTd(g.pl) : h('td',{style:{color:T.blue}}, '→ ' + g.trades[0].converted_to)));
          if (open) for (const p of g.trades) {
            const conv = p.status === 'converted';
            rows.push(h('tr',{key:p.id, ...openTrade(p), style:{cursor:'pointer', background:T.inset, fontSize:12}},
              h('td',{style:{paddingLeft:28, color:T.textDim}}, conv ? 'Converted' : (p.sold_via === 'alch' ? 'Alched @ ' : 'Sold @ ') + fmt.gp(p.sold_price || 0) + 'gp',
                h('span',{style:{marginLeft:8, fontSize:11}}, 'cost ' + fmt.gp(p.cost_basis) + 'gp')),
              h('td',null, tradeQty(p).toLocaleString()),
              h('td',null),
              pctTd(tradeReturn(p)),
              h('td',{style:{color:T.textDim}}, conv ? '—' : fmt.gp(tradeTax(p)) + 'gp'),
              h('td',{style:{color:T.textDim}}, fmtPosDate(conv ? p.converted_at : p.sold_at)),
              conv ? h('td',{style:{color:T.blue}}, '→ ' + p.converted_to) : plTd(p.realized_pl || 0)));
          }
        }
        return h('table',{className:'ge-table pt-closed'},
          h('thead',null,h('tr',null,
            closedTh('item', 'Item'), closedTh('qty', 'Traded'),
            thSort('win', 'Win rate', 'Sales that made a profit, out of all sales of this item'),
            thSort('ret', 'Avg return', 'Total realized P&L as a % of the gp you paid for what you sold'),
            closedTh('tax', 'Tax paid'), closedTh('date', 'Last closed'),
            thSort('pl', 'Total P&L', 'Profit & Loss locked in on these sales, after GE tax. Conversions have no realized P&L: no cash changed hands, the cost basis carried forward to the new item.'))),
          h('tbody',null, rows));
      })()
    ),

    // Closed position context menu
    ctxMenu && createPortal(h('div', {
      style:{position:'fixed', inset:0, zIndex:800},
      onClick: () => setCtxMenu(null),
      onContextMenu: e => { e.preventDefault(); setCtxMenu(null); },
    },
      h('div', {style:{
        position:'fixed',
        left: ctxMenu.x + 180 > window.innerWidth  ? ctxMenu.x - 160 : ctxMenu.x,
        top:  ctxMenu.y + 100 > window.innerHeight ? ctxMenu.y - 80  : ctxMenu.y,
        zIndex:801,
        background:T.panel2, border:`1px solid ${T.border}`, borderRadius:4,
        boxShadow:'0 4px 12px rgba(0,0,0,0.5)', minWidth:160, overflow:'hidden',
      }},
        h('div', {style:{padding:'6px 8px', fontSize:10, color:T.textDim, borderBottom:`1px solid ${T.borderDim}`}},
          ctxMenu.pos.item_name
        ),
        h('div', {
          onClick: async () => {
            const res = await onReopenPosition(ctxMenu.pos.id);
            setCtxMenu(null);
            if (res?.success) toast('Position reopened', 'success');
            else toast(res?.error || 'Could not reopen position', 'error');
          },
          style:{padding:'8px 12px', fontSize:12, color:T.text, cursor:'pointer', display:'flex', alignItems:'center', gap:6},
          onMouseEnter: e => e.currentTarget.style.background = 'rgba(255,255,255,0.06)',
          onMouseLeave: e => e.currentTarget.style.background = 'transparent',
        }, '↩ Reopen position'),
        h('div', {
          onClick: async () => {
            await onDeletePosition(ctxMenu.pos.id);
            setCtxMenu(null);
            toast('Position removed', 'success');
          },
          style:{padding:'8px 12px', fontSize:12, color:T.red, cursor:'pointer', display:'flex', alignItems:'center', gap:6},
          onMouseEnter: e => e.currentTarget.style.background = 'rgba(229,57,53,0.1)',
          onMouseLeave: e => e.currentTarget.style.background = 'transparent',
        }, '🗑 Delete position'),
      )
    ), document.body),

    // Modals
    showModal && h(PositionModal, {items, position:editPos, onClose:()=>{setShowModal(false);setEditPos(null);}, onSave:handleSave, userShorthands}),
    sellModal  && h(SellModal,    {position:sellModal, onClose:()=>setSellModal(null),
      item: items.find(it => it.name.toLowerCase() === (sellModal.item_name || '').toLowerCase()),
      onSell: async (opts) => {
        const res = await onSellPosition(opts);
        setSellModal(null);
        if (res?.success) toast(`${opts.alch ? 'Alched' : 'Sold'}! Net P&L: ${res.realized_pl>=0?'+':''}${fmt.gp(res.realized_pl)}gp`, 'success');
        else toast(res?.error || 'Could not sell', 'error');
      }
    }),
    convertModal && h(ConvertModal, {position:convertModal, allItems:items, userShorthands, onClose:()=>setConvertModal(null),
      otherPositions: openPos.filter(p => p.id !== convertModal.id),
      onConvert: async (opts) => {
        const res = await onConvertPosition(opts);
        setConvertModal(null);
        if (res?.success) toast(`Converted! New cost basis: ${fmt.gp(res.newCostBasis)}gp`, 'success');
        else toast(res?.error || 'Conversion failed', 'error');
      }
    }),
    tierModal === 'investor'   && h(TierLadderModal, {title:'Investor Tier — all tiers', tiers:PORTFOLIO_TIERS, achievedIndex:tierIndex, onClose:()=>setTierModal(null)}),
    tierModal === 'tradeCount' && h(TierLadderModal, {title:'Trade Count — all tiers', tiers:TRADE_COUNT_TIERS, achievedIndex:tradeTierIndex, onClose:()=>setTierModal(null)})
  );
}

/* ─── First-run welcome tour ─────────────────────────────────── */
// Content drafted in TODO.txt (2026-08-05) — deliberately short (7 steps)
// since a tour that tries to cover everything just trains people to mash
// "skip". Picks non-obvious AND high-value things a new user could easily
// never stumble onto (feature-discovery problem), not things that are
// already self-evident from clicking around (tab navigation, opening an
// item's detail panel, etc).
const WELCOME_TOUR_STEPS = [
  {
    icon: '🔍',
    title: 'Shorthand search',
    body: "Type a few letters or an acronym — FSOA, AGS, and 40+ others are built in — instead of a full item name. Add your own custom shorthands anytime in Settings.",
  },
  {
    icon: '📊',
    title: 'GE vs Live prices',
    body: "Most price columns show two numbers: GE (the 15-minute snapshot) and Live (the wiki's real-time buy/sell feed) — look for the toggle wherever you see a price.",
  },
  {
    icon: '🔔',
    title: 'Watchlist & Alerts',
    body: "Star any item to add it to your Watchlist, then set alerts on price thresholds, percent moves, or market signals — with optional Discord notifications.",
  },
  {
    icon: '⚡',
    title: 'Signal badges',
    body: "Badges like Surge, Dump, Frenzy, and Manipulated appear automatically on items showing unusual activity. Click one to see what triggered it.",
  },
  {
    icon: '🌦️',
    title: 'The GEnius Almanac',
    body: "Not just current prices — historical DXP-event intelligence, showing how items have actually moved across past Double XP Weekends.",
  },
  {
    icon: '💰',
    title: 'Portfolio is a real trade log',
    body: "Log actual positions, not just a watchlist — GE tax is handled automatically, and your full closed-trade history is kept.",
  },
  {
    icon: '🎯',
    title: 'Opportunity Score',
    body: "Not sure what to look at? Every item gets a 0–100 score from momentum, volume behavior, active signals, and alch profitability — ranked for you.",
  },
];

function WelcomeTour({onDone}) {
  const [step, setStep] = useState(0);
  const total = WELCOME_TOUR_STEPS.length;
  const s = WELCOME_TOUR_STEPS[step];
  const isLast = step === total - 1;

  useEffect(() => {
    const onKey = e => {
      if (e.key === 'Escape') onDone();
      else if (e.key === 'ArrowRight') setStep(v => Math.min(total - 1, v + 1));
      else if (e.key === 'ArrowLeft') setStep(v => Math.max(0, v - 1));
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [total, onDone]);

  return h('div', {className:'chart-modal-overlay', onClick:onDone},
    h('div', {className:'chart-modal', style:{width:440, padding:'22px 24px 18px'}, onClick:e=>e.stopPropagation()},
      h('div', {style:{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:18}},
        h('div', {style:{fontSize:10, color:T.textDim, letterSpacing:'0.08em', textTransform:'uppercase'}},
          `Welcome to GEnius — ${step+1} of ${total}`),
        h('button', {className:'ge-btn', style:{padding:'2px 9px', fontSize:11}, onClick:onDone}, 'Skip')
      ),
      h('div', {style:{textAlign:'center', marginBottom:20}},
        h('div', {style:{fontSize:38, marginBottom:10}}, s.icon),
        h('div', {style:{fontSize:16, fontWeight:'bold', color:T.goldBright, marginBottom:10}}, s.title),
        h('div', {style:{fontSize:13, color:T.text, lineHeight:1.6}}, s.body)
      ),
      h('div', {style:{display:'flex', justifyContent:'space-between', alignItems:'center'}},
        h('div', {style:{display:'flex', gap:5}},
          WELCOME_TOUR_STEPS.map((_, i) => h('div', {key:i, style:{
            width:6, height:6, borderRadius:'50%',
            background: i===step ? T.gold : T.border,
          }}))
        ),
        h('div', {style:{display:'flex', gap:8}},
          step > 0 && h('button', {
            className:'ge-btn', style:{padding:'5px 14px', fontSize:12},
            onClick:()=>setStep(v=>v-1)
          }, 'Back'),
          h('button', {
            className:'ge-btn gold', style:{padding:'5px 14px', fontSize:12},
            onClick:()=> isLast ? onDone() : setStep(v=>v+1)
          }, isLast ? 'Get Started' : 'Next')
        )
      )
    )
  );
}

/* ─── History population popup ───────────────────────────────── */
function HistoryPopup({state, onDismiss}) {
  if (!state) return null;
  // Always driven by the REAL persisted stored/total counts — never a
  // per-session counter that restarts at 0. That per-session counter
  // (items processed in just this run) is what made a resumed,
  // already-mostly-complete backfill look like it had lost hundreds or
  // thousands of items of progress on every single relaunch, when
  // nothing was actually lost (see SESSION_LOG.md, 2026-06-26).
  // initial300Done is persisted across restarts too, so an interruption
  // during the first 300 correctly resumes still showing "first 300"
  // messaging instead of jumping straight to "background" framing.
  const { stored, total, initial300Done, fullyComplete } = state;
  const pct = total > 0 ? Math.round((stored / total) * 100) : 0;

  return h('div', {style:{
    position:'fixed', bottom:20, right:20, zIndex:900,
    background:T.panel, border:`1px solid ${T.border}`,
    borderRadius:6, padding:'14px 16px', width:320,
    boxShadow:'0 4px 20px rgba(0,0,0,0.6)'
  }},
    h('div', {style:{display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:8}},
      h('div', {style:{fontSize:12, fontWeight:'bold', color:T.goldBright}},
        fullyComplete
          ? '✓ Price history complete'
          : initial300Done
            ? '📊 Building history in background...'
            : '📊 Building price history...'
      ),
      h('button', {
        className:'ge-btn', style:{padding:'1px 8px', fontSize:10},
        onClick:onDismiss
      }, '✕')
    ),

    !initial300Done && h('div', {style:{fontSize:11, color:T.textDim, marginBottom:10, lineHeight:1.5}},
      `Fetching history for the most traded items (${stored}/300). `,
      'After this, history builds in the background — any item you open populates immediately.'
    ),

    initial300Done && !fullyComplete && h('div', {style:{fontSize:11, color:T.textDim, marginBottom:10, lineHeight:1.5}},
      `${stored.toLocaleString()} of ${total.toLocaleString()} items loaded. `,
      'You can dismiss this — history continues even if hidden, and picks up where it left off if interrupted.'
    ),

    fullyComplete && h('div', {style:{fontSize:11, color:T.textDim, marginBottom:10}},
      state.unavailable && stored < total
        ? `${stored.toLocaleString()} items have price history. ${state.unavailable} (usually brand-new items) have none available yet — GEnius will try them again tomorrow.`
        : 'All GE items have price history. You\'re fully loaded.'
    ),

    h('div', {style:{background:'rgba(0,0,0,0.3)', borderRadius:3, height:6, overflow:'hidden'}},
      h('div', {style:{
        height:'100%', borderRadius:3,
        width: fullyComplete ? '100%' : `${pct}%`,
        background: fullyComplete ? T.green : initial300Done ? T.blue : T.gold,
        transition:'width 0.5s'
      }})
    ),
    !fullyComplete && h('div', {style:{fontSize:10, color:T.textDim, marginTop:4, display:'flex', justifyContent:'space-between'}},
      h('span', null, `${stored.toLocaleString()} / ${total.toLocaleString()} items`),
      h('span', null, `${pct}%`)
    )
  );
}

