function MoneyMakersTab({items, onSelect, description}) {
  const [skill, setSkill] = useState('archaeology');
  // Ctrl+K can open a skill directly (QuickSearch).
  useEffect(() => { const go = e => setSkill(e.detail); window.addEventListener('genius-money-skill', go); return () => window.removeEventListener('genius-money-skill', go); }, []);
  const [herbSub, setHerbSub] = useState('herbs');
  const [magicSub, setMagicSub] = useState('grinding');
  const [fletchingBuffs, setFletchingBuffs] = useState(FLETCHING_BUFF_DEFAULTS);
  const [varrockArmour, setVarrockArmour] = useState(false);
  const [smithSub, setSmithSub] = useState('scratch');
  const [summoningSub, setSummoningSub] = useState('pouches');
  const [buffs, setBuffs] = useState(HERBLORE_BUFF_DEFAULTS);
  const [craftingSub, setCraftingSub] = useState('cloth');
  const [craftingBuffs, setCraftingBuffs] = useState(CRAFTING_BUFF_DEFAULTS);

  const herbRows = useMemo(() => {
    return items
      .filter(it => it.name.toLowerCase().startsWith('grimy '))
      .map(it => {
        const cleanName = 'Clean ' + it.name.slice(6);
        const stats = computeConversionStats([{name: it.name, qty:1}], {name: cleanName, qty:1}, items);
        return { label: `${it.name} → ${cleanName}`, itemName: cleanName, stats };
      })
      .filter(r => r.stats.missing.length === 0);
  }, [items]);

  const potionRows = useMemo(() => {
    return POTION_RECIPES.map(r => {
      const stats = computePotionStats(r, items, buffs);
      return { label: `${r.name} (3)`, itemName: `${r.name} (3)`, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items, buffs]);

  const decantingRows = useMemo(() => {
    return POTION_RECIPES.map(r => {
      const stats = computeDecantingStats(r.name, items);
      if (stats.missing.length || !stats.buyForm || !stats.sellForm || stats.buyForm === stats.sellForm) return null;
      const label = `${r.name}: (${stats.buyForm.doses}) → (${stats.sellForm.doses})`;
      return { label, itemName: stats.sellForm.itemName, stats };
    }).filter(Boolean);
  }, [items]);

  const divinationRows = useMemo(() => {
    return DIVINATION_RECIPES.map(r => {
      const stats = computeConversionStats(r.inputs, r.output, items);
      return { label: r.name, itemName: r.output.name, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items]);

  const constructionRows = useMemo(() => {
    const plankMachine = INVENTION_MACHINES.find(m => m.id === 'plank');
    if (!plankMachine) return [];
    const chargeGpRate = machineChargeGpRate(items);
    const rows = [];
    for (const c of plankMachine.conversions) {
      const manualStats = computeConversionStats([{name:c.input, qty:1}], {name:c.output, qty:1}, items);
      if (manualStats.missing.length === 0) rows.push({ label: `${c.input} → ${c.output} (Manual, free)`, itemName: c.output, stats: manualStats });

      const chargeCost = plankMachine.chargePerItem * chargeGpRate;
      const machineStats = computeConversionStats([{name:c.input, qty:1}], {name:c.output, qty:1}, items);
      if (machineStats.missing.length === 0) {
        const adjusted = { ...machineStats, cost: machineStats.cost + chargeCost, margin: machineStats.margin != null ? machineStats.margin - chargeCost : null };
        rows.push({ label: `${c.input} → ${c.output} (Machine, ${fmt.gp(chargeCost)}gp charge)`, itemName: c.output, stats: adjusted });
      }
    }
    // Refined-plank -> Wooden frame chain, Fort Forinthry sawmill (Ben,
    // 2026-08-11): 4 Plank -> 1 Refined planks -> (3 Refined planks) 1
    // Wooden frame, i.e. 12 Plank per frame overall. Modeled as a single
    // combined conversion since "most people do not sell the refined
    // versions" — buy 12 Plank, sell 1 Wooden frame, skipping the
    // intermediate entirely (matches how it's actually played).
    const frameStats = computeConversionStats([{name:'Plank', qty:12}], {name:'Wooden frame', qty:1}, items);
    if (frameStats.missing.length === 0) rows.push({ label: '12 × Plank → Wooden frame (Fort Forinthry sawmill)', itemName:'Wooden frame', stats: frameStats });
    return rows;
  }, [items]);

  const magicSpellRows = (recipes, runes, inQtyKey, outQtyKey) => recipes.map(r => {
    const inQty = r[inQtyKey] ?? 1;
    const outQty = r[outQtyKey] ?? 1;
    const inputs = [{name:r.input, qty:inQty}, ...runes];
    const stats = computeConversionStats(inputs, {name:r.name, qty:outQty}, items);
    return { label: `${inQty} × ${r.input} → ${outQty} × ${r.name}`, itemName: r.name, stats };
  }).filter(r => r.stats.missing.length === 0);

  const grindingRows = useMemo(() => magicSpellRows(TELEKINETIC_GRIND_RECIPES, TELEKINETIC_GRIND_RUNES, 'inQty', 'outQty'), [items]);
  const tanningRows = useMemo(() => magicSpellRows(MAKE_LEATHER_RECIPES.map(r=>({...r, inQty:28, outQty:28})), MAKE_LEATHER_RUNES, 'inQty', 'outQty'), [items]);
  const boltRows = useMemo(() => magicSpellRows(ENCHANT_BOLT_RECIPES.map(r=>({...r, inQty:ENCHANT_BOLT_QTY, outQty:ENCHANT_BOLT_QTY})), ENCHANT_BOLT_RUNES, 'inQty', 'outQty'), [items]);

  // Ben (2026-08-12): he doesn't actually sell these — every Onyx/Ascendri
  // bolt he enchants goes straight into an Alchemiser (Invention device,
  // Divine charge cost / 500 per item, same math the Alch tab already
  // uses). Real revenue for him is high alch value, not GE sell price, so
  // this sits alongside the normal sell-based row rather than replacing
  // it — other players who DO sell the enchanted bolts still want that
  // number too.
  const boltAlchRows = useMemo(() => {
    const natureRunePrice = (items.find(it => it.natureRunePrice) || {}).natureRunePrice || 0;
    const divineChargeItem = items.find(it => it.name && it.name.toLowerCase() === 'divine charge');
    const divineChargePrice = liveBuyOf(divineChargeItem) || 0;
    const chargePerItem = divineChargePrice ? Math.round(divineChargePrice / 500) : 0;
    return ENCHANT_BOLT_RECIPES.map(r => {
      const inputCost = findItemBuyPrice(items, r.input);
      const outItem = items.find(it => it.name.toLowerCase() === r.name.toLowerCase());
      const alch = outItem ? (outItem.alch || 0) : 0;
      const runeCost = ENCHANT_BOLT_RUNES.reduce((s,ru) => s + (findItemBuyPrice(items, ru.name) || 0) * ru.qty, 0);
      if (inputCost == null || !alch) return null;
      // Per-bolt: buy 1 unenchanted bolt (+ this bolt's share of the
      // per-10-cast rune cost) -> enchant -> Alchemiser converts to coins
      // at high alch value, minus its own nature rune + charge cost.
      const costPerBolt = inputCost + runeCost/ENCHANT_BOLT_QTY;
      const alchemiserProfit = alch - costPerBolt - natureRunePrice - chargePerItem;
      return { name: r.name, costPerBolt, alch, alchemiserProfit };
    }).filter(Boolean);
  }, [items]);
  const humidifyRows = useMemo(() => magicSpellRows([{name:'Soft porcelain clay', input:'Porcelain clay', inQty:1, outQty:1}], HUMIDIFY_RUNES, 'inQty', 'outQty'), [items]);

  const fletchingRows = useMemo(() => {
    return FLETCHING_RECIPES.map(r => {
      const stats = computeFletchingRecipeStats(r, items, fletchingBuffs);
      const outLabel = stats.multiplier !== 1 ? `${(r.output.qty*stats.multiplier).toFixed(4)}× ${r.output.name}` : `${r.output.qty} × ${r.output.name}`;
      return { label: `${r.inputs.map(i=>`${i.qty} × ${i.name}`).join(' + ')} → ${outLabel}`, itemName:r.output.name, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items, fletchingBuffs]);

  const craftingRows = useMemo(() => {
    return CRAFTING_RECIPES.map(r => {
      const stats = computeConversionStats(r.inputs, r.output, items);
      return { label: `${r.inputs.map(i=>`${i.qty} × ${i.name}`).join(' + ')} → ${r.output.qty} × ${r.output.name}`, itemName:r.output.name, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items]);

  const urnRows = useMemo(() => {
    return URN_RECIPES.map(r => {
      const stats = computeUrnStats(r, items, craftingBuffs);
      const label = r.gem
        ? `${r.clayQty} × ${r.clay} + 1 × ${r.gem} → ${r.output}`
        : `${r.clayQty} × ${r.clay} → ${r.output}`;
      return { label, itemName:r.output, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items, craftingBuffs]);

  const dragonhideRows = useMemo(() => {
    return DRAGONHIDE_RECIPES.map(r => {
      const stats = computeDragonhideStats(r, items, craftingBuffs);
      return { label: `${r.leatherQty} × ${r.leather} → ${r.output}`, itemName:r.output, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items, craftingBuffs]);

  const smithingRows = useMemo(() => {
    return SMITHING_BAR_RECIPES.map(r => {
      const stats = computeSmithingBarStats(r, items, varrockArmour);
      const outLabel = stats.outQty !== 1 ? `${stats.outQty.toFixed(4).replace(/\.?0+$/,'')}× ${r.name}` : `1 × ${r.name}`;
      return { label: `${r.inputs.map(i=>`${i.qty} × ${i.name}`).join(' + ')} → ${outLabel}`, itemName:r.name, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items, varrockArmour]);

  const summoningRows = useMemo(() => {
    return SUMMONING_SCROLL_RECIPES.map(r => {
      const stats = computeSummoningScrollStats(r, items);
      return { label: `1 × ${r.pouch} → ${SUMMONING_SCROLLS_PER_POUCH} × ${r.scroll} (VoS)`, itemName:r.scroll, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items]);

  const ancientSummoningRows = useMemo(() => {
    return ANCIENT_SUMMONING_RECIPES.map(r => {
      const stats = computeSummoningScrollStats(r, items, ANCIENT_SUMMONING_SCROLLS_PER_CONTRACT);
      return { label: `1 × ${r.pouch} → ${ANCIENT_SUMMONING_SCROLLS_PER_CONTRACT} × ${r.scroll} (VoS)`, itemName:r.scroll, stats };
    }).filter(r => r.stats.missing.length === 0);
  }, [items]);

  const onSelectItem = (itemName) => {
    if (!onSelect) return;
    const it = items.find(i => i.name.toLowerCase() === itemName.toLowerCase());
    if (it) onSelect(it);
  };

  return h('div', {style:{padding:'4px 0'}},
    description && h('div', {style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}},
      description
    ),
    h('div', {style:{padding:'14px'}},
      h('div', {style:{display:'flex', gap:4, marginBottom:14, flexWrap:'wrap'}},
        MONEY_MAKER_SKILLS.map(s => h('button', {
          key:s.key, onClick:()=>setSkill(s.key),
          style:{
            padding:'4px 12px', fontSize:11, cursor:'pointer', borderRadius:3,
            background: skill===s.key ? 'rgba(201,168,76,0.2)' : 'transparent',
            border: `1px solid ${skill===s.key ? T.gold : T.border}`,
            color: skill===s.key ? T.goldBright : T.textDim,
          }
        }, s.label))
      ),

      skill === 'herblore' && h('div', null,
        h('div', {style:{display:'flex', gap:4, marginBottom:12}},
          ['herbs','potions','decanting'].map(sub => h('button', {
            key:sub, onClick:()=>setHerbSub(sub),
            style:{
              padding:'3px 10px', fontSize:10, cursor:'pointer', borderRadius:3,
              background: herbSub===sub ? 'rgba(201,168,76,0.2)' : 'transparent',
              border: `1px solid ${herbSub===sub ? T.gold : T.border}`,
              color: herbSub===sub ? T.goldBright : T.textDim,
              textTransform:'capitalize',
            }
          }, sub))
        ),
        herbSub === 'potions' && h(HerbloreBuffCheckboxes, {buffs, setBuffs}),
        herbSub === 'herbs' && h(MoneyMakerTable, {rows:herbRows, onSelect:onSelectItem}),
        herbSub === 'potions' && h(MoneyMakerTable, {rows:potionRows, onSelect:onSelectItem}),
        herbSub === 'decanting' && h(PhoneFold, {style:{fontSize:11, color:T.textDim, marginBottom:10, lineHeight:1.5}},
          'Price per dose across (1)/(2)/(3)/(4) and the 6-dose flask (flask price minus an empty Potion flask, so container cost isn\'t counted as potion value). Each row buys the cheapest dose form and decants into the priciest one for resale — both sides need real daily volume or the potion is left off entirely.'
        ),
        herbSub === 'decanting' && h(MoneyMakerTable, {rows:decantingRows, onSelect:onSelectItem}),
      ),

      skill === 'divination' && h(MoneyMakerTable, {rows:divinationRows, onSelect:onSelectItem}),

      skill === 'construction' && h(MoneyMakerTable, {rows:constructionRows, onSelect:onSelectItem}),

      skill === 'magic' && h('div', null,
        h('div', {style:{display:'flex', gap:4, marginBottom:12}},
          [{key:'grinding',label:'Grinding'},{key:'tanning',label:'Tanning'},{key:'bolts',label:'Bolt Enchanting'},{key:'humidify',label:'Humidify'}].map(sub => h('button', {
            key:sub.key, onClick:()=>setMagicSub(sub.key),
            style:{
              padding:'3px 10px', fontSize:10, cursor:'pointer', borderRadius:3,
              background: magicSub===sub.key ? 'rgba(201,168,76,0.2)' : 'transparent',
              border: `1px solid ${magicSub===sub.key ? T.gold : T.border}`,
              color: magicSub===sub.key ? T.goldBright : T.textDim,
            }
          }, sub.label))
        ),
        magicSub === 'grinding' && h(PhoneFold, {style:{fontSize:11, color:T.textDim, marginBottom:10, lineHeight:1.5}},
          'Telekinetic Grind — 2 Astral + 1 Law rune per cast (elemental staff covers the rest). Grinds up to 60 of a stackable item per cast.'
        ),
        magicSub === 'grinding' && h(MoneyMakerTable, {rows:grindingRows, onSelect:onSelectItem}),
        magicSub === 'tanning' && h(PhoneFold, {style:{fontSize:11, color:T.textDim, marginBottom:10, lineHeight:1.5}},
          'Make Leather — 2 Astral + 2 Body rune per cast (elemental staff covers the rest). Tans up to 28 hides per cast.'
        ),
        magicSub === 'tanning' && h(MoneyMakerTable, {rows:tanningRows, onSelect:onSelectItem}),
        magicSub === 'bolts' && h(PhoneFold, {style:{fontSize:11, color:T.textDim, marginBottom:10, lineHeight:1.5}},
          'Enchant Crossbow Bolt — only Onyx and Ascendri are worth casting, every other tier runs at a loss. 1 Cosmic + 1 Death rune per cast (elemental staff covers the rest). Enchants 10 bolts per cast.'
        ),
        magicSub === 'bolts' && h(MoneyMakerTable, {rows:boltRows, onSelect:onSelectItem}),
        magicSub === 'bolts' && boltAlchRows.length > 0 && h('div', {style:{marginTop:14, padding:'10px 12px', background:T.panel, border:`1px solid ${T.border}`, borderRadius:4}},
          h('div', {style:{fontSize:11, color:T.gold, fontWeight:'bold', marginBottom:8}}, 'If alching instead of selling (Alchemiser)'),
          boltAlchRows.map(r => h('div', {key:r.name, style:{display:'flex', justifyContent:'space-between', fontSize:12, padding:'3px 0', borderBottom:`1px solid ${T.borderDim}`}},
            h('span', {style:{color:T.textDim}}, `${r.name} — cost ${fmt.gp(r.costPerBolt)}gp, alch ${fmt.gp(r.alch)}gp`),
            h('span', {style:{color: r.alchemiserProfit>=0 ? T.gold : T.red, fontWeight:'bold'}}, (r.alchemiserProfit>=0?'+':'')+fmt.gp(r.alchemiserProfit)+'gp/bolt'),
          ))
        ),
        magicSub === 'humidify' && h(PhoneFold, {style:{fontSize:11, color:T.textDim, marginBottom:10, lineHeight:1.5}},
          'Humidify — only worth casting on Porcelain clay → Soft porcelain clay. 1 Astral rune per cast (elemental staff covers the rest).'
        ),
        magicSub === 'humidify' && h(MoneyMakerTable, {rows:humidifyRows, onSelect:onSelectItem}),
      ),

      skill === 'fletching' && h('div', null,
        h(FletchingBuffCheckboxes, {buffs:fletchingBuffs, setBuffs:setFletchingBuffs}),
        h(MoneyMakerTable, {rows:fletchingRows, onSelect:onSelectItem}),
      ),

      skill === 'crafting' && h('div', null,
        h('div', {style:{display:'flex', gap:4, marginBottom:12}},
          [{key:'cloth',label:'Cloth'},{key:'urns',label:'Urns'},{key:'dragonhide',label:'Dragonhide'}].map(sub => h('button', {
            key:sub.key, onClick:()=>setCraftingSub(sub.key),
            style:{
              padding:'3px 10px', fontSize:10, cursor:'pointer', borderRadius:3,
              background: craftingSub===sub.key ? 'rgba(201,168,76,0.2)' : 'transparent',
              border: `1px solid ${craftingSub===sub.key ? T.gold : T.border}`,
              color: craftingSub===sub.key ? T.goldBright : T.textDim,
            }
          }, sub.label))
        ),
        craftingSub === 'cloth' && h(MoneyMakerTable, {rows:craftingRows, onSelect:onSelectItem}),
        (craftingSub === 'urns' || craftingSub === 'dragonhide') && h(CraftingBuffCheckboxes, {buffs:craftingBuffs, setBuffs:setCraftingBuffs}),
        craftingSub === 'urns' && h(MoneyMakerTable, {rows:urnRows, onSelect:onSelectItem}),
        craftingSub === 'dragonhide' && h(MoneyMakerTable, {rows:dragonhideRows, onSelect:onSelectItem}),
        craftingSub === 'dragonhide' && dragonhideRows.length > 0 && h('div', {style:{marginTop:14, padding:'10px 12px', background:T.panel, border:`1px solid ${T.border}`, borderRadius:4}},
          h('div', {style:{fontSize:11, color:T.gold, fontWeight:'bold', marginBottom:8}}, 'High alch value (these usually sell below what alching is worth)'),
          dragonhideRows.map(r => h('div', {key:r.itemName, style:{display:'flex', justifyContent:'space-between', fontSize:12, padding:'3px 0', borderBottom:`1px solid ${T.borderDim}`}},
            h('span', {style:{color:T.textDim}}, `${r.itemName} — sell ${fmt.gp(r.stats.outPrice)}gp`),
            h('span', {style:{color: r.stats.alch > (r.stats.outPrice||0) ? T.gold : T.textDim, fontWeight:'bold'}}, `alch ${fmt.gp(r.stats.alch)}gp`),
          ))
        ),
      ),

      skill === 'archaeology' && h(ArchaeologyCalc, {items}),

      skill === 'smithing' && h('div', null,
        h('div', {style:{display:'flex', gap:4, marginBottom:12}},
          [{key:'scratch',label:'Smithing from scratch'},{key:'smelting',label:'Smelting'}].map(sub => h('button', {
            key:sub.key, onClick:()=>setSmithSub(sub.key),
            style:{
              padding:'3px 10px', fontSize:10, cursor:'pointer', borderRadius:3,
              background: smithSub===sub.key ? 'rgba(201,168,76,0.2)' : 'transparent',
              border: `1px solid ${smithSub===sub.key ? T.gold : T.border}`,
              color: smithSub===sub.key ? T.goldBright : T.textDim,
            }
          }, sub.label))
        ),
        smithSub === 'scratch' && h(SmithingFromScratch, {items, onSelect:onSelectItem}),
      ),
      skill === 'smithing' && smithSub === 'smelting' && h('div', null,
        h('label', {style:{display:'flex', alignItems:'center', gap:5, cursor:'pointer', fontSize:11, marginBottom:12}},
          h('input', {type:'checkbox', checked:varrockArmour, onChange:()=>setVarrockArmour(v=>!v)}),
          h('span', {style:{color:T.textDim}}, 'Varrock armour', h('span',{style:{color:T.gold}},' (4%/3%/2%/1% chance of an extra bar, tier-scoped to bronze-steel/mithril-adamant/rune-necronium/bane-elder rune respectively)')),
        ),
        h(MoneyMakerTable, {rows:smithingRows, onSelect:onSelectItem}),
      ),

      skill === 'summoning' && h('div', null,
        h('div', {style:{display:'flex', gap:4, marginBottom:12}},
          [{key:'pouches',label:'Pouches'},{key:'ancient',label:'Ancient Summoning'}].map(sub => h('button', {
            key:sub.key, onClick:()=>setSummoningSub(sub.key),
            style:{
              padding:'3px 10px', fontSize:10, cursor:'pointer', borderRadius:3,
              background: summoningSub===sub.key ? 'rgba(201,168,76,0.2)' : 'transparent',
              border: `1px solid ${summoningSub===sub.key ? T.gold : T.border}`,
              color: summoningSub===sub.key ? T.goldBright : T.textDim,
            }
          }, sub.label))
        ),
        summoningSub === 'pouches' && h(MoneyMakerTable, {rows:summoningRows, onSelect:onSelectItem}),
        summoningSub === 'ancient' && h(MoneyMakerTable, {rows:ancientSummoningRows, onSelect:onSelectItem}),
      ),

      h('div', {style:{fontSize:10, color:T.goldBright, border:`1px solid ${T.borderDim}`, borderRadius:4, padding:'6px 8px', marginTop:14}},
        '⚠ Margins assume you already have the processing method available (portables, other buffs, elemental battlestaff, etc.) — no time/click cost factored in beyond GE tax. Buy limits reset per 4 hours.'
      ),
    )
  );
}

/* ─── Tab descriptions ───────────────────────────────────────── */
// ─── Buy Planner ─────────────────────────────────────────────────────────────
// Goals for slowly accumulating an item under its 4-hour GE buy limit (Ben,
// 2026-10-06 — born from the dragon hatchet grind, 630 bought and counting).
// The user only ever enters running totals (total bought + total gp spent,
// both visible on the GE offer); everything else is derived. Three finish
// estimates, because "full limit every 4h" is rarely what actually happens:
//   best case   — a full limit every 4h, around the clock (offers keep
//                 filling while you're offline, so 6 limits/day)
//   market      — capped by how much of the item actually trades per day
//   your pace   — from the user's own timestamped total updates
const LIMITS_PER_DAY = 6;
const DAY_MS = 86400000;

function plannerPace(history) {
  // Needs at least two updates spanning 12h+, or the rate is just noise.
  if (!history || history.length < 2) return null;
  const first = history[0], last = history[history.length - 1];
  const days = (last.t - first.t) / DAY_MS;
  if (days < 0.5) return null;
  const perDay = (last.bought - first.bought) / days;
  return perDay > 0 ? { perDay, updates: history.length } : null;
}

function plannerFinish(left, perDay) {
  if (!(perDay > 0)) return null;
  const days = Math.ceil(left / perDay);
  return { days, date: new Date(Date.now() + days * DAY_MS) };
}

// A goal's offers: one row per account buying it (buy limits are per
// account, so two accounts fill twice as fast). Goals saved before this
// (Ben, 2026-10-20) have no offers list: their totals are the one offer.
function goalOffers(goal) {
  if (goal.offers?.length) return goal.offers;
  return [{id: 'main', label: '', bought: goal.bought || 0, spent: goal.spent || 0}];
}
const offerInputs = offers => offers.map(o => ({...o, bought: o.bought || '', spent: o.spent || ''}));

function BuyGoalCard({goal, item, onUpdate, onEdit, onDelete, onToggle, editor}) {
  // Editable copy of the offers; numbers stay as typed text until saved.
  const [rows, setRows] = useState(() => offerInputs(goalOffers(goal)));
  const [avgVolume, setAvgVolume] = useState(null);
  useEffect(() => { setRows(offerInputs(goalOffers(goal))); }, [goal.bought, goal.spent, goal.offers]);
  const accounts = rows.length;

  // Average daily volume over the last 30 days of local history, when it
  // exists — one day's volume alone swings too much to plan around.
  useEffect(() => {
    if (!item?.id) return;
    let stale = false;
    window.genius?.getItemHistoryLocal(item.id).then(hist => {
      if (stale) return;
      const vols = (hist || []).slice(-30).map(p => p.volume).filter(v => v > 0);
      setAvgVolume(vols.length >= 5 ? vols.reduce((a, b) => a + b, 0) / vols.length : null);
    }).catch(() => {});
    return () => { stale = true; };
  }, [item?.id]);

  const target = Number(goal.target) || 0;
  const bought = goal.bought || 0;
  const spent = goal.spent || 0;
  const left = Math.max(0, target - bought);
  const avgCost = bought > 0 ? spent / bought : null;
  const pctDone = target > 0 ? Math.min(100, bought / target * 100) : 0;
  const price = item ? (item.liveBuy ?? item.high ?? item.low ?? null) : null;
  const overMax = goal.max_price && price != null && price > goal.max_price;
  // Each account has its own buy limit, so the combined limit scales.
  const limit = item?.limit ? item.limit * accounts : null;
  const dailyVolume = avgVolume ?? (item?.volume || null);
  const share = (goal.market_share || 25) / 100;
  const done = left === 0 && target > 0;

  const best = limit ? plannerFinish(left, limit * LIMITS_PER_DAY) : null;
  const marketPerDay = dailyVolume ? Math.min(dailyVolume * share, limit ? limit * LIMITS_PER_DAY : Infinity) : null;
  const market = marketPerDay ? plannerFinish(left, marketPerDay) : null;
  const pace = plannerPace(goal.history);
  const yours = pace ? plannerFinish(left, pace.perDay) : null;
  // The bottleneck is whichever estimate is slowest — that's the real
  // finish date. "Your pace" counts too: once there's enough history, it's
  // the ground truth the other two are only predicting.
  const slowest = [['best', best], ['market', market], ['pace', yours]]
    .filter(([, e]) => e).sort((a, b) => b[1].days - a[1].days)[0];
  const bottleneck = slowest && [best, market, yours].filter(Boolean).some(e => e.days < slowest[1].days) ? slowest[0] : null;

  const fmtDate = d => d.toLocaleDateString(undefined, {month:'short', day:'numeric', year:'numeric'});
  const row = (icon, label, sub, est, highlight) =>
    h('div',{style:{display:'flex', justifyContent:'space-between', alignItems:'center', gap:12, padding:'8px 10px',
      border:`1px solid ${highlight ? T.copper : T.borderDim}`, borderRadius:3, background: highlight ? 'rgba(184,115,51,0.08)' : T.inset}},
      h('div',null,
        h('div',{style:{fontSize:13, color:T.text}}, icon+' '+label,
          highlight && h('span',{style:{marginLeft:8, fontSize:10, letterSpacing:1, textTransform:'uppercase', color:T.copper, border:`1px solid ${T.copper}`, borderRadius:3, padding:'1px 6px'}},'Bottleneck')),
        h('div',{style:{fontSize:11, color:T.textDim, marginTop:2}}, sub)),
      h('div',{style:{textAlign:'right', whiteSpace:'nowrap'}},
        est ? [h('div',{key:'d',style:{fontSize:14, color:T.textBright}}, est.days+' day'+(est.days===1?'':'s')),
               h('div',{key:'t',style:{fontSize:11, color:T.textDim}}, fmtDate(est.date))]
            : h('div',{style:{fontSize:12, color:T.textDim}}, '—')));

  const nextReset = goal.last_fill_at ? goal.last_fill_at + 4*3600000 - Date.now() : null;
  const stat = (lbl, val, color) => h('div',{style:{background:T.inset, border:`1px solid ${T.borderDim}`, borderRadius:3, padding:'8px 10px'}},
    h('div',{className:'form-lbl', style:{marginBottom:2}}, lbl),
    h('div',{style:{fontSize:16, color: color || T.textBright}}, val));

  // Saves every row at once; the backend adds them up into the goal totals.
  const save = (list = rows) => onUpdate(goal, list.map(r => ({...r,
    bought: Math.round(parseGpString(r.bought) || 0), spent: parseGpString(r.spent) || 0})));
  const setRow = (i, k) => e => setRows(rs => rs.map((r, j) => j === i ? {...r, [k]: e.target.value} : r));
  const addAccount = () => setRows(rs => [...rs.map((r, i) => i === 0 && !r.label ? {...r, label: 'Account 1'} : r),
    {id: Date.now().toString(), label: 'Account ' + (rs.length + 1), bought: '', spent: ''}]);
  const removeAccount = i => {
    const r = rows[i];
    if ((parseGpString(r.bought) || 0) > 0 && !confirm(`Remove ${r.label || 'this account'}? Its ${r.bought} bought come off the goal's totals.`)) return;
    const next = rows.filter((_, j) => j !== i);
    setRows(next); save(next);
  };

  return h('div',{style:{background:T.panel, border:`1px solid ${T.border}`, borderRadius:4, padding:14, marginBottom:14}},
    h('div',{style:{display:'flex', justifyContent:'space-between', alignItems:'flex-start', gap:10, flexWrap:'wrap'}},
      h('div',{style:{display:'flex', alignItems:'center', gap:10}},
        h(ItemThumb,{name:goal.item_name, size:32}),
        h('div',null,
          h('div',{style:{fontSize:16, color:T.gold, fontFamily:"'Cinzel', serif"}}, goal.item_name,
            done && h('span',{style:{marginLeft:8, fontSize:10, color:T.green, border:`1px solid ${T.green}`, borderRadius:3, padding:'1px 6px', fontFamily:'inherit'}},'COMPLETE')),
          h('div',{style:{fontSize:11, color:T.textDim}},
            `Goal ${target.toLocaleString()}`+(goal.max_price ? ` · max ${fmt.gp(goal.max_price)}gp` : '')
              +(limit ? ` · buy limit ${limit.toLocaleString()}`+(accounts > 1 ? ` (${item.limit.toLocaleString()} × ${accounts} accounts)` : '') : ' · buy limit unknown')))),
      h('div',{style:{display:'flex', gap:6, flexWrap:'wrap'}},
        h('button',{className:'ge-btn', title: goal.linked ? "Updating totals also sets this item's Portfolio position (quantity + average cost). Click to unlink." : 'Not linked: the Portfolio is left alone. Click to link.', onClick:()=>onToggle(goal,'linked')}, goal.linked ? '🔗 Linked to portfolio' : 'Not linked'),
        h('button',{className:'ge-btn', title:'Notify when your 4-hour buy limit should be free again (estimated from your last update)', onClick:()=>onToggle(goal,'notify')}, goal.notify ? '🔔 Notify on' : '🔕 Notify off'),
        h('button',{className:'ge-btn', onClick:()=>onEdit(goal)}, 'Edit'),
        h('button',{className:'ge-btn danger', onClick:()=>onDelete(goal)}, 'Del'))),
    editor && h('div',{style:{marginTop:12, padding:10, border:`1px solid ${T.copper}`, borderRadius:3, background:T.inset}},
      h('div',{className:'form-lbl', style:{marginBottom:6}}, 'Edit goal'), editor),

    h('div',{style:{display:'flex', justifyContent:'space-between', fontSize:12, color:T.text, margin:'12px 0 4px'}},
      h('span',null, `${bought.toLocaleString()} / ${target.toLocaleString()} bought`),
      h('span',{style:{color:T.textDim}}, pctDone.toFixed(1)+'%')),
    h('div',{style:{height:8, background:T.inset, border:`1px solid ${T.borderDim}`, borderRadius:3, overflow:'hidden'}},
      h('div',{style:{width:pctDone+'%', height:'100%', background: done ? T.green : T.gold}})),

    h('div',{style:{display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(130px, 1fr))', gap:8, marginTop:12}},
      stat('Average cost', avgCost != null ? Math.round(avgCost).toLocaleString()+'gp' : '—'),
      stat('Total spent', fmt.gp(spent)+'gp'),
      stat('Left to buy', left.toLocaleString()),
      stat('Current price', price != null ? fmt.gp(price)+'gp' : '—', overMax ? T.red : (avgCost && price != null ? (price <= avgCost ? T.green : T.text) : T.text))),
    overMax && h('div',{style:{marginTop:8, fontSize:12, color:T.red}}, `⚠ Current price is above your max of ${fmt.gp(goal.max_price)}gp`),
    goal.max_price && h(PriceTargetOdds,{items: item ? [item] : [], itemName:goal.item_name, target:goal.max_price, direction:'below'}),

    !done && h('div',{style:{marginTop:14}},
      h('div',{className:'form-lbl'},'Estimated finish'),
      h('div',{style:{display:'flex', flexDirection:'column', gap:6}},
        row('⚡','Best case', limit ? `Full limit every 4 hours, around the clock · ${(limit*LIMITS_PER_DAY).toLocaleString()}/day` : 'Buy limit unknown for this item', best, bottleneck === 'best'),
        row('📊','Market-limited', dailyVolume
          ? `~${Math.round(dailyVolume).toLocaleString()} trade per day on the whole GE${avgVolume ? ' (30-day avg)' : ''} · assumes you get ${goal.market_share || 25}% · ${Math.round(marketPerDay).toLocaleString()}/day`
          : 'No volume data for this item', market, bottleneck === 'market'),
        row('👤','Your pace', pace ? `${pace.perDay.toFixed(1)}/day over your last ${pace.updates} updates` : 'Needs two updates at least 12 hours apart', yours, bottleneck === 'pace'))),

    h('div',{style:{marginTop:14, paddingTop:12, borderTop:`1px solid ${T.borderDim}`}},
      rows.map((r, i) => h('div',{key:r.id, style:{display:'flex', gap:8, alignItems:'flex-end', flexWrap:'wrap', marginBottom:8}},
        accounts > 1 && h('div',{style:{flex:'1 1 110px'}},
          h('label',{className:'form-lbl'},'Account'),
          h('input',{className:'ge-input', value:r.label, onChange:setRow(i,'label'), placeholder:'Main'})),
        h('div',{style:{flex:'1 1 120px'}},
          h('label',{className:'form-lbl'}, accounts > 1 ? 'Bought' : 'Total bought'),
          h('input',{className:'ge-input', value:r.bought, onChange:setRow(i,'bought'), placeholder:'500'})),
        h('div',{style:{flex:'1 1 150px'}},
          h('label',{className:'form-lbl'}, accounts > 1 ? 'Gp spent' : 'Total gp spent'),
          h('input',{className:'ge-input', value:r.spent, onChange:setRow(i,'spent'), placeholder:'15,000,000 or 15m'})),
        accounts > 1 && h('button',{className:'ge-btn danger', title:'Remove this account', onClick:()=>removeAccount(i)}, '✕'))),
      h('div',{style:{display:'flex', gap:8, flexWrap:'wrap'}},
        h('button',{className:'ge-btn gold', onClick:()=>save()}, 'Update totals'),
        h('button',{className:'ge-btn', title:'Buying this on another account too? Each account has its own buy limit, so give it its own row.', onClick:addAccount}, '+ Add account'))),
    h('div',{style:{display:'flex', justifyContent:'space-between', flexWrap:'wrap', gap:6, fontSize:11, color:T.textDim, marginTop:8}},
      h('span',null, (accounts > 1 ? "Enter each account's numbers from its own GE offer; the goal adds them up." : 'Both numbers are on your GE offer.')+(goal.linked ? ' Saving also updates your Portfolio position.' : '')),
      h('span',null,
        goal.notify && nextReset != null && nextReset > 0 ? `Limit free in ~${Math.floor(nextReset/3600000)}h ${Math.floor(nextReset%3600000/60000)}m · ` : '',
        goal.history?.length ? 'Last updated '+new Date(goal.history[goal.history.length-1].t).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) : 'No updates yet')));
}

function BuyPlannerTab({items, toast, description, userShorthands, onPortfolioChanged}) {
  const BLANK = {item_name:'', target:'', max_price:'', market_share:'25'};
  const [goals, setGoals] = useState([]);
  const [newForm, setForm] = useState(BLANK);
  const [editId, setEditId] = useState(null);
  // Edits happen inside the goal's own card (Ben, 2026-10-20: the shared
  // form at the top was easy to miss), so the edit draft is kept apart from
  // the New goal form.
  const [editForm, setEditForm] = useState(BLANK);
  const goalFields = (f, setF, onSave, saveLabel, onCancel) => {
    const set = k => e => setF(x=>({...x,[k]:e.target.value}));
    return h('div',{style:{display:'flex', gap:10, flexWrap:'wrap', alignItems:'flex-end'}},
      h('div',{style:{flex:'2 1 200px'}}, h('label',{className:'form-lbl'},'Item'),
        h(ItemAutocomplete,{items, value:f.item_name, onChange:name=>setF(x=>({...x,item_name:name})), placeholder:'Search item...', userShorthands})),
      h('div',{style:{flex:'1 1 100px'}}, h('label',{className:'form-lbl'},'How many'),
        h('input',{className:'ge-input', value:f.target, onChange:set('target'), placeholder:'2,000'})),
      h('div',{style:{flex:'1 1 110px'}}, h('label',{className:'form-lbl', title:'Optional: warns you when the current price is above this'},'Max price (opt.)'),
        h('input',{className:'ge-input', value:f.max_price, onChange:set('max_price'), placeholder:'33k'})),
      h('div',{style:{flex:'1 1 90px'}}, h('label',{className:'form-lbl', title:"What share of the item's daily GE volume you expect to win. Lower it for items with lots of competing buyers."},'Market share %'),
        h('input',{className:'ge-input', type:'number', min:1, max:100, value:f.market_share, onChange:set('market_share')})),
      h('button',{className:'ge-btn gold', onClick:onSave}, saveLabel),
      onCancel && h('button',{className:'ge-btn', onClick:onCancel}, 'Cancel'));
  };
  const byName = useMemo(() => Object.fromEntries(items.map(it => [it.name.toLowerCase(), it])), [items]);

  const reload = async () => { const g = await window.genius?.getBuyGoals(); if (g) setGoals(g); };
  useEffect(() => { reload(); }, []);

  const submit = async (editing) => {
    const form = editing ? editForm : newForm;
    const item = byName[(form.item_name||'').toLowerCase()];
    if (!item) { toast('Pick an item from the list','error'); return; }
    const target = Math.round(parseGpString(form.target));
    if (!(target > 0)) { toast('Enter how many you want to buy','error'); return; }
    const share = Math.min(100, Math.max(1, Number(form.market_share) || 25));
    const goal = { id: editing ? editId : Date.now().toString(), item_name: item.name, item_id: item.id, target,
      max_price: form.max_price ? parseGpString(form.max_price) : null, market_share: share };
    await window.genius?.saveBuyGoal(goal);
    if (editing) { setEditId(null); setEditForm(BLANK); } else setForm(BLANK);
    await reload();
    toast(editing ? 'Goal updated' : 'Goal added','success');
  };

  const onUpdate = async (goal, offers) => {
    if (offers.some(o => !Number.isInteger(o.bought) || o.bought < 0)) { toast('Enter bought as a whole number','error'); return; }
    if (offers.some(o => !(o.spent >= 0))) { toast('Enter gp spent','error'); return; }
    // A single unnamed offer saves as plain totals, exactly as before.
    const r = offers.length === 1 && !offers[0].label
      ? await window.genius?.updateBuyGoalTotals({id: goal.id, bought: offers[0].bought, spent: offers[0].spent})
      : await window.genius?.updateBuyGoalTotals({id: goal.id, offers});
    if (!r?.success) { toast(r?.error || 'Could not save','error'); return; }
    await reload();
    if (goal.linked) onPortfolioChanged?.();
    toast('Totals updated','success');
  };
  const onToggle = async (goal, key) => { await window.genius?.saveBuyGoal({id: goal.id, [key]: !goal[key]}); await reload(); };
  const onEdit = goal => { setEditId(goal.id); setEditForm({item_name:goal.item_name, target:String(goal.target), max_price:goal.max_price?String(goal.max_price):'', market_share:String(goal.market_share||25)}); };
  const onDelete = async goal => {
    if (!confirm(`Delete the ${goal.item_name} goal? Its Portfolio position stays, it just goes back to normal editing.`)) return;
    await window.genius?.deleteBuyGoal(goal.id);
    await reload(); onPortfolioChanged?.();
  };

  return h('div',null,
    description && h('div',{style:{padding:'8px 14px', borderBottom:`1px solid ${T.border}`, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, description),
    h('div',{style:{padding:14}},
      h('div',{className:'ge-section-head'}, 'New goal'),
      h('div',{style:{marginBottom:18}}, goalFields(newForm, setForm, ()=>submit(false), 'Add goal')),
      h('div',{className:'ge-section-head'}, `Goals (${goals.length})`),
      goals.length === 0
        ? h('div',{className:'empty'}, h('div',{className:'icon'},'🛒'),
            h('p',null,"Add an item you're stocking up on over time, since the GE only lets you buy so many every 4 hours. Then enter your running totals from the GE whenever you check it."))
        : goals.map(g => h(BuyGoalCard,{key:g.id, goal:g, item:byName[(g.item_name||'').toLowerCase()], onUpdate, onEdit, onDelete, onToggle,
            editor: g.id === editId ? goalFields(editForm, setEditForm, ()=>submit(true), 'Save goal', ()=>{setEditId(null); setEditForm(BLANK);}) : null}))));
}

// ─── Opportunity History (Track record) ──────────────────────────────────────
// (Ben, 2026-10-06) Grades the Opportunity Score: every item that scored
// 40+ gets recorded (backend recordOpportunities, once per item per day),
// and this shows what its price actually did 1/7/30 days later. Split by
// direction, because the score is direction-blind — a crash scores like a
// spike — so "was it a good opportunity?" really means "did the move keep
// going, or snap back?".
const OPP_BUCKETS = [[70, Infinity, '70+'], [60, 70, '60–69'], [50, 60, '50–59'], [40, 50, '40–49']];

function oppChange(r, later) { return later != null && r.p ? (later - r.p) / r.p * 100 : null; }
function oppDirection(r) {
  if ((r.g || []).includes('SURGE') || (r.c != null && r.c > 0)) return 'up';
  if ((r.g || []).includes('DUMP')  || (r.c != null && r.c < 0)) return 'down';
  // Flat price on heavy volume (ACCUMULATION/DISTRIBUTION): no direction
  // to judge, so these are graded on whether a real move followed at all.
  return 'flat';
}
const OPP_FLAT_MOVE_PCT = 5;

function OpportunityTrackRecord({onSelect, items}) {
  const [data, setData] = useState(null);
  useEffect(() => { window.genius?.getOpportunityHistory().then(setData).catch(() => setData({records: []})); }, []);
  const byId = useMemo(() => Object.fromEntries((items || []).map(it => [it.id, it])), [items]);

  const summary = useMemo(() => {
    if (!data) return [];
    const rows = [];
    for (const dir of ['up', 'down', 'flat']) {
      for (const [lo, hi, label] of OPP_BUCKETS) {
        const recs = data.records.filter(r => r.s >= lo && r.s < hi && oppDirection(r) === dir);
        const avg = key => {
          const vals = recs.map(r => oppChange(r, r[key])).filter(v => v != null);
          return vals.length ? { avg: vals.reduce((a, b) => a + b, 0) / vals.length, n: vals.length } : null;
        };
        // "Kept going" = moved further the same way it was moving when flagged.
        const resolved7 = recs.map(r => oppChange(r, r.d7)).filter(v => v != null);
        const kept = resolved7.length ? resolved7.filter(v => dir === 'up' ? v > 0 : dir === 'down' ? v < 0 : Math.abs(v) >= OPP_FLAT_MOVE_PCT).length / resolved7.length * 100 : null;
        rows.push({ dir, label, count: recs.length, d1: avg('d1'), d7: avg('d7'), d30: avg('d30'), kept, keptN: resolved7.length });
      }
    }
    return rows;
  }, [data]);

  if (!data) return h('div', {className:'empty'}, h('p', null, 'Loading…'));

  const pctCell = v => v == null
    ? h('td', {style:{color:T.textDim}}, '—')
    : h('td', {className: v >= 0 ? 'pct-up' : 'pct-down', title: `Average of ${v.n} flag${v.n===1?'':'s'} with a price that many days later`}, fmt.pct(v.avg));
  const rawPct = v => v == null ? h('td', {style:{color:T.textDim}}, '—') : h('td', {className: v >= 0 ? 'pct-up' : 'pct-down'}, fmt.pct(v));
  const since = data.since ? new Date(data.since).toLocaleDateString(undefined, {month:'short', day:'numeric', year:'numeric'}) : null;
  const recent = [...data.records].sort((a, b) => b.t - a.t).slice(0, 50);

  return h('div', {style:{padding:14}},
    h('div', {style:{fontSize:12, color:T.textDim, lineHeight:1.6, marginBottom:14}},
      since ? `Recording since ${since} · ${data.records.length.toLocaleString()} flags so far. ` : 'Nothing recorded yet: the first flags are saved after the next price update. ',
      `Every item scoring ${data.recordMin}+ is saved once a day with its price, then graded on what the price did 1, 7 and 30 days later. Results fill in as those days pass.`),

    h('div', {className:'ge-section-head'}, 'Score vs. what happened next'),
    h('table', {className:'ge-table', style:{marginBottom:20}},
      h('thead', null, h('tr', null,
        h('th', null, 'Flagged while'), h('th', null, 'Score'), h('th', null, 'Flags'),
        h('th', null, 'After 1 day'), h('th', null, 'After 7 days'), h('th', null, 'After 30 days'),
        h('th', {title:`Rising/falling: share whose price kept moving the same way within 7 days. Flat: share that then moved ${OPP_FLAT_MOVE_PCT}%+ either way.`}, 'Kept going (7d)'))),
      h('tbody', null, summary.filter(row => row.count > 0).map(row => h('tr', {key: row.dir + row.label},
        h('td', {style:{color: row.dir === 'up' ? T.green : row.dir === 'down' ? T.red : T.textDim},
          title: row.dir === 'flat' ? `Price flat but volume heavy. "Kept going" here means it then moved ${OPP_FLAT_MOVE_PCT}%+ either way.` : null},
          row.dir === 'up' ? '▲ Rising' : row.dir === 'down' ? '▼ Falling' : '◆ Flat, heavy volume'),
        h('td', null, row.label),
        h('td', null, row.count.toLocaleString()),
        pctCell(row.d1), pctCell(row.d7), pctCell(row.d30),
        h('td', {style:{color: row.kept == null ? T.textDim : T.text}}, row.kept == null ? '—' : `${Math.round(row.kept)}% of ${row.keptN}`))))),

    h('div', {className:'ge-section-head'}, 'Recent flags'),
    recent.length === 0
      ? h('div', {className:'empty', style:{padding:'20px 0'}}, h('p', null, 'No flags yet.'))
      : h('table', {className:'ge-table'},
          h('thead', null, h('tr', null,
            h('th', null, 'Flagged'), h('th', null, 'Item'), h('th', null, 'Score'), h('th', null, 'Moving'),
            h('th', null, 'Price then'), h('th', null, '1d'), h('th', null, '7d'), h('th', null, '30d'))),
          h('tbody', null, recent.map(r => {
            const dir = oppDirection(r);
            return h('tr', {key: r.id + '_' + r.t},
              h('td', {style:{color:T.textDim}}, new Date(r.t).toLocaleDateString(undefined, {month:'short', day:'numeric'})),
              h('td', {style:{cursor: byId[r.id] ? 'pointer' : 'default', color:T.gold}, onClick: () => byId[r.id] && onSelect(byId[r.id])}, r.n),
              h('td', null, Math.round(r.s)),
              h('td', {style:{color: dir === 'up' ? T.green : dir === 'down' ? T.red : T.textDim}},
                dir === 'up' ? '▲ ' : dir === 'down' ? '▼ ' : '◆ ', r.c != null ? fmt.pct(r.c) : 'flat'),
              h('td', null, fmt.gp(r.p) + 'gp'),
              rawPct(oppChange(r, r.d1)), rawPct(oppChange(r, r.d7)), rawPct(oppChange(r, r.d30)));
          }))));
}

function OpportunitiesArea(props) {
  const [view, setView] = useState('today');
  return h('div', null,
    h('div', {style:{display:'flex', gap:6, padding:'8px 12px', borderBottom:`1px solid ${T.border}`}},
      h('button', {className: view==='today' ? 'ge-btn gold' : 'ge-btn', onClick:()=>setView('today')}, 'Today'),
      h('button', {className: view==='record' ? 'ge-btn gold' : 'ge-btn', onClick:()=>setView('record'), title:'How past high-scoring items actually performed afterwards'}, '📈 Track record')),
    view === 'today'
      ? h(OpportunitiesTab, props)
      : h(OpportunityTrackRecord, {onSelect: props.onSelect, items: props.items}));
}

// Portfolio tab = Positions + Buy Planner pills (Ben, 2026-10-06). The
// planner manages Portfolio positions, so it lives beside them rather than
// as another sidebar entry.
// Upcoming updates that could affect what you hold or watch (Ben, 2026-11-02).
// Says what's changing and how much is exposed, never what to do about it.
// Shared by the panel and the per-item warnings; one short-lived copy so opening
// items doesn't re-read the news files each time.
let updateRisksCache = null;
function loadUpdateRisks(fresh) {
  if (fresh || !updateRisksCache || Date.now() - updateRisksCache.at > 300000) {
    updateRisksCache = { at: Date.now(), list: Promise.resolve(window.genius?.getUpdateRisks?.()).then(r => r || []).catch(() => []) };
  }
  return updateRisksCache.list;
}
function useUpdateRisks() {
  const [risks, setRisks] = useState([]);
  useEffect(() => { let live = true; loadUpdateRisks().then(r => { if (live) setRisks(r); }); return () => { live = false; }; }, []);
  return risks;
}
// The bar on Dashboard, Portfolio and Watchlist. Clicking opens the full page.
// scope: 'yours' (held + watched), 'watched' (Watchlist).
function UpdateRisksBar({scope = 'yours'}) {
  const allRisks = useUpdateRisks();
  const risks = allRisks.filter(r => scope === 'yours' ? r.group !== 'other' : r.watched);
  if (!risks.length) return null;
  const exposed = risks.reduce((sum, r) => sum + (r.value || 0), 0);
  const updates = new Set(risks.map(r => r.updateId)).size;
  return h('div', {
    style:{margin:'8px 12px 12px', padding:'8px 10px', border:'1px solid '+T.borderDim, borderLeft:'3px solid '+T.gold, borderRadius:4, fontSize:12, cursor:'pointer', display:'flex', gap:8, alignItems:'center'},
    title:'See everything that may be affected',
    onClick:()=>{ _alertsInitialPill = 'upcoming'; window.dispatchEvent(new CustomEvent('genius-goto', {detail:'alerts'})); },
  },
    h('span', {style:{flex:1}}, '⚠️ ', h('b', {style:{color:T.gold}}, 'Upcoming updates'), ' may affect '+risks.length+' of your item'+(risks.length===1?'':'s'),
      exposed > 0 ? ' · '+fmt.gp(exposed)+'gp held' : '', updates > 1 ? ' · '+updates+' updates' : ''),
    h('span', {style:{color:T.gold}}, 'View all →'));
}

// Everything upcoming updates may affect (Ben, 2026-11-03): your holdings, then
// your watchlists, then every other item the posts name.
function UpdateRisksTab({items, onSelect, description}) {
  const [risks, setRisks] = useState(null);
  const [update, setUpdate] = useState('all');
  const load = fresh => loadUpdateRisks(fresh).then(setRisks);
  useEffect(() => { load(); }, []);
  if (!risks) return h('div', {className:'empty'}, h('p', null, 'Loading…'));
  const updateList = [...new Map(risks.map(r => [r.updateId, r.updateTitle])).entries()];
  const shown = risks.filter(r => update === 'all' || r.updateId === update);
  const byName = name => (items || []).find(it => it.name.toLowerCase() === name.toLowerCase());
  const row = r => {
    const item = byName(r.itemName);
    return h('div', {key:r.key, style:{padding:'10px 0', borderTop:'1px solid '+T.borderDim, lineHeight:1.5, fontSize:13}},
      h('div', {style:{display:'flex', gap:10, alignItems:'center', flexWrap:'wrap'}},
        h('b', {style:{color:T.gold, cursor:item?'pointer':'default'}, onClick:()=>item&&onSelect(item)}, r.itemName),
        r.kind === 'known' && h('span', {className:'cat-tag'}, 'Confirmed in preview'),
        r.kind === 'mention' && h('span', {className:'cat-tag'}, 'Named'),
        r.kind === 'related' && h('span', {className:'cat-tag', style:{opacity:0.7}}, 'Related'),
        h('span', {style:{color:T.textDim, flex:1, fontSize:12}}, r.quantity ? r.quantity.toLocaleString()+' held · '+fmt.gp(r.value)+'gp' : ''),
        h('button', {className:'ge-btn', style:{padding:'2px 8px', fontSize:11}, onClick:async()=>{ await window.genius.dismissUpdateRisk(r.key); load(true); }}, 'Dismiss')),
      h('div', {style:{color:T.text, marginTop:2}}, r.effect),
      h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, r.updateTitle, r.when ? ' · '+r.when : '',
        r.url && h('span', {style:{color:T.gold, cursor:'pointer', marginLeft:8}, onClick:()=>window.genius?.openExternal(r.url)}, 'Read post →')));
  };
  const section = (title, list) => list.length > 0 && h('div', {style:{marginBottom:22}},
    h('div', {className:'ge-section-head'}, title+' ('+list.length+')'), list.map(row));
  const held = shown.filter(r => r.group === 'held');
  const exposed = held.reduce((sum, r) => sum + (r.value || 0), 0);
  return h('div', null,
    description && h('div', {style:{padding:'8px 14px', borderBottom:'1px solid '+T.border, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}}, description, ' ', h('sup', {style:{fontSize:'0.8em'}}, 'Ayo...')),
    h('div', {style:{padding:14}},
      h('div', {style:{fontSize:12, color:T.textDim, marginBottom:12, lineHeight:1.6}},
        'What may change, not advice. Confirmed means the preview states the effect. Named means a post about future plans names the item, which could mean a lot or nothing. Related means the post discusses a skill the item is tied to, so it\'s the weakest signal.',
        exposed > 0 ? ' You hold '+fmt.gp(exposed)+'gp in these items.' : ''),
      updateList.length > 1 && h('select', {className:'ge-input', style:{marginBottom:16, maxWidth:420}, value:update, onChange:ev=>setUpdate(ev.target.value)},
        h('option', {value:'all'}, 'All updates ('+updateList.length+')'),
        updateList.map(([id, title]) => h('option', {key:id, value:id}, title))),
      shown.length === 0 && h('div', {className:'empty'}, h('p', null, 'Nothing flagged right now.')),
      section('Your portfolio', held),
      section('Your watchlists', shown.filter(r => r.group === 'watched')),
      section('Named in update posts', shown.filter(r => r.group === 'other'))));
}

// The Alerts tab's pills (Ben, 2026-11-04). Set _alertsInitialPill before
// navigating to open a specific one. Notifications and Almanac are built next.
let _alertsInitialPill = null;

// Each pill has a color, or an emoji for people who can't tell the colors apart
// (Settings > Notifications). Pills map to the Inbox entry kinds they cover.
const NOTIF_MARKS = {
  notifications: {color:'#4a9eff', emoji:'📥', label:'Inbox'},
  upcoming:      {color:'#f0a030', emoji:'⚠️', label:'Upcoming Changes'},
  almanac:       {color:'#4caf50', emoji:'🌱', label:'Almanac'},
  mine:          {color:'#e05050', emoji:'🔔', label:'My Alerts'},
};
const notifEmojiOn = () => { try { return localStorage.getItem('genius_notif_emoji') === '1'; } catch { return false; } };
// Which marks the unread entries light up. Every unread entry lights the Inbox.
const unreadMarks = inbox => {
  const unread = inbox.filter(e => !e.read);
  if (!unread.length) return [];
  return ['notifications', ...['upcoming','almanac','mine'].filter(k => unread.some(e => e.kind === k))];
};
const refreshInbox = () => window.dispatchEvent(new CustomEvent('genius-inbox-changed'));
function useInbox() {
  const [inbox, setInbox] = useState([]);
  useEffect(() => {
    let live = true;
    // Same list keeps the same state, or the whole app redraws on every poll.
    let shown = '';
    const load = () => window.genius?.getInbox?.().then(l => {
      if (!live || !l) return;
      const next = JSON.stringify(l);
      if (next !== shown) { shown = next; setInbox(l); }
    }).catch(() => {});
    load();
    const timer = setInterval(load, 30000);
    window.addEventListener('genius-inbox-changed', load);
    return () => { live = false; clearInterval(timer); window.removeEventListener('genius-inbox-changed', load); };
  }, []);
  return inbox;
}
// One dot or emoji. With several marks it steps through them.
function NotifMark({marks, style}) {
  const [step, setStep] = useState(0);
  useEffect(() => {
    if (marks.length < 2) return;
    const timer = setInterval(() => setStep(s => s + 1), 1500);
    return () => clearInterval(timer);
  }, [marks.length]);
  if (!marks.length) return null;
  const mark = NOTIF_MARKS[marks[step % marks.length]];
  const title = 'New: ' + marks.map(m => NOTIF_MARKS[m].label).join(', ');
  return notifEmojiOn()
    ? h('span', {title, style:{fontSize:12, lineHeight:1, transition:'opacity .3s', ...style}}, mark.emoji)
    : h('span', {title, style:{width:8, height:8, borderRadius:'50%', background:mark.color, display:'inline-block', flexShrink:0, transition:'background .5s', ...style}});
}

function InboxView({onOpenPill}) {
  const [list, setList] = useState(null);
  // What was unread when it appeared, so it stays highlighted while you're here.
  const fresh = useRef(new Set());
  const load = async () => {
    const l = await window.genius.getInbox();
    setList(l);
    const unread = l.filter(e => !e.read);
    if (!unread.length) return;
    unread.forEach(e => fresh.current.add(e.id));
    // Only what's on screen counts as seen; anything newer stays unread.
    await window.genius.markInboxRead(null, Math.max(...unread.map(e => e.at)));
    refreshInbox();
  };
  useEffect(() => {
    load();
    window.addEventListener('genius-inbox-changed', load);
    const timer = setInterval(load, 30000);
    return () => { window.removeEventListener('genius-inbox-changed', load); clearInterval(timer); };
  }, []);
  const clear = async id => { await window.genius.clearInbox(id); await load(); refreshInbox(); };
  return h('div', null,
    h('div', {style:{padding:'8px 14px', borderBottom:'1px solid '+T.border, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}},
      'Here lies all of the unread ', h('s', null, 'emails'), ' alerts we flood you with.'),
    h('div', {style:{padding:14}},
      list && list.length > 0 && h('div', {style:{display:'flex', justifyContent:'flex-end', marginBottom:8}},
        h('button', {className:'ge-btn', style:{fontSize:11}, onClick:()=>clear()}, 'Clear all')),
      list && list.length === 0 && h('div', {className:'empty'}, h('p', null, 'Nothing here. New notifications will land here until you clear them.')),
      (list || []).map(e => {
        const pill = NOTIF_MARKS[e.kind] ? e.kind : null;
        return h('div', {key:e.id, style:{padding:'10px 0', borderTop:'1px solid '+T.borderDim, fontSize:13, lineHeight:1.5, display:'flex', gap:10, alignItems:'flex-start'}},
          h('span', {style:{width:14, paddingTop:5, flexShrink:0}}, fresh.current.has(e.id) && h(NotifMark, {marks:[pill || 'notifications']})),
          h('div', {style:{flex:1, minWidth:0}},
            h('div', {style:{color:fresh.current.has(e.id) ? T.textBright : T.text, fontWeight:fresh.current.has(e.id) ? 'bold' : 'normal', cursor:pill ? 'pointer' : 'default'}, onClick:()=>pill && onOpenPill(pill)}, e.title),
            h('div', {style:{color:T.textDim, whiteSpace:'pre-line'}}, e.body),
            h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, new Date(e.at).toLocaleString())),
          h('button', {className:'ge-btn', style:{padding:'2px 8px', fontSize:11}, onClick:()=>clear(e.id)}, 'Clear'));
      })));
}

// Almanac flags, shared by the pill and the bars (Ben, 2026-11-04).
let _almanacSignals = null, _almanacSignalsAt = 0;
function loadAlmanacSignals(fresh) {
  if (!window.genius?.getAlmanacSignals) return Promise.resolve({now:[], soon:[]});
  if (!fresh && _almanacSignals && Date.now() - _almanacSignalsAt < 300000) return _almanacSignals;
  _almanacSignalsAt = Date.now();
  _almanacSignals = window.genius.getAlmanacSignals().catch(() => ({now:[], soon:[]}));
  return _almanacSignals;
}
// The bar on Dashboard, Portfolio, Watchlist and the Almanac tab.
function AlmanacFlagsBar({scope = 'yours'}) {
  const [data, setData] = useState(null);
  useEffect(() => { let live = true; loadAlmanacSignals().then(d => { if (live) setData(d); }); return () => { live = false; }; }, []);
  const rows = (data?.now || []).filter(r => scope === 'watched' ? r.star : r.group !== 'other');
  if (!rows.length) return null;
  const sells = rows.filter(r => r.action === 'sell').length, buys = rows.length - sells;
  return h('div', {
    style:{margin:'8px 12px 12px', padding:'8px 10px', border:'1px solid '+T.borderDim, borderLeft:'3px solid '+NOTIF_MARKS.almanac.color, borderRadius:4, fontSize:12, cursor:'pointer', display:'flex', gap:8, alignItems:'center'},
    title:'See what the Almanac is flagging',
    onClick:()=>{ _alertsInitialPill = 'almanac'; window.dispatchEvent(new CustomEvent('genius-goto', {detail:'alerts'})); },
  },
    h('span', {style:{flex:1}}, '🌱 ', h('b', {style:{color:NOTIF_MARKS.almanac.color}}, 'Almanac'), ' says of your items: ',
      [sells && sells+' to sell now', buys && buys+' to buy now'].filter(Boolean).join(', ')),
    h('span', {style:{color:NOTIF_MARKS.almanac.color}}, 'View all →'));
}

const fmtDayShort = s => new Date(s + 'T12:00:00Z').toLocaleDateString(undefined, {month:'short', day:'numeric'});
function AlmanacFlagsView({items, onSelect}) {
  const [data, setData] = useState(null);
  useEffect(() => { let live = true; loadAlmanacSignals(true).then(d => { if (live) setData(d); }); return () => { live = false; }; }, []);
  const quip = h('div', {style:{padding:'8px 14px', borderBottom:'1px solid '+T.border, fontSize:12, color:T.textDim, fontStyle:'italic', lineHeight:1.5}},
    'Planting a seed of potential. (waitaminute)');
  if (!data) return h('div', null, quip, h('div', {className:'empty'}, h('p', null, 'Loading…')));
  const byId = id => (items || []).find(it => String(it.id) === String(id));
  const star = r => h('span', {style:{width:16, flexShrink:0, color:T.gold}, title:r.star ? 'On your watchlist' : undefined}, r.star ? '★' : '');
  const nameEl = r => { const it = byId(r.id); return h('b', {style:{color:T.gold, cursor:it?'pointer':'default'}, onClick:()=>it&&onSelect(it)}, r.name); };
  const details = r => {
    const bits = [];
    if (r.quantity) bits.push(r.quantity.toLocaleString()+' held');
    if (r.action === 'sell' && r.liveSell) bits.push('live sell '+fmt.gp(r.liveSell));
    if (r.action === 'buy' && r.liveBuy) bits.push('live buy '+fmt.gp(r.liveBuy));
    if (r.breakEven) bits.push('your break-even '+fmt.gp(r.breakEven));
    if (r.estimated) bits.push('DXP date is an estimate, not announced');
    return bits.join(' · ');
  };
  const label = r => {
    if (r.action === 'buy' && r.priceHigh) return ['Buy now, price high', '#f0a030', 'Already '+r.runUpPct+'% above its usual price this month, so much of the rise may be gone.'];
    if (r.belowBreakEven) return ['Sell now, below break-even', '#f0a030', 'The usual exit time is here, but live sell is below your break-even.'];
    return r.action === 'sell' ? ['Sell now', '#e05050'] : ['Buy now', '#4caf50'];
  };
  const nowRow = r => {
    const [text, color, warn] = label(r);
    return h('div', {key:r.key, style:{padding:'10px 0', borderTop:'1px solid '+T.borderDim, fontSize:13, lineHeight:1.5, display:'flex', gap:8, alignItems:'flex-start'}},
      star(r),
      h('div', {style:{flex:1, minWidth:0}},
        nameEl(r),
        h('div', {style:{color:T.text}}, r.evidence),
        warn && h('div', {style:{color, fontSize:12}}, warn),
        h('div', {style:{fontSize:11, color:T.textDim, marginTop:2}}, details(r))),
      h('span', {className:'cat-tag', style:{color, borderColor:color, whiteSpace:'nowrap'}}, text));
  };
  const soonRow = r => h('div', {key:r.key, style:{padding:'8px 0', borderTop:'1px solid '+T.borderDim, fontSize:13, lineHeight:1.5, display:'flex', gap:8, alignItems:'flex-start'}},
    star(r),
    h('div', {style:{flex:1, minWidth:0}}, nameEl(r), h('div', {style:{color:T.textDim, fontSize:12}},
      (r.action === 'sell' ? 'Start selling' : 'Start buying')+' in about '+r.inDays+' day'+(r.inDays===1?'':'s')+(r.estimated?' (estimated)':''))),
    h('span', {style:{color:T.textDim, fontSize:12, whiteSpace:'nowrap'}}, fmtDayShort(r.day)));
  const section = (title, list, row, color) => list.length > 0 && h('div', {style:{marginBottom:18}},
    h('div', {className:'ge-section-head', style:color ? {color} : undefined}, title+' ('+list.length+')'), list.map(row));
  const sells = data.now.filter(r => r.action === 'sell'), buys = data.now.filter(r => r.action === 'buy');
  const inGroup = g => data.soon.filter(r => r.group === g);
  const next = data.nextDxp;
  return h('div', null, quip,
    h('div', {style:{padding:14}},
      h('div', {style:{fontSize:12, color:T.textDim, marginBottom:12, lineHeight:1.6}},
        next ? 'Next Double XP: '+fmtDayShort(next.start)+(next.end ? ' to '+fmtDayShort(next.end) : '')+(next.estimated ? ' (estimated from past gaps, not announced).' : '.') : '',
        ' Timing comes from how each item moved around past DXPs, on guide prices. Past patterns can break, so check the live price first.'),
      !data.now.length && !data.soon.length && h('div', {className:'empty'}, h('p', null, 'Nothing flagged right now.')),
      section('Start selling now', sells, nowRow, '#e05050'),
      section('Start buying now', buys, nowRow, '#4caf50'),
      section('Coming up: your portfolio', inGroup('held'), soonRow),
      section('Coming up: your watchlists', inGroup('watched'), soonRow),
      section('Coming up: everything else', inGroup('other'), soonRow)));
}

function AlertsArea(props) {
  const [pill, setPill] = useState(() => { const p = _alertsInitialPill || 'notifications'; _alertsInitialPill = null; return p; });
  const inbox = useInbox();
  const marks = unreadMarks(inbox);
  // Opening a pill counts its entries as seen, in the Inbox too.
  useEffect(() => {
    if (pill === 'notifications') return; // InboxView does this after it loads
    window.genius?.markInboxRead?.(pill)?.then(refreshInbox);
  }, [pill]);
  return h('div', null,
    h('div', {style:{display:'flex', gap:6, padding:'8px 12px', borderBottom:`1px solid ${T.border}`, flexWrap:'wrap'}},
      [['notifications','Inbox'],['upcoming','Upcoming Changes'],['almanac','Almanac'],['mine','My Alerts']].map(([id, label]) =>
        h('button', {key:id, className: pill===id ? 'ge-btn gold' : 'ge-btn', onClick:()=>setPill(id), style:{display:'inline-flex', alignItems:'center', gap:6}},
          label, pill !== id && marks.includes(id) && h(NotifMark, {marks:[id]})))),
    pill === 'notifications' && h(InboxView, {onOpenPill:setPill}),
    pill === 'upcoming' && h(UpdateRisksTab, {items:props.items, onSelect:props.onSelect, description:TAB_DESCRIPTIONS.update_risks}),
    pill === 'almanac' && h(AlmanacFlagsView, {items:props.items, onSelect:props.onSelect}),
    pill === 'mine' && h(AlertsTab, props));
}

// GE offer reader (dev mode, desktop): check what was read from the screen, then
// save it. Totals on the offer are running totals, so buys replace the offer's
// numbers and sells only log what's new since the last read of that offer.
const geSoldLog = () => { try { return JSON.parse(localStorage.getItem('genius_ge_sold_log') || '{}'); } catch { return {}; } };
function GeReaderModal({offer, items, toast, onClose, onSaved}) {
  const commas = v => v == null || v === '' ? '' : Number(v).toLocaleString();
  const [f, setF] = useState(() => ({side:offer.side || 'buy', name:offer.name || '', quantity:commas(offer.quantity), price:commas(offer.price), filled:commas(offer.filled ?? 0), coins:commas(offer.coins ?? 0)}));
  // Number boxes take commas and K/M/B ("60k", "1.5m"), and tidy up when you leave them.
  const num = k => Math.round(parseGpString(f[k])) || 0;
  const [goals, setGoals] = useState([]);
  const [portfolio, setPortfolio] = useState({positions:[]});
  const [offerId, setOfferId] = useState(null);
  const [posId, setPosId] = useState(null);
  useEffect(() => {
    window.genius.getBuyGoals().then(setGoals);
    window.genius.getPortfolio().then(p => p && setPortfolio(p));
  }, []);
  const set = k => e => setF(x => ({...x, [k]:e.target.value}));
  const nameLow = String(f.name).trim().toLowerCase();
  const filled = num('filled'), coins = num('coins');
  const goal = goals.find(g => g.item_name.toLowerCase() === nameLow);
  const known = (items || []).find(i => i.name.toLowerCase() === nameLow);
  // The offer these totals most likely belong to: the fullest that isn't past them.
  const offers = goal?.offers || [];
  const guessOffer = offers.filter(o => o.bought <= filled).sort((a, b) => b.bought - a.bought)[0] || offers[0];
  const chosenOffer = offers.find(o => o.id === offerId) || guessOffer;
  const open = (portfolio.positions || []).filter(p => p.status === 'open' && (p.item_name || '').toLowerCase() === nameLow);
  const chosenPos = open.find(p => p.id === posId) || [...open].sort((a, b) => b.quantity - a.quantity)[0];
  // Identifies the offer, so re-reading it only logs what's new. Price stays out of
  // it since an offer's price can be edited in-game.
  const logKey = [nameLow, num('quantity')].join('|');
  const alreadySold = geSoldLog()[logKey] || 0;
  const newSold = Math.max(0, filled - alreadySold);
  const finish = async msg => { toast(msg, 'success'); await onSaved(); onClose(); };
  const requireItem = () => { if (!known) { toast('Pick an item name GEnius knows', 'error'); return false; } if (!(filled > 0)) { toast('Nothing filled yet', 'error'); return false; } return true; };

  const saveToGoal = async () => {
    if (!requireItem()) return;
    const body = offers.length
      ? {id:goal.id, offers:offers.map(o => o.id === chosenOffer.id ? {...o, bought:filled, spent:coins} : o)}
      : {id:goal.id, bought:filled, spent:coins};
    const r = await window.genius.updateBuyGoalTotals(body);
    if (!r?.success) { toast(r?.error || 'Could not save', 'error'); return; }
    finish(known.name + ' planner updated');
  };
  const newGoal = async () => {
    if (!requireItem()) return;
    const id = Date.now().toString();
    await window.genius.saveBuyGoal({id, item_name:known.name, item_id:known.id, target:num('quantity') || filled, max_price:num('price')});
    await window.genius.updateBuyGoalTotals({id, bought:filled, spent:coins});
    finish(known.name + ' added to the Buy Planner');
  };
  const newPosition = async () => {
    if (!requireItem()) return;
    await window.genius.savePosition({id:Date.now().toString(), item_name:known.name, quantity:filled, cost_basis:coins / filled, status:'open',
      created_at:new Date().toISOString(), date_opened:localDayStr(), target_price:'', target_profit_pct:'', stop_loss:''});
    finish(known.name + ' added to your Portfolio');
  };
  const saveSale = async () => {
    if (!requireItem() || !chosenPos) return;
    if (!(num('quantity') > 0)) { toast('Enter the offer quantity first', 'error'); return; }
    if (!(newSold > 0)) { toast('Those sales are already logged', 'error'); return; }
    const qty = Math.min(newSold, chosenPos.quantity);
    // The GE shows coins after its 2% tax, and sellPosition takes the tax off itself,
    // so it gets the price before tax. Items under 50gp aren't taxed.
    const received = coins / filled;
    const sellPrice = received / 0.98 >= 50 ? received / 0.98 : received;
    const r = await window.genius.sellPosition({id:chosenPos.id, sell_price:sellPrice, quantity:qty});
    if (!r?.success) { toast('Could not save', 'error'); return; }
    try { localStorage.setItem('genius_ge_sold_log', JSON.stringify({...geSoldLog(), [logKey]:alreadySold + qty})); } catch {}
    finish('Logged '+qty.toLocaleString()+' '+known.name+' sold');
  };

  const field = (label, key, isNumber) => h('label', {style:{display:'block', fontSize:11, color:T.textDim}}, label,
    h('input', {className:'ge-input', type:'text', value:f[key], onChange:set(key),
      onBlur: isNumber ? () => setF(x => ({...x, [key]:commas(Math.round(parseGpString(x[key])) || 0)})) : undefined,
      style:{display:'block', width:'100%', marginTop:2}}));
  const avg = filled > 0 ? coins / filled : 0;
  return h('div', {style:{position:'fixed', inset:0, background:'rgba(0,0,0,0.6)', zIndex:9999, display:'flex', alignItems:'center', justifyContent:'center', padding:16}, onClick:e=>{ if (e.target === e.currentTarget) onClose(); }},
    h('div', {style:{background:T.bg || '#14100a', border:'1px solid '+T.gold, borderRadius:6, padding:18, width:460, maxWidth:'100%', maxHeight:'90vh', overflow:'auto'}},
      h('div', {className:'ge-section-head'}, 'Read from the GE'),
      offer.error ? h('p', {style:{color:'#e05050', fontSize:13}}, 'Could not read the screen: '+offer.error) :
      h('div', {style:{fontSize:12, color:offer.confirmed ? '#4caf50' : '#f0a030', marginBottom:10}},
        offer.confirmed ? 'Read twice, and the numbers add up. Still worth a glance.' : 'Couldn\'t confirm these. Compare every number with the GE before saving.'),
      h('div', {style:{display:'flex', gap:6, marginBottom:10}},
        ['buy','sell'].map(s => h('button', {key:s, className:f.side===s ? 'ge-btn gold' : 'ge-btn', onClick:()=>setF(x=>({...x, side:s}))}, s === 'buy' ? 'Buy offer' : 'Sell offer'))),
      h('div', {style:{display:'grid', gridTemplateColumns:'1fr 1fr', gap:10, marginBottom:10}},
        h('div', {style:{gridColumn:'1 / -1'}}, field('Item', 'name')),
        field('Offer quantity', 'quantity', true), field('Offer price', 'price', true),
        field(f.side === 'buy' ? 'Bought so far' : 'Sold so far', 'filled', true), field(f.side === 'buy' ? 'Coins spent so far' : 'Coins received so far', 'coins', true)),
      !known && f.name && h('div', {style:{color:'#f0a030', fontSize:12, marginBottom:8}}, 'GEnius doesn\'t know that item name.'),
      filled > 0 && h('div', {style:{fontSize:12, color:T.text, marginBottom:12}}, 'Average '+fmt.gp(Math.round(avg))+' each'+(f.side === 'sell' ? ' after GE tax.' : '.')),

      f.side === 'buy' && (goal
        ? h('div', null,
            offers.length > 1 && h('label', {style:{display:'block', fontSize:11, color:T.textDim, marginBottom:8}}, 'Which offer in the planner',
              h('select', {className:'ge-input', value:chosenOffer?.id, onChange:e=>setOfferId(e.target.value), style:{display:'block', width:'100%', marginTop:2}},
                offers.map(o => h('option', {key:o.id, value:o.id}, (o.label || 'Offer')+' ('+o.bought.toLocaleString()+' bought)')))),
            h('div', {style:{fontSize:12, color:T.text, marginBottom:10}}, 'Updates '+goal.item_name+' from '+(offers.length ? (chosenOffer?.bought || 0) : goal.bought).toLocaleString()+' to '+filled.toLocaleString()+' bought.'),
            h('button', {className:'ge-btn gold', onClick:saveToGoal}, 'Update planner'))
        : h('div', {style:{display:'flex', gap:6}},
            h('button', {className:'ge-btn gold', onClick:newGoal}, 'New planner goal'),
            h('button', {className:'ge-btn', onClick:newPosition}, 'Add to Portfolio'))),

      f.side === 'sell' && (chosenPos
        ? h('div', null,
            open.length > 1 && h('label', {style:{display:'block', fontSize:11, color:T.textDim, marginBottom:8}}, 'Which position',
              h('select', {className:'ge-input', value:chosenPos.id, onChange:e=>setPosId(e.target.value), style:{display:'block', width:'100%', marginTop:2}},
                open.map(p => h('option', {key:p.id, value:p.id}, p.quantity.toLocaleString()+' at '+fmt.gp(Math.round(p.cost_basis)))))),
            h('div', {style:{fontSize:12, color:T.text, marginBottom:10}},
              alreadySold ? alreadySold.toLocaleString()+' already logged from this offer. ' : '', 'Logs '+Math.min(newSold, chosenPos.quantity).toLocaleString()+' sold.'),
            h('button', {className:'ge-btn gold', onClick:saveSale}, 'Log sale'))
        : h('div', {style:{fontSize:12, color:'#f0a030'}}, 'No open position for this item to sell from.')),

      h('div', {style:{marginTop:10}}, h('button', {className:'ge-btn', onClick:onClose}, 'Cancel'))));
}

function PortfolioArea(props) {
  const [view, setView] = useState('positions');
  return h('div', null,
    h('div', {style:{display:'flex', gap:6, padding:'8px 12px', borderBottom:`1px solid ${T.border}`}},
      h('button', {className: view==='positions' ? 'ge-btn gold' : 'ge-btn', onClick:()=>setView('positions')}, 'Positions'),
      h('button', {className: view==='planner' ? 'ge-btn gold' : 'ge-btn', onClick:()=>setView('planner')}, '🛒 Buy Planner')),
    h(UpdateRisksBar),
    h(AlmanacFlagsBar),
    view === 'positions'
      ? h(PortfolioTab, props)
      : h(BuyPlannerTab, {items: props.items, toast: props.toast, userShorthands: props.userShorthands,
          description: TAB_DESCRIPTIONS.buy_planner, onPortfolioChanged: props.onPortfolioChanged}));
}

