/* ─── App ─────────────────────────────────────────────────────── */
function App() {
  const [tab, setTab] = useState('dashboard');
  useEffect(() => {
    const go = e => { setTab(e.detail); setSelected(null); };
    window.addEventListener('genius-goto', go);
    return () => window.removeEventListener('genius-goto', go);
  }, []);
  const navMarks = unreadMarks(useInbox());
  const [geOffer, setGeOffer] = useState(null);
  useEffect(() => { window.genius?.onGeReader?.(o => setGeOffer({...o, readAt:Date.now()})); }, []);
  const contentRef = useRef(null);
  const scrollContentTo = pos => contentRef.current?.scrollTo({top: pos, behavior:'smooth'});
  // Sidebar starts closed — only actually matters on a narrow/mobile
  // screen (the CSS media query that turns .sidebar into an overlay drawer
  // only applies under ~700px; on desktop .sidebar ignores this entirely
  // and stays permanently visible regardless of this state).
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [items, setItems] = useState([]);
  // Items Jagex removed from the GE (run.js removedItems): kept out of
  // `items` so market scans skip them; Watchlist/Portfolio show them labelled.
  const [removedItems, setRemovedItems] = useState([]);
  const [news, setNews] = useState([]);
  const [indexes, setIndexes] = useState([]);
  const [officialTop100, setOfficialTop100] = useState({byWindow:{}});
  const [compareList, setCompareList] = useState([]);
  const [watchlist, setWatchlist] = useState([]);
  const [hiddenItems, setHiddenItems] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [reminders, setReminders] = useState([]);
  // Shared by AlertsTab's own form and the item panel's quick-add popup —
  // both just need "here's a saved alert/reminder object, merge it in."
  const upsertAlert = a => setAlerts(al => { const i = al.findIndex(x=>x.id===a.id); return i>=0 ? al.map((x,j)=>j===i?a:x) : [...al,a]; });
  const upsertReminder = r => setReminders(rl => { const i = rl.findIndex(x=>x.id===r.id); return i>=0 ? rl.map((x,j)=>j===i?r:x) : [...rl,r]; });
  const [settings, setSettings] = useState({});
  applyAccentColor(settings.accentColor);
  const [portfolio, setPortfolio] = useState({positions:[], tax_stats:{}});
  const [notes, setNotes] = useState({});
  const [userShorthands, setUserShorthands] = useState({});
  const [monsterShorthands, setMonsterShorthands] = useState({});
  const [updateInfo, setUpdateInfo]         = useState(null);
  const [historyPopup, setHistoryPopup] = useState(null); // null | {done, total, complete}
  // First-run welcome tour — shown once automatically (localStorage flag,
  // this is purely a "have they seen it" UI toggle, no reason to involve
  // the backend store), and replayable anytime from Settings regardless
  // of whether the flag is set.
  const [showTour, setShowTour] = useState(() => {
    try { return localStorage.getItem('genius_seen_welcome_tour') !== '1'; } catch { return false; }
  });
  const dismissTour = useCallback(() => {
    try { localStorage.setItem('genius_seen_welcome_tour', '1'); } catch {}
    setShowTour(false);
  }, []);
  const [populatedHistoryIds, setPopulatedHistoryIds] = useState(null); // null = not loaded yet | Set<number>
  const refreshPopulatedHistoryIds = useCallback(() => {
    window.genius?.getHistoryPopulatedIds?.().then(ids => setPopulatedHistoryIds(new Set(ids)));
  }, []);
  // Trigger history population if needed. Previously this only ever ran
  // once, inside the initial-mount getData() effect, gated on that FIRST
  // call already having items — which is empty on a genuine first launch
  // (no latest.json exists yet; the initial price fetch fires 3s later
  // and takes real time to complete), so the whole check got skipped
  // permanently rather than just delayed. Confirmed for real (Ben,
  // 2026-08-02, across several fresh mobile installs tonight): the
  // "Building history" popup never showed up on a true first launch, only
  // on the SECOND one, once latest.json already had real data from the
  // completed first-launch fetch. Extracted so onFetchComplete can also
  // call this with its own freshly-fetched items — covers the true-
  // first-launch case the moment real data first exists, not just on the
  // next restart. Safe to call repeatedly (e.g. every periodic refresh):
  // startHistoryPopulation/runHistoryQueue already no-op if a population
  // run is already active or genuinely complete.
  //
  // Previously this only ever fired on a true first run or while under 50
  // items were stored — meaning if the app got closed before the (~45+
  // minute) full catalogue backfill finished, it never resumed on later
  // launches. Confirmed for real: after a long time using the app, only
  // ~20% of the catalogue (1415/7182 items) had ever been populated.
  // Comparing against the actual remaining gap instead means it keeps
  // making progress across restarts until genuinely done.
  // startHistoryPopulation already filters to just the unfetched ids
  // internally, so calling it with the full list here is safe.
  const triggerHistoryPopulationIfNeeded = useCallback((items) => {
    if (!items || !items.length) return;
    window.genius?.getHistoryStatus().then(status => {
      // Untradeable items (Invention components, combo potions — ~106 of
      // them, added by untradeable.js) have an id but no real GE exchange
      // history to ever fetch. Without excluding them, the queue can
      // never reach 100% — it perpetually re-queues and re-fails the same
      // ~100 ids on every single launch, which is exactly why the
      // "Building history" popup kept reappearing stuck at the same
      // not-quite-complete count.
      const sorted = [...items]
        .filter(it => it.id && !it.untradeable)
        .sort((a,b) => (b.volume||0) - (a.volume||0));
      const allIds = sorted.map(it => it.id);
      // Always ask the backend to queue whichever of THESE items lack
      // history (it skips ones already on disk) instead of comparing raw
      // counts — the file count includes delisted items, which hid 33 new
      // Havenhythe II items with no history at all (FIX 2026-10-11, Ben:
      // "new items don't download automatically"). The popup only shows
      // when something was actually queued, seeded from the backend's real
      // stored-of-these count (never a per-session counter from 0 — see
      // SESSION_LOG.md, 2026-06-26).
      window.genius?.startHistoryPopulation(allIds).then(res => {
        if (!res || !res.queued) return;
        setHistoryPopup({stored: res.stored ?? status.stored, total: allIds.length, unavailable: res.unavailable || 0,
          initial300Done: status.initial300Done, fullyComplete: false});
      }).catch(() => {});
    });
  }, []);
  const [selected, setSelected] = useState(null);
  const [quickAddPos, setQuickAddPos] = useState(null); // pre-filled position from margin calc
  const [fetching, setFetching] = useState(false);
  const [lastUpdate, setLastUpdate] = useState(null);
  // Re-render every 30s so the header's "Nm ago" status keeps counting
  // even when nothing else changes on screen.
  const [, setStatusTick] = useState(0);
  useEffect(() => { const t = setInterval(() => setStatusTick(n => n + 1), 30000); return () => clearInterval(t); }, []);
  const {toasts, add:toast} = useToast();
  const theme = settings.theme || 'dark';
  SHOW_THUMBNAILS = settings.showThumbnails !== false;
  FULL_NUMBERS = settings.fullNumbers === true;
  const [detailPanelWidth, setDetailPanelWidth] = useState(settings.detailPanelWidth || 296);
  useEffect(() => { if (settings.detailPanelWidth) setDetailPanelWidth(settings.detailPanelWidth); }, [settings.detailPanelWidth]);
  const panelWidthRef = useRef(detailPanelWidth);
  const startPanelResize = e => {
    e.preventDefault();
    const startX = e.clientX, startW = detailPanelWidth;
    const onMove = me => {
      const w = Math.min(600, Math.max(260, startW - (me.clientX - startX)));
      panelWidthRef.current = w;
      setDetailPanelWidth(w);
    };
    const onUp = () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
      window.genius?.saveSettings({...settings, detailPanelWidth: panelWidthRef.current});
    };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };

  const uiScale = (settings.uiScale || 100) / 100;
  const [scaleDims, setScaleDims] = useState({w: window.innerWidth, h: window.innerHeight});
  useEffect(() => {
    const onResize = () => setScaleDims({w: window.innerWidth, h: window.innerHeight});
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  // Custom nav order — flatten NAV when user has custom order (no group separators)
  const navBase = NAV;
  const navItems = useMemo(() => {
    const order = settings.navOrder;
    if (!order || !order.length) return navBase;
    const byId = Object.fromEntries(navBase.filter(n=>n.id).map(n=>[n.id,n]));
    const known = order.map(id=>byId[id]).filter(Boolean);
    const newOnes = navBase.filter(n=>n.id && !order.includes(n.id));
    return [...known, ...newOnes]; // flat list, no groups
  }, [settings.navOrder, navBase]);

  useEffect(() => {
    if (!window.genius) { console.error('[GEnius] window.genius is not defined!'); return; }
    console.log('[GEnius] Loading initial data...');
    // Each piece loads independently, retrying up to 3 times. This used to be
    // one Promise.all, so a single failed call (portfolio.json rename
    // EPERM, Ben 2026-10-08) dropped EVERYTHING and the UI showed blank
    // defaults — settings, watchlist, portfolio all looked wiped, and any
    // save from that state could have overwritten the real files.
    const retry = (fn, tries = 3) => fn().catch(e => {
      if (tries <= 1) throw e;
      return new Promise(r => setTimeout(r, 500)).then(() => retry(fn, tries - 1));
    });
    Promise.all([
      () => window.genius.getData(),
      () => window.genius.getWatchlist(),
      () => window.genius.getAlerts(),
      () => window.genius.getSettings(),
      () => window.genius.getPortfolio(),
      () => window.genius.getHidden(),
      () => window.genius.getNotes(),
      () => window.genius.getShorthands(),
      () => window.genius.getReminders(),
      () => window.genius.getMonsterShorthands(),
    ].map(fn => retry(fn))).then(([data,wl,al,s,pf,hidden,nt,sh,rm,msh]) => {
      console.log('[GEnius] getData returned:', data?.items?.length ?? 0, 'items, timestamp:', data?.timestamp);
      if (data.items)     setItems(data.items);
      setRemovedItems(data.removedItems || []);
      if (data.news)      setNews(data.news);
      if (data.indexes)   setIndexes(data.indexes);
      if (data.officialTop100) setOfficialTop100(data.officialTop100);
      if (data.timestamp) setLastUpdate(data.timestamp);
      setWatchlist(wl||[]);
      setAlerts(al||[]);
      setSettings(s||{});
      if (pf) setPortfolio(pf);
      setHiddenItems(hidden||[]);
      setNotes(nt||{});
      setUserShorthands(sh||{});
      setReminders(rm||[]);
      setMonsterShorthands(msh||{});

      const splash = document.getElementById('splash');
      if (splash) {
        splash.style.opacity = '0';
        setTimeout(() => splash.remove(), 400);
      }

      triggerHistoryPopulationIfNeeded(data.items);
      refreshPopulatedHistoryIds();
    }).catch(e => {
      console.error('[GEnius] Initial load error:', e);
      // Don't drop into the app with blank defaults — a save from that
      // state could overwrite the user's real settings/portfolio on disk.
      const splash = document.getElementById('splash');
      if (splash) splash.innerHTML = '<div style="color:#e8d5a3;font-family:sans-serif;text-align:center;padding:40px;max-width:420px;margin:auto">'
        + '<div style="font-size:18px;margin-bottom:12px">GEnius couldn’t load your data</div>'
        + '<div style="font-size:13px;opacity:.8;line-height:1.5">Your settings and portfolio are safe on disk. Please close GEnius completely (including the tray icon) and open it again.</div></div>';
    });

    window.genius.onHistoryProgress(d => {
      refreshPopulatedHistoryIds();
      setHistoryPopup(prev => {
        if (!prev) return prev;
        // d.total here is just "items left in this run's queue," not
        // the overall catalogue size — keep using prev.total (set once,
        // from the real full item count) for that. Only stored count
        // and the persisted initial300Done flag come from the live tick.
        // Finished = every item has history OR the queue ran out and the
        // rest are items with no history available (counted, not stuck).
        const fullyComplete = d.stored >= prev.total || (d.finished && d.stored + (d.unavailable || 0) >= prev.total);
        return {...prev, stored: d.stored, unavailable: d.unavailable || 0, initial300Done: d.initial300Done, fullyComplete};
      });
    });
    // Covers fetches the renderer didn't itself initiate (the scheduler's
    // own interval tick, and the post-launch auto-fetch) — those never
    // touched setFetching(true) before, so the header button sat on
    // "Fetch Now" the whole time even while a real fetch (possibly a
    // slow one, see main.js's runFetch comment) was genuinely running.
    window.genius.onFetchStart(() => setFetching(true));
    window.genius.onFetchComplete(d => {
      // A sync changed user data, not prices: re-read what it writes, which
      // otherwise only loads at startup (Ben had to restart the app to see it).
      if (d.mode === 'sync') {
        Promise.all([window.genius.getWatchlist(), window.genius.getAlerts(), window.genius.getPortfolio(), window.genius.getHidden(), window.genius.getNotes(), window.genius.getShorthands(), window.genius.getReminders()])
          .then(([wl, al, pf, hidden, nt, sh, rm]) => {
            setWatchlist(wl || []); setAlerts(al || []); if (pf) setPortfolio(pf);
            setHiddenItems(hidden || []); setNotes(nt || {}); setUserShorthands(sh || {}); setReminders(rm || []);
          }).catch(e => console.error('[GEnius] Reload after sync error:', e));
        return;
      }
      window.dispatchEvent(new Event('genius-news-read')); // refresh the News badge
      console.log('[GEnius] fetch-complete received:', d);
      setFetching(false); setLastUpdate(d.timestamp);
      window.genius.getData().then(data => {
        console.log('[GEnius] getData after fetch returned:', data?.items?.length ?? 0, 'items');
        if (data.items)   setItems(data.items);
        setRemovedItems(data.removedItems || []);
        if (data.news)    setNews(data.news);
        if (data.indexes) setIndexes(data.indexes);
        if (data.officialTop100) setOfficialTop100(data.officialTop100);
        triggerHistoryPopulationIfNeeded(data.items);
      }).catch(e => console.error('[GEnius] getData after fetch error:', e));
      // Ben, 2026-08-09: checkPriceAlerts()/checkReminders() run server-side
      // right after every fetch (scheduler tick or a manual Fetch Now) and
      // can flip an alert's active/firedAt state on disk — but the Alerts
      // tab's in-memory list was only ever loaded once at startup, so a
      // fired-in-the-background alert wouldn't show as Active until the
      // next full app restart. Re-pulling both here keeps the UI in sync
      // with whatever the backend just did.
      window.genius.getAlerts().then(a => a && setAlerts(a)).catch(()=>{});
      window.genius.getReminders().then(r => r && setReminders(r)).catch(()=>{});
      toast('Prices updated','success');
    });
    window.genius.onFetchError(d => { setFetching(false); toast('Fetch error: '+(d.error||'unknown'),'error'); console.error('[GEnius] fetch-error:', d); });
    window.genius.onUpdateAvailable(d => setUpdateInfo(d));
    return () => { window.genius.removeAllListeners('fetch-start'); window.genius.removeAllListeners('fetch-complete'); window.genius.removeAllListeners('fetch-error'); window.genius.removeAllListeners('update-available'); };
  }, []);

  // Global shortcut: S or / focuses the search bar unless a text field is active
  useEffect(() => {
    const onKey = e => {
      const tag = document.activeElement?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
      if (document.activeElement?.isContentEditable) return;
      if (e.key === 's' || e.key === 'S' || e.key === '/') {
        e.preventDefault();
        document.querySelector('.ge-search-input')?.focus();
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  // F5 (Ben, 2026-08-13: "F5 would be natural since that's the refresh on
  // the browser") triggers the same Fetch Now the header button does —
  // Electron doesn't intercept F5 for its own page-reload the way a real
  // browser would (that's disabled app-wide, see main.js), so it was just
  // sitting unbound. No text-field guard needed like the S//-shortcut
  // above — F5 isn't a character you'd ever be typing into a field.
  useEffect(() => {
    const onKey = e => {
      if (e.key === 'F5') { e.preventDefault(); if (!fetching) handleFetch(); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [fetching]);

  // Backspace closes the item detail panel (when no text field is focused),
  // or the sidebar drawer if that's open instead. This is also what the
  // Android hardware/gesture back button drives on mobile (see
  // mobile/bridge-src/bridge.js) — it dispatches this exact same
  // synthetic keydown rather than having its own separate back-stack
  // logic, so anything that responds to desktop's Backspace key
  // automatically gets real Android back-button support for free, with
  // no risk of the two ever drifting out of sync.
  //
  // Escape does the same thing — added separately (2026-07-16) after
  // feedback that the panel had no Escape support at all, unlike every
  // modal in the app (ChartModal, ImageModal, etc. all close on Escape).
  // Kept as its own condition rather than folded into the Backspace
  // check above: Escape shouldn't be guarded behind "no text field
  // focused" the way Backspace has to be (Backspace is a real character
  // that would otherwise delete text; Escape never types anything, so
  // blurring/closing on it even while a field is focused is the
  // conventional, expected behavior — same as every modal already does).
  useEffect(() => {
    const onKey = e => {
      if (e.key === 'Backspace') {
        const tag = document.activeElement?.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;
        if (document.activeElement?.isContentEditable) return;
      } else if (e.key !== 'Escape') {
        return;
      }
      if (sidebarOpen) { e.preventDefault(); setSidebarOpen(false); }
      else if (selected) { e.preventDefault(); setSelected(null); }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [selected, sidebarOpen]);

  // Swipe in from the left edge to open the sidebar drawer — standard
  // mobile nav-drawer convention, alongside the hamburger button. Only
  // matters at the same narrow width where .sidebar actually becomes an
  // overlay drawer at all (see the @media (max-width: 700px) block in
  // buildCSS) — on desktop's much wider window this just never triggers,
  // since the start-x check below requires a touch within ~24px of the
  // left edge AND a narrow viewport.
  useEffect(() => {
    let startX = null, startY = null, tracking = false;
    const EDGE_PX = 24, OPEN_THRESHOLD_PX = 60;
    const onTouchStart = e => {
      if (sidebarOpen || window.innerWidth > 700 || e.touches.length !== 1) { tracking = false; return; }
      const t = e.touches[0];
      if (t.clientX > EDGE_PX) { tracking = false; return; }
      startX = t.clientX; startY = t.clientY; tracking = true;
    };
    const onTouchMove = e => {
      if (!tracking) return;
      const t = e.touches[0];
      const dx = t.clientX - startX, dy = t.clientY - startY;
      // Require the swipe to be clearly more horizontal than vertical —
      // without this, a normal vertical scroll starting near the left
      // edge (e.g. scrolling a sidebar-adjacent list) would also crack
      // the drawer open by accident.
      if (Math.abs(dx) > OPEN_THRESHOLD_PX && Math.abs(dx) > Math.abs(dy) * 1.5) {
        setSidebarOpen(true);
        tracking = false;
      }
    };
    const onTouchEnd = () => { tracking = false; };
    window.addEventListener('touchstart', onTouchStart, { passive: true });
    window.addEventListener('touchmove', onTouchMove, { passive: true });
    window.addEventListener('touchend', onTouchEnd, { passive: true });
    return () => {
      window.removeEventListener('touchstart', onTouchStart);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', onTouchEnd);
    };
  }, [sidebarOpen]);

  const toggleWatch = useCallback(async id => {
    const nw = watchlist.includes(id) ? watchlist.filter(x=>x!==id) : [...watchlist,id];
    setWatchlist(nw);
    await window.genius?.setWatchlist(nw);
    toast(watchlist.includes(id) ? 'Removed from watchlist' : 'Added to watchlist', 'info');
  }, [watchlist]);

  const toggleHide = useCallback(async id => {
    const ids = Array.isArray(id) ? id : [id];
    let nh = [...hiddenItems];
    ids.forEach(i => {
      if (nh.includes(i)) nh = nh.filter(x=>x!==i);
      else nh.push(i);
    });
    setHiddenItems(nh);
    await window.genius?.setHidden(nh);
    if (ids.length > 1) {
      toast(`${ids.length} items hidden — manage in Settings`, 'info');
    } else if (!hiddenItems.includes(ids[0])) {
      setSelected(null);
      toast('Item hidden — manage in Settings', 'info');
    } else {
      toast('Item unhidden', 'info');
    }
  }, [hiddenItems]);

  const addToCompare = useCallback(it => {
    if (it._add) {
      // called from CompareTab search — item already pushed to list externally; just force re-render
      setCompareList(prev => prev.find(c=>c.id===it.id) ? prev : [...prev.slice(0,3), it]);
      return;
    }
    setCompareList(prev => {
      if (prev.find(c=>c.id===it.id)) { toast('Already in compare','info'); return prev; }
      if (prev.length>=4) { toast('Max 4 items in compare','info'); return prev; }
      toast(`${it.name} added to compare`,'success');
      return [...prev, it];
    });
  }, []);

  // Filter hidden items from everything except the settings hidden manager
  const visibleItems = useMemo(() => {
    if (!hiddenItems.length) return items;
    return items.filter(it => !hiddenItems.includes(it.id));
  }, [items, hiddenItems]);

  const byCategory = useMemo(() => {
    const m={};
    visibleItems.forEach(it=>(it.categories||['materials']).forEach(c=>{if(!m[c])m[c]=[];m[c].push(it);}));
    return m;
  }, [visibleItems]);

  const catItems = useMemo(() => {
    if (['watchlist','market','opportunities','news','alerts','settings'].includes(tab)) return visibleItems;
    return byCategory[tab]||[];
  }, [tab,visibleItems,byCategory]);

  const handleFetch = async () => {
    setFetching(true);
    const res = await window.genius?.fetchNow('full');
    if (res&&!res.success) { setFetching(false); toast('Fetch failed','error'); }
  };

  // Readable ages (Ben, 2026-10-26: the phone said "8341m ago").
  const ago = mins => mins < 60 ? `${mins}m ago` : mins < 48 * 60 ? `${Math.floor(mins / 60)}h ago` : `${Math.floor(mins / 1440)}d ago`;
  // Phone: the background checker keeps notifications current while the app
  // itself is closed, so when the app's data is old, say when it last checked.
  const [bgLastRun, setBgLastRun] = useState(null);
  useEffect(() => {
    if (!window.genius?.getBackgroundLastRun) return;
    const load = () => window.genius.getBackgroundLastRun().then(setBgLastRun).catch(() => {});
    load();
    const t = setInterval(load, 5 * 60000);
    return () => clearInterval(t);
  }, []);
  const stale = lastUpdate ? Math.floor((Date.now()-lastUpdate)/60000) : null;
  const statusType = !lastUpdate ? 'none' : stale < 20 ? 'live' : 'stale';
  const bgMins = bgLastRun ? Math.floor((Date.now() - bgLastRun) / 60000) : null;
  const statusText = (!lastUpdate ? 'No data' : stale < 1 ? 'Live' : ago(stale)) +
    (bgMins != null && stale != null && stale >= 60 && bgMins < stale ? ` · alerts checked ${bgMins < 1 ? 'just now' : ago(bgMins)}` : '');
  const showDetail = selected && !['settings'].includes(tab);

  // Test-mode command surface (only exists in a --test-mode instance) — lets
  // test scripts drive the app by intent instead of guessing at buttons:
  //   __geniusTest.goto('portfolio')      switch sidebar tab (NAV id)
  //   __geniusTest.openItem('Feather')     open an item's detail panel
  //   __geniusTest.click('Buy Planner')    click the first button containing text
  //   __geniusTest.state() / .text()       current tab/item, visible text
  const [newsBadge, setNewsBadge] = useState(0);
  useEffect(() => {
    const load = () => window.genius?.getNewsBadgeCount?.().then(n => setNewsBadge(n || 0)).catch(() => {});
    load();
    window.addEventListener('genius-news-read', load);
    const t = setInterval(load, 5 * 60000);
    return () => { window.removeEventListener('genius-news-read', load); clearInterval(t); };
  }, []);
  const testStateRef = useRef({});
  testStateRef.current = { tab, selected, items };
  useEffect(() => {
    window.genius?.isTestMode?.().then(on => {
      if (!on) return;
      document.title = 'GEnius [TEST MODE]';
      try { localStorage.setItem('genius_seen_welcome_tour', '1'); } catch {}
      setShowTour(false); // the first-run tour would block every scripted test
      const wait = ms => new Promise(r => setTimeout(r, ms));
      window.__geniusTest = {
        tabs: () => NAV.filter(n => n.id).map(n => n.id),
        goto: async id => { setTab(id); await wait(500); return testStateRef.current.tab; },
        openItem: async name => {
          const it = testStateRef.current.items.find(i => i.name.toLowerCase() === String(name).toLowerCase());
          if (!it) return false;
          setSelected(it); await wait(500); return true;
        },
        click: async text => {
          const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim().includes(text));
          if (!b) return false;
          b.click(); await wait(400); return true;
        },
        state: () => ({ tab: testStateRef.current.tab, selected: testStateRef.current.selected?.name || null }),
        text: () => document.getElementById('root').innerText,
      };
    }).catch(() => {});
  }, []);

  const handleSelect = item => {
    if (selected && item && selected.id === item.id) { setSelected(null); return; }
    setSelected(item);
  };

  const handleSearchSelect = item => {
    setSelected(item);
    if (item.categories&&item.categories.length) setTab(item.categories[0]);
    // Scroll to item in the table after a short delay (tab switch needs to render first)
    setTimeout(() => {
      const row = document.querySelector(`tr[data-item-id="${item.id}"]`);
      if (row) {
        row.scrollIntoView({ behavior: 'smooth', block: 'center' });
        row.classList.add('search-highlight');
        setTimeout(() => row.classList.remove('search-highlight'), 2000);
      }
    }, 80);
  };

  const logicalW = scaleDims.w / uiScale, logicalH = scaleDims.h / uiScale;
  return h('div',{id:'scale-root', style:{
    width: logicalW, height: logicalH,
    transform: `scale(${uiScale})`,
  }},
  h('div',{className:'app', style:{width: logicalW, height: logicalH}},
    h('style',null,buildCSS()),
    theme==='black'&&h('style',null,buildBlackCss()),

    updateInfo && h('div', {style:{
      position:'fixed', bottom:16, right:16, zIndex:10000,
      background:T.panel2, border:`1px solid ${T.gold}`,
      borderRadius:6, padding:'10px 14px',
      boxShadow:'0 4px 20px rgba(0,0,0,0.6)',
      display:'flex', alignItems:'center', gap:12, maxWidth:340,
    }},
      h('div', null,
        h('div', {style:{fontSize:12, fontWeight:'bold', color:T.goldBright, marginBottom:2}},
          `GEnius v${updateInfo.latest} is available`),
        h('div', {style:{fontSize:11, color:T.textDim}},
          `You're on v${updateInfo.current}. Click to download the latest release.`),
      ),
      h('div', {style:{display:'flex', flexDirection:'column', gap:4, flexShrink:0}},
        h('button', {
          className:'ge-btn gold',
          style:{padding:'4px 10px', fontSize:11},
          onClick: () => window.genius?.openExternal(updateInfo.url),
        }, 'Download'),
        h('button', {
          className:'ge-btn',
          style:{padding:'4px 10px', fontSize:11},
          onClick: () => setUpdateInfo(null),
        }, '✕'),
      )
    ),

    // Backdrop — only rendered while the drawer is open, so it can't
    // intercept clicks (or just sit there invisibly) the rest of the time.
    // Only ever visible at all under the mobile media query (.sidebar-backdrop
    // is display:none by default, see buildCSS).
    sidebarOpen && h('div',{className:'sidebar-backdrop',onClick:()=>setSidebarOpen(false)}),

    h('nav',{className:'sidebar'+(sidebarOpen?' open':'')},
      h('div',{style:{padding:'12px 12px 8px',borderBottom:`2px solid ${T.border}`,marginBottom:4}},
        h('div',{style:{fontFamily:'Cinzel,serif',fontSize:18,fontWeight:700,color:T.goldBright,letterSpacing:3,textShadow:`0 0 10px rgba(255,215,0,0.3)`}},'GE',h('span',{style:{color:T.copper}},'nius')),
        h('div',{style:{fontSize:9,color:T.textDim,letterSpacing:2,textTransform:'uppercase',marginTop:1}},'Market Intelligence')
      ),
      navItems.map((entry,i) =>
        entry.group!==undefined
          ? h('div',{key:'g'+i,className:'nav-group-label'},entry.group)
          : h('button',{
              key:entry.id,
              className:'nav-btn'+(tab===entry.id?' active':''),
              onClick:()=>{
                if (tab===entry.id) { scrollContentTo(0); return; }
                setTab(entry.id);setSelected(null);setSidebarOpen(false);
              }
            },
            h('span',{className:'nav-icon'},entry.icon),
            entry.label,
            entry.id === 'alerts' && tab !== 'alerts' && h(NotifMark, {marks:navMarks, style:{marginLeft:'auto'}}),
            entry.id === 'dxp_intel' && navMarks.includes('almanac') && h(NotifMark, {marks:['almanac'], style:{marginLeft:'auto'}}),
            entry.id === 'news' && newsBadge > 0 && h('span', {style:{marginLeft:'auto', background:T.gold, color:'#1a1209', borderRadius:9, fontSize:10, fontWeight:'bold', padding:'0 6px', fontFamily:'Arial, sans-serif'}, title:'Unread news that matches your News ⚙ settings'}, newsBadge)
          )
      )
    ),

    geOffer && geOffer.reading && h('div', {style:{position:'fixed', inset:0, background:'rgba(0,0,0,0.6)', zIndex:9999, display:'flex', alignItems:'center', justifyContent:'center', padding:16}},
      h('div', {style:{background:T.panel, border:'1px solid '+T.gold, borderRadius:6, padding:'18px 24px', color:T.text, fontSize:14}}, '📷 Screen captured. Reading your GE offer...')),
    geOffer && !geOffer.reading && h(GeReaderModal, {key:geOffer.readAt, offer:geOffer, items, toast, onClose:()=>setGeOffer(null),
      onSaved:async()=>{ const p = await window.genius?.getPortfolio(); if (p) setPortfolio(p); }}),
    h('div',{className:'main'},
      h('div',{className:'ge-header'},
        h('button',{
          className:'sidebar-toggle', title:'Menu',
          onClick:()=>setSidebarOpen(v=>!v),
        }, '☰'),
        h('span',{className:'ge-logo'},'GE',h('span',null,'nius')),
        h('div',{className:'ge-header-divider', style:{width:2,height:20,background:T.borderDim,flexShrink:0}}),
        h(GESearchBar,{items,onSelect:handleSearchSelect,userShorthands}),
        h('div',{className:'ge-status'},h('div',{className:`status-dot ${statusType}`}),statusText),
        h('button',{
          className:'ge-btn gold ge-header-fetch',disabled:fetching,onClick:handleFetch,
          title: fetching ? 'Fetching fresh prices…' : 'Fetch fresh prices now (or press F5)',
          style:{display:'flex',alignItems:'center',gap:6,flexShrink:0}
        },
          fetching&&h('span',{className:'spinner'}),
          // Two labels, one hidden by CSS depending on screen width (see
          // the mobile media query) — narrow header has no room to spell
          // out "Fetch Now"/"Fetching..." next to the hamburger, logo, and
          // search bar all competing for the same ~360px of space.
          h('span',{className:'fetch-text'}, fetching?'Fetching...':'Fetch Now'),
          !fetching && h('span',{className:'fetch-text', style:{fontSize:10, opacity:0.65, border:`1px solid ${T.borderDim}`, borderRadius:3, padding:'1px 4px', marginLeft:2}}, 'F5'),
          h('span',{className:'fetch-icon'}, fetching?'':'⟳'),
        ),
        h('div',{className:'ge-header-divider', style:{width:1,height:20,background:T.borderDim,flexShrink:0,margin:'0 2px'}}),
        h('button',{
          className:'ge-btn danger ge-header-quit', title:'Quit GEnius',
          style:{padding:'4px 8px', flexShrink:0},
          onClick:()=>{ if (window.confirm('Quit GEnius? Background price fetching will stop.')) window.genius?.quitApp(); }
        }, '⏻')
      ),
      h('div',{style:{flex:1,display:'flex',overflow:'hidden',position:'relative'}},
        IS_PHONE && h(TouchTooltips),
        h('div',{className:'scroll-jump-buttons'},
          h('button',{className:'scroll-jump-btn',title:'Scroll to top',onClick:()=>scrollContentTo(0)},'▲'),
          h('button',{className:'scroll-jump-btn',title:'Scroll to bottom',onClick:()=>scrollContentTo(contentRef.current?.scrollHeight||0)},'▼')
        ),
        h('div',{className:'content',style:{flex:1},ref:contentRef},
          tab==='dashboard'&&h(DashboardTab,{items:visibleItems,indexes,selected,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,onToggleHide:toggleHide,onAddCompare:addToCompare,description:TAB_DESCRIPTIONS.dashboard,alerts,portfolio,onNavigate:setTab,news,overpricedThreshold:settings.overpricedThreshold||30,officialTop100}),
          tab==='compare' &&h(CompareTab,{compareList,onRemove:it=>it._add?addToCompare(it):setCompareList(prev=>prev.filter(c=>c.id!==it.id)),onClear:()=>setCompareList([]),allItems:visibleItems,description:TAB_DESCRIPTIONS.compare,userShorthands}),
          tab==='watchlist'&&h(WatchlistTab,{items:visibleItems,removedItems,watchlist,selected,onSelect:handleSelect,onToggleWatch:toggleWatch,description:TAB_DESCRIPTIONS.watchlist,devMode:settings.devMode}),
          tab==='invention'&&h(SplitTab,{items:catItems,selected,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,onToggleHide:toggleHide,onAddCompare:addToCompare,description:TAB_DESCRIPTIONS.invention,splitLabel:'Components',showMachines:true,allItems:visibleItems,onNavigate:setTab}),
          tab==='herblore' &&h(SplitTab,{items:catItems,selected,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,onToggleHide:toggleHide,onAddCompare:addToCompare,description:TAB_DESCRIPTIONS.herblore, splitLabel:'Combination Potions'}),
          ['melee','magic','ranged','necromancy','hybrid','ammo','pocket','artisan','food','farming','mining','prayer','archaeology','runes','summoning','boss','treasure_trails','rares','codex','cosmetics','low_tier','materials','supplies'].includes(tab)&&
            h(ItemTable,{items:catItems,selected,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,onToggleHide:toggleHide,onAddCompare:addToCompare,description:TAB_DESCRIPTIONS[tab]||''}),
          tab==='alch'    &&h(AlchTab,    {items:visibleItems,selected,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,description:TAB_DESCRIPTIONS.alch}),
          tab==='expensive'&&h(ExpensiveTab,{items:visibleItems,selected,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,threshold:settings.expensiveThreshold||500000000,description:TAB_DESCRIPTIONS.expensive}),
          tab==='portfolio'&&h(PortfolioArea,{
            onPortfolioChanged: async () => { const p = await window.genius?.getPortfolio(); if (p) setPortfolio(p); },
            items, removedItems, portfolio, toast, dateFormat: settings.dateFormat,
            onSavePosition: async pos => {
              await window.genius?.savePosition(pos);
              const p = await window.genius?.getPortfolio();
              if (p) setPortfolio(p);
              // Anything you put real gp into is worth tracking on the
              // watchlist too — auto-add the item if it isn't there yet.
              const it = items.find(i => i.name === pos.item_name);
              if (it && !watchlist.includes(it.id)) {
                const nw = [...watchlist, it.id];
                setWatchlist(nw);
                await window.genius?.setWatchlist(nw);
              }
            },
            onDeletePosition: async id => { await window.genius?.deletePosition(id); const p = await window.genius?.getPortfolio(); if(p) setPortfolio(p); },
            onSellPosition: async opts => { const r = await window.genius?.sellPosition(opts); const p = await window.genius?.getPortfolio(); if(p) setPortfolio(p); return r; },
            onConvertPosition: async opts => { const r = await window.genius?.convertPosition(opts); const p = await window.genius?.getPortfolio(); if(p) setPortfolio(p); return r; },
            onReopenPosition: async id => { const r = await window.genius?.reopenPosition(id); const p = await window.genius?.getPortfolio(); if(p) setPortfolio(p); return r; },
            onSelect: handleSelect,
            devMode: settings.devMode,
            userShorthands,
          }),
          tab==='market'        &&h(MarketTab,        {items:visibleItems,selected,onSelect:handleSelect,description:TAB_DESCRIPTIONS.market}),
          tab==='opportunities' &&h(OpportunitiesArea, {items:visibleItems,selected,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,onToggleHide:toggleHide,onAddCompare:addToCompare,description:TAB_DESCRIPTIONS.opportunities,overpricedThreshold:settings.overpricedThreshold||30}),
          tab==='flips' &&h(FlipsTab, {items:visibleItems,selected,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,onToggleHide:toggleHide,description:TAB_DESCRIPTIONS.flips}),
          tab==='top_movers' &&h(TopMoversTab, {items:visibleItems,officialTop100,onSelect:handleSelect,watchlist,onToggleWatch:toggleWatch,description:TAB_DESCRIPTIONS.top_movers}),
          tab==='money_makers' &&h(MoneyMakersTab, {items:visibleItems,onSelect:handleSelect,description:TAB_DESCRIPTIONS.money_makers}),
          tab==='news'    &&h(NewsTab,    {onOpen:url=>window.genius?.openExternal(url),description:TAB_DESCRIPTIONS.news,items:visibleItems,onSelect:handleSelect,toast,onNavigate:setTab}),
          tab==='monster_lookup'&&h(MonsterLookupTab,{description:TAB_DESCRIPTIONS.monster_lookup,monsterShorthands,items,onSelectItem:handleSelect}),
          tab==='alerts'  &&h(AlertsArea, {
            items,alerts,toast,description:TAB_DESCRIPTIONS.alerts,userShorthands,onSelect:handleSelect,
            onSave: upsertAlert,
            onDelete:id=>setAlerts(al=>al.filter(a=>a.id!==id)),
            reminders,
            onSaveReminder: upsertReminder,
            onDeleteReminder: id=>setReminders(rl=>rl.filter(r=>r.id!==id)),
          }),
          tab==='settings'&&h(SettingsTab,{settings,onChange:setSettings,toast,hiddenItems,items,onUnhide:toggleHide,userShorthands,onSaveShorthands:async sh=>{await window.genius?.saveShorthands(sh);setUserShorthands(sh);},monsterShorthands,onSaveMonsterShorthands:async sh=>{await window.genius?.saveMonsterShorthands(sh);setMonsterShorthands(sh);},onReplayTour:()=>setShowTour(true)}),
          tab==='about'&&h(AboutTab),
          tab==='dxp_intel'&&h(DXPIntelTab,{items,selected,onSelect:handleSelect,userShorthands,toast})
        ),
        showDetail&&h('div',{style:{position:'relative', display:'flex'}},
          h('div',{
            className:'panel-resize-handle',
            onMouseDown:startPanelResize,
            style:{width:5, cursor:'col-resize', flexShrink:0, background:'transparent'},
            title:'Drag to resize',
          }),
          h(DetailPanel,{item:selected,watchlist,onToggleWatch:toggleWatch,onToggleHide:toggleHide,hiddenItems,onClose:()=>setSelected(null),onCategoryChange:()=>{},notes,onSaveNote:(id,text)=>{window.genius?.saveNote(id,text);setNotes(n=>({...n,[id]:text}));},allItems:items,dateFormat:settings.dateFormat,onAddToPortfolio:pos=>setQuickAddPos(pos),panelWidth:detailPanelWidth,populatedHistoryIds,devMode:settings.devMode,onSelectItem:handleSelect,
            onSaveAlert:upsertAlert, onSaveReminder:upsertReminder, toast}),
        ),
      h(HistoryPopup,{state:historyPopup, onDismiss:()=>setHistoryPopup(null)}),
      !IS_PHONE && h(QuickSearch, {items, tabs: NAV.filter(n => n.id && n.label), onTab: id => { setTab(id); setSelected(null); }, onItem: it => setSelected(it)}),
      showTour && h(WelcomeTour, {onDone:dismissTour})
      )
    ),

    quickAddPos && h(PositionModal, {
      items,
      position: {...quickAddPos, id: Date.now().toString(), status:'open', created_at: new Date().toISOString()},
      onClose: () => setQuickAddPos(null),
      userShorthands,
      onSave: async (pos, createAlert) => {
        await window.genius?.savePosition(pos);
        const p = await window.genius?.getPortfolio();
        if (p) setPortfolio(p);
        if (createAlert && pos.target_price) {
          await window.genius?.saveAlert({id:`p-${pos.id}`, item_name:pos.item_name, condition:'above', price:pos.target_price});
        }
        setQuickAddPos(null);
        toast('Position added', 'success');
      },
    }),

    h('div',{className:'toast-tray'},
      toasts.map(t=>h('div',{key:t.id,className:`toast ${t.type}`},t.msg))
    )
  ));
}

// Ctrl+F find bar, desktop only (Ben, 2026-11-09). Searches the page's own text and
// colours matches with the CSS Highlight API, so it never moves focus out of the box
// (Chromium's find-in-page did, which dropped keystrokes and felt laggy).
function FindBar() {
  const [open, setOpen] = useState(false);
  const [text, setText] = useState('');
  const [res, setRes] = useState({ at: 0, total: 0 });
  const ref = useRef(null);
  const barRef = useRef(null);
  const ranges = useRef([]);
  const timer = useRef(null);
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = '::highlight(genius-find){background:rgba(201,168,76,0.45);color:inherit}::highlight(genius-find-now){background:#e08030;color:#000}';
    document.head.appendChild(style);
    const key = e => {
      if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey && e.key.toLowerCase() === 'f') {
        e.preventDefault(); setOpen(true); setTimeout(() => { ref.current?.focus(); ref.current?.select(); }, 0);
      }
    };
    window.addEventListener('keydown', key);
    return () => { window.removeEventListener('keydown', key); style.remove(); };
  }, []);
  const clear = () => { if (window.CSS?.highlights) { CSS.highlights.delete('genius-find'); CSS.highlights.delete('genius-find-now'); } ranges.current = []; };
  const show = (list, i) => {
    if (!window.CSS?.highlights) return;
    CSS.highlights.set('genius-find', new Highlight(...list));
    if (list[i]) {
      CSS.highlights.set('genius-find-now', new Highlight(list[i]));
      const el = list[i].startContainer.parentElement;
      el?.scrollIntoView({ block:'center', inline:'nearest' });
    } else CSS.highlights.delete('genius-find-now');
  };
  const search = t => {
    clear();
    const q = t.trim().toLowerCase();
    if (!q) { setRes({ at:0, total:0 }); return; }
    const list = [];
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, { acceptNode: n =>
      (barRef.current && barRef.current.contains(n)) || !n.nodeValue.trim() || /^(SCRIPT|STYLE)$/.test(n.parentElement?.tagName) || !n.parentElement?.offsetParent
        ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT });
    for (let n = walker.nextNode(); n && list.length < 2000; n = walker.nextNode()) {
      const v = n.nodeValue.toLowerCase();
      for (let i = v.indexOf(q); i >= 0 && list.length < 2000; i = v.indexOf(q, i + q.length)) {
        const r = new Range(); r.setStart(n, i); r.setEnd(n, i + q.length); list.push(r);
      }
    }
    ranges.current = list;
    setRes({ at: list.length ? 1 : 0, total: list.length });
    show(list, 0);
  };
  const step = dir => {
    // The page may have re-rendered since the last search; search again if so.
    if (!ranges.current.length || !ranges.current[0].startContainer.isConnected) { search(text); return; }
    const total = ranges.current.length;
    const at = ((res.at - 1 + dir + total) % total) + 1;
    setRes({ at, total });
    show(ranges.current, at - 1);
  };
  const close = () => { setOpen(false); clear(); setRes({ at:0, total:0 }); };
  if (!open) return null;
  return h('div', {ref:barRef, style:{position:'fixed', top:44, right:18, zIndex:99990, display:'flex', alignItems:'center', gap:6,
    background:T.panel || T.bg, border:`1px solid ${T.gold}`, borderRadius:4, padding:'5px 8px', boxShadow:'0 4px 16px rgba(0,0,0,0.5)'}},
    h('input', {ref, className:'ge-input', value:text, placeholder:'Find on this page', style:{width:200, fontSize:12},
      onChange:e => { const v = e.target.value; setText(v); clearTimeout(timer.current); timer.current = setTimeout(() => search(v), 150); },
      onKeyDown:e => {
        if (e.key === 'Escape') { e.preventDefault(); close(); }
        else if (e.key === 'Enter') { e.preventDefault(); step(e.shiftKey ? -1 : 1); }
      }}),
    h('span', {style:{fontSize:11, color:T.textDim, minWidth:54, textAlign:'center'}}, !text.trim() ? '' : res.total ? `${res.at} of ${res.total}` : 'No matches'),
    h('button', {className:'ge-btn', title:'Previous (Shift+Enter)', style:{fontSize:11, padding:'2px 7px'}, onMouseDown:e=>e.preventDefault(), onClick:()=>step(-1)}, '▲'),
    h('button', {className:'ge-btn', title:'Next (Enter)', style:{fontSize:11, padding:'2px 7px'}, onMouseDown:e=>e.preventDefault(), onClick:()=>step(1)}, '▼'),
    h('button', {className:'ge-btn', title:'Close (Esc)', style:{fontSize:11, padding:'2px 7px'}, onClick:close}, '✕'));
}
const findRootEl = document.createElement('div');
document.body.appendChild(findRootEl);
createRoot(findRootEl).render(h(FindBar, null));
createRoot(document.getElementById('root')).render(h(App,null));
